/* Contenido de charlas (ferreteria): más información y preguntas más exigentes. Lo aplica mejoras_comunes.js (sección 23). */
window.__mjContenidoAplicar && window.__mjContenidoAplicar({"grupo":"fer","temas":[{"id":"autocuidado","sec":"todos","title":"Actos inseguros, condiciones inseguras y autocuidado","thumb":"c5au_cadena","learn":[{"s":"c5au_acto","t":"¿Qué es un acto inseguro?","x":"Es una <b>acción u omisión de la persona</b> que se aparta de la forma segura de trabajar: lo que hacemos o dejamos de hacer. Ejemplos en {EMP}:<ul><li>Trepar a una góndola o a un rack en vez de usar la escala.</li><li>Pasar detrás de un camión que retrocede.</li><li>Operar la grúa horquilla sin estar autorizado.</li><li>No usar el EPP o usar el celular mientras conduces.</li></ul>"},{"s":"c5au_cond","t":"¿Qué es una condición insegura?","x":"Es una situación del <b>lugar, el equipo o el material</b> que puede causar un accidente, aunque en ese momento nadie esté haciendo algo mal. Ejemplos:<ul><li>Pintura o aceite derramado en el pasillo.</li><li>Viga del rack doblada o pallet roto.</li><li>Extensión eléctrica cruzando el paso.</li><li>Eslinga o cinta de amarre con un corte.</li><li>Luz quemada en un pasillo de bodega.</li></ul>Se señaliza, se reporta y se corrige."},{"s":"c5au_cadena","t":"La cadena del accidente","x":"Un accidente casi nunca tiene una sola causa: es como una <b>fila de fichas de dominó</b>. El apuro, la falta de EPP, un atajo y una condición insegura se suman hasta que cae la última ficha: la lesión. <b>La mayoría de los accidentes se relacionan con una acción insegura.</b> Si sacas una sola ficha, la cadena se corta, y esa ficha casi siempre está en tus manos."},{"s":"c5au_porque","t":"¿Por qué cometemos actos inseguros?","x":"<ul><li><b>Apuro:</b> el cliente espera o hay que sacar el despacho.</li><li><b>Exceso de confianza:</b> llevo años haciéndolo así.</li><li><b>Costumbre:</b> el riesgo se vuelve invisible.</li><li><b>Cansancio o sueño:</b> bajan la atención y los reflejos.</li><li><b>Siempre se ha hecho así:</b> que nunca haya pasado nada no significa que sea seguro; puede haber sido solo suerte.</li></ul>Reconocer estas trampas es el primer paso para no caer en ellas."},{"s":"c5au_ppa","t":"Para, piensa, actúa","x":"Antes de cada tarea, sobre todo si es nueva, poco habitual o si algo cambió:<ul><li><b>Para:</b> detente unos segundos.</li><li><b>Piensa:</b> ¿qué puede salir mal? ¿Tengo el EPP, la escala, la transpaleta o la ayuda que necesito? ¿Estoy autorizado para hacerlo?</li><li><b>Actúa:</b> hazlo de la forma segura. Si no puedes controlar el riesgo, no empieces y consulta a tu jefatura.</li></ul>"},{"s":"c5au_alcohol","t":"Cero alcohol y cero drogas","x":"El alcohol y las drogas bajan los reflejos y la atención, aunque te sientas bien. El alcohol de la noche anterior puede seguir en la sangre al día siguiente, y ni el café ni una ducha lo eliminan: solo el tiempo. Para conducir, la Ley 20.580 considera <b>bajo la influencia desde 0,3 gramos por litro</b> de sangre y <b>ebriedad desde 0,8 gramos por litro</b>. La regla segura es <b>cero alcohol y cero drogas</b>. Si un compañero llega así, avisa a tu jefatura.","k":"Si bebiste, no conduces ni operas equipos: avisa a tu jefatura."},{"s":"c5au_companero","t":"Me cuido y cuido a mi compañero","x":"Si ves a un compañero a punto de hacer algo riesgoso, <b>avísale de inmediato y con respeto</b>: ¡Alto, el camión viene retrocediendo!, o Ponte el chaleco. Si no te escucha y el riesgo sigue, avisa a la jefatura. No es meterse en lo ajeno ni acusar: es cuidarnos entre todos. Y si te avisan a ti, agradece y corrige: te pueden estar evitando una lesión."},{"s":"c5au_reporte","t":"Reporta condiciones inseguras y casi accidentes","x":"Si ves una eslinga cortada, una viga del rack golpeada, un derrame, o tienes un casi accidente:<ul><li><b>Saca de uso</b> lo dañado, si puedes hacerlo sin riesgo.</li><li><b>Señaliza</b> sin exponerte.</li><li><b>Avisa</b> a tu jefatura, al Comité Paritario (si tu sucursal o empresa lo tiene) o al asesor en prevención.</li></ul>No lo arregles a tu manera ni lo dejes para después: callar deja la trampa armada para el próximo."},{"s":"c5au_184","t":"Derecho a interrumpir ante riesgo grave","x":"Si hay un <b>riesgo grave e inminente</b> para tu vida o tu salud, tienes derecho a <b>interrumpir tus labores</b> y, si es necesario, abandonar el lugar, avisando a tu jefatura lo antes posible (Código del Trabajo, art. 184 bis). Ejemplos: un rack que se dobla, una carga que se suelta en el camión o un fuerte olor a gas. Ejercer este derecho de buena fe no puede perjudicarte.","k":"Ante un riesgo grave e inminente: detente, aléjate y avisa."},{"s":"c5au_conse","t":"Autocuidado: piensa en quién te espera","x":"Un accidente te afecta a ti, a tu familia y a tu equipo. La acción insegura típica es <b>ahorrarse un paso por apuro</b>: trepar a la góndola en vez de ir a buscar la escala, o cargar solo lo que es para dos. Decide seguro antes, no después. Cumplir el Reglamento Interno, seguir los procedimientos y usar el EPP también es tu deber (Ley 16.744, art. 67)."}],"quiz":[{"s":"c5au_mal","v":[{"q":"Un vendedor trepa por las repisas de la góndola para alcanzar una caja. Eso es:","o":["Un acto inseguro","Una condición insegura","Un casi accidente","Una condición y un acto a la vez"],"w":"Es una decisión de la persona que se aparta de la forma segura: para llegar arriba se usa una escala."},{"q":"¿Cómo se clasifica subirse a la góndola en vez de ir a buscar la escala?","o":["Acto inseguro: lo decide la persona","Condición insegura: la góndola es alta","Condición insegura: falta una escala","No es inseguro si se hace con cuidado"],"w":"Lo que hacemos o dejamos de hacer es un acto. La altura de la góndola no obliga a treparla."},{"q":"Subirse a una góndola es una condición insegura, porque el peligro está en la altura de la repisa.","vf":false,"w":"Falso. Es un acto inseguro: la persona decide treparse en vez de usar la escala."}]},{"s":"c5au_cond","v":[{"q":"En el pasillo de la bodega hay pintura derramada y una extensión cruzando el paso. Eso es:","o":["Una condición insegura","Un acto inseguro","Un casi accidente","Un accidente del trabajo"],"w":"Son peligros del lugar o del material: se señalizan, se reportan y se corrigen."},{"q":"¿Cuál de estos es un ejemplo de condición insegura?","o":["Una viga del rack doblada","Pasar detrás de un camión que retrocede","Operar la grúa sin autorización","Conducir mirando el celular"],"w":"La viga doblada es un problema del equipo. Las otras son acciones de personas: actos inseguros."},{"q":"¿Qué tienen en común un derrame, un cable cruzando el paso y un pallet roto?","o":["Son condiciones inseguras del lugar o del material","Son actos inseguros de quien pasa por ahí","Son casi accidentes que ya ocurrieron","Son peligros que solo debe ver la jefatura"],"w":"Están en el ambiente, aunque nadie esté haciendo algo mal. Todos pueden y deben reportarlos."}]},{"s":"c5au_cadena","v":[{"q":"La mayoría de los accidentes se relacionan con:","o":["Una acción insegura, como apurarse o no usar el EPP","Fallas de equipos que nadie podía prever","Las condiciones del clima y del terreno","La mala suerte del momento"],"w":"Por eso nuestras decisiones son la principal herramienta para evitarlos."},{"q":"En la cadena de fichas de dominó del accidente, ¿qué pasa si sacas una ficha?","o":["La cadena se corta y el accidente se puede evitar","Las demás fichas caen igual y nada cambia","Solo baja la gravedad de la lesión","Nada, si queda una condición insegura"],"w":"Cada ficha es una causa. Si quitas una, la cadena no llega a la lesión."},{"q":"Si se saca una sola ficha de la cadena del accidente, el accidente puede evitarse.","vf":true,"w":"Verdadero. Basta cortar una causa, por ejemplo no apurarse o usar el EPP, para que la cadena no avance."}]},{"s":"c5au_porque","v":[{"q":"Si una tarea siempre se ha hecho así y nunca ha pasado nada, entonces es segura.","vf":false,"w":"Falso. Que no haya pasado nada todavía puede ser suerte: el riesgo sigue ahí."},{"q":"Un compañero dice: llevo diez años subiéndome al rack y nunca me he caído. ¿Qué trampa es esta?","o":["Exceso de confianza","Cansancio","Apuro","Falta de herramientas"],"w":"Creer que la experiencia protege hace que se ignore el riesgo."},{"q":"Que una tarea riesgosa nunca haya causado un accidente significa que:","o":["Pudo ser suerte: el riesgo sigue ahí","El riesgo ya quedó bien controlado","Se puede seguir haciendo de esa forma","Solo es peligrosa para los más nuevos"],"w":"Siempre se ha hecho así es una de las trampas más comunes."}]},{"s":"c5au_ok","v":[{"q":"Necesitas una caja de la repisa más alta de la góndola. ¿Qué haces?","o":["Busco una escala en buen estado y la uso","Me apoyo en la repisa baja solo un segundo","Uso una caja firme como peldaño","Le pido a un compañero que me levante"],"w":"Para llegar a lo alto se usa una escala en buen estado, nunca la góndola ni objetos improvisados."},{"q":"Vas atrasado, la escala está en otro pasillo y un cliente espera. ¿Cuál es la decisión segura?","o":["Ir a buscar la escala, aunque tarde más","Trepar por la góndola, porque es rápido","Subirme a un balde dado vuelta","Estirarme desde la repisa más baja"],"w":"El apuro es la trampa típica. Unos segundos más evitan una caída."},{"q":"En el paso Piensa, antes de alcanzar algo en altura, ¿qué te preguntas?","o":["Qué puede salir mal y si tengo la escala","Cuánto me voy a demorar en subir y bajar","Si la jefatura me está mirando o no","Si alguna vez alguien se ha caído aquí"],"w":"Pensar en lo que puede salir mal y en lo que necesitas permite actuar de forma segura."}]},{"s":"c5au_alcohol","v":[{"q":"Anoche tomaste bastante y hoy te sientes bien. Te toca conducir el camión de despacho. ¿Qué haces?","o":["No conduzco y aviso a mi jefatura","Conduzco, porque dormí varias horas","Tomo un café cargado y salgo","Conduzco despacio y solo en la ciudad"],"w":"El alcohol puede seguir en la sangre aunque te sientas bien. La regla es cero alcohol al trabajar."},{"q":"¿Qué elimina el alcohol de la sangre?","o":["Solo el paso del tiempo","Un café cargado","Una ducha fría","Comer bien antes de salir"],"w":"El café o la ducha pueden hacerte sentir más despierto, pero el alcohol sigue en la sangre."},{"q":"Un compañero llega con olor a alcohol y le toca operar la grúa horquilla. ¿Qué haces?","o":["Aviso a la jefatura para que no opere","Lo dejo, si dice que se siente bien","Le doy café y le pido que opere despacio","Opero yo la grúa aunque no esté autorizado"],"w":"Avisar protege a tu compañero y a todos en el patio. Nadie opera sin autorización."}]},{"s":"camion_conduccion_alcohol","v":[{"q":"Según la Ley 20.580, desde 0,3 gramos de alcohol por litro de sangre ya se conduce bajo la influencia del alcohol.","vf":true,"w":"Verdadero. Desde 0,3 es bajo la influencia y desde 0,8 gramos por litro, estado de ebriedad."},{"q":"Según la Ley 20.580, ¿desde qué nivel se considera estado de ebriedad?","o":["0,8 gramos por litro","0,3 gramos por litro","0,5 gramos por litro","1,0 gramo por litro"],"w":"Desde 0,3 es bajo la influencia; desde 0,8, ebriedad. En el trabajo, la regla segura es cero."},{"q":"Según la Ley 20.580, conducir con 0,4 gramos de alcohol por litro de sangre es:","o":["Conducir bajo la influencia del alcohol","Conducir en estado de ebriedad","Permitido, porque es menos de 0,5","Permitido, si no hay accidente"],"w":"Entre 0,3 y menos de 0,8 gramos por litro es bajo la influencia del alcohol."}]},{"s":"c5au_companero","v":[{"q":"Un compañero camina detrás de un camión que retrocede y no se ha dado cuenta. ¿Qué haces?","o":["Le grito ¡Alto! de inmediato y le aviso","Espero a que el conductor lo vea por el espejo","Le aviso después, para no asustarlo","Le hago señas al conductor sin decir nada"],"w":"Avisar a tiempo y directamente puede salvarle la vida."},{"q":"Le adviertes a un compañero que se ponga el chaleco y no te hace caso. El riesgo sigue. ¿Qué haces?","o":["Aviso a la jefatura: es cuidarlo, no acusarlo","Lo dejo, porque ya le avisé una vez","Discuto con él hasta que me haga caso","Le saco una foto para tener una prueba"],"w":"Si el aviso no basta y el riesgo continúa, se informa a la jefatura."},{"q":"Un compañero te advierte que vas a pasar detrás de un camión que retrocede. ¿Cuál es la actitud correcta?","o":["Agradezco y corrijo de inmediato","Le explico que sé lo que hago","Sigo, porque el conductor ya me vio","Me molesto, porque no es mi jefe"],"w":"Quien te avisa te está cuidando. Agradecer y corregir es parte del autocuidado."}]},{"s":"c5au_reporte","v":[{"q":"Ves una eslinga con un corte en la bodega. ¿Qué haces?","o":["La saco de uso, la señalizo y aviso a mi jefatura","La uso solo para cargas livianas","La reparo con cinta y la sigo usando","La dejo donde estaba y aviso a fin de mes"],"w":"Una eslinga dañada puede cortarse con la carga arriba. Se retira, se señaliza y se reporta."},{"q":"Una caja cayó del rack cerca de ti, sin golpearte. ¿A quién puedes reportarlo?","o":["A mi jefatura, al Comité Paritario o al asesor","A nadie, porque no hubo ninguna lesión","Solo al compañero que estaba conmigo","Solo a la Mutual, si después me duele"],"w":"El casi accidente se reporta para corregir la causa antes de que lesione a alguien."},{"q":"Una caja que cae cerca sin golpear a nadie es un casi accidente y también se debe avisar.","vf":true,"w":"Verdadero. Lo que no se reporta no se corrige, y el próximo puede salir lesionado."}]},{"s":"c5au_184","v":[{"q":"Un rack con carga empieza a doblarse mientras repones. ¿Qué derecho tienes?","o":["Interrumpir la labor, alejarme y avisar","Ninguno: debo terminar la reposición","Detenerme solo si la jefatura lo autoriza","Alejarme, pero sin necesidad de avisar"],"w":"Ante riesgo grave e inminente puedes interrumpir tus labores, avisando lo antes posible."},{"q":"¿Qué norma establece el derecho a interrumpir tus labores ante un riesgo grave e inminente?","o":["Código del Trabajo, art. 184 bis","Ley 16.744, art. 68","DS 594, art. 53","Ley 16.744, art. 76"],"w":"El art. 184 bis del Código del Trabajo protege este derecho."},{"q":"Si interrumpes tu trabajo de buena fe ante un riesgo grave e inminente:","o":["No puede perjudicarte; avisas lo antes posible","Te pueden descontar el tiempo detenido","Necesitas un permiso escrito antes de parar","Solo lo puede decidir el Comité Paritario"],"w":"Es un derecho del trabajador. La condición es avisar a la jefatura lo antes posible."}]}]},{"id":"peligros","sec":"todos","title":"Peligros y riesgos: identificación y control (MIPER)","thumb":"c5pe_vs","learn":[{"s":"c5pe_vs","t":"Peligro y riesgo no son lo mismo","x":"<b>Peligro</b> es la fuente que puede causar daño: una carga en altura, un camión en movimiento, el canto filoso del zinc, un solvente inflamable. <b>Riesgo</b> es la posibilidad de que ese peligro te dañe, junto con qué tan grave sería. Ejemplo: sacos mal apilados en lo alto del rack son el peligro; que te caigan encima mientras repones es el riesgo. Si te alejas, el peligro sigue ahí, pero tu riesgo baja."},{"s":"c5pe_sala","t":"Peligros en la sala de ventas","x":"<ul><li><b>Productos pesados en altura:</b> caída de objetos.</li><li><b>Reponer en altura:</b> caídas desde la escala o por trepar.</li><li><b>Cuchillo cartonero y cantos:</b> cortes.</li><li><b>Piso mojado o con productos caídos:</b> resbalones. Si ves un derrame, señalízalo y avisa de inmediato, aunque no lo hayas provocado.</li><li><b>Atención de público:</b> clientes agresivos y asaltos en caja.</li><li><b>Carros y transpaletas</b> en pasillos con clientes: golpes.</li></ul>"},{"s":"c5pe_patio","t":"Peligros en bodega y patio","x":"<ul><li><b>Grúas horquilla y camiones:</b> atropellos y aplastamiento.</li><li><b>Racks, pilas y cargas suspendidas:</b> caída de carga.</li><li><b>Sacos, fierro y planchas:</b> sobreesfuerzo.</li><li><b>Fierro, zinc y perfiles:</b> cortes por cantos vivos.</li><li><b>Gas, pinturas y solventes:</b> incendio.</li><li><b>Polvo de cemento:</b> irritación de ojos y piel.</li><li><b>Clientes</b> caminando donde se mueven vehículos.</li></ul>"},{"s":"c5pe_cargos","t":"Todos los cargos tienen peligros","x":"<ul><li><b>Conductores:</b> choques, cansancio, carga mal estibada, bajar de la cabina.</li><li><b>Peonetas:</b> subir y bajar de la plataforma, cortes, sobreesfuerzo.</li><li><b>Bodega y patio:</b> grúa, caída de carga, sobreesfuerzo.</li><li><b>Ventas y caja:</b> productos en altura, asaltos, clientes agresivos.</li><li><b>Administración:</b> malas posturas, pantalla, escaleras y estrés.</li></ul>Nadie está fuera de los riesgos: cambian según el puesto."},{"s":"c5pe_miper","t":"La matriz MIPER","x":"La <b>Matriz de Identificación de Peligros y Evaluación de Riesgos</b> ordena cada tarea con sus peligros, sus riesgos y las medidas de control. Por ejemplo: mover sacos tiene el peligro del peso, el riesgo de un lumbago y el control de usar la transpaleta. <b>La empresa debe identificar los peligros, evaluar los riesgos e informártelos.</b> La matriz se revisa cuando cambia una tarea, llega un equipo nuevo u ocurre un accidente."},{"s":"c5pe_eval","t":"¿Cómo se evalúa un riesgo?","x":"Se hacen dos preguntas: <b>¿qué tan seguido puede pasar?</b> (probabilidad) y <b>¿qué tan grave sería?</b> (consecuencia). Al cruzarlas, el riesgo queda en verde (bajo), amarillo o naranja (medio) o rojo (alto). Que caiga una carga desde lo alto del rack quizás no es frecuente, pero puede ser mortal: por eso se controla con prioridad. <b>Si un riesgo es alto, no se trabaja hasta controlarlo.</b>"},{"s":"c5pe_jer","t":"Jerarquía de controles","x":"De más a menos efectivo:<ul><li><b>Eliminar</b> el peligro: retirar de uso un pallet roto.</li><li><b>Sustituir</b> por algo menos peligroso: una pintura al agua en vez de una con solvente.</li><li><b>Ingeniería:</b> barandas, topes, separación física de peatones y grúas.</li><li><b>Administrativos:</b> procedimientos, demarcación, señalización y capacitación.</li><li><b>EPP:</b> la última barrera, porque no elimina el peligro.</li></ul>","k":"Primero se elimina el peligro; el EPP es la última barrera."},{"s":"c5pe_eslinga","t":"Ejemplo: la cinta de amarre y el canto vivo","x":"Una cinta de amarre o una eslinga puede cortarse con el <b>canto vivo</b> de la carga. El peligro: el filo del fierro, el zinc o los perfiles. El riesgo: que la cinta se corte y la carga caiga del camión. Controles:<ul><li><b>Proteger los cantos</b> con cantoneras.</li><li><b>Revisar la cinta</b> antes de usarla: si tiene cortes, se retira, aunque sean pequeños.</li><li><b>Nadie al costado de la carga</b> mientras se tensa o se suelta.</li></ul>"},{"s":"c5pe_irl","t":"Tu derecho a saber","x":"El DS 44 obliga a la empresa a <b>informarte los riesgos</b> de tu trabajo, las medidas preventivas y los métodos de trabajo correctos: es la información de riesgos laborales (IRL). Se entrega al ingresar y también cuando cambias de cargo o de sucursal, o cuando llega un equipo nuevo. Si no te queda claro, pregunta: <b>¿qué riesgos tiene y cómo me protejo?</b>"},{"s":"c5pe_auto","t":"Autocuidado: no te acostumbres al peligro","x":"La acción insegura típica es <b>acostumbrarse</b>: pasar bajo la carga de la grúa porque siempre se pasa, bajar mercadería pesada sin escala o ignorar una viga golpeada. <b>Nunca pases ni te quedes bajo una carga suspendida</b>: si cae, ningún casco te protege de ese golpe. Espera a que baje o rodea lejos. Ante un peligro nuevo: <b>detente, mira y avisa</b> a tu jefatura, al Comité Paritario (si lo hay) o al asesor en prevención.","k":"Nunca pases ni te quedes bajo una carga suspendida."}],"quiz":[{"s":"c5pe_vs","v":[{"q":"Sacos mal apilados en lo alto del rack son un ejemplo de:","o":["Peligro","Riesgo","Medida de control","Acto inseguro"],"w":"La carga en altura es la fuente que puede causar daño: un peligro."},{"q":"En el ejemplo del rack, ¿qué es el peligro?","o":["La carga mal apilada en altura","Que la carga te caiga encima","La probabilidad de que ocurra","Usar casco al reponer"],"w":"El peligro es la fuente del daño. Que te caiga encima es el riesgo."},{"q":"Una caja pesada que sobresale del nivel alto del rack es:","o":["Un peligro: la fuente del daño","Un riesgo: la posibilidad de daño","Un control de tipo administrativo","Un casi accidente ya ocurrido"],"w":"La caja que puede caer es la fuente del daño, es decir, el peligro."}]},{"s":"c5pe_vs","v":[{"q":"La posibilidad de que esa carga te caiga encima, y qué tan grave sería, es:","o":["El riesgo","El peligro","La medida de control","La condición insegura"],"w":"Riesgo es la posibilidad de daño junto con su gravedad."},{"q":"Si te alejas de la zona bajo la carga mal apilada, ¿qué cambia?","o":["Baja tu riesgo, aunque el peligro sigue ahí","Desaparece el peligro","Baja el peligro, pero sube el riesgo","No cambia nada, ni peligro ni riesgo"],"w":"El peligro sigue en el rack hasta que se corrija; lo que baja es tu posibilidad de daño."},{"q":"El riesgo combina la probabilidad de que un peligro cause daño y la gravedad de ese daño.","vf":true,"w":"Verdadero. Por eso se evalúa con dos preguntas: qué tan seguido y qué tan grave."}]},{"s":"c5pe_jer","v":[{"q":"¿Cuál es la medida de control más efectiva?","o":["Eliminar el peligro","Usar el EPP adecuado","Poner un letrero de advertencia","Capacitar a los trabajadores"],"w":"Eliminar está en la cima de la jerarquía de controles: si no hay peligro, no hay riesgo."},{"q":"Hay un pallet roto en el rack. ¿Qué medida está más arriba en la jerarquía?","o":["Retirarlo de uso","Ponerle un letrero de cuidado","Avisar a todos que no se acerquen","Usar casco al pasar cerca"],"w":"Retirarlo elimina el peligro. Las demás medidas lo dejan ahí."},{"q":"¿Cuál es el orden de la jerarquía de controles, de más a menos efectivo?","o":["Eliminar, sustituir, ingeniería, administrativos, EPP","EPP, administrativos, ingeniería, sustituir, eliminar","Sustituir, eliminar, EPP, ingeniería, administrativos","Ingeniería, eliminar, sustituir, EPP, administrativos"],"w":"Se parte por eliminar el peligro y el EPP queda al final, como última barrera."}]},{"s":"c5pe_jer","v":[{"q":"El EPP es la primera medida que se debe aplicar.","vf":false,"w":"Falso. Es la última barrera, después de los demás controles."},{"q":"¿Qué lugar ocupa el EPP en la jerarquía de controles?","o":["Es la última barrera","Es la primera medida","Va antes de la ingeniería","Reemplaza a los procedimientos"],"w":"El EPP protege de lo que queda después de aplicar los demás controles."},{"q":"¿Por qué el EPP es la última barrera?","o":["No elimina el peligro: solo reduce el daño","Porque es lo más caro de implementar","Porque solo lo usan algunos cargos","Porque la ley lo menciona al final"],"w":"Los controles de más arriba actúan sobre el peligro; el EPP solo sobre sus consecuencias."}]},{"s":"horquilla_patio_zonas","v":[{"q":"Instalar una baranda que separe el paso peatonal de la zona de grúas es un control:","o":["De ingeniería","Administrativo","De EPP","De sustitución"],"w":"Las barreras físicas, como barandas y topes, son controles de ingeniería."},{"q":"Pintar la demarcación de una ruta peatonal y poner señalética es un control:","o":["Administrativo","De ingeniería","De eliminación","De EPP"],"w":"Demarcar y señalizar orienta a las personas, pero no las separa físicamente: es administrativo."},{"q":"¿Cuál de estas medidas es un control de ingeniería?","o":["Topes y barandas que separan peatones de grúas","Un procedimiento escrito para el patio","Una charla sobre atropellos","Chalecos reflectantes para todos"],"w":"Ingeniería es una barrera física; los procedimientos y charlas son administrativos y el chaleco es EPP."}]},{"s":"camion_estiba_canto_mal","v":[{"q":"¿Qué ayuda a evitar que una cinta de amarre se corte con el canto vivo del fierro?","o":["Cantoneras y revisar la cinta antes","Tensar la cinta con mucha más fuerza","Usar dos cintas viejas en vez de una","Amarrar rápido para que no alcance a rozar"],"w":"La cantonera protege la cinta del filo, y revisarla permite retirar la que está dañada."},{"q":"En una carga de perfiles de acero, ¿cuál es el peligro que puede cortar la cinta?","o":["El canto vivo del perfil","El peso total de la carga","El tensor de la cinta","La velocidad del camión"],"w":"El filo del fierro, el zinc o los perfiles corta la cinta si no se protege."},{"q":"Si una cinta de amarre tiene un corte pequeño, se puede seguir usando sobre fierro si se pone cantonera.","vf":false,"w":"Falso. Una cinta con cortes se retira, aunque sean pequeños: puede cortarse con la carga en tensión."}]},{"s":"camion_carga_susp_mal","v":[{"q":"La grúa horquilla levanta un pallet y necesitas pasar al otro lado. ¿Qué haces?","o":["Espero a que baje la carga o rodeo lejos","Paso rápido por debajo","Paso por debajo con el casco puesto","Le hago una seña al operador y paso"],"w":"Nadie pasa ni se queda bajo una carga suspendida, ni por un segundo."},{"q":"Puedo pasar bajo una carga suspendida si llevo casco y lo hago rápido.","vf":false,"w":"Falso. Si la carga cae, ningún casco te protege de ese golpe."},{"q":"¿Por qué nadie debe quedarse bajo una carga suspendida?","o":["Si cae, ningún casco protege de ese golpe","Porque tapa la visión del operador de la grúa","Porque lo prohíbe solo el Reglamento Interno","Porque la carga podría soltar polvo o suciedad"],"w":"La caída de una carga puede ser mortal. La única protección es no estar debajo."}]},{"s":"c5pe_avisa","v":[{"q":"Un vendedor ve un derrame en un pasillo de la sala de ventas. ¿Qué debe hacer?","o":["Señalizarlo y avisar de inmediato","Seguir atendiendo; lo limpia el aseo","Esquivarlo y avisar al final del turno","Taparlo con un cartón y seguir"],"w":"Señalizar y avisar evita que un cliente o un compañero resbale."},{"q":"Un cliente botó un envase de pintura y el piso quedó resbaloso. Estás atendiendo a otro cliente. ¿Qué haces?","o":["Señalizo el derrame y aviso de inmediato","Termino la venta y después veo","Le pido al cliente que lo limpie","Lo dejo, porque no lo boté yo"],"w":"El piso resbaloso es un peligro para todos. Señalizar toma segundos."},{"q":"Ves un derrame que no provocaste. ¿Te corresponde hacer algo?","o":["Sí: señalizar sin exponerme y avisar","No: es tarea del personal de aseo","Solo si un cliente se resbala","Solo si la jefatura me lo pide"],"w":"Detectar y avisar los peligros es tarea de todos, no solo de quien los provocó."}]},{"s":"c5pe_irl","v":[{"q":"La empresa debe informarte los riesgos de tu puesto, las medidas preventivas y la forma correcta de trabajar.","vf":true,"w":"Verdadero. Es tu derecho a saber, establecido en el DS 44."},{"q":"Te cambian de la sala de ventas a la bodega. ¿Qué corresponde?","o":["Que te informen los nuevos riesgos y cómo protegerte","Nada, porque ya te informaron cuando ingresaste","Aprender el trabajo mirando a los compañeros","Firmar el registro de información sin leerlo"],"w":"La información de riesgos se entrega también al cambiar de cargo o de sucursal."},{"q":"¿Qué norma obliga a la empresa a informarte los riesgos de tu trabajo?","o":["El DS 44","La Ley 20.580","La Ley de Tránsito","El DS 18"],"w":"El DS 44 establece la obligación de informar los riesgos laborales."}]},{"s":"c5pe_eval","v":[{"q":"Un riesgo poco frecuente pero que puede ser mortal, como la caída de carga desde el rack:","o":["Se controla con prioridad","Se deja para después, porque casi no pasa","Se controla solo con EPP","Se acepta si nunca ha ocurrido"],"w":"La gravedad pesa tanto como la probabilidad: lo que puede matar se controla primero."},{"q":"¿Qué dos preguntas se usan para evaluar un riesgo?","o":["Qué tan seguido puede pasar y qué tan grave sería","Quién tiene la culpa y cuánto cuesta","Cuándo pasó la última vez y quién lo vio","Qué EPP se usa y dónde se compra"],"w":"Probabilidad y consecuencia: al cruzarlas se obtiene el nivel del riesgo."},{"q":"Si un riesgo resulta alto, en rojo en la matriz, ¿qué corresponde?","o":["No trabajar hasta controlarlo","Trabajar con más cuidado","Trabajar solo con EPP","Trabajar rápido para exponerse menos"],"w":"Un riesgo alto debe controlarse antes de hacer la tarea."}]}]},{"id":"transito","sec":"todos","title":"Patio y estacionamiento: peatones y vehículos juntos","thumb":"transito_retro","learn":[{"s":"transito_intro","t":"Un patio, muchos vehículos","x":"En el patio de {EMP} se juntan <b>camiones de despacho, grúas horquilla y camionetas de clientes</b>, con vendedores, peonetas y clientes caminando entre ellos. Un camión pesa toneladas, una grúa con carga puede pesar más que un auto y sus conductores no siempre te ven. Por eso en el patio nadie anda distraído: peatones y conductores van atentos, cada uno por su zona y a velocidad moderada."},{"s":"transito_ruta","t":"Camina por la ruta peatonal","x":"<ul><li>Usa las <b>rutas y pasos peatonales</b> demarcados. Si tu sucursal no los tiene, camina por el borde, lejos de la zona de carga.</li><li>No cortes camino entre camiones ni por la zona de carga.</li><li>No pases entre un vehículo que maniobra y una pared, un rack u otro vehículo: <b>quedarías atrapado</b>.</li><li>Si una ruta está bloqueada, no la rodees por la zona de grúas: avisa para que la despejen.</li></ul>"},{"s":"transito_retro","t":"Nunca detrás de un vehículo en retroceso","x":"El retroceso es el momento más peligroso: el conductor ve poco o nada detrás.<ul><li><b>Nunca camines ni te detengas detrás</b> de un camión o una grúa que retrocede.</li><li>Si escuchas una alarma de retroceso, sal hacia un costado donde el conductor te vea.</li><li>La alarma avisa que el vehículo se mueve; no le dice al conductor que tú estás ahí.</li><li>No te apoyes en un camión detenido: puede moverse.</li></ul>","k":"Alarma de retroceso: sal de atrás hacia un costado donde el conductor te vea."},{"s":"transito_ciego","t":"Puntos ciegos","x":"Camiones y grúas tienen <b>zonas donde el conductor no te ve</b>: atrás, pegado a los costados y justo delante de la cabina. En la grúa horquilla, una carga alta tapa la vista hacia adelante, y por eso el operador debe avanzar en reversa. Que tú veas el vehículo no significa que el conductor te vea. Regla simple: <b>si no ves los ojos del conductor, en su espejo o por el parabrisas, él no te ve a ti</b>.","k":"Si no ves los ojos del conductor, él no te ve a ti."},{"s":"transito_contacto","t":"Contacto visual antes de cruzar","x":"<ul><li>Antes de cruzar frente a un vehículo, <b>busca los ojos del conductor</b> y espera su seña.</li><li>Un vehículo detenido puede partir: si el conductor mira hacia otro lado, no cruces.</li><li>No toques ni golpees el vehículo para avisar que estás.</li><li>Conductores y operadores: si hay un peatón cerca, deténganse y denle la pasada con una seña clara.</li></ul>"},{"s":"transito_chaleco","t":"Chaleco reflectante","x":"En patio y bodega, el <b>chaleco reflectante</b> hace que los conductores te vean antes, sobre todo con poca luz, lluvia o neblina, comunes en el sur. Úsalo <b>cerrado, limpio y en buen estado</b>: abierto o con barro se ve mucho menos. Si tu puesto lo exige, es tu EPP: la empresa debe entregarlo sin costo y tú debes usarlo, también de día."},{"s":"transito_clientes","t":"Guía a los clientes","x":"Los clientes no conocen los riesgos del patio.<ul><li>Indícales dónde <b>estacionar y esperar</b>.</li><li>Mientras se carga su vehículo con la grúa, que <b>apaguen el motor y esperen fuera de la zona de carga</b>.</li><li>No los dejes pasear entre camiones ni grúas, ni que ayuden a cargar.</li><li>Si un cliente maneja rápido o entra a la zona de carga, ponte a salvo y avisa a tu jefatura.</li></ul>"},{"s":"transito_vel","t":"Conductores y operadores","x":"<ul><li>Conduce a <b>velocidad moderada</b>, según las reglas internas, y toca la bocina en esquinas ciegas.</li><li>Antes de retroceder, mira. Si no ves bien, <b>bájate a mirar o pide un señalero</b>, aunque tengas alarma o cámara.</li><li>La grúa horquilla solo la opera quien está <b>capacitado y autorizado</b> por la empresa.</li><li>Nunca lleves personas en la grúa.</li><li>Atento a clientes y niños en el estacionamiento.</li></ul>"},{"s":"transito_celular","t":"Celular: ni caminando ni conduciendo","x":"Mirar el celular en el patio te deja <b>ciego y sordo</b> frente a un camión o una grúa, aunque vayas por la ruta peatonal.<ul><li>Para usarlo, detente en un lugar seguro, fuera de la circulación.</li><li>Al conducir está prohibido por ley manipularlo: ni llamar con el teléfono en la mano, ni escribir.</li><li>Evita los audífonos en el patio: no escucharías una alarma de retroceso ni un aviso.</li></ul>"},{"s":"transito_auto","t":"Autocuidado en el patio","x":"La mayoría de los accidentes se relacionan con una acción insegura. En el patio, la típica es <b>cortar camino</b> por detrás de un camión porque es un segundo, o cruzar mirando el celular. La decisión segura: rodear por la ruta peatonal y buscar contacto visual. <b>Avisar</b> a tu jefatura si un conductor va rápido o si un paso está bloqueado también es autocuidado."}],"quiz":[{"s":"transito_retro","v":[{"q":"Un camión empieza a retroceder y suena su alarma. Estás detrás. ¿Qué haces?","o":["Salgo hacia un costado donde el conductor me vea","Sigo caminando: la alarma le avisa al conductor","Me quedo quieto detrás hasta que se detenga","Golpeo la carrocería y me quedo atrás"],"w":"Detrás del vehículo el conductor no te ve. Sal hacia un lado visible."},{"q":"¿Por qué el retroceso es el momento más peligroso en el patio?","o":["Porque el conductor ve poco o nada detrás","Porque el camión va más rápido en reversa","Porque la alarma confunde a los peatones","Porque solo ocurre con camiones cargados"],"w":"Hacia atrás la visión del conductor es mínima: nadie debe estar ahí."},{"q":"Al escuchar una alarma de retroceso, lo correcto es salir hacia un costado donde el conductor me vea.","vf":true,"w":"Verdadero. La alarma avisa que el vehículo se mueve; tú debes salir de atrás hacia un lugar visible."}]},{"s":"transito_cortaMal","v":[{"q":"Para llegar a la bodega, lo más corto es pasar entre dos camiones estacionados. ¿Qué haces?","o":["Rodeo por la ruta peatonal","Paso rápido entre los camiones","Paso entre ellos si los motores están apagados","Paso agachado, pegado a la carrocería"],"w":"Un camión puede moverse en cualquier momento. El camino más corto no es el más seguro."},{"q":"Un camión maniobra cerca de un rack y queda un espacio angosto. ¿Puedes pasar por ahí?","o":["No: podría quedar atrapado","Sí, si paso corriendo y agachado","Sí, si el conductor tocó la bocina","Sí, si llevo el chaleco reflectante"],"w":"Entre un vehículo que maniobra y una pared, un rack u otro vehículo puedes quedar aplastado."},{"q":"Pasar entre un camión que maniobra y otro vehículo es seguro si lo hago rápido.","vf":false,"w":"Falso. Puedes quedar atrapado. Rodea por la ruta peatonal."}]},{"s":"transito_ciego","v":[{"q":"Si yo veo el camión, el conductor también me ve a mí.","vf":false,"w":"Falso. Hay puntos ciegos. Si no ves los ojos del conductor, él no te ve."},{"q":"¿Dónde están los puntos ciegos de un camión?","o":["Atrás, a los costados y delante de la cabina","Solo detrás del camión, en la zona de carga","Solo en el lado contrario al conductor","En ninguna parte, si tiene buenos espejos"],"w":"Los espejos no cubren todo. Alrededor del camión hay varias zonas que el conductor no ve."},{"q":"¿Cómo sabes si el conductor de un camión puede verte?","o":["Si veo sus ojos en el espejo o el parabrisas","Si yo veo el camión completo desde donde estoy","Si el camión tiene las luces encendidas","Si estoy parado a un costado de la cabina"],"w":"Si no ves sus ojos, él no te ve a ti."}]},{"s":"transito_contacto","v":[{"q":"Antes de cruzar frente a una grúa horquilla detenida, ¿qué haces?","o":["Busco los ojos del operador y espero su seña","Cruzo rápido mientras está detenida","Toco la grúa para que sepa que estoy ahí","Cruzo si tiene la baliza encendida"],"w":"Solo cruzas cuando el operador te vio y te dio la pasada."},{"q":"La grúa se detuvo frente a ti, pero el operador mira hacia la carga. ¿Qué haces?","o":["Espero hasta que me vea y me dé la pasada","Cruzo, porque ya se detuvo","Cruzo por detrás de la grúa","Le grito y cruzo al mismo tiempo"],"w":"Un vehículo detenido puede partir. Sin contacto visual, no se cruza."},{"q":"Eres operador y un peatón quiere cruzar delante de ti. ¿Qué haces?","o":["Me detengo y le doy la pasada con una seña","Toco la bocina para que cruce más rápido","Sigo despacio, porque él me va a esquivar","Paso yo primero y luego cruza él"],"w":"Los conductores se detienen ante los peatones y les dan la pasada."}]},{"s":"transito_chaleco","v":[{"q":"¿Para qué sirve el chaleco reflectante en el patio?","o":["Para que conductores y operadores te vean a tiempo","Para que los clientes sepan a quién preguntar","Para protegerte del frío y la lluvia","Para distinguir a qué área perteneces"],"w":"Te hace visible; con lluvia, neblina o poca luz la diferencia es enorme."},{"q":"¿Cómo debe usarse el chaleco reflectante?","o":["Cerrado, limpio y en buen estado","Abierto, para trabajar más cómodo","Sobre el hombro, para tenerlo a mano","Solo de noche o con lluvia"],"w":"Un chaleco abierto o sucio se ve mucho menos."},{"q":"Si tu puesto exige chaleco reflectante, la empresa debe entregártelo sin costo.","vf":true,"w":"Verdadero. Es tu EPP: la empresa lo entrega gratis y tú debes usarlo."}]},{"s":"transito_clientes","v":[{"q":"Un cliente se baja de su camioneta y camina hacia donde la grúa está cargando. ¿Qué haces?","o":["Lo guío con amabilidad a la zona de espera","Lo dejo pasar, porque es cliente","Le pido que ayude a cargar para avanzar","Le pido que espere junto a la grúa"],"w":"Los clientes no conocen los riesgos del patio: guiarlos es cuidarlos."},{"q":"Se está cargando con la grúa la camioneta de un cliente. ¿Dónde debe estar el cliente?","o":["Fuera de la zona de carga, con el motor apagado","Al lado de su camioneta, mirando la carga","Arriba de la plataforma, ordenando","Dentro de la camioneta, con el motor en marcha"],"w":"Mientras opera la grúa, el cliente espera lejos y con su vehículo apagado."},{"q":"Un cliente entra al patio manejando rápido hacia la zona de carga. ¿Qué haces?","o":["Me pongo a salvo y aviso a mi jefatura","Me paro delante para que frene","Lo dejo, el cliente decide cómo maneja","Corro detrás de él para hablarle"],"w":"Primero tu seguridad. Luego la jefatura toma las medidas."}]},{"s":"transito_celular","v":[{"q":"Puedo cruzar el patio mirando el celular si voy por la ruta peatonal.","vf":false,"w":"Falso. Mirando el celular no ves ni escuchas los vehículos. Detente en un lugar seguro para usarlo."},{"q":"Necesitas contestar un mensaje urgente mientras caminas por el patio. ¿Qué haces?","o":["Me detengo en un lugar seguro, fuera de la circulación","Lo contesto caminando por la ruta peatonal","Lo contesto con audífonos para tener las manos libres","Lo contesto mientras espero detrás de un camión"],"w":"El celular se usa detenido y fuera de donde circulan vehículos."},{"q":"¿Por qué no conviene usar audífonos en el patio?","o":["Porque no escucharías una alarma de retroceso","Porque se pueden caer y romper","Porque distraen al conductor","Porque gastan la batería del celular"],"w":"En el patio tus oídos te avisan del peligro: la alarma, la bocina o un grito."}]},{"s":"transito_vel","v":[{"q":"Conduces el camión y debes retroceder, pero no ves bien atrás. ¿Qué haces?","o":["Me bajo a mirar o pido un señalero","Retrocedo tocando la bocina","Retrocedo despacio confiando en los espejos","Retrocedo: la alarma basta para avisar"],"w":"Si no ves, no retrocedes: primero mira o pide un señalero."},{"q":"¿Cuándo debe un conductor pedir un señalero para retroceder?","o":["Cuando no ve bien lo que hay detrás","Solo cuando el camión va cargado","Solo de noche","Nunca, si tiene cámara de retroceso"],"w":"La alarma y la cámara ayudan, pero no reemplazan mirar o tener un señalero."},{"q":"Tu camión tiene alarma de retroceso, pero hay clientes cerca y no ves bien atrás. ¿Qué haces?","o":["Me detengo y pido un señalero","Retrocedo: la alarma ya los avisa","Retrocedo rápido para terminar luego","Retrocedo mirando solo por un espejo"],"w":"Si no ves, no retrocedes. La alarma no garantiza que se aparten."}]},{"s":"horquilla_autorizado","v":[{"q":"¿Quién puede operar la grúa horquilla?","o":["Solo quien está capacitado y autorizado por la empresa","Cualquiera con licencia de conducir de auto","Cualquier bodeguero, si es un tramo corto","El trabajador con más años en el patio"],"w":"Operar sin capacitación ni autorización pone en riesgo a todo el patio."},{"q":"El operador salió a colación y hay que mover un pallet urgente. Sabes manejar, pero no estás autorizado. ¿Qué haces?","o":["Espero al operador autorizado o aviso a la jefatura","Lo muevo yo, porque es un tramo corto","Lo muevo despacio con ayuda de un compañero","Le pido a un cliente que me guíe"],"w":"Saber manejar no basta: se requiere capacitación y autorización."},{"q":"¿Qué necesita una persona para operar la grúa horquilla?","o":["Capacitación y autorización de la empresa","Solo licencia de conducir de auto","Solo experiencia de años en bodega","Solo el permiso de un compañero"],"w":"La grúa la opera únicamente quien fue capacitado y autorizado."}]},{"s":"transito_auto","v":[{"q":"Llevas una caja y la bodega está justo detrás de un camión estacionado. ¿Qué haces?","o":["Rodeo por la ruta peatonal, aunque tarde más","Paso por detrás, es solo un segundo","Paso por detrás mirando hacia la cabina","Paso pegado a la carrocería"],"w":"Cortar camino es la acción insegura típica. Rodear cuesta segundos."},{"q":"Ves que un paso peatonal quedó bloqueado con pallets. ¿Qué haces?","o":["Aviso a la jefatura para que lo despejen","Paso por la zona de grúas mientras tanto","Salto los pallets con cuidado","Lo dejo, alguien más va a avisar"],"w":"Avisar un paso bloqueado también es autocuidado y cuida a los demás."},{"q":"Un conductor del patio va siempre muy rápido. ¿Qué haces?","o":["Lo aviso a mi jefatura","Nada, conducir no es mi tarea","Le grito cuando pase","Me cruzo delante para que frene"],"w":"Reportar una conducta peligrosa evita un atropello."}]}]},{"id":"cargas","sec":"todos","title":"Manejo manual de cargas","thumb":"c5ca_tecnica","mins":5,"learn":[{"s":"c5ca_intro","t":"¿Qué es el manejo manual de carga?","x":"Es cualquier tarea en que usas tu fuerza para <b>levantar, bajar, empujar, arrastrar o trasladar</b> algo. En {EMP}: sacos de cemento de 25 kg, fierro, planchas de OSB y yeso-cartón, cajas de cerámica y tinetas de pintura. <b>La zona que más se lesiona es la espalda baja (zona lumbar)</b>, seguida de hombros y manos. Un lumbago puede venir de un solo mal levantamiento o de muchos repetidos."},{"s":"c5ca_limites","t":"Los límites de la ley","x":"La Ley 20.949 fijó en el Código del Trabajo estos máximos para la carga manual:<ul><li><b>Hombre adulto:</b> 25 kg (art. 211-H).</li><li><b>Mujeres y menores de 18 años:</b> 20 kg (art. 211-J).</li><li><b>Trabajadoras embarazadas:</b> prohibido cargar y descargar manualmente, sin importar el peso (art. 211-I).</li></ul>Sobre el límite se usa ayuda mecánica. Y aunque pese menos, levantarla mal igual puede lesionarte.","k":"Sobre el límite legal: ayuda mecánica, nunca a pulso."},{"s":"c5ca_piensa","t":"Antes de levantar, piensa 5 segundos","x":"<ul><li>¿Cuánto pesa? Mira la etiqueta: un saco de cemento dice 25 kg.</li><li>¿Tiene buen agarre o es largo e incómodo, como el fierro?</li><li>¿Tiene cantos filosos? Ponte guantes.</li><li>¿El camino está libre y el piso seco?</li><li>¿Dónde lo voy a dejar?</li></ul>Si algo no calza, pide ayuda o usa transpaleta o carro."},{"s":"c5ca_tecnica","t":"Levanta con las piernas, no con la espalda","x":"<ul><li>Pies separados, a los lados de la carga.</li><li>Flecta las rodillas y mantén la espalda recta.</li><li>Agarra firme con toda la mano y pega la carga al cuerpo.</li><li>Sube con la fuerza de las piernas, de forma suave y sin tirones.</li></ul>Mientras más lejos del cuerpo va la carga, más esfuerzo hace tu espalda. Para dejarla, haz lo mismo al revés.","k":"Rodillas flectadas, espalda recta y la carga pegada al cuerpo."},{"s":"c5ca_giro","t":"No gires la cintura","x":"Pasa mucho al cargar la camioneta de un cliente: se gira el tronco con los pies quietos. <b>Torcer la cintura con peso</b> es la receta para una lesión lumbar. <b>Gira moviendo los pies</b>, con la carga siempre frente a ti. Tampoco levantes carga pesada por sobre los hombros: si hay que dejarla en alto, usa una plataforma o pide ayuda."},{"s":"c5ca_ayuda","t":"Ayuda mecánica: tu mejor compañera","x":"Un pallet de cemento no se mueve a mano. Para eso están la <b>transpaleta y el carro plataforma</b>, y la grúa horquilla, que solo opera quien está capacitado y autorizado. Usa el carro también para varias cajas de cerámica o tinetas. <b>Empujar es mejor que tirar</b>: ves el camino y usas el peso de tu cuerpo. Si la transpaleta o el carro están dañados, no los uses y avisa."},{"s":"c5ca_equipo","t":"Fierro y planchas: entre dos","x":"Una barra de fierro larga o una plancha de yeso-cartón no pesan tanto, pero son incómodas y se balancean. Llévenla entre dos, a la misma altura. <b>Una sola persona dirige y avisa</b> con voces claras: ¡arriba!, ¡vamos!, ¡abajo!, y ambos levantan, caminan y bajan al mismo tiempo. Antes de partir, revisen que el camino esté libre y usen guantes por los cantos."},{"s":"c5ca_camion","t":"Cargar camionetas y camiones","x":"<ul><li>Pide que el vehículo se acerque lo más posible.</li><li>Apoya la carga en la orilla de la plataforma y empújala; no te subas con un saco al hombro.</li><li><b>No lances</b> sacos ni planchas: lesionas tu espalda y puedes golpear a quien recibe.</li><li>Si es mucha carga, túrnense o usen ayuda mecánica.</li></ul>"},{"s":"c5ca_zona","t":"Lo pesado, a la altura correcta","x":"La zona más segura para manipular es <b>entre las rodillas y los hombros</b>. Guarda lo pesado, como sacos de cemento o tinetas, en los niveles bajos o medios, <b>nunca arriba</b>, y deja lo liviano en lo alto. Así levantas con menos esfuerzo y nada pesado cae desde la altura. Para alcanzar algo alto usa una escala: nunca te subas al rack ni a la góndola."},{"s":"c5ca_auto","t":"Autocuidado: tú decides","x":"La mayoría de los accidentes se relacionan con una acción insegura. En cargas, la típica es <b>es rápido, lo levanto solo</b>: apurarse, doblar la espalda o cargar sobre el límite. La decisión segura: <b>pedir ayuda o usar la transpaleta</b>. Avisa las condiciones inseguras: transpaleta dañada, piso irregular o pasillo bloqueado. Y si sientes dolor en la espalda, avisa de inmediato a tu jefatura."}],"quiz":[{"s":"c5ca_intro","v":[{"q":"Según la ley, ¿cuál es el peso máximo que un trabajador hombre adulto puede manipular manualmente?","o":["25 kg","20 kg","30 kg","50 kg"],"w":"Código del Trabajo, art. 211-H: 25 kg. Para mujeres y menores de 18 años, 20 kg."},{"q":"Un trabajador adulto debe mover a mano cajas de 30 kg. ¿Qué corresponde?","o":["Usar ayuda mecánica: supera los 25 kg","Moverlas a mano, con buena técnica","Moverlas a mano, pero de a una","Moverlas a mano, si tiene faja"],"w":"Sobre 25 kg no se carga a pulso: se usa transpaleta, carro u otra ayuda mecánica."},{"q":"¿Qué ley fijó los límites de carga manual que hoy rigen en el Código del Trabajo?","o":["Ley 20.949","Ley 20.580","Ley 16.744","Ley 18.290"],"w":"La Ley 20.949 estableció los máximos de 25 kg y 20 kg."}]},{"s":"c5ca_limites","v":[{"q":"¿Cuál es el límite de carga manual para mujeres y menores de 18 años?","o":["20 kg","25 kg","15 kg","30 kg"],"w":"Art. 211-J del Código del Trabajo: 20 kg."},{"q":"Un trabajador de 17 años debe mover cajas de cerámica de 23 kg. ¿Puede hacerlo a mano?","o":["No: el máximo para menores de 18 es 20 kg","Sí: el límite es 25 kg para todos los hombres","Sí, si las lleva de a una","Sí, si usa buena técnica"],"w":"Para menores de 18 años el límite es 20 kg, sean hombres o mujeres."},{"q":"Una trabajadora debe trasladar tinetas de pintura de 22 kg. ¿Qué corresponde?","o":["Usar ayuda mecánica: supera su límite de 20 kg","Cargarlas a mano, porque son menos de 25 kg","Cargarlas a mano, pero más despacio","Cargarlas de a dos para terminar antes"],"w":"Para las mujeres el máximo legal de carga manual es 20 kg."}]},{"s":"c5ca_limites","v":[{"q":"Una trabajadora embarazada puede cargar cajas si pesan menos de 20 kg.","vf":false,"w":"Falso. Las trabajadoras embarazadas tienen prohibido cargar y descargar manualmente, sin importar el peso (art. 211-I)."},{"q":"¿Qué dice la ley sobre las trabajadoras embarazadas y la carga manual?","o":["Tienen prohibida la carga manual","Pueden cargar hasta 20 kg","Pueden cargar hasta 10 kg","Pueden cargar si usan faja lumbar"],"w":"El art. 211-I del Código del Trabajo prohíbe la carga manual durante el embarazo."},{"q":"Una cajera embarazada debe reponer bolsas de 8 kg. ¿Qué corresponde?","o":["No debe cargarlas, sin importar el peso","Puede, porque pesan menos de 20 kg","Puede, si usa buena técnica","Puede, si un compañero se las pasa"],"w":"La prohibición en el embarazo es total: no depende del peso."}]},{"s":"c5ca_tecnica","v":[{"q":"¿Cuál es la forma correcta de levantar un saco de cemento desde el suelo?","o":["Rodillas flectadas, espalda recta y saco pegado al cuerpo","Piernas rectas y espalda doblada, para ir más rápido","Rodillas flectadas, pero con el saco lejos del cuerpo","Espalda recta y levantarlo de un tirón"],"w":"Las piernas hacen la fuerza, la espalda va recta y la carga pegada al cuerpo."},{"q":"¿Por qué conviene llevar la carga pegada al cuerpo?","o":["Lejos del cuerpo, la espalda hace más esfuerzo","Porque así se ve mejor el camino por delante","Porque así se ensucia menos la ropa de trabajo","Porque así se puede girar mejor la cintura"],"w":"La carga alejada multiplica el esfuerzo sobre la zona lumbar."},{"q":"Al levantar una carga, la fuerza debe salir de las piernas y no de la espalda.","vf":true,"w":"Verdadero. Rodillas flectadas y espalda recta: las piernas trabajan."}]},{"s":"c5ca_giro","v":[{"q":"Al dejar un saco en la camioneta, lo correcto es girar la cintura sin mover los pies.","vf":false,"w":"Falso. Se gira moviendo los pies; torcer la cintura con carga daña la espalda."},{"q":"Cargas un saco en la camioneta de un cliente que está a tu lado. ¿Cómo giras?","o":["Muevo los pies, con el saco siempre frente a mí","Giro la cintura con los pies fijos","Giro rápido para que pese menos tiempo","Giro el tronco y estiro los brazos"],"w":"Primero los pies, después el cuerpo."},{"q":"¿Qué movimiento con carga es la receta para una lesión lumbar?","o":["Torcer la cintura con los pies quietos","Girar el cuerpo moviendo los pies","Empujar el carro plataforma cargado","Flectar las rodillas al bajar la carga"],"w":"La torsión con peso es uno de los movimientos más dañinos para la espalda."}]},{"s":"c5ca_ayuda","v":[{"q":"Hay que mover un pallet completo de sacos de cemento. ¿Qué haces?","o":["Uso la transpaleta u otra ayuda mecánica","Lo descargo a mano, saco por saco, rápido","Lo arrastramos entre dos","Lo movemos entre cuatro, uno en cada esquina"],"w":"Para eso está la ayuda mecánica: es más rápido y no arriesgas tu espalda."},{"q":"Para mover varias cajas de cerámica por la bodega, ¿qué es mejor?","o":["Usar el carro plataforma y empujarlo","Llevarlas a mano de dos en dos","Usar el carro tirándolo de espaldas","Arrastrarlas por el piso"],"w":"El carro evita el sobreesfuerzo, y empujarlo es mejor que tirarlo."},{"q":"¿Por qué es mejor empujar un carro que tirarlo?","o":["Ves el camino y usas el peso de tu cuerpo","Porque así el carro frena solo en las bajadas","Porque así se puede llevar más peso del límite","Porque tirar un carro está prohibido por ley"],"w":"Empujando ves hacia dónde vas y haces menos fuerza con la espalda."}]},{"s":"c5ca_equipo","v":[{"q":"Para trasladar una barra de fierro larga entre dos, lo más importante es:","o":["Que uno dirija y ambos se muevan al mismo tiempo","Que cada uno camine a su propio ritmo","Que el más fuerte vaya adelante sin avisar","Que ambos den instrucciones a la vez"],"w":"Una sola voz dirige y ambos levantan, caminan y bajan juntos."},{"q":"Al bajar una plancha de yeso-cartón entre dos, ¿cómo se coordinan?","o":["Uno dirige con voces claras y bajan juntos","Cada uno la suelta cuando se cansa","Bajan sin hablar, para concentrarse","El de adelante la suelta primero"],"w":"Si uno suelta antes, todo el peso cae sobre el otro."},{"q":"Para trasladar una carga larga entre dos personas, debe dirigir una sola de ellas.","vf":true,"w":"Verdadero. Dos voces confunden; una sola dirige la maniobra."}]},{"s":"c5ca_camion","v":[{"q":"Un cliente apurado te pide que le lances los sacos a la camioneta. ¿Qué haces?","o":["No los lanzo: los apoyo en la plataforma y los empujo","Los lanzo, pero de a uno","Le pido que los reciba en el aire","Los lanzo desde cerca para que no se rompan"],"w":"Lanzar la carga lesiona la espalda y puede golpear a otra persona."},{"q":"Vas a cargar sacos en una camioneta. ¿Qué haces primero?","o":["Pido que acerque el vehículo lo más posible","Me subo a la plataforma con el saco al hombro","Lanzo los sacos desde donde estoy","Cargo dos sacos a la vez para terminar antes"],"w":"Mientras más cerca está el vehículo, menos distancia cargas."},{"q":"¿Por qué no se lanzan sacos ni planchas al vehículo?","o":["Lesiona tu espalda y puede golpear a otro","Porque se rompe el embalaje del producto","Porque el cliente se puede molestar","Porque demora más que cargarlos a mano"],"w":"El lanzamiento exige un esfuerzo brusco y la carga puede golpear a alguien."}]},{"s":"c5ca_zona","v":[{"q":"¿Dónde conviene guardar lo más pesado?","o":["En niveles bajos o medios","En el nivel más alto del rack","En el piso del pasillo, a mano","Donde haya espacio disponible"],"w":"Así se manipula con menos esfuerzo y no cae desde la altura."},{"q":"¿Cuál es la zona más segura para manipular una carga?","o":["Entre las rodillas y los hombros","Sobre la cabeza","Desde el suelo hasta los tobillos","A la altura de los ojos o más arriba"],"w":"En esa zona la espalda y los hombros trabajan con menos esfuerzo."},{"q":"Al reponer, ¿dónde ubicas los sacos de cemento?","o":["En un nivel bajo o medio","En el nivel más alto","Encima de las cajas livianas","En el pasillo, junto al rack"],"w":"Lo pesado va abajo o al medio; lo liviano, arriba."}]},{"s":"c5ca_auto","v":[{"q":"Vas atrasado y el saco es pesado. ¿Cuál es la decisión segura?","o":["Pedir ayuda o usar la transpaleta","Levantarlo solo, de un tirón","Arrastrarlo con la espalda doblada","Levantarlo solo, pero muy rápido"],"w":"Apurarse es la acción insegura típica. Pedir ayuda toma segundos; una lesión lumbar, meses."},{"q":"Hay que mover diez sacos y vas atrasado. ¿Qué es lo más seguro?","o":["Usar la transpaleta o pedir ayuda","Llevar dos sacos a la vez","Arrastrarlos para ahorrar fuerza","Lanzarlos sobre el pallet"],"w":"La ayuda mecánica es más rápida y no daña tu espalda."},{"q":"La transpaleta tiene una rueda trabada. ¿Qué haces?","o":["La dejo fuera de uso y aviso","La uso igual, empujando más fuerte","Muevo toda la carga a mano","La arreglo yo con lo que tenga"],"w":"Una herramienta dañada es una condición insegura: se retira y se reporta."}]}]},{"id":"epp","sec":"todos","title":"Uso y cuidado del EPP","thumb":"c5ep_cargo","mins":5,"learn":[{"s":"c5ep_que","t":"¿Qué es el EPP?","x":"Son los <b>Elementos de Protección Personal</b>: zapatos de seguridad, guantes, chaleco reflectante, casco, lentes y otros según la tarea, como protector auditivo o mascarilla. Son la <b>última barrera</b> de la jerarquía de controles: primero se elimina o controla el peligro en el lugar o en la forma de trabajar, y el EPP protege de lo que queda. No elimina el peligro: reduce el daño si algo pasa."},{"s":"c5ep_ley","t":"Gratis y obligatorio","x":"El DS 594 (art. 53) obliga al empleador a <b>proporcionar, libres de costo, los EPP adecuados al riesgo</b> y a enseñar su correcto uso. La Ley 16.744 (art. 68) también obliga a entregarlos sin costo: no se descuentan del sueldo. Tú <b>debes usarlos todo el tiempo que estés expuesto al riesgo</b>, aunque la tarea dure segundos y aunque nadie te mire, como lo exige el Reglamento Interno.","k":"La empresa los entrega gratis; tú los usas todo el tiempo que estés expuesto."},{"s":"c5ep_cargo","t":"El EPP según tu cargo","x":"Algunos ejemplos:<ul><li><b>Bodega, patio y carga:</b> zapatos de seguridad, guantes y chaleco reflectante; casco en bodega y zonas señalizadas.</li><li><b>Conductores y peonetas:</b> zapatos de seguridad, chaleco al bajar del camión y guantes al amarrar o descargar.</li><li><b>Ventas:</b> zapatos de seguridad y guantes al manipular productos pesados o con filo, si tu puesto lo indica.</li></ul>Tu IRL y tu jefatura definen el EPP exacto de tu puesto."},{"s":"c5ep_pies","t":"Zapatos de seguridad","x":"La <b>puntera</b> protege tus dedos si cae un saco, un fierro o un pallet, y la <b>suela antideslizante</b> ayuda a evitar resbalones en el patio mojado. Úsalos bien abrochados y no los cambies por zapatillas, ni siquiera un rato. Si la puntera queda a la vista, la suela está gastada o se despegó, <b>pide recambio</b>."},{"s":"c5ep_manos","t":"Guantes para cantos y astillas","x":"El zinc, el fierro, los perfiles y las planchas tienen <b>cantos filosos</b>, y la madera suelta astillas. Usa <b>guantes de trabajo</b> para manipularlos. El guante depende de la tarea: no es lo mismo cargar fierro que manipular solventes, que requieren guantes para químicos según su etiqueta. Un guante de látex delgado o de lana no protege de cortes. Revisa que no tengan hoyos ni cortes."},{"s":"c5ep_chaleco","t":"Chaleco reflectante: que te vean","x":"En el patio se mueven camiones, camionetas y grúas horquilla. Sus conductores tienen <b>puntos ciegos</b> y poco espacio para frenar. El chaleco reflectante hace que te vean antes, <b>de día y de noche</b>, y con lluvia o neblina. Úsalo <b>cerrado y limpio</b>: un chaleco sucio, roto o abierto se ve mucho menos."},{"s":"c5ep_casco","t":"Casco donde se exija","x":"Úsalo en las zonas o tareas <b>señalizadas</b>: donde hay carga en altura, maniobras de izaje o grúas trabajando. Protege de golpes y de objetos que caen. Ajústalo a tu cabeza y no lo uses sobre un gorro grueso. No lo pintes, no lo perfores y no le pegues adhesivos que no estén autorizados. Si tiene trizaduras o recibió un golpe fuerte, aunque no se vea dañado, pide que lo cambien."},{"s":"c5ep_lentes","t":"Lentes al cortar","x":"Cortar fierro, perfiles o PVC con esmeril o sierra, o dimensionar madera, lanza <b>partículas y chispas</b> a los ojos. Usa <b>lentes de seguridad</b> puestos en los ojos durante todo el corte, aunque sea uno rapidito: sobre el casco o colgados del cuello no protegen. También úsalos al manipular solventes, según su etiqueta y su hoja de datos de seguridad (HDS)."},{"s":"c5ep_cuida","t":"Revisa, cuida y pide recambio","x":"<ul><li><b>Revísalo antes de usarlo:</b> sin trizaduras, hoyos ni cortes.</li><li>Guárdalo limpio y seco. Es personal: no lo prestes.</li><li>No lo modifiques ni lo arregles con cinta.</li><li>Si se daña o se pierde, <b>pide recambio</b>: la empresa debe reponerlo sin costo.</li><li>Usa EPP <b>certificado</b> (DS 18 de 1982).</li></ul>","k":"EPP dañado no protege: pide recambio de inmediato."},{"s":"c5ep_auto","t":"Autocuidado con el EPP","x":"La mayoría de los accidentes se relacionan con una <b>acción insegura</b>: apurarse, saltarse un paso, no usar el EPP. La típica aquí: salir al patio un ratito <b>sin chaleco</b> a ayudar a un cliente, o cargar fierro sin guantes. Decide seguro: póntelo antes de salir. Si te incomoda, pide otra talla y, mientras llega, usa el que tienes. Y avisa a tu jefatura si falta EPP."}],"quiz":[{"s":"c5ep_ley","v":[{"q":"¿Quién debe pagar el EPP que usas?","o":["La empresa, sin costo para el trabajador","Yo, con descuento por planilla","Lo pagamos a medias con la empresa","La Mutual, después de un accidente"],"w":"DS 594, art. 53, y Ley 16.744, art. 68: el empleador lo proporciona sin costo."},{"q":"Te entregan zapatos de seguridad y te dicen que te descontarán una parte del sueldo. ¿Es correcto?","o":["No: la empresa debe entregarlos sin costo","Sí, si es una parte pequeña","Sí, porque los puedes usar fuera del trabajo","Sí, si firmaste el registro de entrega"],"w":"El EPP adecuado al riesgo es siempre gratuito para el trabajador."},{"q":"El empleador debe entregar el EPP sin costo y enseñar a usarlo correctamente.","vf":true,"w":"Verdadero. Así lo exige el DS 594, art. 53."}]},{"s":"c5ep_cargo","v":[{"q":"Trabajas en patio y carga. ¿Qué EPP básico usas, según los ejemplos de la charla?","o":["Zapatos de seguridad, guantes y chaleco","Solo zapatos de seguridad y casco","Solo chaleco reflectante y lentes","Solo guantes, porque uso las manos"],"w":"En patio y carga hay caída de objetos, cantos filosos y vehículos: se necesitan los tres."},{"q":"¿Quién define el EPP exacto de tu puesto?","o":["Tu IRL y tu jefatura","Cada trabajador, según su comodidad","El compañero con más antigüedad","El cliente que atiendes"],"w":"El EPP se define según los riesgos del puesto, informados en tu IRL."},{"q":"Eres peoneta y vas a amarrar la carga del camión. ¿Qué EPP agregas a tus zapatos de seguridad?","o":["Guantes y chaleco reflectante","Solo lentes de seguridad","Nada más, porque vas en el camión","Solo el casco"],"w":"Al amarrar hay cantos y vehículos cerca: guantes y chaleco."}]},{"s":"c5ep_que","v":[{"q":"El EPP elimina el peligro de la tarea.","vf":false,"w":"Falso. Es la última barrera: reduce el daño si algo pasa, pero el peligro sigue."},{"q":"¿Qué hace realmente el EPP?","o":["Reduce el daño, pero no elimina el peligro","Elimina el peligro de la tarea","Reemplaza a los procedimientos de trabajo","Permite saltarse los otros controles"],"w":"Por eso se usa junto con los demás controles, nunca en su reemplazo."},{"q":"¿Por qué el EPP es la última barrera?","o":["Primero se controla el peligro en su origen","Porque es lo último que se compra","Porque se usa solo al final del turno","Porque solo lo exige el Comité Paritario"],"w":"Los controles que actúan sobre el peligro van primero; el EPP protege de lo que queda."}]},{"s":"c5ep_manos","v":[{"q":"Vas a cargar fierro y planchas de zinc. ¿Qué protege tus manos?","o":["Guantes de trabajo en buen estado","Guantes de látex delgados","Guantes de lana, para el frío","Ninguno: basta con tener cuidado"],"w":"Los cantos del fierro y el zinc cortan. Se usan guantes de trabajo sin hoyos ni cortes."},{"q":"Tus guantes de trabajo tienen un hoyo en la palma y vas a cargar zinc. ¿Qué haces?","o":["Pido recambio antes de cargar","Los uso igual, el hoyo es chico","Cargo sin guantes, con cuidado","Uso el guante roto solo en una mano"],"w":"Un guante roto deja la mano expuesta justo donde toca el filo."},{"q":"¿Por qué no sirve cualquier guante para cualquier tarea?","o":["Cada peligro, como cortes o químicos, pide uno distinto","Porque los guantes más caros duran más tiempo","Porque cada trabajador elige el que le acomoda","Porque el color del guante indica la tarea"],"w":"El guante se elige según el peligro: cortes, químicos u otro."}]},{"s":"c5ep_chaleco","v":[{"q":"¿Para qué sirve el chaleco reflectante en el patio?","o":["Para que los conductores te vean a tiempo","Para protegerte del frío y del viento","Para que los clientes te identifiquen","Para completar el uniforme de trabajo"],"w":"Los vehículos tienen puntos ciegos: el chaleco hace que te vean antes."},{"q":"Tu chaleco está abierto y sucio de barro. ¿Qué problema tiene?","o":["Se ve menos y no cumple bien su función","Ninguno, mientras lo lleves puesto","Solo se ve feo, pero protege igual","Ninguno, si es de día"],"w":"Cerrado y limpio refleja mejor la luz y se ve desde más lejos."},{"q":"El chaleco reflectante solo es necesario de noche.","vf":false,"w":"Falso. Se usa de día y de noche: también ayuda con lluvia, neblina y en zonas de sombra."}]},{"s":"c5ep_lentes","v":[{"q":"Para un corte rápido de fierro con el esmeril no hace falta usar lentes.","vf":false,"w":"Falso. Una partícula o chispa llega al ojo en menos de un segundo."},{"q":"Vas a cortar un perfil con esmeril angular. ¿Cuándo usas los lentes de seguridad?","o":["Durante todo el corte, aunque sea uno rápido","Solo si el corte dura más de un minuto","Solo si saltan muchas chispas","Solo si no tienes casco"],"w":"Las partículas saltan desde el primer segundo del corte."},{"q":"¿Dónde deben ir los lentes de seguridad mientras cortas?","o":["Puestos en los ojos","Sobre el casco, listos para bajarlos","Colgados del cuello","En el bolsillo del chaleco"],"w":"Solo protegen si están puestos en los ojos."}]},{"s":"c5ep_pies","v":[{"q":"La puntera del zapato de seguridad te protege de:","o":["Objetos pesados que caen sobre los dedos","Cortes en las manos al cargar zinc","Caídas desde la plataforma del camión","El frío y la humedad del patio"],"w":"Un saco, un fierro o un pallet sobre el pie pueden fracturar los dedos."},{"q":"¿Qué parte del zapato de seguridad ayuda a evitar resbalones en el patio mojado?","o":["La suela antideslizante","La puntera de acero","Los cordones bien atados","La plantilla acolchada"],"w":"La suela antideslizante da agarre en superficies mojadas."},{"q":"La puntera de tu zapato quedó a la vista y la suela está gastada. ¿Qué haces?","o":["Pido recambio","Los sigo usando hasta que se rompan","Les pego una suela nueva yo mismo","Uso zapatillas mientras tanto"],"w":"Un zapato dañado ya no protege bien: se pide recambio sin costo."}]},{"s":"c5ep_cuida","v":[{"q":"Tu casco tiene una trizadura. ¿Qué haces?","o":["Aviso y pido uno nuevo","Lo sigo usando con cuidado","Le pongo cinta adhesiva","Lo uso solo en tareas cortas"],"w":"Un casco trizado ya no protege: se reemplaza sin costo."},{"q":"Tu casco recibió un golpe fuerte, aunque no se ve dañado. ¿Qué haces?","o":["Aviso y pido que lo cambien","Lo sigo usando, porque no se ve trizado","Lo reviso yo y decido","Lo marco con pintura y lo sigo usando"],"w":"Un golpe fuerte puede debilitar el casco aunque no se note."},{"q":"Si tu EPP se daña o se pierde, la empresa debe reponerlo sin costo.","vf":true,"w":"Verdadero. El recambio también es gratuito para el trabajador."}]},{"s":"epp_time","v":[{"q":"Según el DS 594, ¿cuándo debes usar tu EPP?","o":["Todo el tiempo que esté expuesto al riesgo","Solo cuando la jefatura está mirando","Solo en tareas de más de una hora","Solo cuando la tarea es nueva"],"w":"El trabajador debe usarlo mientras esté expuesto al riesgo."},{"q":"Vas a hacer un solo corte de madera que dura segundos. ¿Usas el EPP?","o":["Sí: basta un segundo para lesionarte","No, solo en cortes largos","Solo los lentes, el resto no","No, si tienes experiencia"],"w":"La exposición corta también puede lesionarte: el EPP va desde el primer segundo."},{"q":"¿Cuál es tu obligación con el EPP que te entregaron?","o":["Usarlo mientras estés expuesto al riesgo","Usarlo solo en las inspecciones","Guardarlo nuevo para cuando se dañe el otro","Usarlo solo si te lo piden por escrito"],"w":"La empresa lo entrega y tú lo usas mientras dure el riesgo."}]},{"s":"c5ep_auto","v":[{"q":"Sales un ratito al patio a ayudar a un cliente. ¿Qué haces con el chaleco?","o":["Me lo pongo antes de salir","Salgo sin él, es solo un momento","Lo llevo en la mano por si acaso","Salgo sin él si es de día"],"w":"El accidente no espera a que vuelvas por el chaleco. Póntelo antes de salir."},{"q":"Tu chaleco te queda grande e incómodo. ¿Qué haces?","o":["Pido otra talla y mientras uso el que tengo","Dejo de usarlo hasta que llegue otro","Lo corto para ajustarlo","Lo uso abierto para estar más cómodo"],"w":"La incomodidad se resuelve con otra talla, no dejando de usarlo."},{"q":"Un cliente te pide ayuda urgente en el patio y dejaste el chaleco en la sala. ¿Qué haces?","o":["Vuelvo por el chaleco y salgo con él puesto","Salgo sin él, porque el cliente está apurado","Salgo sin él, pero camino por el borde","Salgo sin él y vuelvo rápido"],"w":"El apuro es la trampa típica. Unos segundos por el chaleco pueden evitar un atropello."}]}]},{"id":"orden","sec":"todos","title":"Orden y aseo","thumb":"c5or_gondola","mins":5,"learn":[{"s":"c5or_trip","t":"El desorden también accidenta","x":"Las <b>caídas al mismo nivel</b> están entre los accidentes más comunes. Casi siempre hay algo en el piso: <b>zunchos, cartones, plásticos de embalaje, pallets vacíos, cables</b> o un producto caído. Un tropiezo con un saco en los brazos puede terminar en un esguince, una fractura o un golpe en la cabeza. Lo que sacas de un embalaje va al contenedor de inmediato."},{"s":"c5or_pasillo","t":"Pasillos despejados","x":"Los pasillos deben permitir el <b>movimiento seguro</b> de personas y materiales, libres de obstáculos (DS 594, art. 8). En la sala pasan clientes con carros; en bodega y patio, grúas y transpaletas. No dejes cajas, pallets ni carros un rato en el pasillo: obligas a otros a esquivar, a meterse en la ruta de la grúa o a tropezar. Respeta la demarcación peatonal."},{"s":"c5or_gondola","t":"Góndolas ordenadas y estables","x":"<ul><li><b>Lo pesado abajo</b> (cemento, cerámica, tinetas); lo liviano arriba. Así la góndola es más estable y nada pesado cae sobre alguien.</li><li>Nada sobresaliendo del borde.</li><li>No sobrecargues las repisas.</li><li>Al reponer, no dejes cajas en el pasillo.</li><li>Si una repisa está doblada o suelta, avisa y no la cargues.</li></ul>"},{"s":"c5or_rack","t":"Racks de bodega","x":"<ul><li>Respeta la <b>capacidad</b> del rack si está indicada.</li><li>Pallets en buen estado y bien apoyados sobre las vigas.</li><li>Carga pareja, sin nada sobresaliendo.</li><li>Nunca te subas al rack.</li><li>Si una grúa golpea un pilar o una viga, <b>avisa de inmediato aunque no se vea daño</b>. Una viga doblada no se carga ni se endereza a golpes: espera a que la revisen.</li></ul>","k":"Rack golpeado: avisa y no lo cargues hasta que lo revisen."},{"s":"c5or_patio","t":"Orden en el patio","x":"<ul><li><b>Fierro y perfiles</b> en sus soportes, sin puntas hacia el paso.</li><li><b>Planchas</b> apiladas parejas sobre separadores, nunca directo en el barro.</li><li><b>Zunchos y amarras</b> cortados, al contenedor de inmediato: se enredan en los pies.</li><li>El paso peatonal y la zona de carga, siempre libres: no se usan para dejar material ni un rato.</li></ul>"},{"s":"c5or_salOk","t":"Salidas, extintores y tableros libres","x":"Nunca dejes materiales delante de una <b>salida de emergencia, un extintor o un tablero eléctrico</b>, ni siquiera por un rato o aunque sea algo liviano. En una emergencia cada segundo cuenta: nadie debería tener que mover pallets para escapar, apagar un amago o cortar la energía. La señalética de estos elementos también debe quedar a la vista.","k":"Nunca bloquees una salida, un extintor ni un tablero eléctrico."},{"s":"c5or_derrame","t":"Derrames: avisa, señaliza y limpia","x":"Si cae pintura, aceite, solvente o agua al piso: <b>avisa, señaliza y limpia</b> de inmediato con material absorbente. Si es un solvente o químico, sigue su etiqueta y su hoja de datos de seguridad (HDS) y aleja cualquier fuente de calor o chispa. No lo tapes con un cartón ni lo dejes para después: el siguiente cliente o compañero puede resbalar."},{"s":"c5or_peligrosos","t":"Pinturas, solventes y gas: en su lugar","x":"<ul><li>Envases <b>cerrados y etiquetados</b>, en el lugar asignado.</li><li><b>Cilindros de gas de pie y asegurados</b> con cadena o soporte, lejos del calor y del sol directo: un cilindro que cae puede dañar su válvula y provocar una fuga.</li><li><b>No fumar</b> ni hacer fuego cerca.</li><li>Envase dañado o con fuga: sepáralo si es seguro y avisa.</li></ul>"},{"s":"c5or_5s","t":"Las 5S: cinco hábitos simples","x":"<ul><li><b>Separar:</b> saca lo que no sirve.</li><li><b>Ordenar:</b> un lugar para cada cosa y cada cosa en su lugar.</li><li><b>Limpiar:</b> al limpiar, revisa si algo está dañado.</li><li><b>Estandarizar:</b> marca lugares, pasillos y zonas.</li><li><b>Sostener:</b> hazlo todos los días, no solo cuando hay visita.</li></ul>Con estos hábitos encuentras todo rápido y nada queda tirado."},{"s":"c5or_auto","t":"Autocuidado: orden y aseo","x":"La mayoría de los accidentes se relacionan con una <b>acción insegura</b>. Aquí la típica es <b>lo ordeno después</b>: el zuncho en el piso, el cuchillo cartonero sobre la repisa, la caja en el pasillo. Mientras tanto, alguien puede tropezar o cortarse. Decide seguro: ordena al momento y <b>avisa</b> a tu jefatura las condiciones inseguras, como un piso roto, una luz quemada o una repisa suelta."}],"quiz":[{"s":"c5or_trip","v":[{"q":"¿Cuál es una causa frecuente de caídas al mismo nivel en la bodega?","o":["Zunchos, cartones y plásticos en el piso","Las grúas horquilla en movimiento","Los racks de mucha altura","Las escalas de tijera"],"w":"Lo que queda en el piso hace tropezar o resbalar."},{"q":"Abriste un pallet y quedaron zunchos y plástico en el piso. ¿Qué haces?","o":["Los boto al contenedor de inmediato","Los junto en un rincón del pasillo","Los dejo para el aseo de fin de turno","Los empujo bajo el rack"],"w":"Mientras queden en el piso, alguien puede enredarse y caer."},{"q":"Las caídas al mismo nivel están entre los accidentes más comunes.","vf":true,"w":"Verdadero. Por eso el orden del piso es tan importante."}]},{"s":"c5or_5s","v":[{"q":"En las 5S, ¿qué significa Ordenar?","o":["Un lugar para cada cosa y cada cosa en su lugar","Juntar todo en un solo lugar a mano","Sacar lo que no sirve","Limpiar y revisar si algo está dañado"],"w":"Así encuentras todo rápido y nada queda tirado en el piso."},{"q":"En las 5S, ¿qué significa Separar?","o":["Sacar lo que no sirve","Marcar lugares, pasillos y zonas","Hacerlo todos los días","Un lugar para cada cosa"],"w":"Separar es la primera S: retirar lo que sobra."},{"q":"¿Qué S consiste en mantener el orden todos los días, y no solo cuando hay visita?","o":["Sostener","Estandarizar","Limpiar","Ordenar"],"w":"Sostener convierte el orden en un hábito diario."}]},{"s":"c5or_salMal","v":[{"q":"Llegó mucha mercadería y un compañero quiere dejar pallets frente a la salida de emergencia por una hora. ¿Qué haces?","o":["Le digo que no: la salida debe quedar libre siempre","Acepto, si es solo por una hora","Acepto, si dejan un paso angosto","Acepto, si después avisamos a la jefatura"],"w":"Una emergencia puede ocurrir en cualquier minuto: las salidas nunca se bloquean."},{"q":"¿Qué elementos deben quedar siempre despejados?","o":["Salidas, extintores y tableros eléctricos","Solo las salidas de emergencia del local","Solo los extintores y las mangueras","Solo las puertas de la oficina y la caja"],"w":"Para escapar, apagar un amago o cortar la energía no debe haber nada que mover."},{"q":"Se puede dejar una caja delante de un extintor si es liviana y fácil de mover.","vf":false,"w":"Falso. Nada se deja delante de un extintor, aunque sea liviano."}]},{"s":"c5or_derrame","v":[{"q":"Se derramó un galón de pintura en el pasillo. ¿Qué haces?","o":["Aviso, señalizo y limpio de inmediato","Sigo atendiendo; después alguien limpia","Lo tapo con un cartón y sigo","Aviso al final del turno"],"w":"Avisar, señalizar y limpiar evita que un cliente o un compañero resbale."},{"q":"¿Con qué se limpia un derrame de pintura o aceite?","o":["Con material absorbente","Con agua a presión","Tapándolo con cartones","Esparciéndolo para que se seque"],"w":"El absorbente recoge el líquido sin extenderlo."},{"q":"Se derramó un solvente en la bodega. ¿Qué haces además de señalizar?","o":["Sigo su etiqueta y HDS y alejo el calor","Lo limpio con agua y detergente","Lo seco con un ventilador eléctrico","Lo dejo evaporar solo, con la puerta abierta"],"w":"Los solventes pueden ser inflamables: se siguen sus instrucciones y se aleja el calor y las chispas."}]},{"s":"c5or_gondola","v":[{"q":"¿Dónde van los sacos de cemento y las cajas de cerámica en la góndola?","o":["En los niveles bajos","Arriba, para que se vean","En el nivel del medio, siempre","En el pasillo, junto a la góndola"],"w":"Lo pesado abajo da estabilidad y evita que caiga sobre alguien."},{"q":"¿Qué va en las repisas altas de la góndola?","o":["Lo liviano","Lo pesado","Las tinetas de pintura","Los sacos de cemento"],"w":"Lo liviano arriba; lo pesado abajo."},{"q":"¿Por qué lo pesado va abajo en la góndola?","o":["Da estabilidad y no cae sobre nadie","Para que el cliente lo vea primero","Para ahorrar espacio en las repisas altas","Porque así lo pide el proveedor"],"w":"Una góndola con peso abajo es más estable y más segura."}]},{"s":"c5or_pasillo","v":[{"q":"Puedo dejar un pallet un rato en el pasillo si voy a volver pronto.","vf":false,"w":"Falso. El pasillo debe estar libre: obligas a otros a esquivar y a meterse en la ruta de la grúa."},{"q":"Un carro con mercadería queda en el pasillo mientras vas a buscar otra cosa. ¿Qué problema genera?","o":["Obliga a esquivar y causa tropiezos","Ninguno, si vuelves en cinco minutos","Ninguno, si el carro tiene freno puesto","Solo molesta a los clientes que pasan"],"w":"El pasillo es para circular, no para guardar."},{"q":"Según el DS 594, ¿cómo deben estar los pasillos de circulación?","o":["Libres de obstáculos, para circular seguro","Con mercadería solo a un costado","Despejados solo en horario de atención","Con pallets solo si están demarcados"],"w":"El DS 594, art. 8, exige pasillos que permitan circular de forma segura."}]},{"s":"racks_golpe","v":[{"q":"Ves una viga del rack golpeada. ¿Qué haces?","o":["Aviso de inmediato y no le pongo carga","La cargo igual, si se ve firme","La enderezo con un martillo","La cargo solo con productos livianos"],"w":"Una viga dañada puede ceder. Se avisa y no se usa hasta que la revisen."},{"q":"La grúa golpeó un pilar del rack y no se ve daño. ¿Qué haces?","o":["Aviso igual para que lo revisen","Nada, si no se ve ningún daño","Lo reviso yo mismo y sigo","Aviso solo si se llega a doblar"],"w":"Un golpe puede dañar el rack aunque no se note a simple vista."},{"q":"Un rack golpeado puede seguir cargándose si la viga no se ve muy doblada.","vf":false,"w":"Falso. Se avisa y no se carga hasta que lo revisen."}]},{"s":"c5or_peligrosos","v":[{"q":"¿Cómo deben estar los cilindros de gas?","o":["De pie, asegurados y lejos del calor","Acostados, para que no se caigan","Junto a la caja, para tenerlos a mano","Al sol, para que no se humedezcan"],"w":"De pie y sujetos no caen; lejos del calor no aumenta su presión."},{"q":"¿Cómo deben estar los envases de pintura y solventes en la bodega?","o":["Cerrados, etiquetados y en su lugar asignado","Abiertos, para que ventilen","Sin etiqueta, si todos saben qué son","Junto a los cilindros de gas"],"w":"Cerrados y etiquetados no derraman ni confunden a nadie."},{"q":"Un cilindro de gas que cae puede dañar su válvula y provocar una fuga.","vf":true,"w":"Verdadero. Por eso se guardan de pie y asegurados con cadena o soporte."}]},{"s":"c5or_patio","v":[{"q":"Cortas los zunchos de un paquete de fierro en el patio. ¿Qué haces con ellos?","o":["Los llevo al contenedor de inmediato","Los dejo junto al paquete hasta terminar","Los dejo en el piso hasta el fin del día","Los enrollo y los dejo a un costado del paso"],"w":"Los zunchos en el piso se enredan en los pies y hacen tropezar."},{"q":"¿Cómo deben quedar las barras de fierro y los perfiles en el patio?","o":["En sus soportes, sin puntas hacia el paso","Apoyados contra la pared, inclinados","En el piso, donde haya espacio","Sobre las planchas, para ahorrar lugar"],"w":"En sus soportes no ruedan ni golpean a quien pasa."},{"q":"¿Cómo se apilan las planchas en el patio?","o":["Parejas, sobre separadores","Inclinadas contra un rack","Cruzadas, para que no resbalen","Directo sobre el suelo"],"w":"Parejas y sobre separadores quedan estables y fáciles de tomar."}]},{"s":"c5or_auto","v":[{"q":"Terminas de reponer y quedan cajas en el pasillo. ¿Qué haces?","o":["Las ordeno ahora mismo","Las ordeno al final del turno","Espero que otro las saque","Las dejo a un costado del pasillo"],"w":"Lo ordeno después es la acción insegura típica: el próximo que pase puede tropezar."},{"q":"Ves una luz quemada en un pasillo de la bodega. ¿Qué haces?","o":["Aviso a mi jefatura","Nada, porque no es mi tarea","La cambio yo subiéndome al rack","Aviso solo si alguien se cae"],"w":"Una condición insegura se reporta para que la corrijan."},{"q":"¿Por qué lo ordeno después es una acción insegura?","o":["Mientras tanto, alguien puede tropezar","Porque la jefatura puede darse cuenta","Porque después se pierde más tiempo","Porque las 5S lo prohíben por escrito"],"w":"El desorden es un peligro mientras exista, aunque sea por un rato."}]}]},{"id":"accidente","sec":"todos","title":"¿Qué hacer si tengo un accidente del trabajo?","thumb":"c5ac_ley","mins":5,"learn":[{"s":"c5ac_ley","t":"Estás protegido por la Ley 16.744","x":"Todo trabajador tiene un <b>seguro obligatorio</b> que cubre accidentes del trabajo, accidentes de trayecto y enfermedades profesionales. En {EMP}, el organismo administrador es la <b>Mutual de Seguridad CChC</b>, y su <b>atención es gratuita</b> para ti: atención médica, exámenes, remedios y rehabilitación. Si corresponde, el seguro también paga tus días de licencia (subsidio) y, si queda una secuela, indemnización o pensión.","k":"La atención en la Mutual de Seguridad CChC es gratuita para ti."},{"s":"c5ac_que","t":"¿Qué es un accidente del trabajo?","x":"Según la Ley 16.744 (art. 5), es toda <b>lesión que sufres a causa o con ocasión del trabajo</b> y que te produce incapacidad o la muerte. En {EMP}: un corte con una plancha de zinc, un saco que cae en un pie, un lumbago al cargar fierro, una torcedura al bajar de la cabina. Aunque parezca pequeña, si te lesionaste trabajando, es accidente del trabajo."},{"s":"c5ac_despacho","t":"En ruta o en caja también cuenta","x":"Si te lesionas trabajando fuera de la sucursal, también es accidente del trabajo:<ul><li>Un <b>choque o una caída</b> durante un despacho a una obra o a un cliente.</li><li>Una lesión al descargar en la obra.</li><li>Un <b>asalto</b> sufrido mientras trabajas, en caja o en ruta.</li></ul>Avisa a tu jefatura para saber dónde atenderte y di siempre que fue trabajando."},{"s":"c5ac_asalto","t":"Si te asaltan: primero tu vida","x":"<ul><li><b>No resistas</b> y obedece con calma.</li><li><b>No persigas</b> al asaltante.</li><li><b>Observa</b> sin arriesgarte rasgos, ropa y vehículo, para después.</li><li>Cuando sea seguro, <b>avisa a tu jefatura y llama al 133</b> (Carabineros).</li></ul>Un asalto en el trabajo es accidente del trabajo: tienes atención en la Mutual de Seguridad CChC, que incluye <b>apoyo psicológico</b>, aunque no tengas lesiones físicas.","k":"Ningún producto ni dinero vale tu vida: no resistas ni persigas."},{"s":"c5ac_avisa","t":"Avisa de inmediato","x":"<b>Por pequeña que sea la lesión, avisa a tu jefatura de inmediato</b>, el mismo día y antes de irte. Un corte sin importancia con zinc puede infectarse; un tirón en la espalda puede empeorar mañana. Si no avisaste o la ocultaste, después cuesta probar que ocurrió en el trabajo. Avisar no es quejarse: es tu derecho y permite atenderte a tiempo."},{"s":"c5ac_diat","t":"La DIAT: la denuncia del accidente","x":"La empresa debe hacer la <b>DIAT</b> (Denuncia Individual de Accidente del Trabajo) de inmediato (Ley 16.744, art. 76). <b>Si no la hace, la puedes presentar tú directamente en la Mutual de Seguridad CChC</b>; también pueden hacerlo tu familia, el Comité Paritario o el médico que te atendió. No pierdes la cobertura por eso. Pide siempre una copia o el número de la denuncia."},{"s":"c5ac_donde","t":"¿Dónde me atiendo?","x":"<ul><li>En la <b>Mutual de Seguridad CChC</b>. Pregunta hoy a tu jefatura dónde queda el centro más cercano a tu sucursal.</li><li>Al llegar, <b>di que fue un accidente del trabajo</b>; no te atiendas como particular con tu Fonasa o isapre.</li><li>Para emergencias y rescate, llama a la Mutual al <b>1407</b>, o al <b>131</b> (SAMU).</li><li>Si estás en ruta, avisa a tu jefatura para saber dónde atenderte.</li></ul>"},{"s":"c5ac_trayecto","t":"Accidente de trayecto","x":"La Ley 16.744 (art. 5) cubre el accidente en el <b>trayecto directo, de ida o regreso, entre tu habitación y el trabajo</b>. Si te desvías por asuntos personales, como ir de compras, ya no es trayecto directo. Para acreditarlo: atiéndete pronto en la Mutual, avisa a tu jefatura, deja <b>constancia en Carabineros</b> si fue un choque, un atropello o un asalto, y anota los datos de los <b>testigos</b>."},{"s":"c5ac_companero","t":"Si un compañero se accidenta","x":"<ul><li><b>No te expongas</b> al mismo peligro: aléjate de la grúa, el camión o la carga.</li><li>Si cayó de altura o recibió un golpe fuerte, <b>no lo muevas</b>: puede tener una lesión de columna.</li><li>Llama al <b>1407</b> o al <b>131</b> y avisa a la jefatura.</li><li>Acompáñalo hasta que llegue la ayuda.</li></ul>Si es <b>grave</b>, como una caída de más de 1,8 m, atrapamiento o pérdida de conocimiento, se paraliza la tarea, se delimita la zona y no se altera el lugar."},{"s":"c5ac_auto","t":"Autocuidado: el casi accidente es una advertencia","x":"Una caja que cae cerca, un resbalón sin caída, la grúa que pasó rozando: <b>esta vez no pasó nada</b>, pero la causa sigue ahí y la próxima vez puede lesionar a alguien. La mayoría de los accidentes se relacionan con una acción insegura, como apurarse o no usar el EPP. La decisión segura: <b>detente, señaliza o corrige si puedes y avisa</b> el casi accidente a tu jefatura."}],"quiz":[{"s":"c5ac_avisa","v":[{"q":"Me hice un corte pequeño con una plancha de zinc. ¿Qué hago?","o":["Aviso a mi jefatura de inmediato","Me pongo una curita y sigo, es muy poco","Lo aviso solo si mañana empeora","Lo aviso al final de la semana"],"w":"Por pequeño que sea, se avisa de inmediato: lo que no se avisa después es difícil de acreditar."},{"q":"¿Por qué hay que avisar de inmediato incluso una lesión pequeña?","o":["Porque después cuesta probar que ocurrió en el trabajo","Porque así no te descuentan el día","Porque la jefatura solo la necesita para estadísticas","Porque si no, la Mutual cobra la atención"],"w":"El aviso oportuno respalda tu caso y permite atenderte a tiempo."},{"q":"Sentiste un tirón en la espalda al cargar fierro, pero puedes seguir. ¿Qué haces?","o":["Aviso hoy mismo a mi jefatura","Sigo y aviso si mañana duele","Me tomo un analgésico y sigo","No aviso para no parecer débil"],"w":"Un tirón puede empeorar al día siguiente. Avisar es tu derecho."}]},{"s":"c5ac_ley","v":[{"q":"La atención por un accidente del trabajo en la Mutual de Seguridad CChC la pago yo.","vf":false,"w":"Falso. La atención es gratuita para el trabajador."},{"q":"¿Cuánto debes pagar por la atención de un accidente del trabajo en la Mutual de Seguridad CChC?","o":["Nada: es gratuita","El copago de mi Fonasa o isapre","La mitad, y la empresa el resto","Solo los remedios"],"w":"El seguro de la Ley 16.744 cubre toda la atención sin costo para ti."},{"q":"¿Cuál es el organismo administrador del seguro de accidentes en {EMP}?","o":["La Mutual de Seguridad CChC","El ISL","Fonasa","La isapre de cada trabajador"],"w":"En {EMP} los accidentes del trabajo se atienden en la Mutual de Seguridad CChC."}]},{"s":"c5ac_diat","v":[{"q":"Si la empresa no hace la DIAT de mi accidente, ¿qué puedo hacer?","o":["Presentarla yo en la Mutual de Seguridad CChC","Nada: sin DIAT de la empresa pierdo la cobertura","Esperar un mes a que la empresa la haga","Atenderme en el consultorio con Fonasa"],"w":"La DIAT la debe hacer la empresa, pero si no la hace puedes presentarla tú."},{"q":"¿Qué es la DIAT?","o":["La Denuncia Individual de Accidente del Trabajo","Un certificado de alta médica","El informe de investigación del accidente","Un permiso para faltar al trabajo"],"w":"Es el documento que registra el accidente ante la Mutual (Ley 16.744, art. 76)."},{"q":"Si la empresa no hace la DIAT, puedo presentarla yo en la Mutual de Seguridad CChC.","vf":true,"w":"Verdadero. También pueden hacerlo tu familia, el Comité Paritario o el médico."}]},{"s":"c5ac_trayecto","v":[{"q":"Un accidente de trayecto es el que ocurre:","o":["En el trayecto directo entre tu habitación y el trabajo","En cualquier traslado, incluso con desvíos personales","Solo dentro de la sucursal o en su patio","Solo si vas en un vehículo de la empresa"],"w":"Así lo define la Ley 16.744, art. 5."},{"q":"Al salir del trabajo pasas a hacer compras personales y luego chocas. ¿Es accidente de trayecto?","o":["No: te desviaste del trayecto directo","Sí: todo regreso a casa está cubierto","Sí, si ocurrió antes de las 21 horas","Sí, si avisas a la jefatura al día siguiente"],"w":"El desvío por asuntos personales interrumpe el trayecto directo."},{"q":"Te atropellan camino al trabajo. ¿Qué ayuda a acreditar el accidente de trayecto?","o":["Constancia en Carabineros y testigos","Solo tu declaración, días después","Una foto del lugar, sin otros datos","Esperar una semana a ver si duele"],"w":"La constancia, los testigos y la atención oportuna respaldan tu caso."}]},{"s":"c5ac_asalto","v":[{"q":"Te asaltan en la caja. ¿Qué haces?","o":["No resisto, obedezco y luego aviso y llamo al 133","Me resisto para proteger el dinero de la caja","Persigo al asaltante para ver dónde va","Activo una alarma frente al asaltante"],"w":"Tu vida vale más que cualquier producto o dinero. No resistas y no persigas."},{"q":"Durante un asalto, ¿qué es útil hacer sin arriesgarte?","o":["Observar rasgos, ropa y vehículo","Seguir al asaltante hasta la calle","Tomarle una foto con el celular","Discutir con él para ganar tiempo"],"w":"Observar con calma ayuda después a Carabineros, sin ponerte en peligro."},{"q":"¿A qué número llamas para denunciar un asalto, cuando ya es seguro?","o":["133, Carabineros","131, SAMU","132, Bomberos","1407, Mutual"],"w":"El 133 es Carabineros. Si hay lesionados, también se pide atención médica."}]},{"s":"as_accidente","v":[{"q":"Un asalto sufrido mientras trabajas es un accidente del trabajo.","vf":true,"w":"Verdadero. Está cubierto por la Ley 16.744 e incluye apoyo psicológico en la Mutual."},{"q":"Un cajero sufre angustia después de un asalto en la caja, sin lesiones físicas. ¿Qué cobertura tiene?","o":["Atención en la Mutual, con apoyo psicológico","Ninguna, porque no tiene lesiones físicas","Solo la de su Fonasa o isapre","Solo si el asaltante lo golpeó"],"w":"El asalto en el trabajo es accidente del trabajo, aunque no haya heridas."},{"q":"Un asalto sufrido mientras trabajas, ¿cómo se considera?","o":["Accidente del trabajo","Accidente particular","Accidente de trayecto","Un hecho policial sin cobertura"],"w":"Ocurre con ocasión del trabajo, por eso lo cubre el seguro."}]},{"s":"c5ac_despacho","v":[{"q":"Chocas con el camión durante un despacho a una obra. ¿Qué es?","o":["Un accidente del trabajo","Un accidente particular, sin cobertura","Un accidente de trayecto","Un accidente que cubre solo el seguro del camión"],"w":"Ocurrió trabajando, a causa o con ocasión del trabajo: es accidente del trabajo."},{"q":"Te lesionas la mano al descargar materiales en la obra de un cliente. ¿Qué es?","o":["Un accidente del trabajo","Un accidente que cubre el cliente","Un accidente de trayecto","Un accidente sin cobertura, fuera de la sucursal"],"w":"Trabajando fuera de la sucursal, el seguro te cubre igual."},{"q":"Te lesionas en ruta, lejos de la sucursal. ¿Qué haces?","o":["Aviso a mi jefatura para saber dónde atenderme","Me atiendo como particular en un consultorio","Espero volver a la sucursal para avisar","No aviso, porque no fue en la sucursal"],"w":"En ruta, la jefatura te indica el centro de la Mutual más cercano."}]},{"s":"c5ac_companero","v":[{"q":"Un compañero cayó de la plataforma del camión y se queja de la espalda. ¿Qué haces?","o":["No lo muevo, llamo al 1407 o al 131 y aviso","Lo levanto rápido para llevarlo en auto","Le digo que se pare y camine si puede","Lo siento y le doy agua"],"w":"Podría tener una lesión de columna: no se mueve y se pide ayuda."},{"q":"¿Por qué no se debe mover a quien cayó de altura o recibió un golpe fuerte?","o":["Porque puede tener una lesión de columna","Porque la Mutual lo prohíbe","Porque hay que esperar la foto del accidente","Porque se pierde la cobertura del seguro"],"w":"Moverlo puede agravar una lesión de columna."},{"q":"Un compañero cayó desde más de 1,8 m y ya fue atendido. ¿Qué corresponde en el lugar?","o":["Paralizar, delimitar y no alterar el lugar","Ordenar todo y seguir trabajando","Retirar la escala para que nadie la use","Limpiar antes de que llegue la jefatura"],"w":"En un accidente grave se paraliza, se delimita y se deja el lugar como quedó."}]},{"s":"c5ac_ocultar","v":[{"q":"Un compañero se cortó y dice: no es nada, sigo no más. ¿Qué le recomiendas?","o":["Que avise de inmediato a la jefatura","Que se cure solo y siga trabajando","Que avise si mañana se infecta","Que no avise, para no afectar las estadísticas"],"w":"Ocultar una lesión deja al trabajador sin respaldo si empeora."},{"q":"¿Qué puede pasar si ocultas una lesión del trabajo?","o":["Después cuesta acreditar que fue en el trabajo","Nada: la cobertura es exactamente igual","Te pagan más días de licencia","La empresa queda obligada a pagarte aparte"],"w":"Sin aviso oportuno, es difícil probar el origen laboral de la lesión."},{"q":"Si no aviso una lesión pequeña, después puede costar probar que ocurrió en el trabajo.","vf":true,"w":"Verdadero. Por eso toda lesión se avisa de inmediato."}]},{"s":"c5ac_auto","v":[{"q":"Si una caja cae del rack cerca de mí, pero no me golpea, no es necesario avisarlo.","vf":false,"w":"Falso. Es un casi accidente: la causa sigue ahí y hay que corregirla."},{"q":"Una caja se cae del rack justo después de que pasaste. ¿Qué haces?","o":["Señalizo si puedo y aviso el casi accidente","Recojo la caja y sigo sin avisar a nadie","Lo aviso solo si alguien sale herido","Lo comento con todos al final de la semana"],"w":"Cada casi accidente muestra dónde puede estar el próximo accidente."},{"q":"¿Por qué se avisa un casi accidente?","o":["La causa sigue ahí y puede lesionar a otro","Porque siempre hay que hacer una DIAT","Porque así se puede cobrar el seguro","Porque es una falta grave del trabajador"],"w":"Avisarlo permite corregir la causa antes de que alguien salga herido."}]}]},{"id":"incendios","sec":"todos","title":"Prevención de incendios y uso del extintor","thumb":"cc6_inc_ext","mins":5,"learn":[{"s":"incendios_tri","t":"El triángulo del fuego","x":"El fuego necesita tres cosas a la vez: <b>combustible</b> (lo que arde: madera, cartón, pintura), <b>oxígeno</b> (el aire) y <b>calor</b> (una chispa, una llama, un cable recalentado). <b>Si quitas una sola, el fuego no parte o se apaga.</b> Prevenir es mantenerlas separadas: envases cerrados, estufas lejos del material y nada de llamas en bodega. El extintor apaga porque enfría o porque ahoga, es decir, quita calor u oxígeno."},{"s":"cc6_inc_combust","t":"En la ferretería sobra combustible","x":"En sala, bodega y patio hay mucho material que arde:<ul><li><b>Madera</b>, terciado, OSB, cartón y embalajes.</li><li><b>Pinturas, diluyentes, solventes</b> y adhesivos.</li><li><b>Cilindros de gas.</b></li><li>Tubos, mangueras y artículos de <b>plástico</b>, que arden con humo negro y tóxico.</li></ul>Retira a diario cartones y embalajes vacíos, y no los acumules junto a enchufes, tableros eléctricos ni estufas."},{"s":"cc6_inc_vapor","t":"Pinturas y solventes: el vapor es el que arde","x":"Diluyentes y solventes desprenden <b>vapores inflamables</b> que no se ven, son más pesados que el aire y pueden viajar varios metros por el piso hasta una estufa, un enchufe o un cigarro.<ul><li>Mantén los envases <b>cerrados</b> y etiquetados.</li><li>Guárdalos <b>lejos del calor</b>, en un lugar ventilado.</li><li>Un envase roto o derramado se avisa de inmediato y se limpia con el EPP que indica su Hoja de Datos de Seguridad.</li></ul>"},{"s":"cc6_inc_gas","t":"Cilindros de gas","x":"<ul><li>Siempre <b>de pie</b> y asegurados con cadena o rejilla para que no caigan.</li><li>En un lugar <b>ventilado</b>, lejos del calor, de enchufes y del sol directo.</li><li>No los golpees, no los arrastres ni los hagas rodar acostados.</li><li>Nunca cerca de pinturas o solventes.</li><li>Si huele a gas, <b>no enciendas ni apagues</b> nada eléctrico: aleja a las personas y avisa a tu jefatura.</li></ul>"},{"s":"incendios_enchufe","t":"Enchufes, estufas y cigarros","x":"<ul><li><b>No sobrecargues enchufes</b> ni conectes alargadores o zapatillas en cadena, ni en caja ni en oficina.</li><li><b>Estufas</b> a distancia de cartón, papeles e inflamables, nunca para secar ropa, y apagadas al cerrar.</li><li>Cable o enchufe <b>caliente, pelado o con olor a quemado</b>: desconéctalo si es seguro, no lo uses y avisa.</li><li><b>No fumes</b> en sala, bodega ni patio: solo en el lugar que autorice la empresa.</li></ul>"},{"s":"cc6_inc_clases","t":"Clases de fuego","x":"<ul><li><b>Clase A:</b> sólidos, como madera, cartón y plásticos.</li><li><b>Clase B:</b> líquidos y gases inflamables, como pinturas, solventes y gas.</li><li><b>Clase C:</b> equipos eléctricos energizados, como un tablero o una máquina enchufada.</li><li><b>Clase D:</b> metales combustibles.</li></ul>La etiqueta de cada extintor dice para qué clases sirve. <b>Nunca uses agua sobre un fuego eléctrico ni sobre pintura o solvente encendido</b>: conduce la corriente o esparce el fuego."},{"s":"cc6_inc_libre","t":"Extintores libres y a la vista","x":"La empresa debe tener extintores <b>del tipo adecuado</b>, en lugares de <b>fácil acceso</b>, señalizados y libres de obstáculos (DS 594, artículos 45 a 48). Tu parte:<ul><li>No pongas exhibiciones, pallets ni mercadería delante, <b>ni por un rato</b>.</li><li>Conoce dónde está el más cercano a tu puesto.</li><li>Avisa si falta, si está descargado, si tiene el sello o el seguro roto o si la aguja del manómetro no está en verde.</li></ul>"},{"s":"cc6_inc_ext","t":"Cómo usar el extintor","x":"Úsalo solo frente a un <b>amago</b> (fuego pequeño que recién empieza), si sabes hacerlo y con la <b>salida a tu espalda</b>. Antes, <b>da aviso a viva voz</b>.<ul><li><b>1. Saca el seguro.</b></li><li><b>2. Apunta a la base</b> del fuego, no a las llamas.</li><li><b>3. Aprieta</b> la manilla.</li><li><b>4. Barre</b> de lado a lado.</li></ul>La descarga dura pocos segundos: <b>si no se apaga, crece o llega al techo, retírate</b> sin darle la espalda, evacúa y llama al <b>132</b>.","k":"Saca el seguro, apunta a la base, aprieta y barre."},{"s":"cc6_inc_evac","t":"Fuego con clientes en la sala","x":"Si hay fuego o humo:<ul><li><b>Da la alarma</b> y avisa a tu jefatura.</li><li><b>Guía a los clientes</b> con calma hacia la salida más cercana: “Por aquí, síganme”.</li><li>No vuelvas por la caja, el dinero ni tus cosas.</li><li>Si hay humo, avanza agachado: el aire más limpio queda cerca del piso.</li><li>Todos al <b>punto de encuentro</b>, y nadie vuelve a entrar hasta que se autorice.</li></ul>","k":"Primero las personas: clientes y compañeros afuera."},{"s":"cc6_inc_self","t":"Autocuidado: incendios","x":"La mayoría de los accidentes se relacionan con una <b>acción insegura</b>: apurarse, saltarse un paso, creer que no pasará nada. En incendios, las típicas son <b>fumar junto a pinturas o gas</b>, dejar una estufa encendida al cerrar, tapar un extintor “por un rato” o querer apagar solo un fuego que ya creció. La decisión segura: <b>da aviso primero</b>, respeta los límites del amago y reporta cualquier condición insegura."}],"quiz":[{"s":"incendios_tri","v":[{"q":"Para que exista fuego, ¿qué tres elementos deben estar juntos a la vez?","o":["Combustible, oxígeno y calor","Combustible, humo y calor","Oxígeno, electricidad y humedad","Calor, humo y una chispa"],"w":"Es el triángulo del fuego: combustible, oxígeno y calor. Si falta uno, no hay fuego."},{"q":"Cerrar el envase de diluyente y alejarlo de la estufa previene un incendio porque:","o":["Separa el combustible del calor","Hace que el diluyente pierda su olor","Aumenta el oxígeno de la bodega","Solo sirve para que no se evapore"],"w":"Prevenir es mantener separados los elementos del triángulo: aquí, el combustible y el calor."},{"q":"Para apagar un fuego hay que quitar los tres elementos del triángulo; quitar solo uno no basta.","vf":false,"w":"Falso. Basta con quitar uno: sin combustible, oxígeno o calor, el fuego se apaga."}]},{"s":"cc6_inc_vapor","v":[{"q":"¿Por qué es peligroso dejar un tarro de diluyente abierto a varios metros de una estufa encendida?","o":["Sus vapores invisibles pueden llegar hasta la estufa y encenderse","El calor de la estufa hace explotar cualquier tarro cerrado","No es peligroso si el tarro está a más de un metro","Solo es peligroso si el tarro está volcado"],"w":"Los vapores no se ven y viajan por el piso: pueden encenderse lejos del envase."},{"q":"Al reponer, encuentras un envase de solvente con la tapa mal cerrada junto a un enchufe. ¿Qué haces?","o":["Lo cierro bien, lo alejo del enchufe y aviso si está dañado","Lo dejo así: el olor avisa a los clientes","Lo tapo con un cartón para que no salga olor","Lo cambio de lado en la misma repisa del enchufe"],"w":"Envase cerrado y lejos de cualquier fuente de calor o chispa."},{"q":"Los vapores de un diluyente pueden encenderse con una chispa aunque esté a varios metros del envase.","vf":true,"w":"Verdadero. Los vapores no se ven y viajan: por eso los envases van cerrados y lejos del calor."}]},{"s":"cc6_inc_extBien","v":[{"q":"Al usar el extintor sobre un fuego en una pila de cartones, ¿hacia dónde se dirige el chorro?","o":["A la base del fuego, donde está el material que arde","A la punta de las llamas, que es lo más caliente","Al humo, para que no se esparza","Al centro de las llamas, sin moverlo"],"w":"Se apunta a la base, donde está el combustible, y se barre de lado a lado."},{"q":"¿Qué movimiento se hace con la boquilla mientras se descarga el extintor?","o":["Barrer de lado a lado sobre la base del fuego","Mantenerla fija en el punto más alto de las llamas","Hacer círculos sobre el humo","Apuntar al techo para enfriar el ambiente"],"w":"Barrer la base cubre todo el material que arde y evita que el fuego se reavive."},{"q":"Un compañero descarga el extintor hacia las llamas más altas y el fuego no baja. ¿Qué le indicas?","o":["Que apunte a la base del fuego y barra de lado a lado","Que se acerque hasta tocar las llamas","Que espere a que las llamas bajen solas","Que descargue hacia el humo para ver mejor"],"w":"Las llamas son el resultado; el fuego se ataca en la base, donde está el combustible."}]},{"s":"cc6_inc_ext","v":[{"q":"¿Cuál es el orden correcto para usar el extintor?","o":["Sacar el seguro, apuntar a la base, apretar y barrer","Apretar, apuntar a la base, sacar el seguro y barrer","Sacar el seguro, apuntar a las llamas, apretar y esperar","Apuntar a la base, apretar, barrer y sacar el seguro"],"w":"Sin sacar el seguro la manilla no funciona; luego se apunta a la base, se aprieta y se barre."},{"q":"Diste aviso a viva voz y tomaste el extintor. ¿Cuál es el primer paso con el equipo?","o":["Sacar el seguro","Apretar la manilla para probarlo","Apuntar a las llamas más altas","Agitarlo hasta que se caliente"],"w":"El seguro bloquea la manilla: es lo primero que se retira."},{"q":"Al tomar el extintor, lo primero es apretar la manilla para probar si funciona y después sacar el seguro.","vf":false,"w":"Falso. Con el seguro puesto la manilla no se mueve: primero se saca el seguro."}]},{"s":"incendios_retirada","v":[{"q":"Intentaste apagar un amago y no se apaga en segundos. ¿Qué haces?","o":["Me retiro sin darle la espalda, evacúo y aviso","Sigo hasta vaciar el extintor aunque crezca","Busco un balde de agua para ayudar","Voy a buscar otro extintor a la bodega del fondo"],"w":"Si no se apaga en segundos, el fuego ya te supera: se evacúa y se llama a Bomberos."},{"q":"¿En qué caso corresponde que intentes apagar un fuego con el extintor?","o":["Es un amago, sé usarlo y tengo la salida a mi espalda","Las llamas ya llegan al techo de la bodega","Hay tanto humo que no veo la salida","El fuego está entre la salida y yo"],"w":"Solo amagos, sabiendo usar el equipo y con una vía de escape segura detrás."},{"q":"En la bodega el fuego de unos pallets ya supera tu altura y sale humo negro. ¿Qué haces?","o":["No lo ataco: evacúo, aviso y se llama al 132","Lo ataco con dos extintores a la vez","Abro todas las puertas para que salga el humo","Muevo los pallets cercanos antes de salir"],"w":"Un fuego que creció no es un amago: tu vida va primero."}]},{"s":"cc6_inc_clases","v":[{"q":"Se enciende un tablero eléctrico energizado. ¿De qué clase es el fuego?","o":["Clase C","Clase A","Clase B","Clase D"],"w":"La clase C es fuego en equipos eléctricos energizados: nunca se usa agua."},{"q":"Se enciende un derrame de diluyente en el piso de la bodega. ¿De qué clase es el fuego?","o":["Clase B","Clase A","Clase C","Clase D"],"w":"La clase B corresponde a líquidos y gases inflamables, como pinturas y solventes."},{"q":"Arden unos pallets de madera y cartones en el patio. ¿De qué clase es el fuego?","o":["Clase A","Clase B","Clase C","Clase D"],"w":"La clase A corresponde a sólidos comunes: madera, cartón y plásticos."}]},{"s":"cc6_inc_gas","v":[{"q":"¿Cómo se deben guardar los cilindros de gas?","o":["De pie, asegurados, ventilados y lejos del calor","Acostados en el piso para que no se caigan","De pie junto a las pinturas, que no tienen llama","En una pieza cerrada para que no les dé el aire"],"w":"De pie y amarrados no caen; con ventilación y lejos del calor, una fuga no encuentra chispa."},{"q":"Llega un camión con cilindros de gas. ¿Cuál es la forma correcta de moverlos?","o":["De pie, sin golpearlos ni arrastrarlos","Haciéndolos rodar acostados por el piso","Arrastrándolos de la válvula","Lanzándolos con cuidado a otro compañero"],"w":"Golpes y arrastres dañan la válvula y pueden causar una fuga."},{"q":"Buscas espacio en bodega para unos cilindros de gas. ¿Cuál es el lugar adecuado?","o":["Uno ventilado, lejos de estufas, enchufes e inflamables","Junto a la estufa, para que no se enfríen","Al lado de los diluyentes, que es la zona de químicos","Bajo la ventana con sol directo, que es lo más ventilado"],"w":"Ventilación y distancia del calor y de otros inflamables evitan un incendio."}]},{"s":"cc6_inc_tapado","v":[{"q":"Armaron una exhibición de pinturas delante del extintor. ¿Qué haces?","o":["La despejo o aviso para que se mueva de inmediato","La dejo: en una emergencia alguien la corre","Pongo un letrero arriba indicando dónde está","La dejo hasta que termine la oferta"],"w":"Un extintor tapado no se puede usar a tiempo: debe estar siempre libre."},{"q":"Llega un pallet de cerámicas y el único espacio libre está delante del extintor del pasillo. ¿Qué haces?","o":["Busco otro lugar o aviso: el extintor no se tapa","Lo dejo ahí solo hasta la tarde","Lo dejo ahí, pero me acuerdo de moverlo","Lo dejo si queda un pasillo angosto al lado"],"w":"Delante del extintor no se deja nada, ni por un rato."},{"q":"Delante de un extintor no se puede dejar mercadería ni siquiera por un rato.","vf":true,"w":"Verdadero. Un incendio no avisa: el extintor debe estar libre todo el tiempo."}]},{"s":"cc6_inc_evac","v":[{"q":"Hay humo en la sala y quedan clientes adentro. ¿Qué haces?","o":["Doy la alarma y guío a los clientes a la salida","Cierro la caja y guardo el dinero antes de salir","Sigo atendiendo hasta que llegue Bomberos","Salgo yo primero para abrir la puerta"],"w":"Las personas van primero: alarma y evacuación guiada."},{"q":"Evacúas la sala y el pasillo tiene humo. ¿Cómo avanzas?","o":["Agachado, porque el aire más limpio queda cerca del piso","Corriendo erguido para salir lo antes posible","Contra el humo, para encontrar el fuego","Esperando a que se despeje el humo"],"w":"El humo caliente sube: cerca del piso se respira mejor."},{"q":"Ya estás afuera y recuerdas que dejaste tu celular y la recaudación en la caja. ¿Qué haces?","o":["Me quedo en el punto de encuentro y aviso","Entro rápido, son solo unos segundos","Le pido a un compañero que entre por ellos","Entro por la otra puerta, que no tiene humo"],"w":"Nadie vuelve a entrar: ningún objeto vale tu vida."}]},{"s":"incendios_enchufe","v":[{"q":"¿Cuál es una práctica segura con enchufes y estufas?","o":["No conectar zapatillas en cadena y alejar la estufa del cartón","Secar la ropa mojada sobre la estufa de la bodega","Encintar un enchufe caliente para seguir usándolo","Usar una sola zapatilla para todos los equipos de la caja"],"w":"Enchufes sobrecargados y estufas junto a material combustible son causas comunes de incendio."},{"q":"En la caja notas que el enchufe de la impresora está caliente y huele a quemado. ¿Qué haces?","o":["Lo desconecto si es seguro, no lo uso y aviso","Lo dejo enchufado hasta el cierre de la caja","Le pongo cinta aislante y sigo trabajando","Lo cambio a una zapatilla con varios equipos"],"w":"Un enchufe caliente es un aviso de sobrecarga o falla: no se usa y se reporta."},{"q":"Un compañero quiere fumar en la bodega, junto a las pinturas, porque llueve. ¿Qué le dices?","o":["Que no: solo se fuma en el lugar autorizado","Que fume rápido y tire la colilla al agua","Que fume en la puerta de la bodega","Que fume si mantiene el tarro cerrado"],"w":"Una colilla o la llama del encendedor puede encender los vapores de las pinturas."}]}]},{"id":"emergencias","sec":"todos","title":"Emergencias, sismos y evacuación","thumb":"cc6_em_sismo","learn":[{"s":"cc6_em_tipos","t":"¿Qué emergencias pueden ocurrir?","x":"<ul><li><b>Incendio:</b> madera, pinturas, solventes y gas arden rápido.</li><li><b>Sismo:</b> góndolas y racks pueden botar productos o volcarse.</li><li><b>Fuga de gas</b> o derrame de un producto químico.</li><li><b>Corte de luz</b> con clientes en la sala: quédate quieto, deja que se encienda la luz de emergencia y calma a los clientes.</li><li><b>Persona lesionada.</b></li><li><b>Tsunami</b>, si tu sucursal está en zona costera.</li></ul>Pensar antes qué harías te ahorra segundos valiosos."},{"s":"cc6_em_plan","t":"El plan de emergencia","x":"{EMP} debe tener un <b>plan de emergencia</b> para cada sucursal. Pregunta a tu jefatura cuál es el tuyo. Desde tu primer día debes conocer:<ul><li>Cómo se da la <b>alarma</b> y quién la da.</li><li>Las <b>vías de evacuación</b> desde tu puesto, y una alternativa.</li><li>El <b>punto de encuentro</b>.</li><li>Dónde están los <b>extintores</b> y el botiquín.</li><li>Quiénes forman la brigada o son líderes de evacuación.</li></ul>"},{"s":"cc6_em_sismo","t":"Durante un sismo","x":"SENAPRED recomienda: <b>agáchate, cúbrete y afírmate</b>.<ul><li>Aléjate de <b>góndolas altas, racks</b> y ventanales: los productos pueden caer.</li><li><b>No corras</b> ni uses escaleras mientras se mueve el piso.</li><li>Pide a los clientes, con voz firme, que se agachen lejos de las estanterías.</li><li>Evacúa cuando termine el movimiento o te lo indiquen, revisando si hay productos caídos o derrames en el camino.</li></ul>","k":"Agáchate, cúbrete y afírmate, lejos de góndolas y racks."},{"s":"cc6_em_patio","t":"Sismo en el patio o en ruta","x":"<ul><li><b>Grúa horquilla:</b> detente, baja la carga al piso, aplica el freno y mantente sentado con el cinturón puesto.</li><li><b>Camión en ruta:</b> detente en un lugar seguro, lejos de postes, cables, puentes, pasos bajo nivel y taludes.</li><li><b>En el patio:</b> aléjate de racks, pilas de material y de la carga de los camiones.</li></ul>Retoma el trabajo solo cuando termine el movimiento y te lo indiquen, y revisa si hay pilas o racks dañados antes de acercarte."},{"s":"cc6_em_fuga","t":"Fuga de gas o derrame","x":"Si huele a gas o un cilindro silba:<ul><li><b>No hagas chispas:</b> no enciendas ni apagues interruptores, no uses llamas ni el celular junto a la fuga.</li><li>Aleja a clientes y compañeros.</li><li>Si es seguro, cierra la válvula y ventila abriendo puertas.</li><li><b>Avisa</b> a tu jefatura y, si es necesario, llama al <b>132</b>.</li></ul>Ante un derrame de pintura o solvente, aleja a las personas y no lo limpies sin el EPP que indica la HDS."},{"s":"emergencias_llamar","t":"Cómo pedir ayuda","x":"<b>131</b> SAMU, ambulancia. <b>132</b> Bomberos. <b>133</b> Carabineros. Ante un accidente del trabajo, la <b>Mutual de Seguridad CChC</b> atiende en el <b>1407</b>.<ul><li>Da la <b>dirección exacta</b> de tu sucursal y una referencia.</li><li>Di qué pasó y cuántos lesionados hay.</li><li>No cortes hasta que te lo indiquen.</li><li>No muevas a un lesionado, salvo que corra un peligro mayor.</li></ul>Avisa también a tu jefatura.","k":"131 SAMU, 132 Bomberos, 133 Carabineros."},{"s":"cc6_em_evac","t":"Evacuar con clientes","x":"Cuando se dé la orden, guía a los clientes hacia la <b>salida más cercana</b>:<ul><li>Camina rápido, <b>sin correr</b> y sin empujar.</li><li>Habla con voz firme y calmada: “Por aquí, síganme”.</li><li>Ayuda a niños, adultos mayores y personas con movilidad reducida.</li><li>No vuelvas por la caja, el dinero ni tus cosas.</li><li>No uses el celular para grabar: necesitas tus manos y tu atención.</li></ul>"},{"s":"cc6_em_punto","t":"En el punto de encuentro","x":"Quédate en el punto de encuentro, aunque la emergencia parezca menor. Ahí se <b>cuenta a las personas</b>: avisa si falta un compañero o si viste clientes que no salieron. <b>Nadie vuelve a entrar</b> hasta que la jefatura o Bomberos lo autoricen. Si alguien falta, avísalo a Bomberos indicando dónde lo viste por última vez: <b>no vuelvas tú a buscarlo</b>."},{"s":"cc6_em_tsunami","t":"Sucursal en zona costera: tsunami","x":"Si tu sucursal está en zona de inundación por tsunami, <b>sigue la señalética de evacuación</b> hacia la zona segura, en altura. Si el sismo es tan fuerte que cuesta mantenerse en pie, <b>evacúa de inmediato</b>, sin esperar la alarma ni una orden. Ve <b>a pie</b>, no en vehículo: los autos y camiones bloquean las calles. No vuelvas hasta que la autoridad lo indique, porque puede haber más de una ola."},{"s":"cc6_em_auto","t":"Autocuidado en emergencias","x":"La mayoría de los accidentes se relacionan con una acción insegura. En emergencias, las típicas: <b>tapar salidas o extintores</b> con mercadería o pallets, volver por la mochila, grabar con el celular, correr durante el sismo. La decisión segura: mantener las salidas despejadas todos los días y seguir el plan. <b>Avisa</b> de inmediato si ves una salida bloqueada, una puerta de emergencia con llave o un extintor sin carga."}],"quiz":[{"s":"cc6_em_sismo","v":[{"q":"Durante un sismo, SENAPRED recomienda:","o":["Agacharse, cubrirse y afirmarse","Correr a la salida apenas empieza","Sujetar la góndola para que no caiga","Ponerse bajo el marco de la puerta de bodega"],"w":"Protege tu cabeza y aléjate de lo que puede caer; se evacúa cuando termina el movimiento."},{"q":"Estás reponiendo en un pasillo de góndolas altas y empieza un sismo fuerte. ¿Qué haces?","o":["Me alejo de la góndola, me agacho, me cubro y me afirmo","Sujeto la góndola con ambas manos para que no se vuelque","Corro hacia la salida esquivando a los clientes","Me quedo de pie junto a la góndola esperando"],"w":"Las góndolas pueden botar productos o volcarse: lejos de ellas y protegiendo la cabeza."},{"q":"Durante el movimiento de un sismo, lo correcto es correr hacia la salida.","vf":false,"w":"Falso. Correr mientras se mueve el piso provoca caídas y golpes; se evacúa al terminar."}]},{"s":"cc6_em_patio","v":[{"q":"Si operas la grúa horquilla durante un sismo, debes:","o":["Detenerte, bajar la carga al piso y frenar","Levantar más la carga para protegerla","Acelerar para salir del patio","Bajarte corriendo y dejarla con la carga arriba"],"w":"Una carga en altura puede caer sobre alguien o volcar la grúa."},{"q":"Vas manejando el camión de despacho y empieza un sismo fuerte. ¿Qué haces?","o":["Me detengo lejos de postes, cables y puentes","Me detengo bajo un puente, que es lo más firme","Acelero para salir luego de la zona urbana","Sigo a menor velocidad hasta la próxima esquina"],"w":"Postes, cables, puentes y taludes pueden caer o ceder: detente lejos de ellos."},{"q":"Estás en el patio junto a una pila de fierros cuando empieza un sismo. ¿Qué haces?","o":["Me alejo de pilas, racks y carga de camiones","Me apoyo en la pila de fierros para no caerme","Me meto bajo el camión estacionado más cercano","Me subo a la cabina de la grúa para protegerme"],"w":"Lo que está apilado o en altura puede caer: aléjate de ello."}]},{"s":"emergencias_llamar","v":[{"q":"¿Cuál es el número de Bomberos?","o":["132","131","133","1407"],"w":"131 SAMU, 132 Bomberos, 133 Carabineros."},{"q":"Un compañero cayó desde la plataforma de un camión y está inconsciente. ¿A qué número llamas para pedir una ambulancia?","o":["131","132","133","1407"],"w":"El 131 es el SAMU, el servicio de ambulancias."},{"q":"Un cliente amenaza con un arma a una cajera. ¿A qué número llamas?","o":["133","131","132","1407"],"w":"El 133 es Carabineros, para delitos y amenazas."}]},{"s":"emergencias_llamar","v":[{"q":"Al llamar al SAMU por un lesionado, ¿qué información es lo primero y más importante?","o":["La dirección exacta, qué pasó y cuántos lesionados hay","El nombre de tu jefatura y el RUT del lesionado","Solo que es urgente, para no perder tiempo","El número de la factura del cliente"],"w":"Sin dirección exacta la ambulancia no llega; el tipo de emergencia define qué envían."},{"q":"Un compañero se golpeó fuerte en la cabeza en la bodega. Mientras llega la ayuda, ¿qué haces?","o":["Lo dejo quieto, salvo que corra un peligro mayor, y aviso","Lo levanto y lo siento en una silla","Lo llevo caminando hasta la puerta","Le doy agua y lo hago caminar para que se despierte"],"w":"Mover a un lesionado puede agravar una lesión; solo se mueve si hay un peligro mayor."},{"q":"Al llamar al 131 debes cortar apenas des la dirección, para dejar la línea libre.","vf":false,"w":"Falso. No cortes hasta que te lo indiquen: pueden darte instrucciones para ayudar."}]},{"s":"cc6_em_libre","v":[{"q":"¿Cómo deben estar las salidas de emergencia y los extintores?","o":["Despejados todo el tiempo, sin nada delante","Despejados solo durante el horario de atención","Pueden tener mercadería si queda un pasillo","Despejados solo cuando hay simulacro"],"w":"Una emergencia no avisa: salidas y extintores deben estar siempre libres."},{"q":"La bodega está llena y un compañero propone dejar unos pallets frente a la salida de emergencia hasta la tarde. ¿Qué haces?","o":["Busco otro lugar y, si no hay, aviso a la jefatura","Acepto si los pallets quedan bien apilados","Acepto si dejamos un espacio para pasar de lado","Acepto porque solo será hasta la tarde"],"w":"Una salida bloqueada, aunque sea por unas horas, puede atrapar a personas en una emergencia."},{"q":"Al abrir la sucursal ves que la puerta de emergencia está cerrada con candado. ¿Qué haces?","o":["Aviso de inmediato para que se abra antes de atender","Lo dejo: en una emergencia alguien busca la llave","Lo dejo, porque así se evitan robos","Lo comento en la próxima reunión"],"w":"Una salida de emergencia debe poder abrirse sin llave desde adentro mientras hay personas."}]},{"s":"cc6_em_evac","v":[{"q":"Se ordena evacuar y hay clientes en la sala. ¿Qué haces?","o":["Los guío con calma a la salida y al punto de encuentro","Salgo primero: cada uno sabe por dónde","Les pido que terminen de pagar antes de salir","Los dejo buscar la salida que conocen"],"w":"Tú conoces las salidas: guía a los clientes, sin correr."},{"q":"Evacúas la sala con clientes y una señora mayor camina lento. ¿Qué haces?","o":["La acompaño o pido a alguien que la ayude, sin correr","La adelanto para abrir la salida y que me siga","Le pido que espere adentro a Bomberos","La dejo, porque debo seguir con los demás"],"w":"Niños, adultos mayores y personas con movilidad reducida necesitan apoyo para evacuar."},{"q":"Durante la evacuación, un compañero se detiene a grabar el humo con el celular. ¿Qué le dices?","o":["Que guarde el celular y siga guiando a los clientes","Que grabe para tener pruebas del incendio","Que grabe pero desde más cerca, para que se vea","Que suba el video para avisar a los demás"],"w":"En una evacuación necesitas tus manos y tu atención para ti y los clientes."}]},{"s":"cc6_em_punto","v":[{"q":"En el punto de encuentro notas que falta un compañero de bodega. ¿Qué haces?","o":["Aviso a Bomberos dónde lo vi por última vez","Entro a buscarlo, porque conozco bien la bodega","Lo llamo al celular y espero a que conteste","Espero, porque seguro salió por otra puerta"],"w":"Avisar permite que Bomberos lo busque con equipo; si entras, puede haber dos víctimas."},{"q":"¿Cuándo puedes volver a entrar a la sucursal después de evacuar?","o":["Cuando la jefatura o Bomberos lo autoricen","Apenas deje de verse humo","Cuando pasen diez minutos","Cuando ya no se escuche la alarma"],"w":"Puede haber peligros que no se ven: solo se entra con autorización."},{"q":"Si falta un compañero en el punto de encuentro, debes avisar a Bomberos en vez de volver a entrar a buscarlo.","vf":true,"w":"Verdadero. Bomberos tiene equipo para entrar; volver solo te pone en riesgo."}]},{"s":"cc6_em_tsunami","v":[{"q":"Tu sucursal está en zona de inundación por tsunami y hay un sismo tan fuerte que cuesta mantenerse en pie. ¿Qué haces?","o":["Evacúo a pie a la zona segura, por la señalética","Espero en la sala hasta que suene la alarma oficial","Saco el camión de despacho para irme más rápido","Espero que la radio confirme si hay alerta de tsunami"],"w":"Con un sismo así en la costa se evacúa de inmediato, a pie, sin esperar la alarma."},{"q":"¿Por qué se evacúa a pie ante un tsunami y no en vehículo?","o":["Porque los vehículos atochan las calles y bloquean la evacuación","Porque caminar es mejor para la salud","Porque los vehículos no pueden subir a la zona segura","Porque así lo exige el seguro del camión"],"w":"Autos y camiones bloquean las vías y dejan atrapadas a las personas."},{"q":"Evacuaste a la zona segura por tsunami y el mar parece tranquilo después de la primera ola. ¿Qué haces?","o":["Me quedo hasta que la autoridad autorice volver","Vuelvo, porque ya pasó la primera ola y está calmo","Vuelvo solo un momento a cerrar la sucursal","Bajo a revisar cómo quedó la sucursal y vuelvo"],"w":"Puede haber más de una ola: se vuelve solo cuando la autoridad lo indica."}]},{"s":"cc6_em_fuga","v":[{"q":"Huele a gas en la bodega. ¿Qué es lo correcto?","o":["No tocar interruptores, alejar a todos y avisar","Encender la luz para encontrar rápido la fuga","Apagar la luz y los equipos para evitar chispas","Buscar la fuga con un encendedor, con cuidado"],"w":"Encender o apagar un interruptor puede hacer una chispa que encienda el gas."},{"q":"Un cilindro de gas silba en el patio. Si es seguro, ¿qué haces?","o":["Cierro la válvula, alejo a las personas y aviso","Lo tapo con un paño mojado y sigo trabajando","Lo acuesto en el piso para que no silbe","Lo llevo a la sala para revisarlo con calma"],"w":"Cerrar la válvula corta la fuga; luego se aleja a las personas y se avisa."},{"q":"Si huele a gas en la bodega, no debes encender ni apagar interruptores.","vf":true,"w":"Verdadero. Un interruptor puede hacer una chispa y encender el gas."}]},{"s":"cc6_em_plan","v":[{"q":"¿Qué debes conocer del plan de emergencia desde tu primer día?","o":["Alarma, vías de evacuación, punto de encuentro y extintores","Solo el teléfono de la jefatura y el de Bomberos","Solo la salida principal, que es la que usan los clientes","Nada en especial, porque eso lo maneja la brigada"],"w":"En una emergencia no hay tiempo de aprender: hay que saberlo antes."},{"q":"Un trabajador nuevo te pregunta por dónde salir si la puerta principal está bloqueada. ¿Qué le respondes?","o":["Le muestro la vía alternativa y el punto de encuentro","Que siga a los clientes, que saben por dónde","Que espere a la jefatura en la puerta principal","Que salga por la bodega, aunque no tenga señalética"],"w":"Siempre debes conocer una vía de evacuación alternativa desde tu puesto."},{"q":"Te cambiaron a otra sucursal. Respecto a la emergencia, ¿qué haces primero?","o":["Pregunto por su plan, salidas y punto de encuentro","Uso lo que ya sé del plan de mi sucursal anterior","Espero al próximo simulacro para aprender el plan","Le pregunto a un cliente frecuente por la salida"],"w":"Cada sucursal tiene su propio plan, salidas y punto de encuentro."}]}]},{"id":"senaletica","sec":"todos","title":"Señalización de seguridad","thumb":"cc6_sen_porque","learn":[{"s":"cc6_sen_porque","t":"¿Para qué sirven las señales?","x":"Te avisan de un peligro o de una obligación <b>antes</b> de que te expongas, aunque no conozcas la zona. En la sucursal hay señales en la <b>sala de ventas</b>, la <b>bodega</b> y el <b>patio</b>. Siguen normas chilenas: <b>NCh 1410</b> (colores de seguridad) y <b>NCh 1411</b> (letreros de seguridad). La señal no elimina el peligro: te dice cómo protegerte de él."},{"s":"senaletica_formas","t":"Forma y color tienen significado","x":"<ul><li><b>Círculo rojo con barra:</b> prohibición.</li><li><b>Círculo azul:</b> obligación.</li><li><b>Triángulo amarillo con borde negro:</b> advertencia de peligro.</li><li><b>Rectángulo o cuadrado verde:</b> evacuación, salida y primeros auxilios.</li><li><b>Rectángulo o cuadrado rojo:</b> equipos contra incendio.</li></ul>Aprende a leer la forma y el color: te dicen el mensaje aunque no alcances a leer el texto."},{"s":"cc6_sen_prohib","t":"Prohibición: círculo rojo con barra","x":"Indica algo que <b>no se puede hacer</b>: fumar junto a pinturas, solventes o gas; entrar a la bodega o al patio de carga sin autorización; usar el celular al operar la grúa; pasar bajo una carga suspendida. Una prohibición no tiene excepciones “por un rato”. Si un cliente quiere entrar a una zona de “Solo personal autorizado”, <b>detenlo con amabilidad</b> y atiéndelo tú."},{"s":"cc6_sen_oblig","t":"Obligación: círculo azul","x":"Indica lo que <b>debes usar o hacer</b> en esa zona. En bodega y patio se suele pedir <b>chaleco reflectante</b>, <b>zapatos de seguridad</b>, guantes o casco. Si la zona está señalizada, el EPP es <b>obligatorio todo el tiempo</b> que estés en ella, aunque sea “una pasada rápida”, y también para visitas, proveedores y jefaturas."},{"s":"cc6_sen_adv","t":"Advertencia: triángulo amarillo","x":"Avisa de un <b>peligro cercano</b>: tránsito de grúa horquilla, carga suspendida, riesgo eléctrico o <b>piso mojado</b> en la sala. Al verla, baja el ritmo y mira a tu alrededor. Si trapeas o hay un derrame, pon el letrero de piso mojado <b>antes de empezar</b> y retíralo solo cuando el piso esté seco: protege a clientes y compañeros de resbalar."},{"s":"cc6_sen_evac","t":"Verde para salir, rojo para el fuego","x":"Las señales <b>verdes</b> muestran la vía de evacuación, la salida y los primeros auxilios: las flechas te llevan hasta la salida y luego al punto de encuentro. Las señales <b>rojas</b> marcan dónde están los extintores y equipos contra incendio. Conoce las de tu sucursal para guiar a los clientes, y nunca tapes ninguna con exhibiciones, ofertas o pallets."},{"s":"cc6_sen_sga","t":"Pictogramas en los productos","x":"Pinturas, diluyentes, ácidos, adhesivos y gas llevan pictogramas del <b>Sistema Globalmente Armonizado (SGA)</b>, exigido en Chile por el <b>DS 57</b>: <b>rombos de borde rojo, fondo blanco y símbolo negro</b>. Cada uno indica un peligro: llama, inflamable; mano corroída, corrosivo; silueta dañada, daño grave a la salud. La etiqueta dice además “Peligro” o “Atención”. Si un envase se rompe, revisa su <b>Hoja de Datos de Seguridad (HDS)</b> antes de limpiarlo.","k":"Lee el rombo antes de manipular el envase."},{"s":"cc6_sen_piso","t":"Demarcación en piso y patio","x":"Las líneas pintadas también son señalización: delimitan <b>pasillos peatonales</b>, zonas de <b>carga y tránsito de grúa</b>, pasos peatonales en el patio y el espacio frente a salidas y extintores. Camina por la zona peatonal, cruza por el paso marcado y <b>no dejes mercadería, pallets ni carros sobre las líneas</b> ni en los pasillos, ni siquiera por un rato."},{"s":"cc6_sen_transito","t":"Señales de tránsito en el patio","x":"En el patio circulan camiones, grúas horquilla y vehículos de clientes. Respeta el <b>PARE</b>, el sentido de circulación y los estacionamientos, igual que en la calle según la Ley de Tránsito. Conduce a la velocidad que fijan las reglas internas. Antes de cruzar, <b>busca contacto visual</b> con el conductor: si no te ve, no pases. Nunca camines por detrás de un vehículo que retrocede.","k":"Si el conductor no te ve, no cruces."},{"s":"cc6_sen_auto","t":"Autocuidado: no te acostumbres a las señales","x":"La mayoría de los accidentes se relacionan con una acción insegura. Aquí las típicas: ignorar un letrero “porque siempre ha estado ahí”, cortar camino por la zona de carga, tapar una señal con una exhibición. La decisión segura: <b>obedecer cada señal, cada vez</b>. Si ves una señal caída, rota, borrosa o tapada, o una línea de piso borrada, <b>avísalo</b> a tu jefatura."}],"quiz":[{"s":"cc6_sen_oblig","v":[{"q":"Un círculo azul con un pictograma blanco indica:","o":["Una obligación","Una prohibición","Una advertencia","Una vía de evacuación"],"w":"Azul indica algo que debes usar o hacer en esa zona."},{"q":"Entras a la bodega solo a buscar un producto y hay un círculo azul de zapatos de seguridad. ¿Qué haces?","o":["Uso los zapatos de seguridad, aunque sea una pasada rápida","Entro con zapatillas si es menos de un minuto","Entro con cuidado mirando el piso","Le pido a un compañero que me avise si pasa la grúa"],"w":"La obligación rige todo el tiempo que estés en la zona, sin importar cuánto."},{"q":"Una señal azul de uso obligatorio de EPP solo se aplica a los trabajadores de bodega, no a jefaturas ni visitas.","vf":false,"w":"Falso. La obligación es para todas las personas que entren a esa zona."}]},{"s":"cc6_sen_adv","v":[{"q":"Un triángulo amarillo con borde negro indica:","o":["Advertencia de un peligro cercano","Una obligación de usar EPP","Una salida de emergencia","Que la zona es solo para personal"],"w":"Amarillo con borde negro: atención, hay un peligro cerca."},{"q":"Acabas de trapear un pasillo de la sala. ¿Cuándo retiras el letrero de piso mojado?","o":["Cuando el piso esté completamente seco","Apenas termino de trapear","Cuando pasen cinco minutos","Cuando ya no haya clientes en el pasillo"],"w":"El letrero advierte el riesgo de resbalar mientras el piso siga mojado."},{"q":"En la bodega ves un triángulo amarillo con una grúa horquilla. ¿Qué haces?","o":["Bajo el ritmo, miro a mi alrededor y atento a la grúa","Sigo igual: la grúa tiene bocina","Camino más rápido para salir luego de la zona","Solo me cuido si escucho la grúa"],"w":"La advertencia te pide atención: puede aparecer una grúa en cualquier momento."}]},{"s":"cc6_sen_prohib","v":[{"q":"El círculo rojo con una barra diagonal significa:","o":["Prohibido","Obligatorio","Precaución","Salida"],"w":"Indica una acción que no se puede hacer, sin excepciones."},{"q":"Un cliente quiere entrar a la bodega, donde dice “Solo personal autorizado”. ¿Qué haces?","o":["Lo detengo con amabilidad y lo atiendo yo","Lo dejo pasar si es rápido","Le presto mi chaleco y lo acompaño","Lo dejo pasar si es un cliente conocido"],"w":"La prohibición también protege al cliente: en bodega hay grúas y cargas."},{"q":"Junto a la jaula de cilindros de gas hay un círculo rojo con un cigarro tachado. Un peoneta quiere fumar ahí en la pausa. ¿Qué es lo correcto?","o":["Que no fume ahí: solo en el lugar autorizado","Que fume si el cilindro está cerrado","Que fume rápido mientras nadie lo ve","Que fume si se pone a dos metros"],"w":"Prohibido fumar junto al gas: una llama puede encender una fuga."}]},{"s":"cc6_sen_evac","v":[{"q":"¿Qué color tienen las señales de evacuación y primeros auxilios?","o":["Verde","Rojo","Azul","Amarillo"],"w":"Verde indica evacuación, salida y primeros auxilios."},{"q":"Un letrero rojo con un extintor dibujado indica:","o":["Dónde hay un equipo contra incendio","Que está prohibido usar el extintor","Una vía de evacuación","Una zona con riesgo de incendio"],"w":"El rojo marca la ubicación de extintores y equipos contra incendio."},{"q":"Hay humo en la sala y no conoces bien la sucursal. ¿Qué señales sigues?","o":["Las flechas verdes de evacuación","Los letreros rojos de los extintores","Los círculos azules","Los triángulos amarillos"],"w":"Las señales verdes te llevan a la salida y al punto de encuentro."}]},{"s":"cc6_sen_sga","v":[{"q":"Los pictogramas SGA de un envase de diluyente son:","o":["Rombos de borde rojo, fondo blanco y símbolo negro","Círculos azules con un símbolo blanco al centro","Triángulos amarillos con borde y símbolo negro","Rombos de cuatro colores con números del 0 al 4"],"w":"Así se ven los pictogramas del SGA, exigidos por el DS 57."},{"q":"Se rompe un envase de adhesivo con pictogramas en la góndola. Antes de limpiarlo, ¿qué haces?","o":["Reviso la HDS para saber cómo limpiarlo y con qué EPP","Lo limpio con un paño y agua","Lo tapo con cartón y sigo atendiendo","Lo barro rápido antes de que lo vea un cliente"],"w":"La Hoja de Datos de Seguridad indica cómo actuar y qué EPP usar ante un derrame."},{"q":"En una etiqueta, un rombo de borde rojo con una llama indica que el producto es inflamable.","vf":true,"w":"Verdadero. El pictograma de la llama del SGA indica peligro de inflamabilidad."}]},{"s":"cc6_sen_visible","v":[{"q":"¿Cómo deben estar las señales de evacuación y de extintores?","o":["Visibles y sin nada que las tape","Visibles solo en horario de atención","Pueden taparse si se pone otra señal cerca","Visibles solo en la bodega"],"w":"Una señal tapada no cumple su función cuando más se necesita."},{"q":"Colgaron un letrero de oferta que tapa la señal de salida. ¿Qué haces?","o":["Aviso para que se mueva el letrero de inmediato","Lo dejo: todos saben dónde está la salida","Lo dejo hasta que termine la oferta","Pongo una flecha a mano al lado"],"w":"Los clientes no conocen la sucursal: la señal de salida debe verse siempre."},{"q":"Una ruma de pinturas en oferta tapa el letrero del extintor. ¿Qué es lo correcto?","o":["Despejar señal y extintor, o avisar para hacerlo","Dejarla, porque el extintor sigue en su lugar","Dejarla si queda un espacio libre para pasar","Moverla solo si viene una inspección o auditoría"],"w":"Señales y extintores deben estar visibles y despejados todo el tiempo."}]},{"s":"cc6_sen_piso","v":[{"q":"¿Para qué sirven las líneas amarillas pintadas en el piso de bodega y patio?","o":["Separan pasillos peatonales de zonas de grúas","Solo sirven para ordenar los pallets en filas","Indican dónde se pueden dejar los carros","Marcan la ruta que deben seguir los clientes"],"w":"Las líneas separan a las personas de los vehículos y mantienen zonas libres."},{"q":"Estás reponiendo y necesitas dejar un carro con cajas un momento. ¿Dónde lo dejas?","o":["Fuera de las líneas y del pasillo peatonal","Sobre la línea amarilla, que no estorba","Delante del extintor, que es lo más cercano","En el paso peatonal, si es un rato"],"w":"Las líneas demarcan zonas que deben estar libres en todo momento."},{"q":"Puedo dejar mercadería sobre la línea amarilla del pasillo si es por poco rato.","vf":false,"w":"Falso. Las líneas demarcan zonas que deben estar libres, ni siquiera por un rato."}]},{"s":"cc6_sen_transito","v":[{"q":"Vas a cruzar el patio y un camión está maniobrando. ¿Qué haces?","o":["Espero y busco contacto visual con el conductor","Cruzo rápido por delante","Paso por detrás mientras retrocede","Cruzo si escucho la alarma de retroceso"],"w":"Si el conductor no te ve, no cruces."},{"q":"Conduces una camioneta en el patio y llegas a un PARE. ¿Qué haces?","o":["Me detengo por completo y miro antes de avanzar","Bajo la velocidad y paso si no veo a nadie","Toco la bocina y sigo","Me detengo solo si hay peatones"],"w":"En el patio rigen las mismas reglas de tránsito que en la calle."},{"q":"La camioneta de un cliente retrocede en el patio y quieres pasar detrás de ella. ¿Qué es lo correcto?","o":["No paso: espero a que se detenga y el conductor me vea","Paso rápido, porque va lento","Paso si tiene las luces de retroceso encendidas","Le golpeo la carrocería para que me vea"],"w":"Nunca se camina detrás de un vehículo que retrocede: el conductor no te ve."}]},{"s":"cc6_sen_auto","v":[{"q":"Llevas años en la sucursal y ya no miras el letrero de “Zona de carga”. ¿Por qué es un riesgo?","o":["Porque el peligro sigue ahí aunque me acostumbre","No es un riesgo si conozco bien la zona","Solo es riesgo para los nuevos","Solo es riesgo si cambian el letrero"],"w":"Acostumbrarse a la señal no elimina el peligro."},{"q":"Para llegar más rápido a la caja, un compañero corta camino por la zona de carga. ¿Qué le dices?","o":["Que use el pasillo peatonal, aunque se demore más","Nada, si no hay camiones en ese momento","Que corte camino, pero corriendo","Que lo haga solo cuando no lo vea la jefatura"],"w":"Una grúa o un camión pueden aparecer en cualquier momento en la zona de carga."},{"q":"Si ves una señal de seguridad caída o borrosa, debes avisar a tu jefatura.","vf":true,"w":"Verdadero. Una señal en mal estado no protege: avisar también es autocuidado."}]},{"s":"senaletica_formas","v":[{"q":"Ves de lejos un círculo azul y no alcanzas a leer el texto. ¿Qué te indica?","o":["Que hay algo obligatorio en esa zona","Que hay un peligro cercano en esa zona","Que algo está prohibido en esa zona","Que en esa zona hay un extintor"],"w":"La forma y el color dicen el mensaje aunque no leas el texto."},{"q":"¿Qué forma y color tiene una señal de advertencia?","o":["Triángulo amarillo con borde negro","Círculo rojo con una barra diagonal","Rectángulo verde con una flecha blanca","Círculo azul con un pictograma blanco"],"w":"El triángulo amarillo advierte de un peligro."},{"q":"¿Cuál de estas combinaciones es correcta?","o":["Verde: salida; rojo: equipo contra incendio","Verde: prohibición; azul: salida","Amarillo: obligación; rojo: salida","Azul: advertencia; verde: extintor"],"w":"Verde indica evacuación y primeros auxilios; rojo, equipos contra incendio."}]}]},{"id":"uv","sec":"todos","title":"Radiación UV de origen solar","thumb":"cc6_uv_intro","learn":[{"s":"cc6_uv_intro","t":"Radiación UV: un peligro que no se siente","x":"El sol emite <b>radiación ultravioleta (UV)</b>: no se ve ni se siente como calor, pero daña la piel y los ojos. Te expones en el <b>patio de materiales</b>, en la <b>carga y el despacho</b>, al <b>conducir</b> y al entregar en obra. Un día fresco o con viento puede tener un índice UV alto. El daño se va sumando durante toda la vida."},{"s":"uv_efectos","t":"Efectos en la salud","x":"<ul><li><b>Quemaduras</b> solares: piel roja, dolor, ampollas.</li><li><b>Daño ocular</b>: irritación y, con los años, lesiones como cataratas.</li><li><b>Envejecimiento</b> y manchas en la piel.</li><li><b>Cáncer de piel</b>, por la exposición acumulada.</li></ul>Revisa tu piel: un lunar que cambia de forma, color o tamaño, o una herida que no sana, debe verlo un médico."},{"s":"uv_escala","t":"El índice UV","x":"Indica cuánta radiación UV llega. Mientras más alto, más rápido daña:<ul><li>1 a 2, <b>verde</b>: bajo.</li><li>3 a 5, <b>amarillo</b>: moderado.</li><li>6 a 7, <b>naranjo</b>: alto.</li><li>8 a 10, <b>rojo</b>: muy alto.</li><li>11 o más, <b>violeta</b>: extremo.</li></ul>Desde 3, amarillo, hay que protegerse. Consulta el pronóstico del índice UV del día.","k":"Desde amarillo, 3 o más, hay que protegerse."},{"s":"uv_horario","t":"Horario de mayor radiación","x":"En verano, la radiación es mayor aproximadamente entre las <b>10:00 y las 17:00</b>. Cuando se pueda, deja las cargas y descargas al sol para temprano o para el final de la tarde, y busca la sombra en las pausas. Un truco: <b>si tu sombra es más corta que tú, el sol está fuerte</b> y debes protegerte."},{"s":"uv_nublado","t":"Aunque esté nublado","x":"Las nubes <b>no detienen toda la radiación UV</b>: en un día nublado igual te puedes quemar. Las superficies claras, como el cemento del patio, la arena o las planchas metálicas, también <b>reflejan</b> parte de la radiación hacia tu cara. Protégete siempre que trabajes al aire libre, aunque esté fresco o nublado."},{"s":"uv_ropa","t":"Ropa y EPP contra el sol","x":"<ul><li><b>Manga larga</b> y pantalón largo, de tela que no deje pasar la luz.</li><li><b>Legionario o cubrenuca</b>, bajo el casco si lo usas: protege orejas y cuello.</li><li><b>Lentes con filtro UV</b>.</li><li>Bloqueador en lo que queda descubierto.</li></ul>{EMP} debe entregar estos elementos <b>sin costo</b>. Úsalos durante toda la exposición, no solo cuando sientas calor."},{"s":"uv_bloq","t":"Bloqueador solar","x":"Usa bloqueador <b>FPS 30 o más</b> en cara, orejas, cuello, nuca y manos. Aplícalo unos <b>20 a 30 minutos antes</b> de salir al sol y <b>reaplícalo cada 2 a 3 horas</b>, y más seguido si sudas mucho o te secas la cara con la toalla. No reemplaza a la ropa ni a la sombra: es una barrera más. Si se te acaba, avisa para que te repongan."},{"s":"cc6_uv_cond","t":"Conductores y peonetas","x":"En la ruta, el <b>brazo apoyado en la ventana</b> y la cara reciben sol por horas: el vidrio lateral no siempre filtra la radiación UV. En las entregas esperas y descargas al aire libre.<ul><li>Manga larga y lentes con filtro UV también al conducir.</li><li>Bloqueador en cara, cuello, orejas y manos.</li><li>Lleva agua y espera a la sombra cuando puedas.</li></ul>"},{"s":"uv_ley","t":"Qué dice la normativa","x":"La <b>Ley 20.096</b> (artículo 19) obliga al empleador a adoptar medidas para proteger a quienes trabajan expuestos a radiación UV. El <b>DS 594</b> (artículos 109 a, 109 b y 109 c) y la <b>Guía Técnica de Radiación UV de Origen Solar</b> del MINSAL detallan esas medidas: informar el riesgo y el índice UV, organizar horarios, dar sombra y entregar EPP. Tu parte: <b>usarlos siempre</b>."},{"s":"cc6_uv_auto","t":"Autocuidado: “es solo un rato”","x":"La mayoría de los accidentes y daños se relacionan con una acción insegura. Con el sol, la típica es pensar <b>“es solo un rato”</b> y salir al patio sin manga larga, legionario ni bloqueador, o sacarse la polera por el calor al cargar. Muchos ratos cortos suman horas de exposición. La decisión segura: <b>protegerte cada vez que sales al sol</b>. Avisar si falta bloqueador también es autocuidado.","k":"Cada exposición suma: protégete cada vez."}],"quiz":[{"s":"cc6_uv_intro","v":[{"q":"¿En qué tareas de la sucursal te expones a la radiación UV?","o":["Patio, carga, despacho, conducción y entregas","Solo en el patio y solo en pleno verano","Solo cuando la temperatura supera los 30 grados","Solo en las entregas largas fuera de la ciudad"],"w":"Toda tarea al aire libre te expone, haga calor o no."},{"q":"Es un día de primavera fresco y con viento, y vas a descargar en el patio. Respecto al sol, ¿qué es correcto?","o":["El índice UV puede ser alto aunque no sienta calor","Si no hay calor, no hay radiación UV","El viento elimina la radiación UV","Solo hay riesgo si el día está despejado y caluroso"],"w":"La radiación UV no se siente como calor: un día fresco puede tener índice alto."},{"q":"¿Por qué la radiación UV es un peligro difícil de notar?","o":["Porque no se ve ni se siente, y el daño se acumula","Porque solo actúa de noche","Porque solo afecta a personas de piel clara","Porque sus efectos duran solo unos días"],"w":"No avisa con calor ni dolor inmediato, y el daño se suma durante toda la vida."}]},{"s":"uv_escala","v":[{"q":"Un índice UV de 8 a 10 corresponde al color:","o":["Rojo: muy alto","Naranjo: alto","Amarillo: moderado","Violeta: extremo"],"w":"8 a 10 es rojo, riesgo muy alto."},{"q":"El pronóstico indica índice UV 6 para hoy. ¿Qué nivel de riesgo es?","o":["Alto, color naranjo","Moderado, color amarillo","Bajo, color verde","Muy alto, color rojo"],"w":"6 a 7 es naranjo, riesgo alto: hay que protegerse."},{"q":"Con un índice UV de 3, color amarillo, ya hay que protegerse.","vf":true,"w":"Verdadero. Desde 3, amarillo, se recomienda usar protección."}]},{"s":"uv_horario","v":[{"q":"En verano, ¿en qué horario la radiación UV es mayor?","o":["Aproximadamente de 10:00 a 17:00","De 7:00 a 10:00","De 12:00 a 13:00 solamente","De 17:00 a 20:00"],"w":"Es cuando el sol está más alto en el cielo."},{"q":"Al mediodía en el patio notas que tu sombra es más corta que tú. ¿Qué significa?","o":["Que el sol está fuerte y debo protegerme","Que el sol está bajo y hay poco riesgo","Que pronto se nublará","Que la radiación ya va bajando"],"w":"Sombra más corta que tú: el sol está alto y la radiación es fuerte."},{"q":"Tienes que descargar un camión de cerámicas al sol y puedes elegir la hora. ¿Cuál es la mejor opción?","o":["Temprano en la mañana o al final de la tarde","A las 13:00, para terminar antes de la tarde","A las 15:00, cuando ya pasó el mediodía","Da igual la hora si uso bloqueador"],"w":"Fuera de las 10:00 a 17:00 la radiación es menor."}]},{"s":"uv_nublado","v":[{"q":"Está nublado y vas a cargar en el patio toda la mañana. ¿Qué haces?","o":["Me protejo igual: las nubes no detienen toda la radiación","No me protejo: con nubes no hay radiación UV","Me protejo solo si sale el sol","Uso solo lentes, porque la piel no se quema"],"w":"En un día nublado igual te puedes quemar."},{"q":"¿Por qué en el patio de cemento la radiación puede ser mayor?","o":["Las superficies claras reflejan la radiación","El cemento genera su propia radiación UV","El cemento absorbe toda la radiación del sol","No influye: solo importa el sol directo"],"w":"Cemento, arena y planchas metálicas reflejan parte de la radiación hacia la cara."},{"q":"Si el día está nublado, no hay radiación UV.","vf":false,"w":"Falso. Las nubes no detienen toda la radiación UV."}]},{"s":"uv_bloq","v":[{"q":"¿Cada cuánto se debe reaplicar el bloqueador solar?","o":["Cada 2 a 3 horas, y más seguido si sudo","Una vez al día, en la mañana","Cada 6 horas","Solo cuando la piel se pone roja"],"w":"El bloqueador pierde efecto con el sudor, el roce y el tiempo."},{"q":"¿Qué factor de protección se recomienda como mínimo?","o":["FPS 30 o más","FPS 10","FPS 15","Cualquiera, si se aplica varias veces"],"w":"Se recomienda FPS 30 o superior."},{"q":"Vas a salir a cargar camiones a las 10:00. ¿Cuándo te aplicas el bloqueador?","o":["Unos 20 a 30 minutos antes de salir","Cuando ya llevo una hora al sol","Solo cuando empiece a sentir calor","Al terminar, para calmar la piel"],"w":"Aplicarlo antes de salir le da tiempo de actuar."}]},{"s":"uv_bien","v":[{"q":"¿Qué combinación protege bien del sol al trabajar en el patio?","o":["Manga larga, legionario, lentes con filtro UV y bloqueador","Polera, jockey y bloqueador una vez al día","Manga corta y bloqueador cada 2 a 3 horas","Manga larga y casco, sin lentes ni bloqueador"],"w":"Ropa, legionario, lentes y bloqueador se complementan."},{"q":"Un compañero trabaja con manga larga y bloqueador, pero sin legionario ni lentes. ¿Qué le falta proteger?","o":["Orejas, cuello y ojos","Solo las manos","Nada, ya está protegido","Solo la frente"],"w":"El legionario cubre orejas y cuello; los lentes con filtro UV, los ojos."},{"q":"¿Qué trabajador está bien protegido del sol?","o":["El que usa manga larga, legionario y lentes con filtro UV","El que usa polera y lentes oscuros comunes","El que usa casco y se arremanga por el calor","El que se aplicó bloqueador al llegar y nada más"],"w":"La protección completa combina ropa, legionario, lentes con filtro UV y bloqueador."}]},{"s":"uv_ropa","v":[{"q":"¿Para qué sirve el legionario o cubrenuca?","o":["Protege orejas y cuello del sol","Reemplaza al casco en el patio","Solo protege del polvo","Evita que el casco se caiga"],"w":"Cubre zonas que el casco o el jockey dejan expuestas."},{"q":"¿Qué tipo de lentes protegen los ojos de la radiación UV?","o":["Lentes con filtro UV","Cualquier lente oscuro","Lentes transparentes sin filtro","Lentes de lectura"],"w":"Un lente oscuro sin filtro UV puede dañar más, porque dilata la pupila."},{"q":"Si usas casco, no necesitas legionario.","vf":false,"w":"Falso. El casco no cubre orejas ni cuello: el legionario va bajo el casco."}]},{"s":"cc6_uv_cond","v":[{"q":"Manejas el camión con el brazo apoyado en la ventana todo el día. ¿Qué haces?","o":["Uso manga larga y bloqueador también al conducir","Nada: dentro de la cabina no llega el sol","Me protejo solo en las entregas","Me protejo solo los días de calor"],"w":"El brazo y la cara reciben sol por horas en la ruta."},{"q":"Como peoneta esperas al cliente en una obra al aire libre durante una hora. ¿Qué es lo correcto?","o":["Esperar a la sombra, protegido y con agua","Esperar al sol para que el cliente me vea","Esperar en polera para no pasar tanto calor","Sacarme el legionario mientras dure la espera"],"w":"Las esperas al aire libre también son exposición al sol."},{"q":"¿Por qué un conductor se expone al sol aunque vaya dentro de la cabina?","o":["Porque el vidrio lateral no siempre filtra la radiación UV","Porque el motor genera radiación","No se expone: la cabina lo protege por completo","Solo se expone si maneja de noche"],"w":"La radiación entra por las ventanas, sobre todo con el brazo afuera."}]},{"s":"uv_efectos","v":[{"q":"Notas que un lunar del brazo cambió de color y tamaño. ¿Qué haces?","o":["Pido que lo revise un médico","Lo cubro con bloqueador y lo olvido","Espero a que vuelva a su color normal","Lo reviso solo si me duele"],"w":"Un lunar que cambia puede ser señal de cáncer de piel: debe verlo un médico."},{"q":"¿Cuál de estos es un efecto de la exposición acumulada al sol durante años?","o":["Cáncer de piel y cataratas","Resfríos y dolor de garganta","Dolor de espalda y lumbago","Pérdida de audición y zumbido"],"w":"El daño solar se suma: puede causar cáncer de piel y lesiones en los ojos."},{"q":"Los efectos de la radiación UV incluyen quemaduras, daño ocular y cáncer de piel.","vf":true,"w":"Verdadero. Y el daño se acumula con los años."}]},{"s":"cc6_uv_auto","v":[{"q":"Hace calor y vas a cargar un camión “solo un rato”. ¿Qué haces?","o":["Me protejo igual, con ropa, lentes y bloqueador","Me saco la polera mientras cargo por el calor","Salgo sin protección porque es poco tiempo","Me pongo bloqueador solo en la cara y salgo"],"w":"Cada exposición suma: la protección se usa siempre."},{"q":"Durante el día sales al patio diez veces, cinco minutos cada vez. ¿Qué es correcto?","o":["Esos ratos cortos suman casi una hora de sol","Si son ratos cortos, no hay exposición","Solo cuenta si son más de 30 minutos seguidos","El sol solo daña en exposiciones largas"],"w":"Muchos ratos cortos suman horas de exposición."},{"q":"Se te acabó el bloqueador a mitad de la jornada. ¿Qué haces?","o":["Aviso para que me repongan y uso ropa y sombra","Sigo sin bloqueador hasta mañana, que traigo","Me pongo crema de manos, que también protege","Me arremango para transpirar menos y sigo"],"w":"Avisar también es autocuidado; la ropa y la sombra siguen protegiendo."}]}]},{"id":"enfermedades","sec":"todos","title":"Efectos en la salud y enfermedades profesionales","thumb":"cc6_en_lumbago","learn":[{"s":"cc6_en_vs","t":"Accidente y enfermedad profesional","x":"Un <b>accidente</b> del trabajo ocurre de golpe: un saco que cae, un corte con una plancha. Una <b>enfermedad profesional</b> (Ley 16.744, artículo 7) es la causada de manera directa por el ejercicio de tu trabajo y que te produce incapacidad o muerte. Aparece de a poco, a veces después de años, y casi siempre <b>sin dolor al comienzo</b>. Por eso se previene antes de sentir molestias."},{"s":"c5ca_limites","t":"Espalda: límites de carga","x":"Sacos de cemento, cerámicas, fierro y planchas se cargan todo el día, y la columna se daña de a poco. Si no se pueden usar ayudas mecánicas, la <b>Ley 20.949</b> fija como máximo:<ul><li><b>25 kg</b> para hombres adultos.</li><li><b>20 kg</b> para mujeres y menores de 18 años.</li><li><b>Embarazadas: no pueden cargar ni descargar</b> manualmente.</li></ul>Bajo esos pesos igual debes usar buena técnica: el límite no es una meta.","k":"Más de 25 kg, o de 20 kg para mujeres y menores: ayuda mecánica."},{"s":"cc6_en_cargar","t":"Cómo prevenir el lumbago","x":"<ul><li>Usa <b>carro, transpaleta o grúa</b> cuando existan.</li><li>Acércate a la carga, <b>dobla las rodillas</b> y mantén la espalda recta.</li><li>Lleva la carga <b>pegada al cuerpo</b> y gira con los pies, no con la cintura.</li><li>Planchas, tubos y perfiles largos: <b>entre dos</b>.</li><li>Antes de levantar, revisa el camino: sin obstáculos ni piso resbaloso.</li></ul>Levantar con la espalda doblada o girando el tronco es la causa típica del lumbago."},{"s":"cc6_en_hombros","t":"Hombros, brazos y manos","x":"Reponer góndolas altas con los brazos sobre los hombros, pasar cientos de productos por la caja o digitar todo el día puede causar <b>tendinitis</b> y dolor de hombros, codos y muñecas. Usa escalera o plataforma para lo alto, deja lo pesado en las repisas de media altura, entre cadera y hombros, y aprovecha las pausas para mover el cuerpo. Avisa si sientes dolor u hormigueo que se repite."},{"s":"cc6_en_cemento","t":"Cemento: dermatitis","x":"El cemento, sobre todo húmedo o mezclado con sudor, es <b>alcalino e irritante</b>. El contacto repetido puede causar <b>dermatitis</b>: piel seca, grietas, picazón o alergia, e incluso quemaduras. Usa <b>guantes</b> al manipular sacos, no toques el polvo de un saco roto con las manos desnudas, no limpies tu piel con diluyente y lávate con agua y jabón antes de comer y al terminar."},{"s":"cc6_en_solventes","t":"Pinturas y solventes","x":"Al preparar pinturas o limpiar un derrame, los <b>vapores</b> de diluyentes y solventes pueden causar mareo, dolor de cabeza y náuseas; el contacto con la piel la reseca e irrita.<ul><li>Mantén los envases cerrados.</li><li>Trabaja con ventilación.</li><li>Usa los guantes que indica la <b>HDS</b>.</li><li>Nunca te laves las manos con diluyente.</li></ul>Si te mareas, sal a tomar aire y avisa."},{"s":"cc6_en_ruido","t":"Ruido: ojo con los trabajos de terceros","x":"En nuestras labores propias no hay exposición a ruido peligroso. Puede haberla cuando <b>empresas externas</b> trabajan cerca con maquinaria: cortes, obras, demoliciones. El DS 594 fija <b>85 dB(A) para 8 horas</b>, y por cada 3 dB más el tiempo permitido se reduce a la mitad. La pérdida auditiva por ruido es <b>permanente</b>. Si pasa: aléjate y, donde se señalice, usa protector auditivo."},{"s":"cc6_en_mental","t":"Salud mental","x":"El estrés prolongado, la presión constante o el maltrato pueden causar <b>ansiedad, depresión o trastornos del sueño</b>. Las enfermedades de salud mental causadas por el trabajo también pueden calificarse como <b>enfermedad profesional</b>. Quien evalúa es la <b>Mutual de Seguridad CChC</b>, tu organismo administrador. Si te sientes mal, avisa y pide evaluación."},{"s":"enfermedades_diep","t":"Si crees que es por el trabajo","x":"Avisa a tu jefatura. {EMP} debe hacer la <b>DIEP</b> (Denuncia Individual de Enfermedad Profesional) y derivarte a la <b>Mutual de Seguridad CChC</b> (fono 1407), que evalúa si es de origen laboral. Si la empresa no la hace, <b>puedes presentarla tú</b> directamente en la Mutual. Si se califica como profesional, la Ley 16.744 cubre la atención gratuita y las prestaciones.","k":"La DIEP inicia la evaluación de tu enfermedad."},{"s":"cc6_en_auto","t":"Autocuidado: “es uno no más”","x":"Las acciones inseguras típicas: levantar <b>“un saco no más”</b> con la espalda doblada, cargar solo una plancha larga, tocar cemento sin guantes, ignorar un dolor que se repite o faltar al examen de salud. El daño se suma día a día. La decisión segura: <b>usar la ayuda mecánica, pedir ayuda y protegerte siempre</b>. Avisa si falta un carro o tu EPP está malo."}],"quiz":[{"s":"cc6_en_vs","v":[{"q":"Según la Ley 16.744, una enfermedad profesional es:","o":["La causada de manera directa por el trabajo que realizas","Cualquier enfermedad que aparezca mientras trabajas","Una lesión que ocurre de golpe en el trabajo","Solo la que causa dolor desde el primer día"],"w":"Así la define la Ley 16.744, artículo 7: causada directamente por el trabajo."},{"q":"¿Cuál de estos casos es una enfermedad profesional y no un accidente?","o":["Dermatitis por manipular cemento durante años","Un corte con el canto de una plancha de zinc","Un golpe en el pie al caer un saco","Un esguince al bajar del camión"],"w":"La enfermedad aparece de a poco por la exposición; el accidente ocurre de golpe."},{"q":"Una enfermedad profesional siempre da aviso con dolor desde el primer día de exposición.","vf":false,"w":"Falso. Suele aparecer de a poco, a veces después de años, y sin dolor al comienzo."}]},{"s":"c5ca_limites","v":[{"q":"Si no se pueden usar ayudas mecánicas, ¿cuál es la carga manual máxima para un hombre adulto?","o":["25 kg","50 kg","30 kg","20 kg"],"w":"La Ley 20.949 fija 25 kg para hombres adultos."},{"q":"Un cliente compra sacos de 50 kg y un vendedor quiere cargarlos solo al hombro hasta la camioneta. ¿Qué es lo correcto?","o":["Usar carro o ayuda mecánica: supera los 25 kg","Cargarlo solo si tiene buena técnica","Cargarlo si es solo un saco","Cargarlo entre dos solo si son más de cinco"],"w":"Sobre 25 kg no se carga manualmente: se usa ayuda mecánica."},{"q":"¿Qué significa el límite de 25 kg para un hombre adulto?","o":["Es el máximo, y bajo ese peso igual se usa buena técnica","Es la carga mínima que debe levantar cada vez","Es el peso ideal para trabajar más rápido","Se puede superar si el trabajador es fuerte"],"w":"El límite no es una meta: bajo 25 kg también se cuida la técnica."}]},{"s":"c5ca_limites","v":[{"q":"Para mujeres y menores de 18 años, la carga manual máxima es:","o":["20 kg","25 kg","15 kg","30 kg"],"w":"La Ley 20.949 fija 20 kg para mujeres y menores de 18 años."},{"q":"Una compañera embarazada debe reponer cajas de cerámica en la bodega. Respecto a la carga manual, ¿qué es correcto?","o":["No puede cargar ni descargar manualmente","Puede cargar hasta 20 kg, como toda mujer","Puede cargar hasta 10 kg por cada caja","Puede cargar si usa faja lumbar y va lento"],"w":"Las embarazadas no pueden realizar carga y descarga manual."},{"q":"Un ayudante de 17 años debe mover sacos de cemento de 25 kg. ¿Qué es lo correcto?","o":["No cargarlos a mano: supera su límite de 20 kg","Puede cargarlos si son pocos","Puede cargarlos si dobla las rodillas","Puede cargarlos porque son de 25 kg exactos"],"w":"Para menores de 18 años el máximo es 20 kg."}]},{"s":"cc6_en_ok","v":[{"q":"¿Cuál es la forma correcta de levantar un saco desde el piso?","o":["Rodillas dobladas, espalda recta y carga pegada al cuerpo","Piernas rectas y espalda doblada hacia adelante","Espalda recta pero con los brazos estirados","Levantar rápido de un tirón para no cansarse"],"w":"Las piernas hacen la fuerza y la columna se mantiene recta."},{"q":"Llevas un saco y debes dejarlo a tu lado en el pallet. ¿Cómo giras?","o":["Moviendo los pies, sin torcer la cintura","Girando la cintura con los pies fijos","Girando rápido para soltarlo antes","Lanzando el saco al pallet"],"w":"Girar el tronco con carga es una causa típica de lumbago."},{"q":"Antes de levantar un saco desde el piso, ¿cómo te ubicas?","o":["Cerca de la carga, para llevarla pegada","Lejos de la carga, con los brazos estirados","De lado, para girar al momento de levantar","Con las piernas juntas y las rodillas rectas"],"w":"Acercarse a la carga reduce el esfuerzo sobre la columna."}]},{"s":"cc6_en_cemento","v":[{"q":"Se rompe un saco de cemento en la bodega. ¿Qué haces?","o":["Uso guantes para limpiar y me lavo al terminar","Lo junto con las manos rápido","Lo limpio y me lavo las manos con diluyente","Lo dejo para que lo barra otro turno"],"w":"El polvo de cemento es irritante: guantes y lavado con agua y jabón."},{"q":"¿Por qué el cemento húmedo daña la piel?","o":["Porque es alcalino e irritante","Porque es inflamable","Porque tiene restos de metal","Solo daña si se traga"],"w":"Su alcalinidad irrita la piel y puede causar dermatitis y quemaduras."},{"q":"El cemento húmedo en contacto con la piel puede causar dermatitis.","vf":true,"w":"Verdadero. Es alcalino e irritante: usa guantes y lávate las manos."}]},{"s":"cc6_en_solventes","v":[{"q":"Preparas pintura y sientes mareo por el olor del diluyente. ¿Qué haces?","o":["Salgo a ventilar, cierro los envases y aviso","Sigo igual, ya se pasará","Tomo un café y continúo","Me pongo una mascarilla de papel y sigo"],"w":"El mareo es señal de exposición a vapores: sal, ventila y avisa."},{"q":"Terminaste de entintar pintura y tienes las manos manchadas. ¿Cómo te limpias?","o":["Con agua y jabón, nunca con diluyente","Con diluyente, que saca toda la pintura","Con un paño con aguarrás y luego agua","Con bencina blanca, que es más suave"],"w":"El diluyente reseca e irrita la piel y se absorbe."},{"q":"¿Qué guantes usas para limpiar un derrame de solvente?","o":["Los que indica la HDS del producto","Cualquier guante de algodón","Guantes de cuero de carga","No hace falta si es poco"],"w":"La Hoja de Datos de Seguridad indica el guante que resiste ese producto."}]},{"s":"cc6_en_hombros","v":[{"q":"Debes reponer cajas pesadas en la repisa más alta. ¿Qué es lo correcto?","o":["Usar escalera o plataforma y dejar lo pesado a media altura","Estirarme en puntillas con la caja sobre la cabeza","Subirme a la repisa de abajo","Lanzar la caja hacia arriba"],"w":"Trabajar con los brazos sobre los hombros daña hombros y espalda."},{"q":"¿A qué altura conviene dejar los productos más pesados de la góndola?","o":["En las repisas medias, entre cadera y hombros","En la repisa más alta, para ahorrar espacio","En el piso, para no levantarlos","Da igual, si se usa escalera"],"w":"A media altura se evitan posturas forzadas de espalda y hombros."},{"q":"Eres cajero y hace semanas sientes dolor y hormigueo en la muñeca al final del turno. ¿Qué haces?","o":["Aviso, hago pausas activas y pido evaluación","Lo aguanto hasta que lleguen mis vacaciones","Me pongo una muñequera y no digo nada","Trabajo más rápido para terminar antes"],"w":"El dolor que se repite puede ser tendinitis: avisar permite tratarla a tiempo."}]},{"s":"cc6_en_mental","v":[{"q":"¿Quién evalúa si una enfermedad de salud mental es de origen laboral?","o":["La Mutual de Seguridad CChC","Tu jefatura directa","Un compañero del Comité","Nadie, porque no puede ser laboral"],"w":"La Mutual, como organismo administrador, califica el origen de la enfermedad."},{"q":"¿Cuál de estas puede ser una enfermedad de salud mental relacionada con el trabajo?","o":["Ansiedad por presión constante o maltrato","Un resfrío por cambios bruscos de clima","Un esguince de tobillo al bajar del camión","Una alergia estacional al polen"],"w":"El estrés prolongado y el maltrato pueden causar ansiedad, depresión o trastornos del sueño."},{"q":"Una enfermedad de salud mental nunca puede ser enfermedad profesional.","vf":false,"w":"Falso. Si la causa el trabajo, puede calificarse como profesional."}]},{"s":"enfermedades_diep","v":[{"q":"La sigla DIEP significa:","o":["Denuncia Individual de Enfermedad Profesional","Declaración Interna de Exámenes Preventivos","Denuncia Inmediata de Emergencia Personal","Documento de Inspección de Equipos Protectores"],"w":"Con ella se inicia la evaluación en la Mutual de Seguridad CChC."},{"q":"Crees que tu dolor de espalda es por el trabajo. ¿Qué es lo primero?","o":["Avisar a mi jefatura para que se haga la DIEP","Ir a mi médico particular y pagarlo","Esperar a que sea más grave","Pedir vacaciones para descansar"],"w":"La empresa debe hacer la DIEP y derivarte a la Mutual para evaluarte."},{"q":"Si tu empresa no hace la DIEP, puedes presentarla tú directamente en la Mutual.","vf":true,"w":"Verdadero. El trabajador también puede presentar la denuncia."}]},{"s":"enfermedades_senales","v":[{"q":"Hace semanas tienes picazón y grietas en las manos. ¿Qué haces?","o":["Lo aviso a mi jefatura o al asesor","Lo aguanto hasta que se pase solo","Me limpio las manos con diluyente","Me pongo crema y no le digo a nadie"],"w":"Es una señal de alerta: avisar permite evaluarla a tiempo."},{"q":"¿Cuál de estas es una señal de alerta de enfermedad profesional?","o":["Una molestia que se repite cada vez que haces una tarea","Un cansancio después de un día de inventario","Hambre antes de la colación","Sueño después de almorzar"],"w":"Las molestias repetidas ligadas a una tarea pueden indicar una enfermedad en desarrollo."},{"q":"Tu compañero tose y tiene picazón en la piel desde que manipula un adhesivo nuevo. ¿Qué le aconsejas?","o":["Que avise para revisar el producto y su protección","Que siga, porque ya se acostumbrará","Que se cambie de guantes sin decir nada","Que use otro adhesivo sin avisar"],"w":"Avisar a tiempo permite revisar la exposición y evaluar su salud."}]}]},{"id":"psicosocial","sec":"todos","title":"Riesgos psicosociales y bienestar en el trabajo","thumb":"cc6_ps_publico","learn":[{"s":"cc6_ps_intro","t":"¿Qué son los riesgos psicosociales?","x":"Son condiciones de la <b>organización del trabajo</b> y de las relaciones que pueden dañar la salud mental y física. No se ven como un rack cargado, pero también lesionan: filas de clientes sin respiro, metas imposibles, órdenes confusas o malos tratos pueden enfermar. El <b>DS 44</b> exige a la empresa identificarlos y gestionarlos igual que los demás riesgos."},{"s":"psico_factores","t":"Factores que influyen","x":"<ul><li><b>Carga y ritmo</b> de trabajo.</li><li><b>Claridad:</b> saber qué se espera de ti y quién te da las órdenes.</li><li><b>Apoyo</b> de compañeros y jefatura.</li><li><b>Buen trato</b> y respeto.</li><li><b>Equilibrio</b> entre trabajo y vida personal.</li></ul>Cuando estos factores están bien, el trabajo protege la salud; cuando fallan por mucho tiempo, la dañan."},{"s":"cc6_ps_publico","t":"Atención de público","x":"Atender a clientes apurados, molestos o que reclaman exige controlar las emociones todo el día. Para cuidarte:<ul><li>Escucha, mantén la calma y no lo tomes como algo personal.</li><li>Si la situación te supera, <b>pide apoyo</b> a un compañero o a tu jefatura.</li><li>Si hay insultos o amenazas, es violencia en el trabajo: se informa y se denuncia según la Ley Karin.</li></ul>"},{"s":"cc6_ps_metas","t":"Metas de venta y presión","x":"Si tu cargo tiene <b>metas</b>, deben ser claras y conocidas. Una meta exigente puede motivar; una presión permanente, sin respiro, termina dañando. Si no alcanzas, <b>conversa a tiempo</b> con tu jefatura: qué es prioritario y cómo lograrlo. Saltarse pasos de seguridad para vender o despachar más nunca es la solución, y nadie puede exigírtelo.","k":"Ninguna meta vale más que tu salud o tu seguridad."},{"s":"cc6_ps_turnos","t":"Turnos, jornada y descanso","x":"Los turnos de fin de semana, la temporada alta, los inventarios o los despachos tarde pueden desordenar el sueño y la vida familiar.<ul><li><b>Respeta tus descansos</b> y la hora de colación.</li><li>Duerme lo suficiente antes de conducir u operar la grúa: se recomiendan entre 7 y 8 horas.</li><li>Si la carga horaria te supera, conversa con tu jefatura.</li></ul>"},{"s":"psico_senales","t":"Señales de alerta","x":"<ul><li>Cansancio que no se pasa con el descanso.</li><li>Problemas para dormir.</li><li>Irritabilidad o ganas de llorar.</li><li>Dolores de cabeza, de espalda o de estómago sin otra causa.</li><li>Más errores y olvidos de lo normal.</li><li>No querer ir a trabajar.</li></ul>El estrés también enferma el cuerpo. Si lo notas en ti o en un compañero, no lo ignores: conversa y pide apoyo."},{"s":"cc6_ps_equipo","t":"Equipo y buen trato","x":"Un equipo que se ayuda trabaja mejor y más seguro: apoyar en la fila de la caja, cargar entre dos, explicarle la tarea al nuevo, preguntar “¿cómo estás?”. Gritos, burlas o humillaciones dañan la salud y pueden ser <b>acoso laboral</b> según la Ley Karin. Los errores se corrigen <b>en privado y con respeto</b>, explicando cómo hacerlo bien."},{"s":"psico_ceal","t":"El cuestionario CEAL-SM/SUSESO","x":"El <b>Protocolo de Vigilancia de Riesgos Psicosociales en el Trabajo</b> del MINSAL usa el cuestionario <b>CEAL-SM/SUSESO</b>, que reemplazó al ISTAS21. Evalúa las condiciones del trabajo, <b>no a las personas</b>. Cuando corresponda aplicarlo en tu centro de trabajo, tu participación es <b>anónima y voluntaria</b>, y tus respuestas son confidenciales. Con los resultados se definen medidas para mejorar."},{"s":"cc6_ps_ayuda","t":"¿A quién recurrir?","x":"<ul><li>A tu <b>jefatura</b>.</li><li>Al <b>Comité Paritario</b>, si tu sucursal o empresa lo tiene, o al <b>asesor en prevención</b>.</li><li>Si el malestar se debe al trabajo, la <b>Mutual de Seguridad CChC</b> (fono 1407), tu organismo administrador, puede evaluarlo dentro del seguro de la Ley 16.744.</li></ul>Pedir ayuda a tiempo no es debilidad: es una decisión responsable."},{"s":"cc6_ps_auto","t":"Autocuidado: cansado o apurado, el riesgo sube","x":"La mayoría de los accidentes se relacionan con una acción insegura, y el estrés y el cansancio las hacen más probables: te apuras, te saltas un paso, te distraes al volante o en la grúa. La decisión segura: <b>reconocer que no estás bien y avisar</b>. Respeta los descansos; si tienes sueño conduciendo, <b>detente en un lugar seguro</b> y avisa. Abrir la ventana o subir la radio no quita el sueño.","k":"Si no estás bien, dilo antes de conducir u operar."}],"quiz":[{"s":"psico_factores","v":[{"q":"Los riesgos psicosociales se relacionan con:","o":["La organización del trabajo y las relaciones","Solo las máquinas y herramientas","Solo el clima y la temperatura","Solo la vida personal del trabajador"],"w":"Carga, ritmo, claridad, apoyo y trato son factores psicosociales."},{"q":"¿Cuál de estos es un factor de riesgo psicosocial?","o":["Recibir órdenes contradictorias","Un piso mojado en la sala de ventas","Un rack sobrecargado en la bodega","Una grúa horquilla sin bocina"],"w":"La falta de claridad en el trabajo es un factor psicosocial."},{"q":"Un vendedor trabaja con buen apoyo del equipo, tareas claras y trato respetuoso. ¿Qué efecto tiene en su salud?","o":["El trabajo protege su salud","No influye en su salud","Solo influye en sus ventas","Lo daña igual por la atención de público"],"w":"Cuando los factores están bien, el trabajo protege la salud."}]},{"s":"psico_ceal","v":[{"q":"Cuando corresponda aplicar el cuestionario CEAL-SM en tu centro de trabajo, tu participación es:","o":["Anónima y voluntaria","Con nombre y RUT","Obligatoria y con nota","Revisada por tu jefatura"],"w":"Es anónima y voluntaria, para que puedas responder con sinceridad."},{"q":"¿Qué evalúa el cuestionario CEAL-SM/SUSESO?","o":["Las condiciones del trabajo, no a las personas","El desempeño de cada trabajador","Las ventas de la sucursal","La salud mental de cada persona por separado"],"w":"Evalúa las condiciones de la organización del trabajo."},{"q":"Para responder el cuestionario CEAL-SM debes escribir tu nombre y RUT.","vf":false,"w":"Falso. La participación es anónima y las respuestas son confidenciales."}]},{"s":"psico_ceal","v":[{"q":"¿Qué instrumento usa hoy el Protocolo de Vigilancia de Riesgos Psicosociales del MINSAL?","o":["El cuestionario CEAL-SM/SUSESO","El cuestionario ISTAS21","Una evaluación de desempeño","Una encuesta de satisfacción de clientes"],"w":"El CEAL-SM/SUSESO reemplazó al ISTAS21."},{"q":"¿Para qué sirven los resultados del cuestionario CEAL-SM?","o":["Para definir medidas que mejoren el trabajo","Para elegir a quién desvincular primero","Para calcular los bonos de venta del año","Para sancionar a quienes respondan mal"],"w":"Con los resultados se definen medidas para mejorar el trabajo."},{"q":"El cuestionario CEAL-SM/SUSESO reemplazó al ISTAS21.","vf":true,"w":"Verdadero. Es el instrumento actual del Protocolo de Vigilancia de Riesgos Psicosociales."}]},{"s":"psico_estres","v":[{"q":"¿Cuál de estos puede ser un efecto físico del estrés laboral prolongado?","o":["Dolores de cabeza, espalda o estómago","Mejor visión y más concentración","Más energía y apetito todo el día","Ninguno: el estrés solo afecta el ánimo"],"w":"El estrés también enferma el cuerpo."},{"q":"Un compañero tiene dolores de estómago frecuentes desde que empezó la temporada alta. ¿Qué podría estar pasando?","o":["Puede ser una señal física de estrés","Seguro es algo que comió","Es imposible que sea por el trabajo","Es flojera para trabajar"],"w":"El estrés puede manifestarse con dolores sin otra causa."},{"q":"El estrés laboral nunca afecta la salud física.","vf":false,"w":"Falso. Puede causar dolores, problemas de sueño y más."}]},{"s":"psico_senales","v":[{"q":"¿Cuál es una señal de alerta de estrés?","o":["Problemas para dormir e irritabilidad","Dormir bien y tener energía","Tener hambre a la hora de colación","Cansancio después de un día de inventario"],"w":"Son señales para prestar atención y pedir apoyo."},{"q":"Notas que estás cometiendo más errores en la caja y olvidas cosas. ¿Qué haces?","o":["Lo reconozco como una señal y lo converso","Lo ignoro, ya se pasará","Trabajo más horas para compensar","Lo escondo para que nadie lo note"],"w":"Más errores y olvidos de lo normal pueden ser señal de estrés."},{"q":"Un compañero anda irritable, cansado y dice que no quiere venir a trabajar. ¿Qué haces?","o":["Le pregunto cómo está y lo animo a pedir apoyo","No me meto, es su problema","Le digo que se esfuerce más","Lo comento con los demás para que lo sepan"],"w":"Si notas señales en un compañero, no las ignores."}]},{"s":"cc6_ps_publico","v":[{"q":"Un cliente reclama a gritos en el mesón y la situación te supera. ¿Qué haces?","o":["Mantengo la calma y pido apoyo","Le respondo en el mismo tono para calmarlo","Me quedo callado y lo aguanto solo","Le digo que vuelva otro día más tranquilo"],"w":"Pedir apoyo a tiempo te protege. Si hay insultos o amenazas, se informa."},{"q":"Un cliente apurado te reclama por la demora del despacho. ¿Cuál es la mejor actitud?","o":["Escucharlo con calma, sin tomarlo personal","Discutirle con argumentos hasta que entienda","Ignorarlo y atender al siguiente cliente","Explicarle que la culpa es de la bodega"],"w":"Escuchar y no tomarlo personal ayuda a manejar la emoción."},{"q":"Un cliente insulta y amenaza a un vendedor. Además de pedir apoyo, ¿qué corresponde?","o":["Informarlo y denunciarlo por Ley Karin","Nada, porque es parte de atender público","Que el vendedor lo resuelva por su cuenta","Ofrecerle un descuento para que se calme"],"w":"Insultos y amenazas son violencia en el trabajo: se informan y se denuncian."}]},{"s":"cc6_ps_metas","v":[{"q":"No alcanzas tu meta del mes y te sientes presionado. ¿Qué es lo correcto?","o":["Conversar a tiempo con mi jefatura sobre prioridades","Saltarme pasos de seguridad para vender más","No decir nada y trabajar hasta agotarme","Quedarme sin colación para vender más"],"w":"Hablar a tiempo permite ordenar prioridades sin arriesgarse."},{"q":"Para despachar más rápido, te sugieren cargar el camión sin amarrar la carga. ¿Qué haces?","o":["No me salto la seguridad aunque se atrase","Lo hago si es un viaje corto dentro de la ciudad","Lo hago solo esta vez, porque hay mucho pedido","Lo hago si el cliente está muy apurado"],"w":"Ninguna meta vale más que tu salud o tu seguridad, y nadie puede exigirte saltarte pasos."},{"q":"¿Cómo deben ser las metas de venta de tu cargo?","o":["Claras y conocidas por ti","Secretas, para motivar","Cambiantes cada semana sin aviso","Iguales para todos los cargos"],"w":"Metas claras evitan la presión por incertidumbre."}]},{"s":"psico_respeto","v":[{"q":"¿Cuál es la forma correcta de corregir un error de un compañero?","o":["En privado y con respeto, explicando","Frente a los clientes, para que aprenda","Con un grito, para que no se le olvide","Con una broma, para quitarle peso"],"w":"Corregir con respeto protege la salud y mejora el trabajo."},{"q":"Un compañero etiquetó mal los precios de una góndola. ¿Cómo se lo dices?","o":["En privado: “revisemos juntos cómo se hace”","En voz alta, para que todos aprendan","Por el grupo del trabajo, con una foto","Con un reto, para que no se repita"],"w":"Corregir en privado y explicando cómo hacerlo bien protege la salud y el equipo."},{"q":"Un trabajador nuevo se equivoca al ordenar la bodega. ¿Qué haces?","o":["Le explico con calma cómo se hace","Lo dejo que se equivoque para que aprenda solo","Le aviso a la jefatura que no sirve","Lo corrijo delante de todos"],"w":"Explicar la tarea al nuevo es parte de un buen equipo."}]},{"s":"cc6_ps_ayuda","v":[{"q":"Si tu malestar se debe al trabajo, ¿quién puede evaluarlo dentro del seguro de la Ley 16.744?","o":["La Mutual de Seguridad CChC","Tu isapre o Fonasa","Solo tu jefatura","Un psicólogo particular que pagas tú"],"w":"La Mutual evalúa y atiende según la Ley 16.744."},{"q":"Te sientes sobrepasado por el trabajo hace semanas. ¿A quién puedes recurrir dentro de la empresa?","o":["A mi jefatura, al Comité Paritario o al asesor","Solo a un compañero de confianza, en reserva","A nadie, para que no me vean débil","Solo a recursos humanos de la casa matriz"],"w":"Hay varias vías de apoyo; pedir ayuda a tiempo es responsable."},{"q":"La Mutual de Seguridad CChC puede evaluar si tu malestar es causado por el trabajo.","vf":true,"w":"Verdadero. Es tu organismo administrador del seguro de la Ley 16.744."}]},{"s":"cc6_ps_auto","v":[{"q":"Vas conduciendo el camión y te da mucho sueño. ¿Qué haces?","o":["Me detengo en un lugar seguro y aviso","Sigo para llegar luego y descansar","Abro la ventana y subo la radio","Tomo una bebida energética y sigo"],"w":"El sueño al volante causa accidentes graves; abrir la ventana no lo quita."},{"q":"Dormiste muy poco por un problema familiar y hoy te toca operar la grúa horquilla. ¿Qué haces?","o":["Aviso a mi jefatura antes de operar","Opero igual, con más cuidado","No digo nada para no tener problemas","Opero más rápido para terminar luego"],"w":"Si no estás bien, dilo antes de conducir u operar."},{"q":"¿Por qué el cansancio y el estrés aumentan los accidentes?","o":["Porque te apuras, te saltas pasos y te distraes","No tienen relación con los accidentes","Solo afectan a los conductores","Solo influyen en las ventas"],"w":"El cansancio y el estrés hacen más probables las acciones inseguras."}]}]},{"id":"karin","sec":"todos","title":"Ley Karin: trabajo libre de acoso y violencia","thumb":"cc6_ka_cliente","learn":[{"s":"karin_intro","t":"¿Qué es la Ley Karin?","x":"La <b>Ley 21.643</b>, vigente desde el <b>1 de agosto de 2024</b>, modificó el Código del Trabajo para <b>prevenir, investigar y sancionar</b> tres conductas: el <b>acoso laboral</b>, el <b>acoso sexual</b> y la <b>violencia en el trabajo</b>. Rige para todas las personas: jefaturas, compañeros, practicantes y contratistas. Todos tienen derecho a un trabajo libre de acoso y violencia."},{"s":"karin_sexual","t":"Acoso sexual","x":"Son <b>requerimientos de carácter sexual, en forma indebida y por cualquier medio, no consentidos</b>, que amenacen o perjudiquen la situación laboral o las oportunidades en el empleo de quien los recibe. “Por cualquier medio” incluye comentarios, gestos, miradas insistentes, contacto físico y <b>mensajes o fotos por celular o redes sociales</b>, aunque sea fuera del horario. Basta una vez."},{"s":"karin_laboral","t":"Acoso laboral","x":"Es toda agresión u hostigamiento, por cualquier medio, de la jefatura o de compañeros, que cause menoscabo, maltrato o humillación, o que amenace o perjudique la situación laboral. Con la Ley Karin <b>no requiere reiteración: basta una vez</b>. Ejemplos: gritarle a un vendedor frente a los clientes, humillar, ridiculizar, aislar a alguien o dejarlo sin tareas a propósito."},{"s":"cc6_ka_cliente","t":"Violencia de clientes y proveedores","x":"La ley también cubre la <b>violencia en el trabajo</b> ejercida por <b>terceros</b>: clientes, proveedores o usuarios. Por ejemplo, un cliente que insulta o amenaza al cajero por una devolución, o el chofer de un proveedor que agrede a un bodeguero en la recepción. No es “parte del trabajo”: {EMP} debe prevenirla y tú puedes denunciarla."},{"s":"cc6_ka_actuar","t":"Ante un cliente agresivo","x":"<ul><li>Mantén la calma y <b>no respondas</b> a la agresión.</li><li>Pon <b>distancia</b>: el mesón entre ustedes y una salida libre a tu espalda.</li><li><b>Pide apoyo</b> a un compañero o a tu jefatura.</li><li>Si hay amenaza o agresión física, llama al <b>133</b>.</li><li>Después, <b>informa</b> lo ocurrido: fecha, hora, qué dijo o hizo y testigos.</li></ul>Si te agreden trabajando, es <b>accidente del trabajo</b>: atiéndete en la Mutual de Seguridad CChC.","k":"Calma, distancia, apoyo y aviso."},{"s":"karin_protocolo","t":"Protocolo y Reglamento Interno","x":"El empleador debe tener un <b>protocolo de prevención</b> del acoso sexual, el acoso laboral y la violencia en el trabajo (Código del Trabajo, artículo 211-A), y un <b>procedimiento de investigación</b> en el Reglamento Interno. Debe darlos a conocer a todos los trabajadores. Tienes derecho a conocerlos: pregunta a tu jefatura dónde están y cuáles son los canales de denuncia."},{"s":"karin_denuncia","t":"Cómo denunciar","x":"La denuncia se presenta <b>ante el empleador</b> o ante la <b>Inspección del Trabajo</b>, por escrito o verbalmente. Es <b>reservada</b>: se cuida la intimidad de las personas. Cuenta qué pasó, cuándo, dónde y quién lo vio. La investigación tiene un plazo máximo de <b>30 días</b>. No se permiten <b>represalias</b> contra quien denuncia o declara como testigo.","k":"Denunciar es un derecho protegido, y la denuncia es reservada."},{"s":"karin_resguardo","t":"Medidas de resguardo","x":"Al recibir una denuncia, el empleador debe adoptar <b>de inmediato medidas de resguardo</b> para proteger a la persona denunciante, considerando la gravedad de los hechos, por ejemplo:<ul><li>Separar los espacios físicos.</li><li>Redistribuir la jornada.</li><li>Derivar a <b>atención psicológica temprana</b> en la Mutual de Seguridad CChC.</li></ul>Estas medidas no son una sanción: protegen mientras se investiga."},{"s":"karin_testigo","t":"No seas testigo silencioso","x":"Si ves una situación de acoso o violencia:<ul><li>No participes, no te rías ni la compartas.</li><li>Acompaña a la persona afectada y pregúntale cómo está.</li><li>Oriéntala sobre cómo denunciar.</li><li>Si te citan como testigo, cuenta lo que viste: estás protegido contra represalias.</li></ul>El silencio permite que el maltrato continúe."},{"s":"karin_auto","t":"Autocuidado: la “broma” que daña","x":"Así como la mayoría de los accidentes se relacionan con una acción insegura, el acoso suele empezar con conductas que se normalizan: bromas pesadas, sobrenombres, comentarios sobre el cuerpo, reenviar fotos de un compañero. La decisión segura: <b>parar, no reenviar, respetar el “no”</b> y avisar. Un equipo que se respeta también se avisa los peligros."}],"quiz":[{"s":"karin_intro","v":[{"q":"¿Desde cuándo rige la Ley Karin, Ley 21.643?","o":["Desde el 1 de agosto de 2024","Desde el 1 de enero de 2024","Desde el 1 de febrero de 2025","Desde el 1 de agosto de 2023"],"w":"Rige desde el 1 de agosto de 2024."},{"q":"¿Qué tres conductas busca prevenir, investigar y sancionar la Ley Karin?","o":["Acoso laboral, acoso sexual y violencia en el trabajo","Acoso laboral, atrasos y faltas de respeto","Robos, peleas y acoso sexual","Solo el acoso sexual entre compañeros"],"w":"La ley cubre acoso laboral, acoso sexual y violencia en el trabajo."},{"q":"¿A quiénes protege la Ley Karin dentro de la sucursal?","o":["A todas las personas que trabajan, sin importar su cargo","Solo a los trabajadores con contrato indefinido","Solo a las mujeres","Solo a quienes atienden público"],"w":"Todas las personas tienen derecho a un trabajo libre de acoso y violencia."}]},{"s":"karin_laboral","v":[{"q":"Un jefe humilla una sola vez a un bodeguero frente a todo el equipo. Según la Ley Karin, ¿puede ser acoso laboral?","o":["Sí, basta una sola vez","No, debe repetirse al menos tres veces","No, si fue por un error del bodeguero","Solo si queda grabado"],"w":"Con la Ley Karin el acoso laboral no requiere reiteración."},{"q":"¿Cuál de estas conductas puede ser acoso laboral?","o":["Dejar a alguien sin tareas para aislarlo","Pedir que se cumpla el horario de trabajo","Corregir un error en privado y con respeto","Asignar los turnos según la planificación"],"w":"Aislar, humillar o ridiculizar causa menoscabo y puede ser acoso laboral."},{"q":"Para que exista acoso laboral, la conducta debe repetirse varias veces.","vf":false,"w":"Falso. Con la Ley Karin basta una sola vez."}]},{"s":"karin_sexual","v":[{"q":"Un compañero envía mensajes de carácter sexual por celular a una colega, que no los quiere. Eso puede ser:","o":["Acoso sexual","Algo privado, porque fue por celular","Violencia de terceros","Solo una falta si ocurre en horario de trabajo"],"w":"Son requerimientos sexuales no consentidos, por cualquier medio, incluido el celular."},{"q":"¿Qué incluye “por cualquier medio” en la definición de acoso sexual?","o":["Palabras, gestos, contacto, mensajes o fotos","Solo el contacto físico no consentido","Solo lo que ocurre dentro de la sucursal","Solo lo que queda por escrito en papel"],"w":"El acoso sexual puede darse por palabras, gestos, contacto o medios digitales."},{"q":"Un vendedor hace comentarios insistentes sobre el cuerpo de una cajera, y ella le pidió que parara. ¿Qué es correcto?","o":["Puede ser acoso sexual, porque no hay consentimiento","Es una broma si él no tiene mala intención","Solo es acoso si la toca","Solo es acoso si lo hace un jefe"],"w":"Lo que importa es que la conducta sexual no es consentida."}]},{"s":"cc6_ka_cliente","v":[{"q":"Un cliente insulta y amenaza a una cajera por una devolución. Eso es:","o":["Violencia en el trabajo ejercida por un tercero","Algo normal de la atención de público","Acoso sexual","Acoso laboral entre compañeros"],"w":"La Ley Karin cubre la violencia de clientes, proveedores y usuarios."},{"q":"¿Quiénes pueden ejercer violencia en el trabajo según la Ley Karin, además de jefaturas y compañeros?","o":["Clientes, proveedores y usuarios","Nadie más: solo personas de la empresa","Solo los clientes frecuentes","Solo personas con antecedentes"],"w":"La violencia de terceros también está cubierta por la ley."},{"q":"Un compañero dice que aguantar insultos de clientes es parte del sueldo. ¿Qué es correcto?","o":["No es parte del trabajo: se previene y se puede denunciar","Es cierto, porque el cliente siempre tiene la razón","Solo se denuncia si hay golpes","Solo se denuncia si el cliente vuelve"],"w":"Atender público no significa aguantar insultos ni amenazas."}]},{"s":"karin_terceros","v":[{"q":"El chofer de un proveedor insulta a un bodeguero durante la recepción. ¿Lo cubre la Ley Karin?","o":["Sí, es violencia en el trabajo por un tercero","No, porque el chofer no es de la empresa","Solo si ocurre dos veces","Solo si el bodeguero resulta herido"],"w":"La violencia de terceros ajenos a la empresa también está cubierta."},{"q":"El conductor de un transporte externo amenaza a un peoneta durante la descarga en el patio. ¿Qué es correcto?","o":["Es violencia en el trabajo y se puede denunciar","No se puede denunciar, porque no es de la empresa","Solo se denuncia si hay golpes","Debe resolverlo el peoneta con el conductor"],"w":"La ley protege aunque el agresor sea externo a la empresa."},{"q":"La Ley Karin también protege al trabajador cuando el agresor es el chofer de un proveedor.","vf":true,"w":"Verdadero. Cubre la violencia ejercida por terceros, como clientes y proveedores."}]},{"s":"cc6_ka_actuar","v":[{"q":"Un cliente se pone agresivo y amenaza con golpearte. ¿Qué haces?","o":["Pongo distancia, pido apoyo y llamo al 133","Lo enfrento con calma para que se tranquilice","Salgo del mesón a conversar de cerca con él","Le respondo con firmeza en su mismo tono"],"w":"No respondas a la agresión: distancia, apoyo y aviso."},{"q":"Después de un incidente con un cliente agresivo, ¿qué información conviene registrar al informar?","o":["Fecha, hora, qué hizo y quiénes lo vieron","Solo el nombre del cliente y su RUT","Nada, para no agrandar el problema","Solo lo que la jefatura me pida anotar"],"w":"Un registro claro ayuda a investigar y a tomar medidas."},{"q":"Un cliente molesto se acerca gritando a tu mesón. ¿Dónde te ubicas?","o":["Con el mesón entre ambos y salida libre","Fuera del mesón, para hablarle de cerca","En un rincón de la bodega, para esconderme","Frente a él, sin barreras, para calmarlo"],"w":"La distancia y una vía de salida te protegen."}]},{"s":"karin_denuncia","v":[{"q":"¿Ante quién se puede presentar una denuncia por acoso o violencia en el trabajo?","o":["Ante el empleador o la Inspección del Trabajo","Solo ante Carabineros, en la comisaría","Solo ante el sindicato de la empresa","Solo ante la jefatura directa de la sucursal"],"w":"Ambos canales están disponibles y la denuncia es reservada."},{"q":"¿Cuál es el plazo máximo de la investigación de una denuncia según la Ley Karin?","o":["30 días","6 meses","1 año","No tiene plazo"],"w":"La investigación debe concluir en un plazo máximo de 30 días."},{"q":"Una denuncia por Ley Karin se puede presentar verbalmente, no solo por escrito.","vf":true,"w":"Verdadero. Se puede presentar por escrito o verbalmente."}]},{"s":"karin_represalia","v":[{"q":"Una vendedora denunció acoso y ahora su jefe le cambia los turnos para castigarla. ¿Qué es correcto?","o":["No está permitido: no se permiten represalias","Está permitido si el jefe no está de acuerdo","Está permitido si la denuncia no se comprueba","Está permitido mientras dure la investigación"],"w":"Quien denuncia o declara está protegido contra represalias."},{"q":"Te citan como testigo en una investigación por acoso. ¿Qué es correcto?","o":["Contar lo que vi: estoy protegido","Negarme a declarar para evitar problemas","Decir solo lo que conviene a la jefatura","Agregar detalles para ayudar al afectado"],"w":"Los testigos también están protegidos y deben decir la verdad."},{"q":"Después de una denuncia, se permite castigar al denunciante si la jefatura no está de acuerdo.","vf":false,"w":"Falso. No se permiten represalias contra quien denuncia o declara."}]},{"s":"karin_testigo","v":[{"q":"Ves que unos compañeros se burlan de otro y él se ve afectado. ¿Cuál es la reacción correcta?","o":["No participar, acompañarlo y orientarlo a denunciar","Reírme para no quedar mal con el grupo","Grabarlo para tener pruebas y compartirlo","No meterme, porque no es mi problema"],"w":"No ser testigo silencioso: acompañar a la persona y orientarla a denunciar."},{"q":"¿Por qué es importante no quedarse callado ante el acoso de un compañero?","o":["Porque el silencio permite que el maltrato continúe","Porque así se evita trabajar con esa persona","No es importante si no me afecta a mí","Porque así lo exige el horario"],"w":"El silencio también daña: permite que el maltrato siga."},{"q":"Una compañera te cuenta, afectada, que un compañero la acosa. ¿Qué haces primero?","o":["La escucho, la acompaño y la oriento a denunciar","Le digo que no exagere y que lo deje pasar","Lo comento en el grupo del trabajo para apoyarla","Enfrento yo al compañero a solas para que pare"],"w":"Acompañar y orientar es el apoyo correcto; la denuncia es reservada."}]},{"s":"karin_auto","v":[{"q":"Un compañero reenvía al grupo una foto burlesca de otro. ¿Qué es lo correcto?","o":["No reenviarla, pedir que la borre y avisar","Reenviarla, es solo una broma","Comentarla con un emoji para no quedar mal","Guardarla por si acaso"],"w":"Si a alguien le duele, no es broma. Parar a tiempo protege a todos."},{"q":"En la bodega le pusieron un sobrenombre ofensivo a un compañero nuevo y a él le molesta. ¿Qué haces?","o":["No lo uso y pido al grupo que pare","Lo uso, porque todos lo hacen","Le digo que se acostumbre","Lo uso solo cuando él no está"],"w":"Las conductas que se normalizan pueden terminar en acoso."},{"q":"¿Qué es lo correcto cuando un compañero dice “no” a una broma o comentario?","o":["Respetar el “no” y parar de inmediato","Insistir, porque es en confianza","Seguir si el resto del grupo se ríe","Parar solo si se enoja"],"w":"Respetar el “no” es la base de un trabajo libre de acoso."}]}]},{"id":"camion_conduccion","sec":"conductores","title":"Conducción segura de camiones","thumb":"camion_conduccion_intro","mins":5,"learn":[{"s":"camion_conduccion_intro","t":"Manejas un camión cargado","x":"Un camión con carga pesa varias toneladas: <b>necesita más distancia para frenar</b> y tiene <b>zonas que no ves</b>. Para conducirlo necesitas la <b>licencia profesional que corresponde</b> según la Ley de Tránsito 18.290: <b>clase A4</b> para camión simple de más de 3.500 kg y <b>clase A5</b> para camión articulado. Llévala vigente y contigo. Un choque o atropello durante un despacho es <b>accidente del trabajo</b> (Ley 16.744)."},{"s":"camion_conduccion_revision","t":"Revisión antes de salir","x":"Antes de cada salida, da una <b>vuelta completa</b> al camión y revisa:<ul><li><b>Frenos</b> de servicio y freno de mano.</li><li><b>Neumáticos</b>: presión, cortes, desgaste y pernos.</li><li><b>Luces</b>, intermitentes, bocina y <b>alarma de retroceso</b>.</li><li><b>Espejos</b> limpios y bien ajustados.</li><li>Manchas de aceite o líquido bajo el camión.</li><li>Triángulos y extintor a bordo.</li></ul>Si algo falla, <b>no salgas</b> y avisa a tu jefatura. Una falla en ruta, con carga, es mucho más peligrosa."},{"s":"camion_conduccion_ciegos","t":"Puntos ciegos","x":"Alrededor del camión hay zonas que <b>no ves</b>, ni siquiera con los espejos bien ajustados:<ul><li><b>Atrás</b>: la zona ciega más grande.</li><li><b>Al lado derecho</b>, junto a la cabina y la rampla.</li><li><b>Justo delante</b> de la cabina, donde cabe un niño o una persona agachada.</li></ul>Antes de partir, mira los espejos y, si alguien pudo acercarse, <b>da una vuelta</b>. Al doblar a la derecha, cuidado con ciclistas y peatones. Para los peatones: si no ves los espejos del camión, el conductor no te ve."},{"s":"camion_conduccion_retro_ok","t":"Retroceder con ayuda","x":"Retroceder es la maniobra más riesgosa: atrás está tu zona ciega más grande.<ul><li>Usa un <b>señalero</b> (tu ayudante) ubicado a un costado, siempre <b>visible en tu espejo</b>, nunca justo detrás del camión.</li><li>Acuerden antes las señales: avanzar, parar y girar.</li><li>La <b>alarma de retroceso</b> debe sonar.</li><li>Si pierdes de vista al señalero o alguien cruza, <b>detente</b>.</li><li>Si estás solo y no ves, <b>bájate y mira</b>.</li></ul>","k":"Si pierdes de vista al señalero, detente."},{"s":"camion_conduccion_velocidad","t":"Velocidad y distancia","x":"Respeta los <b>límites de velocidad</b> y las reglas internas de {EMP}. Con carga, el camión tarda más en detenerse: deja <b>al menos 4 segundos</b> de distancia con el vehículo de adelante, y más con lluvia. Baja la velocidad con <b>lluvia, neblina, ripio y curvas</b>, y cerca de colegios y obras. El <b>apuro</b> es la acción insegura típica del despacho: llegar unos minutos tarde no es grave; un choque sí. Si vas atrasado, avisa a tu jefatura y sigue con calma."},{"s":"camion_conduccion_fatiga","t":"Fatiga y sueño","x":"El sueño al volante es traicionero: <b>cierras los ojos dos segundos y el camión avanza decenas de metros sin control</b>. Señales: bostezos, pestañeo seguido, cabeceo y no recordar los últimos kilómetros.<ul><li>Duerme bien antes de tu turno y respeta las pausas.</li><li>Abrir la ventana o subir la música <b>no quita el sueño</b>.</li><li>Si tienes sueño, <b>detente en un lugar seguro</b> y avisa.</li><li>Si un medicamento te da sueño, avisa a tu jefatura antes de conducir.</li></ul>"},{"s":"camion_conduccion_cabina","t":"Cinturón y celular","x":"<ul><li><b>Cinturón de seguridad</b> siempre, para ti y para tu <b>ayudante</b>, aunque el despacho sea a dos cuadras.</li><li>Usar el <b>celular</b> en la mano al conducir está <b>prohibido por la Ley de Tránsito</b>: ni llamar, ni chatear, ni mirar el mapa. Leer un mensaje te deja varios segundos sin mirar el camino.</li><li>Tampoco en el semáforo en rojo: sigues conduciendo y el camión sigue en la vía.</li><li>Para llamar o revisar una dirección, <b>detente en un lugar seguro</b>.</li></ul>"},{"s":"camion_conduccion_alcohol","t":"Cero alcohol y cero drogas","x":"La Ley 20.580, de Tolerancia Cero, establece:<ul><li>desde <b>0,3 hasta 0,8 g/l</b>: conducir <b>bajo la influencia</b> del alcohol;</li><li>desde <b>0,8 g/l</b>: <b>estado de ebriedad</b>.</li></ul>En el trabajo la regla es <b>cero alcohol y cero drogas</b>. El alcohol de la noche anterior puede seguir en tu sangre en la mañana. Si alguien llega con hálito alcohólico o bajo efectos de drogas, <b>no conduce</b>: se avisa a la jefatura.","k":"Al trabajar: cero alcohol y cero drogas."},{"s":"camion_conduccion_obra","t":"Al llegar a la obra","x":"Antes de entrar, <b>mira el lugar</b>:<ul><li><b>Cables eléctricos</b> aéreos: ni la rampla ni la carga deben acercarse a ellos.</li><li><b>Terreno blando</b>, zanjas o rellenos recientes que pueden ceder con el peso.</li><li><b>Pendientes</b>: no descargues en desnivel.</li><li>Personas y niños alrededor.</li></ul>Si no es seguro, <b>no entres</b>: busca otro punto y coordina con el cliente. Si el camión toca un cable, <b>quédate dentro de la cabina</b> y llama al 132 Bomberos."},{"s":"c5ac_despacho","t":"Si ocurre un choque","x":"<ul><li><b>Detente</b>, enciende las luces de emergencia y pon los <b>triángulos</b>.</li><li>Ponte el chaleco reflectante antes de bajar.</li><li>Si hay heridos, llama al <b>131 SAMU</b>; si hay fuego, al <b>132 Bomberos</b>; y avisa al <b>133 Carabineros</b>.</li><li>No muevas a un herido, salvo peligro de incendio o de otro atropello.</li><li>Avisa de inmediato a tu jefatura.</li></ul>Es accidente del trabajo: te atiende la <b>Mutual de Seguridad CChC</b>, fono <b>1407</b>."}],"quiz":[{"s":"camion_conduccion_revision","v":[{"q":"Al revisar el camión antes de salir notas que el freno de mano no sujeta. ¿Qué haces?","o":["No salgo y aviso a mi jefatura para que lo reparen","Salgo y estaciono siempre con un cambio puesto","Salgo y lo informo cuando vuelva del despacho","Salgo y le pido al ayudante que ponga calzos en cada parada"],"w":"Un camión con falla no sale. En ruta y con carga, una falla es mucho más peligrosa."},{"q":"En la vuelta previa ves un neumático con un corte profundo en el costado. ¿Qué corresponde?","o":["Dejar el camión detenido y avisar a la jefatura","Salir despacio y cambiarlo a la vuelta","Inflarlo un poco más para compensar","Salir solo si el despacho es dentro de la ciudad"],"w":"Si el camión no pasa la revisión, no sale. Un neumático cortado puede reventar con carga."},{"q":"¿Qué se revisa en la vuelta al camión antes de cada salida?","o":["Frenos, neumáticos, luces, alarma de retroceso y espejos","Solo el combustible y el nivel de aceite del motor","Solo los papeles del camión y la guía de despacho","Frenos y neumáticos, pero solo si el viaje es largo"],"w":"La revisión se hace antes de cada salida y cubre todo lo que te permite frenar, ver y ser visto."}]},{"s":"camion_conduccion_ciegos","v":[{"q":"¿Dónde está la zona ciega más grande de un camión?","o":["Atrás del camión","Al lado izquierdo, junto al conductor","En la esquina delantera izquierda","Sobre la parte alta de la carga"],"w":"Atrás no ves nada directamente. Por eso al retroceder se usa señalero."},{"q":"Un peatón quiere saber si el conductor del camión lo está viendo. ¿Cuál es la regla?","o":["Si él no ve los espejos del camión, el conductor no lo ve","Si él escucha el motor, el conductor lo ve","Si está a más de un metro, el conductor lo ve","Si el camión tiene las luces encendidas, lo ve"],"w":"Los espejos funcionan en ambos sentidos: si no los ves, el conductor tampoco te ve a ti."},{"q":"Con los espejos bien ajustados, el conductor de un camión ve todo lo que está a su alrededor.","vf":false,"w":"Falso. Aun con buenos espejos quedan zonas ciegas: atrás, al lado derecho y justo delante de la cabina."}]},{"s":"camion_conduccion_retro_mal","v":[{"q":"Retrocedes con señalero y de pronto lo pierdes de vista en tu espejo. ¿Qué haces?","o":["Me detengo hasta volver a verlo","Sigo despacio con la alarma sonando","Toco la bocina y sigo retrocediendo","Sigo, porque él ya conoce la maniobra"],"w":"Si no ves al señalero, no sabes qué hay atrás ni dónde está él. Detente."},{"q":"¿Dónde debe ubicarse el señalero que te guía al retroceder?","o":["A un costado, siempre visible en tu espejo","Justo detrás del camión, al centro","Arriba de la rampla, mirando hacia atrás","Dentro de la cabina, mirando el espejo derecho"],"w":"Detrás del camión el señalero queda en la zona ciega: debe estar a un costado y a la vista."},{"q":"Debes retroceder en el patio, estás solo y no ves bien lo que hay atrás. ¿Qué haces?","o":["Me bajo y miro antes de retroceder","Retrocedo confiando en la alarma","Retrocedo despacio tocando la bocina","Retrocedo guiándome solo por los espejos"],"w":"La alarma y la bocina avisan, pero no te muestran lo que hay atrás. Si no ves, bájate y mira."}]},{"s":"camion_conduccion_auto","v":[{"q":"Vas atrasado con el despacho. ¿Cuál es la decisión segura?","o":["Revisar el camión y maniobrar con calma igual","Saltarme la revisión del camión por esta vez","Retroceder sin señalero para ganar tiempo","Subir la velocidad solo en los tramos rectos"],"w":"El apuro es la acción insegura típica del despacho. Unos minutos no valen un accidente."},{"q":"Un cliente llama apurado preguntando por su pedido. ¿Qué haces?","o":["Mantengo la velocidad segura y aviso el atraso a mi jefatura","Acelero en las rectas para recuperar los minutos","Le contesto en ruta para calmarlo","Paso con luz amarilla para no detenerme"],"w":"Llegar unos minutos tarde no es grave; un choque sí. El atraso se avisa, no se recupera manejando rápido."},{"q":"Te quedan cinco entregas y poco tiempo. ¿Qué es lo seguro?","o":["Hacer las entregas con calma y avisar el atraso","Juntar dos cargas y amarrar solo la primera","Manejar sin pausas hasta terminar","Retroceder sin señalero en las entregas cortas"],"w":"Con apuro se cometen los errores típicos. La decisión segura es trabajar con calma y avisar."}]},{"s":"camion_conduccion_alcohol","v":[{"q":"Según la Ley 20.580, ¿desde qué nivel de alcohol en la sangre hay estado de ebriedad?","o":["Desde 0,8 g/l","Desde 0,3 g/l","Desde 0,5 g/l","Desde 1,0 g/l"],"w":"Desde 0,3 g/l es bajo la influencia; desde 0,8 g/l, ebriedad. En el trabajo: cero."},{"q":"Según la Ley 20.580, ¿desde qué nivel se considera conducir bajo la influencia del alcohol?","o":["Desde 0,3 g/l","Desde 0,8 g/l","Desde 0,5 g/l","Desde 0,1 g/l"],"w":"Desde 0,3 g/l es bajo la influencia y desde 0,8 g/l, ebriedad. En el trabajo la regla es cero."},{"q":"Si el examen marca menos de 0,3 g/l, puedo conducir el camión de {EMP} sin problema.","vf":false,"w":"Falso. La ley fija tramos, pero en el trabajo la regla es cero alcohol y cero drogas."}]},{"s":"camion_conduccion_fatiga","v":[{"q":"Vas manejando y empiezas a bostezar y pestañear seguido. ¿Qué haces?","o":["Me detengo en un lugar seguro y descanso","Abro la ventana y sigo hasta el destino","Subo el volumen de la radio y sigo","Acelero para llegar antes y descansar allá"],"w":"Son señales de sueño. La ventana o la música no lo quitan: detente en un lugar seguro."},{"q":"¿Cuál de estas es una señal de sueño al volante?","o":["No recordar los últimos kilómetros recorridos","Sentir hambre a media mañana","Sentir frío dentro de la cabina","Tener sed después de una descarga"],"w":"No recordar el trayecto, cabecear, bostezar y pestañear seguido son señales de que debes detenerte."},{"q":"Tomaste un remedio para la alergia que da sueño y te toca salir a despachar. ¿Qué haces?","o":["Aviso a mi jefatura antes de conducir","Salgo y tomo un café en el camino","Salgo, porque es un viaje corto","Salgo y manejo con la ventana abierta"],"w":"Un medicamento que da sueño afecta tus reflejos. Se avisa antes de conducir."}]},{"s":"camion_conduccion_celu_mal","v":[{"q":"Suena el celular mientras manejas. ¿Qué haces?","o":["Me detengo en un lugar seguro y devuelvo la llamada","Contesto rápido y corto en seguida","Leo el mensaje cuando pare en el semáforo","Contesto con altavoz, con el teléfono en la mano"],"w":"El celular quita tus ojos y tu mente del camino. Úsalo solo detenido en un lugar seguro."},{"q":"Necesitas revisar en el celular la dirección de la entrega. ¿Cuándo lo haces?","o":["Detenido en un lugar seguro","En el semáforo en rojo","En una recta con poco tráfico","Mientras avanzo despacio en un taco"],"w":"En el semáforo o en un taco sigues conduciendo. El celular se usa detenido en un lugar seguro."},{"q":"Leer un mensaje en un semáforo en rojo sigue siendo usar el celular mientras conduces.","vf":true,"w":"Verdadero. El camión sigue en la vía y puede tener que moverse en cualquier momento."}]},{"s":"camion_conduccion_cabina","v":[{"q":"Tu ayudante no se pone el cinturón porque el despacho es a dos cuadras. ¿Qué corresponde?","o":["Que se lo ponga: en la cabina se usa siempre","Que lo use solo en carretera","Que lo use solo si el camión va cargado","Que lo use solo si va junto a la ventana"],"w":"Un frenazo o un choque pasa en cualquier cuadra. Todos en la cabina usan cinturón, siempre."},{"q":"¿Quién debe usar cinturón de seguridad en la cabina del camión?","o":["El conductor y todos sus acompañantes","Solo el conductor del camión","Solo los que van junto a la ventana","Todos, pero solo en viajes largos"],"w":"El cinturón protege a todos los que van en la cabina, en cualquier trayecto."},{"q":"El ayudante debe usar cinturón de seguridad aunque el viaje sea corto.","vf":true,"w":"Verdadero. Todos los que van en la cabina usan cinturón, siempre."}]},{"s":"camion_conduccion_obra","v":[{"q":"Al llegar a una obra ves cables eléctricos sobre el punto de descarga. ¿Qué haces?","o":["No descargo ahí: busco otro punto y coordino","Descargo rápido, sin levantar mucho la carga","Pido al ayudante que levante los cables con un palo","Descargo si los cables se ven forrados"],"w":"Un contacto con cables eléctricos puede ser mortal. Si no es seguro, no entres."},{"q":"El cliente quiere que descargues sobre un relleno recién hecho. ¿Qué haces?","o":["Busco un punto firme y coordino con el cliente","Entro despacio para no hundirme","Entro solo si el camión va con poca carga","Entro y descargo lo más rápido posible"],"w":"Un relleno reciente puede ceder con el peso y volcar el camión. Se busca otro punto."},{"q":"Mientras maniobras en la obra, la rampla toca un cable eléctrico. ¿Qué haces?","o":["Me quedo dentro de la cabina y llamo al 132","Me bajo de inmediato y me alejo corriendo","Me bajo a revisar si el cable se cortó","Acelero para soltar el cable del camión"],"w":"Dentro de la cabina estás más protegido; al bajar puedes recibir la descarga. Espera a que corten la energía."}]},{"s":"c5ac_despacho","v":[{"q":"Chocas en ruta y tu ayudante queda herido. ¿Qué corresponde?","o":["Señalizar con triángulos, llamar al 131 y avisar a la jefatura","Subirlo a la cabina y llevarlo yo a un centro de salud","Mover el camión fuera de la vía y luego ver al herido","Llamar solo a mi jefatura y esperar instrucciones"],"w":"Primero proteger el lugar y pedir ayuda al SAMU. Al herido no se le mueve, salvo peligro mayor."},{"q":"¿A qué número llamas si hay heridos en un choque durante el despacho?","o":["131, SAMU","132, Bomberos","133, Carabineros","134, PDI"],"w":"El 131 es el SAMU, para heridos. El 132 es Bomberos y el 133, Carabineros."},{"q":"Un choque durante un despacho, ¿qué tipo de accidente es y quién te atiende?","o":["Del trabajo; me atiende la Mutual de Seguridad CChC","De tránsito; lo cubre solo el seguro del camión","Particular; me atiendo en mi Fonasa o isapre","Del trabajo, pero solo si hubo heridos graves"],"w":"Ocurre trabajando, así que es accidente del trabajo (Ley 16.744) y lo atiende la Mutual de Seguridad CChC, fono 1407."}]}]},{"id":"camion_estiba","sec":"conductores","title":"Estiba y amarre de la carga","thumb":"camion_estiba_intro","mins":5,"learn":[{"s":"camion_estiba_intro","t":"Carga suelta = peligro","x":"Una carga mal estibada puede <b>caer a la vía</b>, golpear a alguien al soltar los amarres o <b>volcar el camión</b> en una curva. La regla, que también exige la Ley de Tránsito, es que la carga vaya <b>estibada y amarrada para que no se mueva ni caiga</b>. Su peso no la sujeta: al frenar o doblar, se mueve igual. Tú, como conductor, revisas antes de salir que vaya bien puesta y bien amarrada, <b>aunque la haya cargado otro</b>.","k":"Estibada y amarrada: que no se mueva ni caiga."},{"s":"camion_estiba_peso","t":"Distribuye el peso","x":"<ul><li>Lo <b>más pesado abajo</b> y al centro, sobre los ejes: sacos de cemento, cerámicas, fierro.</li><li>Lo liviano arriba: cajas de clavos, tubos de PVC, accesorios.</li><li>Reparte el peso a ambos lados.</li><li>Apoya la carga contra la <b>cabecera</b> y no dejes huecos entre bultos.</li></ul>¿Por qué? Si el peso va alto o cargado a un lado, el camión se inclina en las curvas y <b>puede volcar</b>. Si va todo atrás, la dirección se pone liviana."},{"s":"camion_estiba_larga","t":"Fierro, tubos, perfiles y planchas","x":"La carga larga es traicionera: <b>se desliza</b> al frenar y puede llegar a la cabina.<ul><li>Átala en paquetes y amárrala en <b>varios puntos</b>, nunca solo en la punta.</li><li>Lo que <b>sobresale atrás</b> se señaliza con <b>bandera o paño rojo</b> y, de noche, con <b>luz roja</b>.</li><li>No debe sobresalir hacia los lados.</li><li><b>Planchas de zinc</b> y paneles van en paquete amarrado: el viento las levanta.</li></ul>Si no cabe de forma segura, se busca otro camión u otro viaje."},{"s":"camion_estiba_amarre","t":"Eslingas, cintas y tensores","x":"Antes de usarlos, revísalos:<ul><li>Cinta sin <b>cortes, quemaduras, desgaste ni hilos sueltos</b>.</li><li><b>Etiqueta legible</b> con su capacidad: sin etiqueta, no se sabe cuánto aguanta.</li><li>Tensor y ganchos sin deformaciones.</li></ul>Usa <b>suficientes amarres</b>, engánchalos en los <b>puntos de amarre del camión</b>, nunca en la baranda ni en la misma carga, y tensa hasta que nada se mueva. Una cinta dañada <b>se retira</b>: no se arregla con nudos."},{"s":"camion_estiba_canto_mal","t":"Protege los cantos vivos","x":"Si una eslinga se apoya en el <b>canto vivo</b> de la carga, se puede cortar. El filo de un perfil de acero, una plancha de zinc o el fierro corta la cinta con el roce y la tensión, y la carga queda suelta. Ya ha pasado en casos reales del rubro.<ul><li>Pon <b>cantoneras</b> o protectores en cada esquina con filo.</li><li>Tensar más o poner doble cinta <b>no reemplaza</b> la cantonera.</li><li>Al llegar, revisa la cinta justo en esos puntos.</li></ul>","k":"Donde hay filo, va cantonera."},{"s":"camion_estiba_frenado","t":"Al frenar, la carga sigue","x":"Cuando el camión frena de golpe, la carga <b>sigue avanzando</b> con la velocidad que llevaba. En un frenazo fuerte empuja hacia adelante con una fuerza <b>cercana a su propio peso</b>. Si no está amarrada o hay huecos, <b>se corre hacia la cabina</b>, y en una curva se cae por los lados. Por eso: carga <b>apoyada contra la cabecera</b>, sin huecos y bien amarrada. Y maneja suave: <b>frena y dobla con anticipación</b>."},{"s":"camion_estiba_revisar","t":"Revisa los amarres en el camino","x":"Con las vibraciones y los baches, la carga se asienta y <b>los amarres se sueltan</b>.<ul><li>Revisa antes de salir.</li><li>Detente en un <b>lugar seguro</b> para revisar después de los primeros minutos de viaje y tras caminos malos.</li><li>Si la carga se movió, <b>reacomódala y vuelve a tensar</b>.</li><li>Al tensar o soltar, <b>párate a un costado</b>: si la carga se corrió, puede caer al soltar la cinta.</li></ul>"},{"s":"camion_estiba_sobrecarga","t":"No sobrecargues","x":"Cada camión tiene una <b>capacidad máxima de carga</b> fijada por el fabricante y anotada en su documentación. Que la carga quepa en la plataforma no significa que el camión la soporte. Si la pasas:<ul><li>los <b>frenos</b> rinden menos;</li><li>los <b>neumáticos</b> y la suspensión se dañan;</li><li>el camión <b>vuelca</b> con más facilidad.</li></ul>Si te piden cargar más, <b>avisa a tu jefatura</b> y divide el despacho en dos viajes."},{"s":"camion_estiba_auto","t":"Autocuidado en la estiba","x":"La mayoría de los accidentes se relacionan con una <b>acción insegura</b>. En la estiba, la típica es pensar que <b>es cerquita y no hace falta amarrar</b>, o usar una cinta dañada por esta vez. La decisión segura: <b>amarrar siempre</b>, aunque sean dos cuadras, porque un frenazo puede pasar en cualquier esquina. Avisa también las condiciones inseguras: cintas rotas, puntos de amarre dañados o falta de cantoneras."}],"quiz":[{"s":"camion_estiba_intro","v":[{"q":"¿Cuál es la regla para la carga del camión?","o":["Estibada y amarrada, para que no se mueva ni caiga","Bien apilada, para que su propio peso la sujete","Amarrada solo cuando el viaje es largo","Amarrada solo si supera la altura de la baranda"],"w":"El peso no basta: al frenar o doblar, la carga se mueve si no va amarrada."},{"q":"La carga la subió la grúa de bodega. ¿Quién revisa que vaya bien amarrada antes de salir?","o":["Yo, como conductor del camión","Solo el operador de la grúa","El cliente, cuando la recibe","Nadie, si la grúa la dejó centrada"],"w":"Aunque la cargue otro, el conductor revisa la estiba y los amarres antes de salir."},{"q":"Si la carga es pesada, su propio peso la mantiene en su lugar y no necesita amarre.","vf":false,"w":"Falso. Al frenar o doblar, la carga pesada también se mueve, y con más fuerza."}]},{"s":"camion_estiba_peso","v":[{"q":"¿Dónde va lo más pesado de la carga?","o":["Abajo, al centro y contra la cabecera","Arriba, para que aplaste y sujete lo liviano","Al final de la plataforma, para bajarlo primero","A un costado, compensado con lo liviano"],"w":"Así el camión es más estable y la carga no se corre al frenar."},{"q":"Cargas sacos de cemento y cajas de clavos. ¿Cómo los ordenas?","o":["Sacos abajo y al centro; cajas arriba","Cajas abajo y sacos arriba para que no se vuelen","Sacos atrás y cajas contra la cabecera","Sacos a un lado y cajas al otro"],"w":"Lo pesado abajo y al centro, sobre los ejes; lo liviano arriba."},{"q":"¿Qué puede pasar si el peso va alto o cargado hacia un lado?","o":["El camión se inclina en las curvas y puede volcar","Solo aumenta el consumo de combustible","La dirección se pone más firme y segura","Nada, si la carga va bien amarrada"],"w":"El peso alto o desparejo hace que el camión se incline en las curvas y vuelque."}]},{"s":"camion_estiba_canto_mal","v":[{"q":"Amarras un paquete de perfiles de acero y la cinta pasa por un canto con filo. ¿Qué haces?","o":["Pongo una cantonera entre la cinta y el filo","Tenso más la cinta para que no se mueva","Pongo una segunda cinta encima de la primera","Paso la cinta más floja en esa esquina"],"w":"El filo corta la cinta con el roce y la tensión. Solo la cantonera lo evita."},{"q":"¿Para qué sirve la cantonera en un amarre?","o":["Evita que el canto vivo corte la cinta","Duplica la capacidad de la cinta","Reemplaza un amarre en cargas cortas","Marca dónde debe ir el tensor"],"w":"La cantonera protege la cinta del filo de perfiles, zinc o fierro."},{"q":"Al llegar a destino, ¿dónde revisas primero si la cinta tiene cortes?","o":["Donde se apoya sobre cantos o filos","En el gancho del punto de amarre","En la etiqueta de capacidad","En el tramo que cuelga suelto"],"w":"Los cortes aparecen donde la cinta roza un filo: ahí se revisa."}]},{"s":"camion_estiba_amarre","v":[{"q":"Una cinta con cortes se puede usar si la carga es liviana.","vf":false,"w":"Falso. Una cinta dañada se retira: puede cortarse con la tensión o en un frenazo."},{"q":"Una cinta tiene la etiqueta borrada, pero se ve en buen estado. ¿La usas?","o":["No: sin etiqueta no se sabe su capacidad","Sí, si se ve firme al tirarla","Sí, para cargas de menos de una tonelada","Sí, si la uso junto con otra cinta"],"w":"La etiqueta indica cuánto aguanta. Sin ella, la cinta no se usa."},{"q":"¿Dónde se enganchan las cintas de amarre?","o":["En los puntos de amarre del camión","En la baranda o el pilar más cercano","En un fierro de la misma carga","Donde la cinta quede más tensa"],"w":"Los puntos de amarre están hechos para aguantar la fuerza; la baranda o la carga, no."}]},{"s":"camion_estiba_larga","v":[{"q":"Llevas fierro que sobresale atrás del camión. ¿Qué corresponde?","o":["Señalizarlo con bandera roja y amarrarlo en varios puntos","Amarrarlo bien solo en la punta que sobresale","Señalizarlo solo si el viaje es de noche","Amarrarlo en varios puntos y no señalizarlo"],"w":"Lo que sobresale se señaliza para que lo vean, y lo largo se amarra en varios puntos."},{"q":"Despachas de noche con tubos que sobresalen atrás. ¿Cómo los señalizas?","o":["Con una luz roja en el extremo","Con un paño blanco amarrado","Con cinta de embalaje amarilla","No se señalizan si van amarrados"],"w":"De día, bandera o paño rojo; de noche, luz roja para que se vean."},{"q":"¿Por qué la carga larga, como fierro o perfiles, es especialmente peligrosa al frenar?","o":["Se desliza hacia adelante y llega a la cabina","Pesa más que el resto de la carga junta","Se dobla con el frenazo y pierde el amarre","Hace que el camión frene más de golpe"],"w":"Lo largo resbala sobre sí mismo y avanza hacia la cabina. Por eso se amarra en varios puntos."}]},{"s":"camion_estiba_frenado","v":[{"q":"Al frenar de golpe, una carga sin amarrar…","o":["Sigue avanzando y se corre hacia la cabina","Se queda quieta por su propio peso","Se desplaza hacia atrás del camión","Solo se mueve si el camión va en bajada"],"w":"La carga sigue con la velocidad que llevaba. Por eso va contra la cabecera y amarrada."},{"q":"Quedó un espacio de medio metro entre la carga y la cabecera. ¿Qué haces?","o":["Corro la carga contra la cabecera antes de salir","Lo dejo, así la carga tiene dónde moverse","Amarro solo la parte trasera de la carga","Lo dejo, si freno con más cuidado"],"w":"En un frenazo, la carga gana fuerza en ese hueco y golpea la cabina."},{"q":"En un frenazo fuerte, la carga empuja hacia adelante con una fuerza cercana a su propio peso.","vf":true,"w":"Verdadero. Por eso va contra la cabecera, sin huecos y bien amarrada."}]},{"s":"camion_estiba_revisar","v":[{"q":"¿Cuándo se revisan los amarres?","o":["Antes de salir y también durante el camino","Solo antes de salir, si quedaron tensos","Solo al llegar a destino","Solo cuando el viaje pasa por ripio"],"w":"Las vibraciones y los baches sueltan los amarres. Revisa detenido en un lugar seguro."},{"q":"Después de un tramo de calles con baches, ¿qué haces?","o":["Me detengo en un lugar seguro y reviso los amarres","Sigo y los reviso al llegar al cliente","Miro la carga por el espejo y sigo","Bajo la velocidad y sigo sin detenerme"],"w":"Tras caminos malos la carga se asienta y los amarres se sueltan."},{"q":"Vas a soltar un amarre y notas que la carga se corrió. ¿Cómo te ubicas?","o":["A un costado, fuera de donde podría caer","Frente a la carga, para sujetarla","Arriba de la plataforma, junto a la carga","Detrás del camión, al centro"],"w":"Al soltar la cinta, una carga corrida puede caer. Párate a un costado."}]},{"s":"camion_estiba_sobrecarga","v":[{"q":"Un camión con sobrecarga frena peor y vuelca con más facilidad.","vf":true,"w":"Verdadero. Por eso se respeta la capacidad máxima; si sobra carga, se hace otro viaje."},{"q":"Te piden subir más carga de la que el camión puede llevar. ¿Qué haces?","o":["Aviso a la jefatura y se divide en dos viajes","La llevo y manejo más despacio","La llevo si el viaje es corto","La llevo si cabe en la plataforma"],"w":"La capacidad máxima no se pasa: frenos y neumáticos no responden igual."},{"q":"¿Dónde se conoce la capacidad máxima de carga del camión?","o":["En la documentación del fabricante","Por lo que cabe en la plataforma","Mirando cómo se hunden los neumáticos","Por lo que el conductor estime"],"w":"La capacidad la fija el fabricante. Que la carga quepa no significa que el camión la soporte."}]},{"s":"camion_estiba_auto","v":[{"q":"El despacho es a dos cuadras. ¿Amarras la carga?","o":["Sí, la carga siempre va amarrada","No, si manejo despacio","Solo si en el camino hay curvas","Solo la carga que va más alta"],"w":"Un frenazo puede ocurrir en cualquier cuadra. La carga siempre va amarrada."},{"q":"Un compañero dice que es cerquita y que no amarren. ¿Qué respondes?","o":["Que se amarra igual: un frenazo pasa en cualquier lado","Que está bien si van a menos de 30 km/h","Que basta con amarrar la parte de atrás","Que está bien si la carga es pesada y baja"],"w":"Pensar que es cerquita es la excusa típica. La decisión segura es amarrar siempre."},{"q":"Notas que en el camión faltan cantoneras. ¿Qué haces?","o":["Aviso a mi jefatura para que las repongan","Amarro igual y tenso menos la cinta","Amarro con doble cinta en los filos","Salgo igual, porque el viaje es corto"],"w":"La falta de cantoneras es una condición insegura: se avisa para que se corrija."}]}]},{"id":"camion_carga","sec":"conductores","title":"Carga y descarga del camión","thumb":"camion_carga_intro","mins":5,"learn":[{"s":"camion_carga_intro","t":"El patio de carga","x":"En el patio se juntan <b>camiones, grúas horquilla, camionetas de clientes y peatones</b>. Los accidentes típicos al cargar y descargar son:<ul><li><b>caídas</b> desde la plataforma o la cabina;</li><li><b>golpes y aplastamientos</b> con la carga;</li><li><b>atropellos</b> en el patio;</li><li>lesiones por levantar mal.</li></ul>Usa tu chaleco reflectante, camina por las vías peatonales donde existan y nunca pases por detrás de un camión que retrocede."},{"s":"camion_carga_preparar","t":"Antes de cargar: asegura el camión","x":"<ul><li><b>Motor apagado</b> y llave fuera del contacto, para que nadie lo mueva.</li><li><b>Freno de mano</b> puesto.</li><li><b>Calzos</b> en las ruedas, sobre todo en pendiente.</li><li>Conos o señalización alrededor, si tu sucursal los tiene.</li></ul>¿Por qué? Un camión que se mueve mientras alguien está arriba o mientras la grúa deja un pallet puede botar a una persona o la carga. Si faltan calzos o conos, avisa a tu jefatura."},{"s":"camion_carga_subir_ok","t":"Subir y bajar: 3 puntos de apoyo","x":"Saltar de la plataforma o de la cabina causa torceduras, fracturas y golpes.<ul><li>Sube y baja <b>de frente</b> al camión, usando peldaños y asideros.</li><li>Mantén <b>3 puntos de apoyo</b>: dos manos y un pie, o dos pies y una mano.</li><li>No bajes con carga en las manos: pásala a otro.</li><li>Cuidado con peldaños mojados o con barro.</li><li>Si un peldaño o asidero está roto, avisa y usa otro acceso seguro.</li></ul>","k":"Nunca saltes: baja de frente con 3 puntos de apoyo."},{"s":"camion_carga_borde","t":"La plataforma es un borde","x":"Sobre la plataforma estás en <b>altura</b>: una caída desde ahí puede causar lesiones graves.<ul><li>No camines <b>de espaldas</b> mientras tiras o acomodas carga: no ves el borde.</li><li>Trabaja lejos del borde y mirando hacia donde caminas.</li><li>No te subas <b>sobre la carga</b> suelta ni a pilas inestables.</li><li>Plataforma mojada o con barro resbala: límpiala.</li><li>Bájate mientras la grúa deja o saca carga.</li></ul>"},{"s":"camion_carga_grua","t":"Coordina con la grúa horquilla","x":"La grúa horquilla <b>solo la opera quien tiene licencia clase D y está capacitado y autorizado</b> por {EMP}. Mientras carga el camión:<ul><li>Ubícate en una <b>zona segura</b>, fuera de su recorrido.</li><li>Haz <b>contacto visual</b> con el operador y espera su seña antes de acercarte.</li><li>Acuerden señales simples: parar, subir, bajar.</li><li>Nadie arriba de la plataforma mientras la grúa deja o saca la carga.</li></ul>"},{"s":"camion_carga_susp_mal","t":"Nadie bajo carga suspendida","x":"Una carga levantada puede <b>caer en cualquier momento</b>, aunque todo se vea bien: un saco que se rompe, un pallet quebrado o una horquilla mal puesta.<ul><li>Nunca te pares ni camines <b>bajo la carga</b> ni en su zona de caída.</li><li>No guíes la carga con las manos desde abajo.</li><li>Acércate solo cuando esté <b>apoyada</b> y el operador te lo indique.</li></ul>Vale igual para la pluma del camión, si tiene.","k":"Nunca te pongas bajo una carga levantada."},{"s":"camion_carga_equipo","t":"Sacos y fierro: en equipo","x":"<ul><li>Un saco de cemento de <b>25 kg</b> se levanta con técnica: espalda recta, piernas flectadas, carga pegada al cuerpo y sin girar la cintura.</li><li>Sin ayuda mecánica, el máximo es <b>25 kg</b> para hombres y <b>20 kg</b> para mujeres y menores de 18 años (Ley 20.949). Las <b>embarazadas no cargan</b>.</li><li><b>Fierro y tubos largos</b>: entre dos o más, del mismo lado, con uno que dirige: a la cuenta de tres.</li></ul>"},{"s":"camion_carga_obra","t":"Descarga con gente alrededor","x":"En la obra o en la casa del cliente hay <b>personas, niños y vehículos</b> que no conocen el riesgo.<ul><li><b>Delimita</b> la zona de descarga con conos o cinta.</li><li>Pide con respeto que se <b>alejen</b>; si se acercan, detén la descarga.</li><li>No dejes que el cliente ayude subiéndose al camión.</li><li>Deja la carga <b>estable</b>, sin bloquear el paso ni la vereda.</li></ul>"},{"s":"camion_carga_epp","t":"Tu EPP para cargar","x":"{EMP} entrega el EPP <b>sin costo</b> (Ley 16.744, art. 68) y tú lo usas siempre:<ul><li><b>Zapatos de seguridad</b>: la carga puede caer a los pies.</li><li><b>Guantes</b>: el fierro, el zinc y las astillas cortan.</li><li><b>Chaleco reflectante</b>: para que te vean en el patio y en la calle.</li><li><b>Casco</b> donde se exija, como en las obras.</li></ul>Revísalo antes de usarlo y, si se daña, pide el recambio."},{"s":"camion_carga_auto","t":"Autocuidado al cargar","x":"La mayoría de los accidentes se relacionan con <b>acciones inseguras</b>. Aquí la típica es <b>el apuro</b>: saltar del camión, pasar bajo la carga un segundo o levantar solo lo que es para dos. La decisión segura: <b>bajar de frente, esperar a que la carga se apoye y pedir ayuda</b>. Avisa también las condiciones inseguras: peldaños rotos, calzos que faltan o pallets dañados."}],"quiz":[{"s":"camion_carga_preparar","v":[{"q":"Antes de que la grúa cargue el camión, ¿qué se hace?","o":["Motor apagado, freno de mano y calzos","Motor encendido, para salir apenas termine","Solo freno de mano, porque es poco rato","Nada: eso le corresponde al operador de la grúa"],"w":"Así el camión no se mueve mientras alguien trabaja arriba o la grúa carga."},{"q":"El camión quedó en una pendiente para cargar. ¿Qué agregas al freno de mano?","o":["Calzos en las ruedas","Dejar el motor en marcha","Dejar puesta la primera y nada más","Encender las luces de emergencia y nada más"],"w":"En pendiente los calzos son indispensables: el freno de mano solo puede no bastar."},{"q":"¿Por qué se retira la llave del contacto mientras se carga el camión?","o":["Para que nadie mueva el camión con gente arriba","Para ahorrar batería mientras espera","Porque lo pide el cliente al recibir","Para que la alarma de retroceso no suene"],"w":"Con la llave fuera, nadie puede mover el camión por error mientras se carga."}]},{"s":"camion_carga_subir_mal","v":[{"q":"Terminas de acomodar la carga arriba de la plataforma. ¿Cómo bajas?","o":["De frente, por los peldaños, con 3 puntos de apoyo","De un salto corto, con las rodillas flectadas","De espaldas al camión, afirmado de una mano","Sentado en el borde y dejándome caer"],"w":"Bajar de frente con 3 puntos de apoyo evita torceduras y fracturas. Nunca se salta."},{"q":"Tienes una caja en las manos y necesitas bajar de la plataforma. ¿Qué haces?","o":["Se la paso a otro y bajo con las manos libres","Bajo con la caja apoyada en el hombro","Salto con cuidado sosteniendo la caja","Bajo con la caja en una mano y me afirmo con la otra"],"w":"Con carga en las manos pierdes los 3 puntos de apoyo. Pásala y baja con las manos libres."},{"q":"¿Qué son los 3 puntos de apoyo?","o":["Dos manos y un pie, o dos pies y una mano","Dos pies en el peldaño y la vista al frente","Una mano, un pie y la rodilla apoyada","Casco, guantes y zapatos de seguridad"],"w":"Siempre tres puntos en contacto con el camión al subir o bajar."}]},{"s":"camion_carga_borde","v":[{"q":"Sobre la plataforma puedo caminar de espaldas si voy mirando la carga.","vf":false,"w":"Falso. De espaldas no ves el borde: es una de las caídas más típicas."},{"q":"Estás arriba de la plataforma y la grúa se acerca a dejar un pallet. ¿Qué haces?","o":["Me bajo y espero en una zona segura","Me quedo arriba para recibir el pallet","Me corro al borde para dar espacio","Me subo sobre la carga para guiarlo"],"w":"Nadie arriba de la plataforma mientras la grúa deja o saca carga."},{"q":"¿Cuál es una caída típica desde la plataforma del camión?","o":["Caminar de espaldas tirando carga y no ver el borde","Bajar de frente usando los peldaños","Trabajar por el centro de la plataforma","Acomodar la carga caminando de frente"],"w":"Al tirar carga caminando hacia atrás, el borde aparece sin aviso."}]},{"s":"camion_carga_grua","v":[{"q":"La grúa horquilla viene a dejar un pallet en el camión. ¿Dónde estás tú?","o":["En una zona segura, con contacto visual con el operador","Arriba de la plataforma para recibir el pallet","Junto a las horquillas para guiar el pallet","Detrás de la grúa para avisarle si viene alguien"],"w":"Fuera del recorrido de la grúa y a la vista del operador."},{"q":"¿Quién puede operar la grúa horquilla para cargar el camión?","o":["Quien tiene licencia clase D y está autorizado","Cualquier conductor con licencia profesional","El chofer del camión, si el operador no está","Quien haya visto operar la grúa muchas veces"],"w":"Solo opera quien tiene licencia clase D y está capacitado y autorizado por la empresa."},{"q":"Antes de acercarte a la grúa que carga tu camión, ¿qué haces?","o":["Busco contacto visual con el operador y espero su seña","Golpeo la carrocería para que me escuche","Me acerco por detrás, donde no estorbo","Me acerco mientras la grúa retrocede"],"w":"Sin contacto visual, el operador no sabe que estás ahí."}]},{"s":"camion_carga_susp_mal","v":[{"q":"La grúa levanta un pallet de cerámicas sobre el camión. ¿Dónde te ubicas?","o":["Fuera de la zona de caída, hasta que se apoye","Debajo, para guiarlo con las manos","Al lado de las horquillas, para alinearlo","Pegado a la plataforma, para recibirlo"],"w":"Nunca bajo la carga levantada ni en su zona de caída."},{"q":"¿Cuándo puedes acercarte a una carga que mueve la grúa?","o":["Cuando está apoyada y el operador lo indica","Cuando va levantada a poca altura","Cuando la grúa avanza despacio","Cuando el pallet se ve firme"],"w":"Mientras la carga esté levantada puede caer. Te acercas cuando está apoyada."},{"q":"Una carga levantada puede caer aunque el pallet y la grúa se vean en buen estado.","vf":true,"w":"Verdadero. Un saco que se rompe o una horquilla mal puesta bastan. Nadie bajo la carga."}]},{"s":"camion_carga_equipo","v":[{"q":"Sin ayuda mecánica, ¿cuál es el máximo de carga manual para un hombre adulto?","o":["25 kg","50 kg","30 kg","40 kg"],"w":"Ley 20.949: 25 kg para hombres; 20 kg para mujeres y menores de 18."},{"q":"Sin ayuda mecánica, ¿cuál es el máximo de carga manual para una mujer?","o":["20 kg","25 kg","15 kg","30 kg"],"w":"Ley 20.949: 20 kg para mujeres y menores de 18; 25 kg para hombres."},{"q":"Una compañera embarazada se ofrece a bajar sacos del camión. ¿Qué corresponde?","o":["No debe cargar: la ley se lo prohíbe","Puede, si cada saco pesa menos de 20 kg","Puede, si levanta con buena técnica","Puede, si lo hace entre dos personas"],"w":"Las trabajadoras embarazadas no realizan carga manual, aunque sea liviana."}]},{"s":"camion_carga_equipo","v":[{"q":"Hay que bajar barras de fierro largas del camión. ¿Cómo se hace?","o":["Entre dos o más, del mismo lado y coordinados","Uno solo, arrastrándolas desde la punta","Deslizándolas desde la plataforma al suelo","Entre dos, uno a cada lado del camión"],"w":"Lo largo se lleva en equipo, del mismo lado y avisando cada movimiento."},{"q":"Levantas un saco de cemento de 25 kg. ¿Cuál es la técnica correcta?","o":["Espalda recta, piernas flectadas y saco pegado al cuerpo","Piernas estiradas y espalda inclinada hacia adelante","Saco alejado del cuerpo para no ensuciarte","Girando la cintura mientras lo levantas"],"w":"Con la espalda recta y la carga pegada, el esfuerzo lo hacen las piernas."},{"q":"Bajan un tubo largo entre dos. ¿Cómo coordinan?","o":["Uno dirige y avisan: a la cuenta de tres","Cada uno levanta cuando está listo","El de adelante tira y el otro lo sigue","Levantan rápido y en silencio"],"w":"Uno dirige y ambos levantan y bajan al mismo tiempo."}]},{"s":"camion_carga_obra","v":[{"q":"Descargas en una casa y unos niños se acercan a mirar. ¿Qué haces?","o":["Detengo la descarga, delimito y pido que se alejen","Sigo, porque ya se van a correr solos","Les pido que me ayuden con lo liviano","Sigo, pero con más cuidado"],"w":"Los niños y los clientes no conocen el riesgo: tú delimitas y alejas."},{"q":"El cliente se ofrece a subir al camión para ayudarte a bajar la carga. ¿Qué haces?","o":["Le agradezco, pero no lo dejo subir","Lo dejo si usa guantes","Lo dejo si solo baja cosas livianas","Lo dejo si yo me quedo abajo recibiendo"],"w":"El cliente no conoce los riesgos ni tiene EPP: no se sube al camión."},{"q":"Terminas de descargar frente a la casa del cliente. ¿Cómo dejas la carga?","o":["Estable y sin bloquear el paso","Apilada alta para ocupar menos espacio","Contra la puerta, para que la vean","En la calzada, junto a la solera"],"w":"Una carga inestable o en el paso puede caer o hacer tropezar a alguien."}]},{"s":"camion_carga_epp","v":[{"q":"El EPP para cargar y descargar lo paga el trabajador.","vf":false,"w":"Falso. La empresa lo entrega sin costo (Ley 16.744, art. 68) y tú lo usas."},{"q":"Tus guantes se rompieron cargando planchas de zinc. ¿Qué haces?","o":["Pido el recambio antes de seguir","Sigo sin guantes hasta terminar","Los parcho con cinta y sigo","Compro otros por mi cuenta al salir"],"w":"El EPP dañado se cambia, y la empresa lo entrega sin costo."},{"q":"¿Por qué se usa chaleco reflectante al cargar y descargar?","o":["Para que te vean en el patio y en la calle","Para protegerte de cortes con el zinc","Para que el cliente identifique tu cargo","Para proteger la ropa del polvo y barro"],"w":"En el patio y en la calle hay vehículos: el chaleco hace que te vean."}]},{"s":"camion_carga_auto","v":[{"q":"Vas atrasado y la grúa sigue con un pallet levantado. ¿Qué haces?","o":["Espero a que la carga se apoye antes de pasar","Paso por debajo, es solo un segundo","Paso rápido junto a las horquillas","Le pido al operador que la baje de golpe"],"w":"Un segundo de apuro no vale una lesión. Se espera a que la carga se apoye."},{"q":"Debes subir a la plataforma y un peldaño está roto. ¿Qué haces?","o":["Aviso a mi jefatura y uso otro acceso seguro","Subo saltando al peldaño de arriba","Subo afirmado de la carga","Subo igual y aviso al final del turno"],"w":"Un peldaño roto es una condición insegura: se avisa y no se usa."},{"q":"Notas que en tu camión faltan los calzos. ¿Qué es lo correcto?","o":["Avisar a la jefatura para que los repongan","Usar un ladrillo suelto y no avisar","Cargar igual si el patio es plano","Cargar con el motor en marcha"],"w":"Avisar una condición insegura también es autocuidado."}]}]},{"id":"horquilla","sec":"grua","title":"Operación segura de grúa horquilla","thumb":"horquilla_portada","mins":5,"learn":[{"s":"horquilla_autorizado","t":"Solo opera quien está autorizado","x":"En {EMP}, la grúa horquilla <b>solo la opera quien cumple tres condiciones</b>:<ul><li><b>Licencia clase D</b> vigente, la que la Ley de Tránsito 18.290 exige para maquinaria automotriz.</li><li><b>Capacitación</b> en la grúa que va a usar.</li><li><b>Autorización</b> de la empresa.</li></ul>Nadie más se sube a manejarla: ni un ratito, ni para moverla un metro. Una licencia de auto, clase B, no sirve. Si te lo piden y no estás autorizado, di que no y avisa a tu jefatura.","k":"Licencia clase D, capacitado y autorizado: si no, no se opera."},{"s":"horquilla_cinturon","t":"Cinturón: siempre puesto","x":"Si la grúa se vuelca, el cinturón te mantiene <b>dentro de la cabina, bajo el techo protector</b>. Sin cinturón, el cuerpo sale disparado y la máquina cae encima. Por eso va puesto <b>en todo recorrido</b>, aunque sean diez metros o dentro de la bodega. Antes de partir: asiento ajustado, cinturón abrochado y nunca brazos ni piernas fuera de la cabina."},{"s":"horquilla_centro","t":"Placa de carga y centro de carga","x":"La <b>placa de capacidad</b> indica cuántos kilos levanta la grúa, a qué <b>centro de carga</b> y hasta qué altura. Si dice 2.000 kg a 500 mm, eso vale solo con la carga a esa distancia del respaldo. La grúa funciona como un <b>balancín</b>: el eje delantero es el apoyo y el contrapeso va atrás. Si la carga queda <b>más lejos</b>, en las puntas o con tablones y fierro largos, soporta <b>menos kilos</b>. Pégala al respaldo y <b>nunca superes la placa</b>."},{"s":"horquilla_vision","t":"Si la carga tapa la vista: en reversa","x":"Un pallet alto con cajas y tarros te tapa la visión hacia adelante. Entonces <b>avanza en reversa</b>, mirando hacia donde vas. Si igual no ves bien, pide a un compañero que te guíe. En los cruces, <b>detente y toca la bocina</b> antes de pasar. <b>Nunca avances a ciegas</b> esperando que los demás se corran: un peatón puede no verte ni oírte."},{"s":"horquilla_bajas","t":"Horquillas bajas al circular","x":"<ul><li>Lleva las horquillas <b>bajas, a unos 15 cm del piso</b>, y el mástil inclinado hacia atrás.</li><li>Sube la carga <b>solo frente al rack</b>, con la grúa detenida.</li><li><b>No gires con la carga en alto</b>, ni siquiera despacio.</li><li>Ve a velocidad moderada, según las reglas internas.</li></ul>Con la carga baja, la grúa es más estable, la carga no se cae y ves mejor hacia adelante."},{"s":"horquilla_rampa","t":"Pendientes y rampas","x":"En una rampa, <b>con carga, la carga siempre va hacia arriba</b> de la pendiente:<ul><li><b>Sube de frente</b>.</li><li><b>Baja en reversa</b>.</li></ul>Así la carga no se cae de las horquillas.<ul><li><b>Sin carga</b>, las horquillas van hacia abajo de la pendiente.</li><li>Nunca gires ni cruces de lado en una rampa.</li><li>Ve despacio y sin frenar de golpe.</li></ul>"},{"s":"horquilla_vuelco","t":"Volcamiento lateral","x":"La grúa se puede volcar hacia el lado al <b>girar rápido</b>, al girar con la <b>carga en alto</b>, al pasar por <b>hoyos o lomos</b> o al andar de lado en una pendiente. Si se vuelca: <b>no saltes</b>, ni hacia un lado ni hacia el otro. Quédate dentro con el cinturón, <b>afírmate al volante</b>, apoya los pies e inclínate al lado contrario del vuelco. Saltar es lo más peligroso: la máquina o el techo protector te pueden aplastar."},{"s":"horquilla_personas","t":"Nunca levantar personas","x":"Las horquillas son para cargas. <b>Nunca levantes a una persona</b> sobre las horquillas ni sobre un pallet para alcanzar algo del rack, ni la lleves de pasajero. No tiene baranda ni sujeción: un movimiento y cae desde altura. Para subir se usa una escalera en buen estado o el <b>equipo diseñado para personas</b>. Tampoco dejes que nadie camine bajo las horquillas levantadas. <b>Subirse a las horquillas es una falta grave que puede ser sancionada.</b>","k":"Las horquillas son para cargas, nunca para personas."},{"s":"horquilla_estacionar","t":"Al estacionar","x":"<ul><li>Horquillas <b>apoyadas en el piso</b>.</li><li><b>Freno de estacionamiento</b> puesto.</li><li>Motor apagado y <b>llave retirada</b>.</li><li>En el lugar que indique tu jefatura, plano y lejos de salidas, extintores, pasillos y cruces.</li></ul>Así nadie tropieza con las horquillas, no se bloquea una salida de emergencia y nadie no autorizado la puede mover."},{"s":"horquilla_auto","t":"Autocuidado: tú decides","x":"La mayoría de los accidentes se relacionan con una acción insegura. Con la grúa, las típicas son <b>apurarse</b> porque hay un camión o un cliente esperando, girar rápido con carga, llevar dos pallets que superan la placa y <b>no ponerse el cinturón</b> porque el recorrido es corto. La decisión segura: <b>trabajar con calma</b>. Avisa a tu jefatura o al asesor en prevención los pisos dañados y las fallas."}],"quiz":[{"s":"horquilla_q_quien","v":[{"q":"¿Quién puede operar la grúa horquilla en la sucursal?","o":["Quien tiene licencia clase D, capacitación y autorización","Quien tiene licencia clase B y sabe manejar bien","Quien tiene licencia clase D, aunque no esté autorizado","El vendedor que esté más cerca cuando se necesite"],"w":"Se exigen las tres cosas: licencia clase D, capacitación y autorización de la empresa."},{"q":"Un compañero con licencia de auto te pide la grúa para mover un pallet un metro. ¿Qué haces?","o":["No se la presto y aviso a mi jefatura","Se la presto, porque es solo un metro","Se la presto, si yo lo voy guiando","Se la presto, si operó grúas en otra empresa"],"w":"Nadie sin licencia clase D y sin autorización opera la grúa, ni un ratito."},{"q":"¿Qué licencia exige la Ley de Tránsito para operar una grúa horquilla?","o":["Clase D","Clase B","Clase A4","Clase C"],"w":"La clase D corresponde a maquinaria automotriz, como la grúa horquilla. Además se requiere autorización de la empresa."}]},{"s":"horquilla_altas","v":[{"q":"Trasladas un pallet de pinturas desde la bodega al patio. ¿Cómo lo llevas?","o":["Horquillas bajas y mástil inclinado hacia atrás","Carga en alto, para ver por debajo","Horquillas a media altura, listas para el rack","Mástil inclinado hacia adelante para dejarlo rápido"],"w":"Con la carga baja, la grúa es más estable y ves mejor."},{"q":"¿Cuándo se sube la carga a la altura del rack?","o":["Frente al rack, con la grúa detenida","Mientras te acercas, para ganar tiempo","Al girar para entrar al pasillo","Apenas sales del patio"],"w":"La carga se sube solo frente al rack y detenido. Circular con carga alta puede volcar la grúa."},{"q":"Puedo girar con la carga en alto si voy despacio.","vf":false,"w":"Falso. Girar con la carga en alto puede volcar la grúa aunque vayas despacio."}]},{"s":"horquilla_q_vision","v":[{"q":"Llevas un pallet alto que no te deja ver hacia adelante. ¿Qué haces?","o":["Avanzo en reversa, mirando hacia donde voy","Avanzo despacio tocando la bocina","Subo la carga para mirar por debajo","Avanzo asomándome por el costado"],"w":"Con la vista tapada se avanza en reversa. Si igual no ves, pide que alguien te guíe."},{"q":"Vas en reversa con la carga tapando la vista y aún no ves bien el camino. ¿Qué haces?","o":["Pido a un compañero que me guíe","Vuelvo a avanzar de frente","Sigo: los demás se van a correr","Subo la carga para ver mejor"],"w":"Si no ves, alguien te guía. Nunca se avanza a ciegas."},{"q":"Llegas a un cruce de la bodega con la vista tapada por la carga. ¿Qué haces?","o":["Me detengo, toco la bocina y paso en reversa","Paso de frente tocando la bocina seguido","Subo un poco la carga para ver y paso","Acelero para despejar pronto el cruce"],"w":"En los cruces: detenerse, avisar con la bocina y pasar mirando hacia donde vas."}]},{"s":"horquilla_centro_mal","v":[{"q":"El pallet quedó en las puntas de las horquillas. ¿Qué haces?","o":["Lo bajo y lo pego al respaldo de carga","Lo llevo igual, pero despacio","Lo llevo con el mástil hacia adelante","Pido a un compañero que se suba atrás de contrapeso"],"w":"En las puntas, el centro de carga se aleja, la grúa soporta menos y se puede ir hacia adelante."},{"q":"La placa dice 2.000 kg a 500 mm. Llevas tablones largos cuyo centro queda más lejos. ¿Qué pasa?","o":["La grúa soporta menos de 2.000 kg","La grúa soporta más de 2.000 kg","La capacidad sigue siendo 2.000 kg","Solo cambia si los subes en altura"],"w":"Como en un balancín: mientras más lejos el centro de la carga, menos kilos soporta."},{"q":"¿Qué indica la placa de capacidad de la grúa?","o":["Los kilos, a qué centro de carga y hasta qué altura","Solo el peso de la grúa vacía","La velocidad máxima de circulación","Los kilos que levanta a cualquier distancia"],"w":"La placa fija kilos, centro de carga y altura. Nunca se supera."}]},{"s":"horquilla_q_rampa","v":[{"q":"Debes bajar una rampa con un pallet de cemento. ¿Cómo lo haces?","o":["En reversa, con la carga hacia arriba","De frente, con la carga hacia abajo","De lado, para ir más despacio","De frente, con la carga bien alta"],"w":"Con carga, la carga siempre va hacia arriba de la pendiente: se sube de frente y se baja en reversa."},{"q":"Subes una rampa con un pallet de cerámicas. ¿Cómo lo haces?","o":["De frente, con la carga hacia arriba","En reversa, con la carga hacia abajo","En diagonal, para que cueste menos","De frente, girando a mitad de la rampa"],"w":"Subiendo de frente la carga queda hacia arriba y no se cae de las horquillas."},{"q":"Vas sin carga por una rampa. ¿Hacia dónde apuntan las horquillas?","o":["Hacia abajo de la pendiente","Hacia arriba de la pendiente","Da lo mismo cuando va sin carga","Hacia el lado, cruzando la rampa"],"w":"Sin carga es al revés: las horquillas van hacia abajo de la pendiente."}]},{"s":"horq_q_vuelco","v":[{"q":"La grúa empieza a volcarse hacia un lado. ¿Qué haces?","o":["Me quedo dentro, me afirmo y me inclino al lado contrario","Salto rápido hacia el lado que se vuelca","Salto hacia el lado contrario al vuelco","Suelto el volante y me agacho en el asiento"],"w":"Saltar es lo más peligroso: la máquina y el techo protector te pueden aplastar."},{"q":"¿Cuál de estas maniobras puede volcar la grúa hacia el lado?","o":["Girar rápido con la carga en alto","Circular despacio con horquillas bajas","Subir una rampa de frente con carga","Frenar suave antes de un cruce"],"w":"Girar rápido, girar con carga alta, pasar hoyos o andar de lado en pendiente provocan vuelcos."},{"q":"Si la grúa se vuelca, saltar de la cabina es más peligroso que quedarse dentro con el cinturón.","vf":true,"w":"Verdadero. Dentro, el cinturón te mantiene bajo el techo protector."}]},{"s":"horquilla_q_pers","v":[{"q":"Un compañero puede subirse a un pallet sobre las horquillas para sacar algo del rack, si subo despacio.","vf":false,"w":"Falso. Las horquillas son para cargas. Nunca se levanta a una persona con la grúa."},{"q":"Un compañero te pide que lo subas en un pallet para alcanzar una caja del rack. ¿Qué haces?","o":["Me niego: para subir se usa escalera o equipo","Lo subo despacio si se afirma bien del mástil","Lo subo si es solo hasta el primer nivel","Lo subo si usa casco, guantes y zapatos"],"w":"Sin baranda ni sujeción, cualquier movimiento lo hace caer desde altura."},{"q":"¿Qué es subirse a las horquillas de la grúa en {EMP}?","o":["Una falta grave que puede ser sancionada","Algo permitido si el operador va despacio","Algo permitido solo en emergencias","Una falta leve si no hay accidente"],"w":"Es una falta grave: pone en riesgo de caída desde altura."}]},{"s":"horquilla_cinturon","v":[{"q":"Vas a mover la grúa solo diez metros dentro de la bodega. ¿Qué haces con el cinturón?","o":["Me lo pongo igual","No lo uso, son pocos metros","Me lo pongo solo si llevo carga","Me lo pongo solo al salir al patio"],"w":"Un vuelco ocurre en segundos, también en recorridos cortos."},{"q":"¿Para qué sirve el cinturón en la grúa horquilla?","o":["Para mantenerte bajo el techo protector si se vuelca","Para no cansarte en recorridos largos","Solo para cumplir con el check-list","Solo para recorridos fuera de la bodega"],"w":"Sin cinturón, en un vuelco el cuerpo sale y la máquina cae encima."},{"q":"El cinturón se usa en la grúa aunque el recorrido sea corto.","vf":true,"w":"Verdadero. El cinturón va puesto en todo recorrido."}]},{"s":"horquilla_q_estac","v":[{"q":"Terminas tu turno. ¿Cómo dejas la grúa?","o":["Horquillas al piso, freno puesto, motor apagado y llave fuera","Horquillas a media altura para la próxima carga","Motor apagado, pero con la llave puesta","Freno puesto, frente al extintor más cercano"],"w":"Así nadie tropieza con las horquillas y nadie no autorizado la puede mover."},{"q":"¿Dónde no debes estacionar la grúa?","o":["Frente a salidas, extintores o en pasillos","En el lugar que indica la jefatura","En una zona plana, lejos de los cruces","En un sector despejado del patio"],"w":"Una grúa mal estacionada bloquea salidas y equipos de emergencia."},{"q":"¿Por qué se retira la llave al dejar la grúa?","o":["Para que nadie no autorizado la mueva","Para que no se descargue la batería","Para que el motor se enfríe antes","Para que no suene la alarma"],"w":"Con la llave fuera, solo un operador autorizado puede usarla."}]},{"s":"horquilla_q_apuro","v":[{"q":"Hay un camión esperando y te piden apurarte. ¿Cuál es la decisión segura?","o":["Trabajar con calma: carga baja, velocidad moderada y cinturón","Girar más rápido con la carga en alto","Cargar dos pallets juntos aunque superen la placa","Andar sin cinturón para subir y bajar más rápido"],"w":"Apurarse es la acción insegura típica. Unos minutos de espera valen menos que un vuelco."},{"q":"Quieres llevar dos pallets juntos para ahorrar un viaje, pero superan la placa. ¿Qué haces?","o":["Hago dos viajes","Los llevo despacio y con la carga baja","Los llevo con un compañero atrás de contrapeso","Los llevo si el recorrido es corto"],"w":"La placa nunca se supera: la grúa puede irse hacia adelante."},{"q":"Ves un hoyo en el piso del patio por donde pasa la grúa. ¿Qué haces?","o":["Aviso a mi jefatura o al asesor en prevención","Paso rápido para no quedar atascado","Lo esquivo y no digo nada","Lo relleno con cartón y sigo"],"w":"Un hoyo puede volcar la grúa. Avisar un piso dañado también es autocuidado."}]}]},{"id":"horquilla_patio","sec":"grua","title":"Grúa horquilla en patio y sala: peatones y clientes","thumb":"horquilla_patio_intro","mins":5,"learn":[{"s":"horquilla_patio_intro","t":"Un patio compartido","x":"En el patio de una ferretería la grúa comparte espacio con <b>clientes, sus camionetas, vendedores, peonetas y camiones</b>. Los clientes no conocen las reglas del patio ni usan chaleco, y los <b>niños</b> que vienen con sus padres no anticipan el peligro. Por eso el operador debe <b>anticiparse</b>: mirar siempre, ir a velocidad moderada según las reglas internas de {EMP} y suponer que alguien puede aparecer. Si hay un niño cerca, <b>detente por completo</b>."},{"s":"horquilla_patio_celular","t":"Peatones distraídos","x":"Un cliente mirando el celular, buscando su auto, conversando o con audífonos <b>no te ve ni te escucha</b>. No esperes que se corra ni lo esquives pasando cerca.<ul><li><b>Detente</b>.</li><li>Toca la bocina.</li><li>Espera a que te vea y se aleje.</li><li>Pasa solo con el camino libre.</li></ul>Si un peatón no te mira, asume que <b>no te ha visto</b>."},{"s":"horquilla_patio_cruce","t":"Cruces, puertas y esquinas","x":"En las <b>esquinas ciegas</b>, salidas de bodega, portones y cruces con pasillos:<ul><li><b>Frena</b> antes de llegar.</li><li>Toca la <b>bocina</b>.</li><li><b>Mira</b> a ambos lados.</li><li>Avanza despacio.</li></ul>Los atropellos ocurren cuando la grúa y el peatón aparecen al mismo tiempo en el mismo punto. Si en tu patio hay un cruce sin visibilidad, avísalo a tu jefatura."},{"s":"horquilla_patio_luces","t":"Bocina y luces: avisan, no protegen","x":"La <b>bocina</b>, la <b>baliza</b> y la <b>alarma de retroceso</b>, si tu grúa la tiene, sirven para avisar. Pero <b>no son un permiso para pasar</b> ni te dan preferencia: el cliente puede no oír, no entender o tener audífonos. Después de avisar, <b>igual tienes que mirar</b> y esperar. Si la bocina, la baliza o la alarma no funcionan, es una falla: se informa antes de operar."},{"s":"horquilla_patio_contacto","t":"Contacto visual","x":"Antes de avanzar cerca de una persona, <b>busca su mirada</b>. Si te mira y te hace una seña, sabes que te vio. Si <b>no te mira</b>, asume que <b>no te vio</b> y detente. Lo mismo con el conductor de una camioneta o de un camión: si no hay contacto visual, no te muevas. Tocar la bocina no reemplaza este paso.","k":"Sin contacto visual, no hay paso."},{"s":"horquilla_patio_zonas","t":"Zonas delimitadas","x":"Si tu sucursal tiene <b>zonas exclusivas</b> para la grúa y <b>pasos peatonales</b> demarcados, respétalos siempre y no los uses como atajo, aunque estén vacíos: un peatón puede aparecer en cualquier momento. Si en tu patio no están marcados o hay un sector peligroso, <b>avisa a tu jefatura</b> o al asesor en prevención. Mientras tanto, usa <b>conos</b> para separar tu zona de maniobra."},{"s":"horquilla_patio_camioneta","t":"Cargar la camioneta de un cliente","x":"<ul><li>Camioneta <b>detenida, con motor apagado</b> y freno puesto.</li><li>El cliente <b>fuera del vehículo y a distancia</b>: nunca dentro de la caja ni ayudando bajo la carga.</li><li>Deja la carga centrada, pareja y sin golpear la carrocería.</li><li>No cargues más de lo que la camioneta soporta.</li></ul>Antes de que salga, la carga debe ir <b>estibada y amarrada</b> para que no se mueva ni caiga a la vía."},{"s":"horquilla_patio_sobre","t":"Nunca carga sobre personas","x":"<b>Nunca pases la carga por encima de una persona</b> ni de un vehículo con gente adentro. Un saco o un tarro puede caer del pallet aunque esté bien cargado. Si alguien se mete bajo la carga o en tu ruta, <b>detente y bájala</b>. Tampoco dejes que nadie camine ni se pare bajo las horquillas levantadas, ni siquiera para mirar un producto.","k":"Bajo la carga levantada no hay nadie. Nunca."},{"s":"horquilla_patio_sala","t":"Operar en bodega o sala con público","x":"Si debes reponer con la grúa donde hay clientes:<ul><li>Pide a un compañero que <b>despeje y te guíe</b>.</li><li><b>Delimita con conos</b> o cinta el área de trabajo.</li><li>Ve muy despacio y con la carga baja hasta llegar al rack.</li><li>Si un cliente entra al área, <b>detente</b> hasta que salga.</li></ul>Pregunta a tu jefatura si hay horarios definidos para esta tarea, como antes de abrir."},{"s":"horquilla_patio_auto","t":"Autocuidado: tú decides","x":"La mayoría de los accidentes se relacionan con una acción insegura. En el patio, las típicas son <b>pasar justo</b> al lado de un cliente, confiar en que <b>la bocina basta</b> y apurarse porque hay fila. La decisión segura: <b>detenerte y esperar</b> el contacto visual. Avisar un patio sin demarcación o un cruce ciego también es autocuidado."}],"quiz":[{"s":"horquilla_patio_celular","v":[{"q":"Un cliente cruza el patio mirando su celular, en tu ruta. ¿Qué haces?","o":["Me detengo, toco la bocina y espero que me vea y se aleje","Sigo despacio, porque él debe fijarse","Lo esquivo pasando por su espalda","Toco la bocina y sigo a la misma velocidad"],"w":"Un peatón distraído no te ve. El que se detiene es el operador."},{"q":"Un cliente busca su auto y camina hacia tu ruta sin verte. ¿Qué haces?","o":["Me detengo y espero que me vea antes de pasar","Toco la bocina seguido y avanzo de a poco","Paso cerca de él, pero bien despacio","Enciendo la baliza y sigo por mi ruta"],"w":"No esperes que se corra: detente hasta que te vea y el camino quede libre."},{"q":"Dos clientes conversan en medio de tu ruta y no te miran. ¿Qué haces?","o":["Me detengo y espero que se den cuenta y se aparten","Paso por el lado más ancho sin detenerme","Toco la bocina y avanzo hacia ellos","Paso por su lado con la carga en alto"],"w":"Quien conversa no te ve ni te escucha. Detente y espera."}]},{"s":"horquilla_patio_contacto","v":[{"q":"Un cliente está cerca de tu ruta. ¿Cuándo puedes avanzar?","o":["Cuando me mira, me hace una seña y se aparta","Cuando ya toqué la bocina dos veces","Cuando tengo la baliza encendida","Cuando está a más de un metro"],"w":"El contacto visual es la única forma de saber que te vio."},{"q":"El conductor de una camioneta está detenido junto a tu ruta, pero no te mira. ¿Qué haces?","o":["Me detengo hasta tener contacto visual","Paso rápido antes de que arranque","Toco la bocina y paso","Paso por detrás de la camioneta"],"w":"Si no hay contacto visual, no te muevas: puede arrancar o retroceder sin verte."},{"q":"Si un peatón no me mira, debo suponer que no me ha visto.","vf":true,"w":"Verdadero. Sin contacto visual, asume que no te vio y detente."}]},{"s":"horquilla_patio_luces","v":[{"q":"Si ya toqué la bocina y la baliza está encendida, puedo pasar aunque el peatón no me haya mirado.","vf":false,"w":"Falso. La bocina y las luces avisan, pero no protegen. Sin contacto visual no hay paso."},{"q":"¿Qué función cumplen la bocina y la baliza de la grúa?","o":["Avisan, pero no dan el paso ni protegen","Dan preferencia de paso a la grúa","Reemplazan el contacto visual","Obligan al peatón a detenerse"],"w":"El peatón puede no oír o no entender. Después de avisar, igual miras y esperas."},{"q":"Al empezar el turno notas que la baliza de la grúa no enciende. ¿Qué haces?","o":["La informo como falla antes de operar","Opero igual, con la bocina basta","Opero solo dentro de la bodega","La informo al terminar el turno"],"w":"Un dispositivo de aviso que no funciona es una falla de la grúa."}]},{"s":"horquilla_patio_camioneta","v":[{"q":"Al cargar su camioneta, el cliente quiere quedarse arriba de la caja para acomodar los sacos. ¿Qué corresponde?","o":["Le pido que baje y se aleje antes de acercar la carga","Lo dejo si se queda al fondo de la caja","Cargo con cuidado, pasando la carga por su lado","Lo dejo si usa guantes y zapatos"],"w":"El cliente debe estar fuera del vehículo y a distancia. Nunca bajo ni junto a la carga."},{"q":"Vas a cargar la camioneta de un cliente y tiene el motor encendido. ¿Qué haces?","o":["Espero que apague, ponga freno y se baje","Cargo rápido para que se vaya luego","Cargo si el cliente se queda al volante","Cargo con la carga alta para no tocarla"],"w":"La camioneta va detenida, con motor apagado y freno puesto, y el cliente afuera y lejos."},{"q":"¿Cómo debe quedar la carga en la camioneta del cliente?","o":["Centrada, pareja, estibada y amarrada","Cargada atrás, para bajarla fácil","Sin amarrar, si el cliente vive cerca","Alta, para aprovechar el espacio"],"w":"La carga debe ir estibada y amarrada para que no se mueva ni caiga a la vía."}]},{"s":"horquilla_patio_cruce","v":[{"q":"Llegas a una esquina ciega entre la bodega y el patio. ¿Qué haces?","o":["Freno, toco la bocina, miro y avanzo despacio","Toco la bocina y paso sin frenar","Acelero para cruzar rápido","Paso sin detenerme, porque es mi ruta"],"w":"En la esquina ciega: frena, bocina y mira."},{"q":"Sales por el portón de la bodega hacia el patio. ¿Qué haces antes de salir?","o":["Freno, toco la bocina y miro a ambos lados","Salgo rápido para despejar el portón","Toco la bocina y salgo de inmediato","Salgo con la carga alta para ver mejor"],"w":"Portones y salidas son puntos ciegos: frena, avisa y mira antes de salir."},{"q":"¿Por qué hay que frenar antes de una esquina ciega?","o":["Porque un peatón puede aparecer al mismo tiempo","Porque la grúa gasta menos al frenar","Porque así lo pide el check-list","Porque la bocina solo funciona detenido"],"w":"Los atropellos ocurren cuando la grúa y el peatón aparecen a la vez en el mismo punto."}]},{"s":"horquilla_patio_q_sala","v":[{"q":"Debes reponer un rack de la sala con la grúa y hay clientes cerca. ¿Qué haces?","o":["Delimito con conos y pido a un compañero que despeje y me guíe","Trabajo rápido para molestar poco a los clientes","Toco la bocina seguido y avanzo","Trabajo con la carga alta para no chocar a nadie"],"w":"Con público cerca: área delimitada, alguien que guíe y detenerse si un cliente entra."},{"q":"Repones con la grúa en la sala y un cliente entra al área delimitada. ¿Qué haces?","o":["Me detengo hasta que salga del área","Sigo, porque el área está marcada","Toco la bocina y sigo trabajando","Sigo, pero más despacio"],"w":"Si un cliente entra al área, la grúa se detiene."},{"q":"Al reponer en la sala con público, ¿cómo circulas hasta el rack?","o":["Muy despacio y con la carga baja","Normal, porque hay un compañero guiando","Con la carga alta para no chocar góndolas","Rápido, para terminar antes"],"w":"En la sala se circula muy despacio y la carga se sube solo frente al rack."}]},{"s":"horquilla_patio_zonas","v":[{"q":"El paso peatonal demarcado está vacío. ¿Puedo usarlo como atajo con la grúa?","o":["No, las zonas demarcadas se respetan siempre","Sí, porque en ese momento está vacío","Sí, si toco la bocina antes de entrar","Sí, si voy sin carga y a poca velocidad"],"w":"Las zonas delimitadas se respetan siempre. Un peatón puede aparecer en cualquier momento."},{"q":"Tu patio no tiene pasos peatonales marcados. ¿Qué haces?","o":["Aviso a mi jefatura y separo mi zona con conos","Trabajo igual, porque nadie lo exige","Circulo por donde caminan los clientes","Trabajo con la baliza y no aviso"],"w":"Un patio sin demarcación es una condición insegura: se avisa y, mientras, se usan conos."},{"q":"Mientras tu patio no tenga demarcación, ¿cómo separas tu zona de maniobra?","o":["Con conos","Con la baliza encendida","Tocando la bocina cada cierto tiempo","Llevando la carga en alto como aviso"],"w":"Los conos separan físicamente la zona de la grúa de los peatones."}]},{"s":"horquilla_patio_sobre","v":[{"q":"¿Puedes pasar la carga por encima de una camioneta con gente adentro?","o":["No, nunca se pasa carga sobre personas","Sí, si la carga va bien centrada","Sí, si paso despacio","Sí, si el pallet tiene film"],"w":"Un saco o un tarro puede caer del pallet. Nunca carga sobre personas."},{"q":"Un cliente se pone bajo las horquillas levantadas para mirar un producto. ¿Qué haces?","o":["Me detengo y bajo la carga","Subo más la carga para darle espacio","Le pido que se apure y sigo","Sigo, porque está fuera de mi ruta"],"w":"Bajo la carga levantada no hay nadie. Detente y bájala."},{"q":"Un saco o un tarro puede caer de un pallet levantado, aunque esté bien cargado.","vf":true,"w":"Verdadero. Por eso nunca se pasa carga sobre personas ni se deja a nadie bajo las horquillas."}]},{"s":"horquilla_patio_nino","v":[{"q":"Un niño que vino con su papá corre hacia el patio, cerca de tu grúa. ¿Qué haces?","o":["Me detengo del todo y espero que el adulto lo aleje","Toco la bocina y sigo bien despacio","Retrocedo rápido para alejarme del niño","Sigo, porque el papá es quien debe cuidarlo"],"w":"Los niños no anticipan el peligro. Detente del todo hasta que el área esté despejada."},{"q":"¿Por qué, con niños cerca, hay que detener la grúa por completo?","o":["Porque no anticipan el peligro y se mueven de improviso","Porque la bocina los puede asustar","Porque lo exige el cliente","Porque los niños no pueden estar en la sucursal"],"w":"Un niño puede correr hacia la grúa sin aviso. Solo detenido evitas el atropello."},{"q":"Si un niño corre cerca de la grúa, basta con tocar la bocina y seguir despacio.","vf":false,"w":"Falso. Con un niño cerca, la grúa se detiene por completo."}]},{"s":"horquilla_patio_auto","v":[{"q":"Hay fila de clientes esperando su carga. ¿Cuál es la decisión segura?","o":["Velocidad moderada y detenerme ante cada peatón","Pasar justo al lado de los clientes para ganar tiempo","Llevar la carga en alto para ir más rápido","Confiar en la bocina y no detenerme"],"w":"Apurarse por la fila es la acción insegura típica. Esperar unos segundos no atrasa a nadie."},{"q":"Hay un cruce ciego en tu patio, sin espejo ni demarcación. ¿Qué haces?","o":["Lo aviso a mi jefatura: es una condición insegura","Lo paso rápido para estar menos tiempo ahí","Me acostumbro a él y no digo nada","Lo paso tocando la bocina sin frenar"],"w":"Avisar un cruce ciego también es autocuidado."},{"q":"¿Cuál es una acción insegura típica del operador en el patio?","o":["Pasar justo al lado de un cliente por apuro","Esperar el contacto visual antes de avanzar","Delimitar la zona con conos","Frenar antes de una esquina ciega"],"w":"Pasar justo, confiar en la bocina y apurarse por la fila son las acciones inseguras típicas."}]}]},{"id":"horquilla_checklist","sec":"grua","title":"Revisión pre-uso y cuidado de la grúa","thumb":"horquilla_checklist_porque","mins":5,"learn":[{"s":"horquilla_checklist_porque","t":"El check-list diario","x":"Antes de usar la grúa <b>en cada turno</b>, revísala con el <b>check-list</b>, aunque otro operador ya la haya usado ese día: algo pudo cambiar. Un freno que falla con un pallet de cemento arriba no se arregla en el momento. La revisión toma unos minutos y te dice si la máquina está en condiciones de trabajar <b>hoy</b>. La hace el operador autorizado que la va a usar."},{"s":"horquilla_checklist_vuelta","t":"La vuelta alrededor","x":"Con el motor apagado, <b>da una vuelta completa</b> a la grúa y mira:<ul><li><b>Neumáticos</b>: cortes, desgaste y pernos completos.</li><li><b>Fugas</b>: manchas de aceite, combustible o líquido bajo la grúa.</li><li>Golpes, piezas sueltas o faltantes.</li><li><b>Techo protector</b> y respaldo de carga en su lugar.</li><li>Niveles de aceite y combustible, o carga de la batería, según tu grúa.</li></ul>Una mancha fresca bajo la grúa es una falla, no un detalle."},{"s":"horquilla_checklist_horq","t":"Horquillas, cadenas y mástil","x":"<ul><li><b>Horquillas</b>: sin trizaduras, sin estar dobladas, sin desgaste excesivo y con su traba puesta.</li><li><b>Cadenas</b>: sin eslabones dañados ni oxidados y con tensión pareja.</li><li><b>Mástil</b>: sin golpes; las <b>mangueras hidráulicas</b> sin fugas ni grietas.</li></ul>Estas partes sostienen la carga: si una horquilla se quiebra o una cadena se corta, la carga cae. No se usa la grúa con cargas livianas mientras tanto: se detiene y se informa."},{"s":"horquilla_checklist_cabina","t":"Desde el asiento, motor encendido","x":"Ponte el cinturón, enciende y prueba:<ul><li><b>Frenos</b> de servicio y de estacionamiento.</li><li><b>Dirección</b>: que gire suave y sin juego.</li><li><b>Bocina</b> y <b>luces</b>.</li><li><b>Alarma de retroceso</b> y baliza, si la tiene.</li><li>Subir, bajar e inclinar el mástil, sin tirones ni ruidos raros.</li><li>Cinturón que abroche y se trabe.</li></ul>Si no frena, no avisa, no gira bien o no levanta bien: no sale."},{"s":"horquilla_checklist_falla","t":"Si algo falla","x":"<ul><li><b>No la uses</b>, ni solo un rato ni con cuidado.</li><li><b>Informa</b> de inmediato a tu jefatura.</li><li><b>Bloquéala</b>: saca la llave y pon una tarjeta de NO OPERAR o el aviso que use tu sucursal.</li></ul>Así el siguiente turno no la usa sin saber. Avisar de palabra no basta. No intentes repararla si no es tu función: la revisa personal de mantención.","k":"Grúa con falla: no se usa, se informa y se bloquea."},{"s":"horquilla_checklist_firma","t":"Marca con la verdad","x":"El check-list es un <b>registro</b>: lo que marcas queda como constancia de que la grúa se revisó. <b>Nunca lo firmes sin revisar</b>, ni aunque te lo pida un compañero, ni marques bien algo que está mal. Si un ítem está malo, <b>anótalo como malo</b>: ese registro sirve para que la reparen y protege al próximo operador. Firmar sin revisar es engañarte a ti mismo."},{"s":"horquilla_checklist_glp","t":"Si tu grúa es a gas: cambio de cilindro","x":"Según el tipo de tu grúa y el manual del fabricante:<ul><li>Primero, <b>motor apagado</b> y <b>válvula del cilindro cerrada</b>.</li><li>En lugar ventilado, <b>lejos de fuego</b> y sin fumar.</li><li>Usa <b>guantes y lentes</b>: el gas licuado quema la piel por frío.</li><li>Fija bien el cilindro y revisa la conexión.</li><li>Busca fugas con <b>agua jabonosa</b>: si salen burbujas, hay fuga. Nunca con una llama.</li></ul>","k":"Las fugas de gas se buscan con agua jabonosa, jamás con fuego."},{"s":"horquilla_checklist_bateria","t":"Si tu grúa es eléctrica: carga de batería","x":"Según el tipo de tu grúa:<ul><li>Carga solo en el <b>lugar destinado</b>, que debe ser <b>ventilado</b>, nunca en una sala cerrada ni en cualquier enchufe.</li><li>Grúa apagada y freno puesto antes de conectar el cargador.</li><li><b>No fumes</b> ni hagas chispas: algunas baterías liberan <b>gases inflamables</b> al cargar.</li><li>Si hay riesgo de contacto con ácido, usa guantes y lentes.</li></ul>"},{"s":"horquilla_checklist_combustible","t":"Carga de combustible","x":"Si tu grúa usa diésel o bencina:<ul><li><b>Motor apagado</b> siempre al cargar, aunque sea un momento.</li><li><b>No fumes</b> ni uses llamas cerca.</li><li>No llenes hasta rebalsar.</li><li>Si se derrama, <b>limpia antes de encender</b>.</li><li>Ten ubicado el <b>extintor</b> más cercano.</li></ul>Un vapor de combustible y una chispa bastan para un incendio."},{"s":"horquilla_checklist_auto","t":"Autocuidado: tú decides","x":"La mayoría de los accidentes se relacionan con una acción insegura. Aquí, la típica es <b>saltarse la revisión</b> porque ayer andaba bien o hay apuro, y <b>usar la grúa con una falla</b> conocida. La decisión segura: revisarla cada turno, aunque haya un camión esperando, y <b>detenerla si algo falla</b>. Avisar una falla a tu jefatura o al asesor en prevención también es autocuidado."}],"quiz":[{"s":"horquilla_checklist_porque","v":[{"q":"¿Cuándo se hace el check-list de la grúa?","o":["Antes de usarla, en cada turno","Una vez a la semana, el lunes","Solo cuando hace ruidos raros","Al final del turno, al dejarla"],"w":"La revisión se hace antes de usarla en cada turno."},{"q":"Entras al turno de la tarde y la grúa ya se usó en la mañana. ¿Qué haces?","o":["La reviso con el check-list antes de usarla","La uso: ya la revisó el turno de la mañana","La reviso solo si el operador anterior avisó algo","La reviso al final de mi turno"],"w":"Cada operador revisa antes de usarla en su turno. Algo pudo cambiar."},{"q":"Si el check-list del turno anterior está firmado, yo no necesito revisar la grúa.","vf":false,"w":"Falso. Cada operador revisa antes de usarla en su turno. Algo pudo cambiar."}]},{"s":"horquilla_checklist_q_frenos","v":[{"q":"Al probar la grúa, el freno se siente blando. ¿Qué haces?","o":["No la uso, informo a mi jefatura y la bloqueo","La uso con cuidado y a poca velocidad","La uso hasta terminar el turno y después aviso","La uso solo dentro de la bodega, sin carga"],"w":"Grúa con falla: no se usa, se informa y se bloquea para que nadie la use sin saber."},{"q":"Encuentras una falla en la grúa. ¿Cuáles son los tres pasos?","o":["No usarla, informar y bloquearla","Usarla con cuidado, informar y repararla","Informar al final del turno y seguir","Bloquearla y repararla yo mismo"],"w":"No se usa, se informa y se bloquea. La reparación la hace quien corresponde."},{"q":"¿Cómo se bloquea una grúa con falla?","o":["Sacando la llave y poniendo una tarjeta de NO OPERAR","Estacionándola en un rincón del patio","Dejando las horquillas en alto como aviso","Avisando de palabra al siguiente turno"],"w":"Sin llave y con tarjeta, el siguiente turno sabe que no debe usarla."}]},{"s":"horquilla_checklist_llama","v":[{"q":"¿Cómo se busca una fuga en la conexión del cilindro de gas?","o":["Con agua jabonosa: las burbujas muestran la fuga","Con un encendedor: la llama muestra la fuga","Oliendo de cerca la conexión","Escuchando si la conexión silba"],"w":"Las fugas se buscan con agua jabonosa. Jamás con una llama."},{"q":"Un compañero acerca un encendedor a la válvula para ver si hay fuga. ¿Qué haces?","o":["Lo detengo: se busca con agua jabonosa","Lo dejo, si lo hace rápido y con cuidado","Lo dejo, si la grúa está apagada","Le pido que lo haga al aire libre"],"w":"Una llama junto a una fuga de gas puede causar un incendio o una explosión."},{"q":"Revisas la conexión del cilindro con agua jabonosa y aparecen burbujas. ¿Qué significa?","o":["Que hay una fuga: no se usa y se informa","Que la conexión está bien apretada","Que el cilindro está lleno","Que el agua tenía mucho jabón"],"w":"Las burbujas indican que sale gas: es una falla."}]},{"s":"horquilla_checklist_vuelta","v":[{"q":"Al dar la vuelta a la grúa ves una mancha de aceite fresca bajo ella. ¿Qué haces?","o":["La informo como falla antes de usar la grúa","La limpio y sigo operando","La uso y reviso de nuevo al final","La uso, si los frenos funcionan"],"w":"Una mancha fresca indica una fuga: es una falla que se informa."},{"q":"¿Qué se revisa en la vuelta alrededor de la grúa, con el motor apagado?","o":["Neumáticos, fugas, golpes y techo protector","Solo el nivel de combustible del estanque","Solo los frenos y la bocina de la grúa","La bocina, las luces y la alarma de retroceso"],"w":"La vuelta revisa lo que se ve desde afuera; frenos, bocina y luces se prueban desde el asiento."},{"q":"En la vuelta ves que falta un perno en una rueda. ¿Qué haces?","o":["No la uso, informo y la bloqueo","La uso solo dentro de la bodega","La uso sin carga hasta que la reparen","Aprieto los otros pernos y sigo"],"w":"Una rueda sin todos sus pernos es una falla: no se usa."}]},{"s":"horquilla_checklist_cabina","v":[{"q":"La alarma de retroceso no suena, pero la bocina sí. ¿Puedo usar la grúa igual?","o":["No: es una falla, se informa y no se usa","Sí, porque con la bocina basta","Sí, si retrocedo poco y despacio","Sí, si un compañero me va guiando"],"w":"Si un dispositivo de aviso falla, es una falla de la grúa. Se informa y no se usa."},{"q":"¿Qué se prueba desde el asiento, con el motor encendido?","o":["Frenos, dirección, bocina, luces y mástil","Solo que el motor encienda y no se apague","Solo el nivel de combustible del estanque","Los neumáticos y las fugas bajo la grúa"],"w":"Desde el asiento se prueba todo lo que te permite frenar, girar, avisar y levantar."},{"q":"Si la dirección tiene juego, la grúa no debe usarse hasta que la revisen.","vf":true,"w":"Verdadero. La dirección debe girar suave y sin juego. Si no, es una falla."}]},{"s":"horquilla_checklist_horq","v":[{"q":"En la revisión ves un eslabón de la cadena del mástil dañado. ¿Qué corresponde?","o":["Detener la grúa e informar: la cadena sostiene la carga","Seguir operando solo con cargas livianas","Echarle aceite a la cadena y seguir","Seguir hasta la próxima mantención"],"w":"Si la cadena se corta, la carga cae. Se detiene la grúa y se informa."},{"q":"Ves una trizadura en una horquilla. ¿Qué haces?","o":["Detengo la grúa e informo","La uso solo con cargas livianas","La uso con la carga pegada al respaldo","Espero la mantención y sigo"],"w":"Una horquilla trizada se puede quebrar con la carga arriba."},{"q":"¿Qué partes de la grúa sostienen la carga y se revisan con más cuidado?","o":["Horquillas, cadenas, mástil y mangueras","Asiento, cinturón, espejos y techo","Luces, bocina, baliza y alarma","Neumáticos traseros y contrapeso"],"w":"Si falla alguna de estas partes, la carga cae."}]},{"s":"horquilla_checklist_q_glp","v":[{"q":"Al cambiar el cilindro de gas, lo primero es:","o":["Apagar el motor y cerrar la válvula del cilindro","Soltar la conexión con el motor andando","Abrir la válvula para vaciar el gas restante","Sacar el cilindro y después apagar"],"w":"Motor apagado y válvula cerrada antes de desconectar, en lugar ventilado y lejos de fuego."},{"q":"¿Dónde se cambia el cilindro de gas de la grúa?","o":["En un lugar ventilado, lejos de fuego y sin fumar","Dentro de la bodega, junto a los racks","Junto al lugar de carga de combustible","En cualquier lugar, si es rápido"],"w":"La ventilación y la ausencia de fuego evitan que un escape se encienda."},{"q":"¿Qué protección usas al cambiar el cilindro de gas?","o":["Guantes y lentes","Solo casco","Ninguna, si la válvula está cerrada","Solo mascarilla"],"w":"El gas licuado puede quemar la piel por frío y saltar a los ojos."}]},{"s":"horquilla_checklist_q_comb","v":[{"q":"Al cargar combustible, el motor puede quedar encendido si es solo un momento.","vf":false,"w":"Falso. El motor va apagado siempre al cargar combustible, y nadie fuma cerca."},{"q":"Cargas combustible y se derrama un poco. ¿Qué haces?","o":["Limpio el derrame antes de encender","Enciendo y dejo que se evapore","Lo tapo con cartón y sigo","Sigo, si es poca cantidad"],"w":"Los vapores del derrame pueden encenderse con una chispa al arrancar."},{"q":"¿Qué debes tener ubicado al cargar combustible?","o":["El extintor más cercano","La llave de agua más cercana","El botiquín de la sucursal","El teléfono del proveedor"],"w":"Ante un inicio de fuego, el extintor debe estar a mano."}]},{"s":"horquilla_checklist_q_bat","v":[{"q":"¿Dónde se carga la batería de una grúa eléctrica?","o":["En el lugar destinado y ventilado, sin fumar","En cualquier enchufe disponible de la bodega","En una sala cerrada, para que no se moje","Junto a los racks, para no tener que moverla"],"w":"Algunas baterías liberan gases inflamables al cargar: lugar ventilado y nada de fuego."},{"q":"¿Por qué no se fuma ni se hacen chispas al cargar la batería?","o":["Porque algunas liberan gases inflamables","Porque el humo daña las celdas de la batería","Porque la batería carga más lento con calor","Porque la chispa descarga el cargador"],"w":"Los gases de la carga pueden encenderse con una chispa."},{"q":"Antes de conectar el cargador, la grúa debe estar apagada y con el freno puesto.","vf":true,"w":"Verdadero. Así no se mueve y no se generan chispas al conectar."}]},{"s":"horquilla_checklist_auto","v":[{"q":"Hay apuro y la grúa ayer andaba bien. ¿Cuál es la decisión segura?","o":["Hacer el check-list igual: toma unos minutos","Saltarme la revisión solo por hoy","Revisar solo los frenos","Usarla y revisarla al final del turno"],"w":"Saltarse la revisión es la acción insegura típica. Unos minutos evitan un accidente."},{"q":"Un compañero te dice que firmes el check-list, total la grúa anda bien. ¿Qué haces?","o":["Reviso antes de firmar y marco lo real","Firmo, si él ya la usó hoy","Firmo y la reviso después","Firmo y anoto aparte lo que vea"],"w":"El check-list es un registro: nunca se firma sin revisar."},{"q":"Un ítem del check-list está malo. ¿Qué haces con el registro?","o":["Lo anoto como malo para que la reparen","Lo marco bien si la falla es menor","Lo dejo en blanco","Lo marco bien y aviso de palabra"],"w":"Marcar con la verdad permite que la reparen y protege al próximo operador."}]}]},{"id":"racks","sec":"bodega","title":"Almacenamiento en racks y caída de materiales","thumb":"racks_pesado","learn":[{"s":"racks_pesado","t":"Lo pesado abajo, lo liviano arriba","x":"En el rack, los <b>sacos de cemento, cerámicas, tarros de pintura y todo lo pesado</b> van en los niveles bajos. Arriba, solo lo liviano. ¿Por qué?<ul><li>El rack queda más estable.</li><li>Lo pesado no cae desde la altura, tampoco en un <b>sismo</b>.</li><li>No tienes que bajarlo a pulso desde arriba.</li></ul>Si ves un rack con lo pesado arriba, avisa para reordenarlo con la grúa y su operador autorizado."},{"s":"racks_sobrecarga","t":"No sobrecargues el rack","x":"Que algo quepa no significa que el rack lo aguante.<ul><li>Si el rack tiene letrero de <b>capacidad</b>, respétalo; si no sabes cuánto aguanta, pregunta antes de cargar.</li><li>Reparte el peso parejo en cada nivel.</li><li>Las vigas deben tener puestos sus <b>pasadores de seguridad</b>: sin ellos, un golpe las puede soltar.</li><li>Una viga <b>curvada</b> por el peso es aviso de falla: no le pongas más carga y avisa de inmediato.</li></ul>"},{"s":"racks_pallet","t":"Pallets en buen estado","x":"Un pallet con <b>tablas quebradas, clavos salidos o tacos sueltos</b> puede ceder en altura y botar toda la carga. Revísalo antes de subirlo al rack. Si está malo, <b>no lo uses</b>: sepáralo y avisa. La carga va <b>centrada y bien apoyada</b>, sin pasarse del borde del pallet. Los pallets vacíos se apilan en el lugar destinado y a baja altura, no en pasillos."},{"s":"racks_sobresale","t":"Nada sobresaliendo ni mal apoyado","x":"<ul><li>Cajas, tubos o planchas que <b>sobresalen</b> hacia el pasillo se enganchan y caen, o golpean a quien pasa.</li><li>Todo bien apoyado sobre las vigas, nunca al aire.</li><li>Paquetes amarrados o con film si se pueden desarmar.</li></ul>Si ves algo a punto de caer, <b>no pases por debajo</b> ni intentes sujetarlo solo: avisa para que lo bajen con el equipo adecuado."},{"s":"racks_planchas","t":"Planchas y fierro: apilado estable","x":"<ul><li>OSB, terciado y yeso-cartón: <b>planos, sobre tacos parejos</b>, nunca directo en el piso, y con planchas del mismo tamaño en cada pila.</li><li>Si se guardan de canto, en un <b>soporte</b> que impida que se vuelquen.</li><li>Fierro y tubos en su rack o sobre tacos, en paquetes amarrados.</li><li>No apiles otros materiales encima de las planchas.</li><li>Pilas a una altura que se pueda manejar con seguridad.</li></ul>"},{"s":"racks_largos","t":"Materiales largos","x":"Fierro, tubos de PVC, perfiles y madera dimensionada son largos, y <b>sus extremos barren todo</b> al girar.<ul><li>Si es largo o pesado, llévalo entre dos y del mismo lado.</li><li><b>Mira los extremos</b> antes de girar, en pasillos y en puertas.</li><li>No lo arrastres por el piso.</li><li>No lo dejes atravesado en pasillos ni sobresaliendo del rack.</li></ul>"},{"s":"racks_trepar","t":"Nunca trepes un rack","x":"El rack <b>no es una escalera</b>. Si trepas por las vigas puedes caer, botar mercadería sobre ti o desestabilizar el rack. Para sacar algo alto, usa una <b>escalera adecuada</b> o pide que lo baje la grúa con su operador autorizado. Con escalera: en buen estado, bien abierta, <b>3 puntos de apoyo</b>, sin pararte en el último peldaño ni estirarte hacia el lado. Nunca te subas a las horquillas.","k":"El rack no es escalera: usa el equipo correcto."},{"s":"racks_golpe","t":"Rack golpeado: informa de inmediato","x":"Un golpe de la grúa horquilla puede <b>doblar un pilar o una viga</b> y debilitar todo el rack, aunque se vea casi bien.<ul><li>No cargues ni descargues ese tramo.</li><li>Señalízalo y aleja a las personas.</li><li><b>Informa de inmediato</b> a tu jefatura, aunque el golpe lo haya dado otro.</li><li>No lo enderezes: lo evalúa personal competente.</li></ul>Revisa también los anclajes al piso. Ocultar un golpe pone en riesgo a tus compañeros.","k":"Pilar golpeado: no se usa, se señaliza y se informa."},{"s":"racks_gondola","t":"Góndolas en la sala de ventas","x":"En la sala, los clientes caminan junto a las góndolas.<ul><li>Lo pesado (pinturas, sacos, cerámicas) en las <b>bandejas bajas</b>.</li><li>Nada apilado sobre la góndola ni al borde de la bandeja.</li><li>Para reponer en altura: escalera, zona delimitada y <b>nadie debajo</b>; si un cliente se acerca, detente.</li><li>Góndola inclinada, suelta o bandeja doblada: avisa de inmediato y aleja a los clientes.</li></ul>"},{"s":"racks_auto","t":"Autocuidado en bodega","x":"La mayoría de los accidentes se relacionan con una acción insegura. En bodega, la típica es dejar la carga <b>así nomás</b>: mal apoyada, sobresaliendo o arriba porque abajo no cabía. La decisión segura: tomarte el minuto para dejarla estable, como si fueras a pasar debajo. Y <b>avisar</b> un rack golpeado, un pallet dañado o una carga inestable también es autocuidado."}],"quiz":[{"s":"racks_pesado","v":[{"q":"¿Dónde van los sacos de cemento de 25 kg en el rack?","o":["En los niveles bajos","En el nivel más alto, para ahorrar espacio","En el nivel medio, a la altura de los ojos","Donde quede espacio libre"],"w":"Lo pesado abajo: el rack queda más estable y nada pesado cae desde la altura."},{"q":"Llegan tarros de pintura de 18 litros y cajas de brochas. ¿Cómo los ubicas en el rack?","o":["Tarros abajo y brochas arriba","Brochas abajo y tarros arriba","Todo junto en el nivel medio","Tarros arriba, donde se ven mejor"],"w":"Lo pesado va en los niveles bajos y lo liviano arriba."},{"q":"¿Por qué lo pesado va en los niveles bajos del rack?","o":["El rack es más estable y nada pesado cae de altura","Para que los clientes lo alcancen mejor","Porque así lo pide el proveedor","Solo para que el rack se vea ordenado"],"w":"Abajo, lo pesado da estabilidad y no cae desde la altura, ni siquiera en un sismo."}]},{"s":"racks_malArriba","v":[{"q":"Ves un rack con sacos de cemento arriba y cajas livianas abajo. ¿Qué haces?","o":["Aviso para reordenarlo con la grúa: pesado abajo","Lo dejo así si las vigas no están curvadas","Bajo los sacos a pulso desde arriba","Pongo más cajas abajo para equilibrar"],"w":"Un rack con lo pesado arriba es inestable. Se reordena con la grúa y su operador."},{"q":"¿Qué riesgo tiene un rack cargado con lo pesado arriba?","o":["Es menos estable y lo pesado puede caer de altura","Ninguno, si el rack es nuevo","Solo hace más lenta la reposición","Solo se aplastan las cajas de abajo"],"w":"Lo pesado arriba sube el centro de gravedad y puede caer desde altura."},{"q":"Si el rack es firme, da lo mismo en qué nivel va lo pesado.","vf":false,"w":"Falso. Lo pesado va siempre abajo: da estabilidad y no cae desde la altura."}]},{"s":"racks_sobrecarga","v":[{"q":"Una viga del rack se ve curvada hacia abajo por el peso. ¿Qué haces?","o":["No le pongo más carga y aviso de inmediato","Reparto la carga hacia los extremos y sigo","Le pongo un taco de madera debajo","La dejo así, si no se ha caído nada"],"w":"Una viga curvada es aviso de falla. Se deja de cargar y se avisa."},{"q":"El material cabe en el nivel, pero no sabes si el rack lo aguanta. ¿Qué haces?","o":["Reviso el letrero de capacidad o pregunto antes","Lo cargo: si cabe, es porque aguanta","Lo cargo y observo si la viga se curva","Lo cargo solo en la mitad del nivel"],"w":"Que quepa no significa que aguante: respeta la capacidad del rack."},{"q":"Una viga sin sus pasadores de seguridad se puede soltar con un golpe.","vf":true,"w":"Verdadero. Los pasadores aseguran la viga al pilar: sin ellos, se avisa."}]},{"s":"racks_pallet","v":[{"q":"Un pallet tiene una tabla quebrada. ¿Qué haces?","o":["No lo uso, lo separo y aviso","Lo subo al nivel más alto, donde no molesta","Lo uso si la carga es liviana","Pongo la carga sobre el lado sano"],"w":"Un pallet dañado puede ceder en altura y botar la carga."},{"q":"Vas a subir un pallet al rack y la carga sobresale del borde. ¿Qué haces?","o":["La reacomodo centrada antes de subirla","La subo con lo que sobresale hacia el pasillo","La subo, si va con film","La subo, pero al nivel más alto"],"w":"La carga va centrada y apoyada, sin pasarse del borde del pallet."},{"q":"¿Qué revisas en un pallet antes de subirlo al rack?","o":["Tablas, clavos y tacos en buen estado","Solo el tamaño del pallet","Solo que no esté mojado","Que tenga el sello del proveedor"],"w":"Tablas quebradas, clavos salidos o tacos sueltos hacen que el pallet ceda."}]},{"s":"racks_golpe","v":[{"q":"La grúa golpeó un pilar del rack y quedó doblado. ¿Qué corresponde?","o":["No usarlo, señalizarlo e informar de inmediato","Seguir usándolo si no se ha caído nada","Enderezarlo y seguir usando ese tramo","Ponerle cinta de peligro y seguir usándolo"],"w":"Un pilar dañado debilita todo el rack. Informar a tiempo protege a todos."},{"q":"Ves un pilar golpeado que nadie ha informado. ¿Qué haces?","o":["Lo informo de inmediato y aviso que no se use","Espero que lo vea la jefatura en su ronda","Lo informo al final de la semana","Lo uso con poca carga mientras tanto"],"w":"Aunque el golpe lo haya dado otro, se informa de inmediato."},{"q":"Golpeaste un pilar con la grúa y se ve casi bien. ¿Qué corresponde?","o":["Informar igual: puede haber debilitado el rack","No decir nada, si no se ve doblado","Enderezarlo con cuidado usando la grúa","Seguir trabajando, si no se cayó carga"],"w":"Un golpe puede debilitar el rack aunque no se note. Ocultarlo pone en riesgo a otros."}]},{"s":"racks_trepar","v":[{"q":"Para sacar una caja liviana del nivel alto, puedo subir por las vigas del rack con cuidado.","vf":false,"w":"Falso. El rack no es escalera: usa una escalera adecuada o la grúa con su operador."},{"q":"Necesitas una caja liviana del tercer nivel. ¿Cómo la sacas?","o":["Con una escalera adecuada o con la grúa y su operador","Subiendo por las vigas, con cuidado","Parándome sobre un pallet vacío","Subiéndome a las horquillas de la grúa"],"w":"Trepar el rack o subirse a las horquillas puede terminar en una caída."},{"q":"Usas una escalera para reponer en altura. ¿Qué es lo correcto?","o":["Escalera en buen estado y 3 puntos de apoyo","Pararme en el último peldaño para alcanzar","Apoyar un pie en la viga del rack","Estirarme hacia el lado sin mover la escalera"],"w":"Con escalera: buen estado, bien abierta, 3 puntos de apoyo y sin estirarse."}]},{"s":"racks_sobresale","v":[{"q":"Ves una caja que sobresale de la viga, a punto de caer sobre el pasillo. ¿Qué haces?","o":["No paso debajo y aviso para que la bajen bien","Paso rápido por debajo antes de que caiga","La empujo hacia adentro con un palo","La sujeto con la mano y la bajo yo solo"],"w":"Nunca te pongas bajo una carga inestable."},{"q":"¿Qué riesgo tiene una plancha que sobresale del rack hacia el pasillo?","o":["Se engancha o golpea a quien pasa","Ninguno, si está bien amarrada","Solo dificulta la vista del pasillo","Solo que se raye la plancha"],"w":"Lo que sobresale se engancha, cae o golpea a quien pasa."},{"q":"Un paquete de cajas se puede desarmar en el rack. ¿Qué haces?","o":["Lo amarro o le pongo film","Lo dejo en el borde para sacarlo fácil","Lo pongo en el nivel más alto","Le apilo más cajas para que se apriete"],"w":"Los paquetes que se pueden desarmar van amarrados o con film."}]},{"s":"racks_planchas","v":[{"q":"¿Cómo se guardan las planchas de OSB o yeso-cartón?","o":["Planas, sobre tacos parejos y en pilas estables","De canto contra la pared, sin soporte","Con fierro apilado encima","Planas, directo sobre el piso"],"w":"Una pila pareja sobre tacos no se desarma ni se vuelca."},{"q":"Tienes planchas de distintos tamaños. ¿Cómo las apilas?","o":["En pilas separadas por tamaño, sobre tacos","Las grandes arriba y las chicas abajo","Todas juntas, con las chicas al medio","De canto, apoyadas en el rack sin soporte"],"w":"Cada pila con planchas del mismo tamaño queda pareja y estable."},{"q":"Las planchas guardadas de canto necesitan un soporte que impida que se vuelquen.","vf":true,"w":"Verdadero. De canto y sin soporte, una plancha se puede volcar sobre alguien."}]},{"s":"racks_largos","v":[{"q":"Trasladas una barra de fierro larga por la bodega. ¿Qué es lo más importante?","o":["Mirar los extremos al girar y llevarla entre dos","Girar rápido para no estorbar a los demás","Arrastrarla por el piso para no cargar peso","Llevarla al hombro mirando solo al frente"],"w":"El extremo de lo largo barre y golpea a quien está cerca."},{"q":"Vas a girar en un pasillo con un tubo largo al hombro. ¿Qué haces?","o":["Miro los extremos antes de girar","Giro rápido para no estorbar","Giro sin mirar, porque ya avisé","Giro con el tubo en alto"],"w":"Al girar, el extremo de lo largo golpea. Mira antes."},{"q":"¿Dónde no se deja un material largo?","o":["Atravesado en el pasillo o sobresaliendo","En su rack de fierro, bien apoyado","Sobre tacos, en un paquete amarrado","En el lugar que indica la jefatura"],"w":"Atravesado o sobresaliendo, alguien tropieza o se golpea."}]},{"s":"racks_gondola","v":[{"q":"Repones pinturas en la parte alta de una góndola y se acerca un cliente. ¿Qué haces?","o":["Detengo la tarea hasta que nadie quede debajo","Sigo, el cliente ya se dará cuenta","Le paso los tarros por encima","Le pido que se apure y sigo reponiendo"],"w":"Al reponer en altura, nadie debe quedar bajo la carga."},{"q":"¿En qué bandejas de la góndola van las pinturas y los sacos?","o":["En las bandejas bajas","En las bandejas altas, para que se vean","Sobre la parte superior de la góndola","Al borde de la bandeja, para tomarlos fácil"],"w":"Lo pesado va abajo: si cae, no golpea desde la altura."},{"q":"Ves una góndola inclinada en la sala. ¿Qué haces?","o":["Aviso de inmediato y alejo a los clientes","La enderezo empujándola yo solo","La dejo, si no se ha caído nada","Le pongo más carga abajo para equilibrar"],"w":"Una góndola inclinada puede caer sobre un cliente. Se avisa de inmediato."}]}]},{"id":"altura","sec":"bodega","title":"Trabajo en altura y uso de escaleras","thumb":"altura_cc_tijera","learn":[{"s":"altura_cc_intro","t":"La altura en la ferretería","x":"Se considera <b>trabajo en altura desde 1,8 m</b>. En {EMP} hay riesgo de caída en la escalera de la sala, en los niveles altos del rack, en la <b>plataforma del camión</b> y en techumbres. Pero también caemos desde menos: una caída de 1 metro puede fracturar una muñeca o golpear la cabeza. Una caída de <b>más de 1,8 m es accidente grave</b>: se paraliza la tarea, se delimita el lugar y se avisa de inmediato a la jefatura."},{"s":"altura_cc_improv","t":"Nada de improvisar para subir","x":"Está prohibido subirse a <b>tarros de pintura, cajas, sacos, pallets, sillas, la góndola o las horquillas</b> de la grúa para alcanzar algo. Se mueven, se hunden o se ladean, y no tienen dónde afirmarse. Las horquillas son para cargas, <b>nunca para personas</b>. Si te falta poco para alcanzar un producto, igual corresponde ir a buscar una escalera adecuada o pedir ayuda.","k":"Nunca te subas a algo que no sea una escalera."},{"s":"altura_inspect","t":"Revisa la escalera antes de usarla","x":"Antes de subir, revisa:<ul><li>Peldaños completos, firmes y sin juego.</li><li>Largueros sin grietas, golpes ni dobleces.</li><li><b>Zapatas antideslizantes</b> completas.</li><li>Tensores y bisagras que traben bien.</li><li>Sin aceite, barro ni pintura en los peldaños.</li></ul>Si está dañada, <b>no la uses</b>: márcala, sácala de circulación y avisa a tu jefatura. Nunca la arregles con alambre, clavos o cinta."},{"s":"altura_cc_tijera","t":"Escalera de tijera en sala y bodega","x":"<ul><li><b>Totalmente abierta</b> y con los tensores trabados.</li><li>Sobre piso firme y parejo, nunca sobre pallets, cajas ni carros.</li><li>No te pares en la <b>tapa superior</b> ni en el último peldaño.</li><li>Nunca la uses cerrada y apoyada en la pared o en la góndola, como si fuera escalera de mano.</li><li>En pasillos con clientes, <b>delimita la zona</b> con conos.</li></ul>"},{"s":"altura_ladder_ok","t":"Escalera de mano o de apoyo","x":"<ul><li>Regla <b>4 a 1</b>: por cada 4 metros de altura, la base se separa 1 metro del muro.</li><li>Debe <b>sobresalir cerca de 1 metro</b> sobre el punto al que llegas, para tener de dónde afirmarte.</li><li>Base en piso firme y parte superior bien apoyada; <b>amarrada</b> arriba o sujeta abajo por un compañero.</li><li>Nunca frente a una puerta sin trabar ni en una zona de paso de la grúa.</li></ul>"},{"s":"altura_3p","t":"Sube y baja con 3 puntos de apoyo","x":"<ul><li>Siempre <b>3 puntos de apoyo</b>: dos manos y un pie, o dos pies y una mano.</li><li>De frente a la escalera, peldaño por peldaño.</li><li><b>Manos libres</b>: no subas con galones, cajas ni herramientas en las manos; que un compañero te los pase o usa un bolso porta herramientas.</li><li>No te estires hacia los lados: tu cuerpo entre los largueros. Si no alcanzas, baja y mueve la escalera.</li><li>Una persona a la vez.</li></ul>"},{"s":"altura_cc_rack","t":"Sacar productos de racks altos","x":"<ul><li>Lo liviano: con escalera adecuada y un compañero que <b>reciba desde abajo</b>.</li><li>Lo pesado o en pallet, como sacos de cemento o cerámicas: lo baja la <b>grúa horquilla</b> con su operador autorizado.</li><li>Nunca tires ni empujes una caja para que caiga sola.</li><li>No trepes por las vigas del rack.</li><li><b>Nadie bajo la zona</b> mientras se baja material.</li></ul>"},{"s":"altura_camion_mal","t":"La plataforma del camión","x":"Al cargar, amarrar o carpar, la plataforma del camión es un <b>borde sin protección</b> a más de un metro del suelo. Caídas típicas: <b>retroceder sin mirar</b> mientras acomodas carga, pisar la orilla o <b>saltar al bajar</b>. Trabaja de frente al borde y lejos de él, mira dónde pisas y baja <b>de frente al camión, por los peldaños, con 3 puntos de apoyo</b> y sin material en las manos."},{"s":"altura_cc_techo","t":"Techumbres: no subir sin autorización","x":"¿Gotera, canaleta tapada o un letrero suelto? <b>No subas al techo</b> por tu cuenta ni trepando por el rack. Las <b>planchas traslúcidas</b> y las planchas viejas <b>no resisten tu peso</b>: se rompen y la caída es directa al piso. Subir a una techumbre es una tarea planificada y autorizada por la jefatura, con personal capacitado y <b>arnés conectado a un punto de anclaje</b> adecuado. Casco y zapatos de seguridad no bastan.","k":"Nunca subas al techo sin autorización, arnés y anclaje."},{"s":"altura_herram","t":"Lo que cae desde arriba","x":"Un tarro de pintura o una herramienta que cae desde la escalera o el rack puede herir gravemente a quien está abajo.<ul><li>No dejes herramientas ni productos sueltos en los peldaños, en la tapa de la tijera o al borde del rack.</li><li><b>Delimita</b> la zona de abajo con conos, también en la sala de ventas.</li><li>No pases bajo personas trabajando en altura.</li><li>Nunca pidas a un cliente que sujete la escalera.</li></ul>"}],"quiz":[{"s":"altura_cc_intro","v":[{"q":"¿Desde qué altura se considera trabajo en altura?","o":["Desde 1,8 m","Desde 2,5 m","Desde 3 m","Desde 1,2 m"],"w":"Desde 1,8 m, aunque caer desde menos altura también puede causar lesiones graves."},{"q":"Un compañero debe trabajar sobre una plataforma a 2 m del suelo. ¿Es trabajo en altura?","o":["Sí, porque supera 1,8 m","No, recién desde 3 m","Solo si es sobre un techo","Solo si usa arnés"],"w":"Todo trabajo sobre 1,8 m es trabajo en altura y requiere sus medidas de control."},{"q":"Una caída desde 1,5 m no puede causar lesiones graves, porque está bajo el límite de 1,8 m.","vf":false,"w":"Falso. Caer desde poca altura puede fracturar o causar un golpe grave en la cabeza."}]},{"s":"altura_cc_improv","v":[{"q":"Para alcanzar un producto alto, ¿qué es lo correcto?","o":["Ir a buscar una escalera adecuada","Pararse en un tarro de pintura lleno y cerrado","Subirse a un pallet bien apilado","Apoyar un pie en la repisa baja de la góndola"],"w":"Tarros, pallets y repisas se mueven, se hunden o se ladean. Para subir se usa una escalera."},{"q":"Te faltan 30 cm para alcanzar una caja en la góndola y la escalera está en bodega. ¿Qué haces?","o":["Voy a buscar la escalera o pido ayuda","Me paro en una caja de cerámica cerrada","Me paro en un saco de cemento","Me estiro apoyado en la repisa"],"w":"Aunque falte poco, improvisar es la causa típica de caídas. La escalera se va a buscar."},{"q":"Pararse en un tarro de pintura de 20 litros está permitido si el tarro está lleno y bien cerrado.","vf":false,"w":"Falso. Un tarro se ladea y no tiene de dónde afirmarse. Solo se sube con escalera."}]},{"s":"altura_cc_tijeraMal","v":[{"q":"Una escalera de tijera debe usarse:","o":["Totalmente abierta y con los tensores trabados","Cerrada y apoyada en la pared si el pasillo es angosto","Abierta a medias si el piso es parejo","Abierta, pudiendo pisar la tapa superior"],"w":"Cerrada o a medio abrir se desliza o se cierra. Va abierta, trabada y sin pararse arriba."},{"q":"El pasillo es angosto y un compañero usa la tijera cerrada, apoyada en la góndola. ¿Qué le dices?","o":["Que la abra completa y la trabe, o use otra escalera","Que está bien si alguien la sujeta abajo","Que está bien si no sube más de tres peldaños","Que está bien si la góndola está firme"],"w":"La tijera cerrada se desliza por la base. Si no hay espacio para abrirla, se usa otra escalera."},{"q":"Usar la escalera de tijera cerrada y apoyada en la pared es seguro si un compañero la sujeta abajo.","vf":false,"w":"Falso. La escalera de tijera se usa siempre totalmente abierta y con los tensores trabados."}]},{"s":"altura_3p","v":[{"q":"Subir con 3 puntos de apoyo significa:","o":["Dos manos y un pie, o dos pies y una mano","Dos pies y la cadera apoyada en la escalera","Una mano, un pie y la carga en la otra mano","Tres peldaños de distancia entre personas"],"w":"Tres puntos de contacto con la escalera en todo momento, de frente y con las manos libres."},{"q":"Debes subir 3 galones de pintura a un nivel alto usando la escalera. ¿Cómo lo haces?","o":["Subo con las manos libres y un compañero me los pasa","Subo con un galón en cada mano, despacio","Subo con los galones en una mano y me afirmo con la otra","Subo de espaldas para ver dónde dejarlos"],"w":"Con material en las manos pierdes los 3 puntos de apoyo. La carga se pasa o se sube aparte."},{"q":"Para subir material por una escalera, lo correcto es subir con las manos libres y que un compañero te lo pase.","vf":true,"w":"Verdadero. Así mantienes los 3 puntos de apoyo al subir y al bajar."}]},{"s":"altura_inspect","v":[{"q":"Encuentras una escalera con un peldaño suelto. ¿Qué haces?","o":["No la uso, la marco, la retiro y aviso","La uso con cuidado, saltándome ese peldaño","La amarro con alambre y la uso","La dejo donde estaba y busco otra"],"w":"Dañada no se usa ni se repara improvisando. Si no se retira y avisa, el próximo la usará."},{"q":"Antes de subir, ¿qué revisas en una escalera?","o":["Peldaños, largueros, zapatas, tensores y que esté limpia","Solo que tenga la altura que necesitas","Solo que los peldaños estén limpios","Solo que tenga la etiqueta del fabricante"],"w":"Cualquier falla en peldaños, largueros, zapatas o tensores puede provocar la caída."},{"q":"La escalera tiene una zapata antideslizante rota y otra sana. ¿Qué corresponde?","o":["No usarla y avisar para que la reparen o cambien","Usarla sobre piso seco","Usarla con un compañero sujetándola","Reemplazar la zapata con cinta adhesiva"],"w":"Sin sus zapatas la escalera puede resbalar. Se retira y se avisa a la jefatura."}]},{"s":"altura_camion_ok","v":[{"q":"¿Cómo se baja correctamente de la plataforma del camión?","o":["De frente al camión, por los peldaños, con 3 puntos de apoyo","Saltando con las rodillas flexionadas","De espaldas al camión, mirando el piso","Por los peldaños, con la carga en una mano"],"w":"Saltar o bajar de espaldas causa torceduras y caídas. Se baja de frente y con las manos libres."},{"q":"Terminaste de amarrar la carga arriba del camión. ¿Cómo bajas?","o":["De frente al camión por los peldaños, con las manos libres","Salto desde la orilla, es poca altura","Me deslizo sentado por la orilla","Por los peldaños, con las eslingas en la mano"],"w":"Bajar de frente con 3 puntos de apoyo evita la caída desde la plataforma."},{"q":"Mientras acomodas carga sobre la plataforma, ¿qué error causa más caídas?","o":["Retroceder sin mirar hacia el borde","Trabajar de frente al borde","Revisar dónde pisas","Mantenerte al centro de la plataforma"],"w":"El borde de la plataforma no tiene protección: retroceder sin mirar es la caída típica."}]},{"s":"altura_cc_rack","v":[{"q":"Hay que bajar un pallet con sacos de cemento desde el nivel alto del rack. ¿Cómo se hace?","o":["Con la grúa horquilla y su operador autorizado","Bajando saco por saco por la escalera","Entre dos personas, pasándose los sacos","Empujando los sacos sobre cartones"],"w":"Lo pesado en altura se baja con equipo, no a pulso por la escalera."},{"q":"Una caja liviana está en el segundo nivel del rack. ¿Cómo la bajas?","o":["Con escalera y un compañero que la reciba abajo","La empujo para que caiga sobre un cartón","Trepo por las vigas del rack","La bajo con la escalera, con la caja en una mano"],"w":"Con escalera y alguien que reciba: manos libres y nada cae."},{"q":"Mientras se baja material desde un nivel alto del rack, nadie debe estar debajo de esa zona.","vf":true,"w":"Verdadero. Si algo cae, no debe haber nadie debajo."}]},{"s":"altura_cc_techo","v":[{"q":"Hay una gotera y quieres revisar el techo de la bodega. ¿Qué haces?","o":["Aviso a mi jefatura: subir requiere autorización y equipo","Subo con casco y zapatos de seguridad","Subo pisando solo las planchas traslúcidas","Subo trepando por el rack con cuidado"],"w":"Al techo solo sube personal autorizado, con arnés conectado a un anclaje adecuado."},{"q":"¿Por qué no se pisa una plancha traslúcida del techo?","o":["Porque no resiste el peso de una persona","Porque se raya y pierde luz","Porque es resbalosa solo cuando llueve","Porque se ensucia con el calzado"],"w":"La plancha traslúcida se rompe y la caída es directa al piso."},{"q":"Para subir a una techumbre, ¿qué se necesita además de autorización?","o":["Personal capacitado con arnés conectado a un anclaje","Solo casco y zapatos de seguridad","Solo un compañero mirando desde abajo","Solo una escalera más larga"],"w":"El arnés anclado detiene la caída; el casco y los zapatos no la evitan."}]},{"s":"altura_ladder_ok","v":[{"q":"Una escalera de mano se apoya en un muro para llegar a 4 m de altura. ¿A qué distancia va su base?","o":["A 1 m del muro","A 2 m del muro","Pegada al muro","A 50 cm del muro"],"w":"Regla 4 a 1: por cada 4 m de altura, la base se separa 1 m."},{"q":"Para subir a un altillo con escalera de mano, ¿cuánto debe sobresalir sobre el borde de llegada?","o":["Cerca de 1 metro","Nada, debe quedar al ras","Unos 10 centímetros","Unos 3 metros"],"w":"Sobresalir cerca de 1 m te da de dónde afirmarte al pasar al altillo."},{"q":"La regla 4 a 1 de la escalera de mano significa:","o":["Por cada 4 m de altura, la base se separa 1 m","Por cada 1 m de altura, la base se separa 4 m","Cuatro peldaños por cada metro","Máximo 4 personas por escalera"],"w":"Con esa inclinación la escalera no resbala ni se va hacia atrás."}]},{"s":"altura_herram","v":[{"q":"Mientras un compañero repone en altura en la sala, la zona de abajo debe:","o":["Estar delimitada, sin clientes ni compañeros debajo","Quedar libre solo para clientes apurados","Usarse para dejar los carros","Quedar abierta si él avisa antes"],"w":"Así nadie queda expuesto a la caída de objetos."},{"q":"Un compañero repone pinturas desde una escalera en un pasillo con clientes. ¿Qué corresponde?","o":["Delimitar con conos y no dejar pasar a nadie debajo","Pedir a los clientes que pasen rápido","Dejar los tarros en la tapa de la tijera","Pedir a un cliente que sujete la escalera"],"w":"La zona se delimita. Un cliente nunca sujeta la escalera ni pasa por debajo."},{"q":"Dejar herramientas sueltas en la escalera es peligroso aunque tú estés arriba: pueden caer sobre quien pase.","vf":true,"w":"Verdadero. Nada suelto en peldaños ni en bordes de rack."}]}]},{"id":"herramientas","sec":"bodega","mins":5,"title":"Herramientas de mano, de corte y eléctricas","thumb":"herr_cc_esmeril","learn":[{"s":"herr_cc_intro","t":"Herramientas en la ferretería","x":"En bodega y patio se corta <b>fierro, tubos, perfiles y madera</b> con esmeril angular y napoleón; en la sala se abren cajas con cartonero y se <b>demuestran herramientas eléctricas</b> a clientes. Los accidentes típicos: cortes en las manos, partículas en los ojos, golpes y descargas eléctricas. Casi siempre vienen de una herramienta <b>dañada, equivocada o sin su protección</b>. Solo usa las herramientas para las que estás capacitado."},{"s":"herr_revisar","t":"Revísala antes de usarla","x":"Antes de cada uso, mira el <b>cable, el enchufe, la carcasa y el interruptor</b>. Cable pelado o parchado con cinta, enchufe quebrado, carcasa rota o interruptor que no corta: <b>no se usa</b>. En las herramientas de mano, revisa mangos, cabezas y filos. Si está dañada, <b>sepárala, márcala</b> para que nadie la use y avisa a tu jefatura. No la repares tú."},{"s":"herr_cc_esmeril","t":"Cortar fierro con esmeril angular","x":"<ul><li>Siempre con su <b>protección del disco</b> y el mango lateral, tomado con las dos manos.</li><li>Fierro sujeto en prensa, nunca con el pie ni con la mano.</li><li>Chispas hacia el piso, lejos de personas, <b>pinturas, solventes y cilindros de gas</b>.</li><li>EPP: <b>lentes y, encima, careta facial</b>; protector auditivo y guantes.</li><li>Espera que el disco se detenga antes de dejar la máquina.</li></ul>","k":"Nunca uses el esmeril sin su protección ni con chispas cerca de lo que arde."},{"s":"herr_disco","t":"El disco correcto","x":"<ul><li>Las <b>RPM del disco</b> deben ser iguales o mayores que las de la máquina: si la máquina gira a 11.000 RPM, sirve un disco de 13.300, no uno de 8.500.</li><li>Diámetro adecuado a la máquina y a su protección: nunca saques la protección para que entre uno más grande.</li><li>Disco de corte para cortar; de desbaste para desbastar.</li><li>Sin trizaduras, golpes ni humedad.</li></ul>Un disco que revienta lanza trozos como proyectiles."},{"s":"herr_cc_cizalla","t":"Napoleón y sierra","x":"<ul><li><b>Napoleón (cizalla):</b> úsalo solo en el fierro que su capacidad permite; si es más grueso, usa otra herramienta. Nunca alargues el mango con un tubo. Dos manos y los dedos fuera de las mandíbulas.</li><li>El <b>trozo cortado puede saltar</b>: lentes puestos y nadie al frente.</li><li><b>Sierra:</b> pieza apoyada y fija, y la mano libre lejos de la línea de corte.</li></ul>"},{"s":"herr_cc_cartBien","t":"Cuchillo cartonero: corta hacia afuera","x":"<ul><li>Corta <b>alejando la hoja de tu cuerpo</b> y de tu otra mano.</li><li>Apoya la caja en el mesón o el piso, nunca en tus piernas.</li><li>Hoja con filo: una gastada obliga a hacer fuerza y se escapa.</li><li>Saca solo la hoja necesaria y <b>retráela</b> al terminar.</li><li>Nunca al bolsillo con la hoja afuera.</li><li>Usa guantes anticorte si tu tarea los indica.</li></ul>"},{"s":"herr_cc_mano","t":"Herramientas de mano","x":"<ul><li>Cada herramienta para lo suyo: un destornillador <b>no es cincel ni palanca</b>; se quiebra o resbala.</li><li>Mangos firmes, sin astillas ni cabezas sueltas.</li><li>Llave del <b>tamaño exacto</b>: una más grande resbala y te golpeas los nudillos.</li><li>Nunca alargues una llave con un tubo.</li><li>Nada de herramientas con filo en los bolsillos ni sueltas en altura.</li></ul>"},{"s":"herr_desenchufar","t":"Herramientas eléctricas portátiles","x":"Taladros, esmeriles y sierras eléctricas:<ul><li><b>Desenchufa</b> o saca la batería para cambiar disco, broca u hoja: con solo rozar el gatillo, la máquina parte.</li><li>Extensiones sin uniones con cinta, desenrolladas y <b>lejos del agua</b>.</li><li>Lleva la herramienta del mango, nunca colgando del cable.</li><li>Desenchufa tomando el enchufe, no tirando del cable.</li><li>Espera que se detenga antes de dejarla.</li></ul>","k":"Desenchufa o saca la batería antes de cambiar disco, broca u hoja."},{"s":"herr_taladro","t":"Taladro: pieza sujeta","x":"<ul><li>La pieza va en <b>prensa o sujeta</b>, nunca en la mano: si la broca se traba, la pieza gira y te golpea o corta.</li><li>Broca adecuada al material y bien apretada; saca la llave del mandril antes de partir.</li><li>Lentes de seguridad.</li><li>Pelo tomado, sin ropa suelta, collares ni pulseras cerca de la broca: se enredan.</li><li>Si la broca se traba, suelta el gatillo; no la fuerces.</li></ul>"},{"s":"herr_cc_demo","t":"Demostrar herramientas a clientes","x":"<ul><li>Demuestra solo si estás capacitado y en el lugar que defina tu jefatura.</li><li>Cliente a <b>distancia segura</b> y herramienta apuntando lejos de las personas.</li><li>Accesorio bien montado, protección puesta y tus lentes.</li><li>Al terminar, <b>desenchufa o saca la batería</b>; no la dejes enchufada en el mesón.</li><li>El cliente <b>no prueba</b> la herramienta sin supervisión.</li></ul>"}],"quiz":[{"s":"herr_cablePelado","v":[{"q":"El cable de la herramienta está pelado. ¿Qué haces?","o":["No la uso, la separo, la marco y aviso","Le pongo cinta aislante y sigo","La uso con guantes de cuero","La uso solo hasta terminar el corte"],"w":"Herramienta dañada no se usa ni se repara improvisando: se separa y se informa."},{"q":"Al revisar el taladro ves el cable parchado con cinta. ¿Qué corresponde?","o":["Dejarlo fuera de uso, marcarlo y avisar","Usarlo si la cinta está bien firme","Usarlo lejos del agua","Cambiar la cinta por una nueva y usarlo"],"w":"Un cable parchado sigue dañado: puede dar una descarga eléctrica."},{"q":"Un cable parchado con cinta aislante queda seguro si la cinta está bien puesta.","vf":false,"w":"Falso. La herramienta con cable dañado no se usa: se separa, se marca y se avisa."}]},{"s":"herr_esmerilMal","v":[{"q":"Un compañero sacó la protección del esmeril para que entre un disco más grande. ¿Qué corresponde?","o":["No usarlo: se repone la protección y se usa el disco correcto","Usarlo, pero con careta facial","Usarlo solo para cortes cortos","Usarlo tomado con las dos manos"],"w":"Sin protección y con un disco más grande, un trozo del disco puede salir disparado hacia ti."},{"q":"¿Qué debe tener puesto el esmeril angular antes de cortar?","o":["La protección del disco y el mango lateral","Solo el mango lateral","La protección, solo si el disco es nuevo","Nada, si el disco es de buena marca"],"w":"La protección frena los trozos y el mango lateral permite controlar la máquina con dos manos."},{"q":"El esmeril angular puede usarse sin la protección del disco si usas careta facial.","vf":false,"w":"Falso. La careta no reemplaza la protección del disco: nunca se saca."}]},{"s":"herr_cc_chispasMal","v":[{"q":"Vas a cortar fierro con esmeril y al lado hay tarros de diluyente y un cilindro de gas. ¿Qué haces?","o":["Corto en otro lugar o alejo esos productos antes","Corto rápido, son pocas chispas","Tapo los tarros con un cartón y corto","Corto apuntando las chispas a la pared"],"w":"Las chispas pueden encender los vapores inflamables o dañar el cilindro."},{"q":"¿Hacia dónde deben ir las chispas del esmeril?","o":["Hacia el piso, lejos de personas y de lo que arde","Hacia la pared, aunque haya pinturas cerca","Hacia arriba, para que se apaguen en el aire","Hacia el operador, para controlarlas mejor"],"w":"Chispas al piso y lejos de pinturas, solventes, gas y personas."},{"q":"¿Cuál es el peligro de cortar fierro junto a tarros de diluyente?","o":["Las chispas pueden encender los vapores","El polvo de fierro contamina el diluyente","El ruido puede romper los envases","El diluyente oxida el disco"],"w":"Los diluyentes liberan vapores inflamables que una chispa puede encender."}]},{"s":"herr_cc_cartMal","v":[{"q":"¿Cómo se corta con el cuchillo cartonero?","o":["Alejando la hoja del cuerpo y de la otra mano","Hacia el cuerpo, para tener más fuerza","Con toda la hoja afuera, para cortar más hondo","Sujetando la caja con la mano frente a la hoja"],"w":"Si la hoja se escapa, debe ir hacia afuera, no hacia tu cuerpo ni tu mano."},{"q":"Abres una caja apoyada en tus piernas, cortando hacia ti. ¿Qué cambias?","o":["La apoyo en el mesón y corto alejando la hoja","Nada, si corto despacio","Me pongo guantes y sigo igual","Saco más hoja para terminar rápido"],"w":"Apoyo firme y corte hacia afuera: si la hoja resbala, no te alcanza."},{"q":"Una hoja de cartonero gastada es peligrosa porque:","o":["Obliga a hacer más fuerza y se escapa","Corta más profundo que una nueva","Se dobla y deja de cortar sin riesgo","Solo raya el cartón"],"w":"Con más fuerza pierdes control y la hoja se escapa hacia ti."}]},{"s":"herr_q_cambio","v":[{"q":"Puedes cambiar el disco del esmeril con la máquina enchufada si no aprietas el gatillo.","vf":false,"w":"Falso. Siempre se desenchufa o se saca la batería antes de cambiar un accesorio."},{"q":"Vas a cambiar el disco del esmeril. ¿Qué haces primero?","o":["Lo desenchufo","Pongo el seguro del gatillo","Espero que se enfríe el disco","Aviso a mi jefatura"],"w":"Desenchufada, la máquina no puede partir aunque roces el gatillo."},{"q":"¿Por qué se desenchufa la herramienta para cambiar el accesorio?","o":["Porque puede encenderse por accidente y herirte","Para ahorrar energía","Porque lo exige la garantía","Para que el disco se enfríe más rápido"],"w":"Un roce en el gatillo basta para que la máquina parta con tu mano en el disco."}]},{"s":"herr_cc_cizalla","v":[{"q":"Al cortar fierro con el napoleón, ¿qué riesgo debes controlar?","o":["El trozo cortado puede saltar: lentes y nadie al frente","El ruido del motor","La descarga de la batería","Las chispas sobre los solventes"],"w":"Es manual: el riesgo está en el trozo que salta y en los dedos cerca de las mandíbulas."},{"q":"Un fierro es más grueso que la capacidad del napoleón. ¿Qué haces?","o":["Uso otra herramienta adecuada para ese grosor","Le pongo un tubo al mango para hacer más fuerza","Le pido a un compañero que empuje conmigo","Lo corto de a poco, en varias pasadas"],"w":"Sobre su capacidad, el napoleón se daña y las piezas pueden saltar."},{"q":"Al cortar con napoleón, nadie debe estar al frente, porque el trozo cortado puede saltar.","vf":true,"w":"Verdadero. Lentes puestos y nadie en la línea del trozo."}]},{"s":"herr_cc_mano","v":[{"q":"¿Puedes usar un destornillador como cincel o palanca?","o":["No: se quiebra o resbala; uso la herramienta correcta","Sí, si golpeo suave","Sí, si el mango es de goma","Sí, si uso guantes"],"w":"Cada herramienta para lo suyo. Mal usada, se quiebra o resbala y te lesionas."},{"q":"Debes soltar una tuerca de 13 mm y solo tienes a mano una llave de 14 mm. ¿Qué haces?","o":["Busco la llave de 13 mm","Uso la de 14 con un cartón para ajustarla","Uso un alicate","Golpeo la llave con un martillo"],"w":"Una llave grande resbala y te golpeas. Se usa la del tamaño exacto."},{"q":"¿Cuál de estas prácticas con herramientas de mano es correcta?","o":["Usar llaves del tamaño exacto y mangos firmes","Alargar la llave con un tubo para más fuerza","Guardar el formón en el bolsillo","Usar un martillo con la cabeza suelta si se usa poco"],"w":"Herramienta correcta, en buen estado y bien guardada."}]},{"s":"herr_cc_demo","v":[{"q":"Un cliente quiere probar el esmeril que estás demostrando. ¿Qué corresponde?","o":["No lo prueba sin supervisión: la demo la hace personal capacitado","Se lo paso enchufado para que pruebe","Lo dejo probar si firma que es su responsabilidad","Lo dejo probar sin protección, para que vea el disco"],"w":"La demostración es segura solo con personal capacitado, cliente a distancia y protección puesta."},{"q":"Terminaste de demostrar un taladro a un cliente. ¿Qué haces?","o":["Lo desenchufo o le saco la batería","Lo dejo enchufado en el mesón para el próximo","Se lo paso al cliente para que lo pruebe","Le saco la broca y lo dejo enchufado"],"w":"Desenchufado nadie lo puede encender por accidente."},{"q":"En una demostración, el cliente debe estar a distancia segura y la herramienta apuntar lejos de las personas.","vf":true,"w":"Verdadero. Además, accesorio bien montado, protección puesta y tus lentes."}]},{"s":"herr_q_disco","v":[{"q":"¿Qué disco puedes montar en el esmeril?","o":["RPM iguales o mayores que la máquina, diámetro correcto y sin daños","Cualquiera que calce en el eje","Uno más grande, sacando la protección","Uno de RPM menores, si cortas despacio"],"w":"Un disco con menos RPM, más grande o trizado puede reventar."},{"q":"La máquina dice 11.000 RPM. ¿Qué disco sirve?","o":["Uno de 13.300 RPM","Uno de 8.500 RPM","Uno de 10.000 RPM","Cualquiera, si es de buena marca"],"w":"El disco debe resistir igual o más RPM que las de la máquina."},{"q":"¿Qué puede pasar si montas un disco con menos RPM que la máquina?","o":["Puede reventar y lanzar trozos","Corta más lento, sin otro riesgo","Solo se gasta más rápido","Solo se calienta más"],"w":"El disco gira más rápido de lo que resiste y revienta."}]},{"s":"herr_cc_esmeril","v":[{"q":"¿Qué protección ocular corresponde al cortar fierro con esmeril angular?","o":["Lentes de seguridad y, encima, careta facial","Solo careta facial, sin lentes","Solo lentes, si el corte es rápido","Lentes de sol oscuros"],"w":"La careta complementa a los lentes, no los reemplaza."},{"q":"¿Qué EPP completo usas al cortar fierro con esmeril?","o":["Lentes, careta facial, protector auditivo y guantes","Lentes y guantes","Careta facial y guantes","Protector auditivo y lentes"],"w":"El esmeril lanza partículas, hace ruido y el fierro corta: protección para ojos, cara, oídos y manos."},{"q":"Al cortar con esmeril, la careta facial se usa encima de los lentes de seguridad, no en su reemplazo.","vf":true,"w":"Verdadero. Si la careta se levanta, los lentes siguen protegiendo tus ojos."}]}]},{"id":"quimicos","sec":"bodega","mins":5,"title":"Pinturas, solventes, cemento, gas y otros químicos","thumb":"quim_cc_intro","learn":[{"s":"quim_cc_intro","t":"Químicos en la ferretería","x":"En sala y bodega de {EMP} manejamos <b>pinturas, diluyentes, solventes, adhesivos de contacto, cemento y cilindros de gas</b>. Te pueden dañar por:<ul><li><b>Respiración:</b> vapores y polvo.</li><li><b>Piel y ojos:</b> quemaduras y alergias.</li><li><b>Boca:</b> manos sucias; lávate antes de comer y no comas en la bodega.</li><li><b>Fuego:</b> muchos son inflamables.</li></ul>"},{"s":"quimicos_hds","t":"La Hoja de Datos de Seguridad (HDS)","x":"Cada producto químico tiene su <b>HDS</b> (NCh 2245), que entrega el proveedor. Ahí están sus peligros, el <b>EPP</b> que corresponde, los <b>primeros auxilios</b>, qué hacer ante un derrame o incendio y cómo almacenarlo. Antes de manipular un producto que no conoces, lee su HDS y su etiqueta; nunca lo huelas para saber qué es. Pregunta a tu jefatura <b>dónde están las HDS</b> de tu sucursal."},{"s":"quimicos_pictos","t":"Etiqueta y pictogramas","x":"Según el <b>DS 57</b>, la etiqueta trae <b>pictogramas</b>: rombos de borde rojo y símbolo negro.<ul><li><b>Llama:</b> inflamable (diluyentes, muchos adhesivos de contacto).</li><li><b>Corrosión:</b> daña piel y ojos.</li><li><b>Exclamación:</b> irritante o nocivo.</li><li><b>Silueta con estrella:</b> daño grave a la salud.</li></ul>Y una palabra de advertencia: <b>Peligro</b> (lo más grave) o <b>Atención</b>."},{"s":"quimicos_bottles","t":"Nunca en botellas de bebida","x":"Un químico va siempre en su <b>envase original</b> o en uno <b>rotulado</b> con su nombre y peligros. Nunca lo trasvasijes a botellas de bebida, tazas o envases de comida, aunque los marques con plumón: alguien puede beberlo por error, y ya ha pasado. Tampoco uses envases sin etiqueta. Si encuentras un envase sin rotular, <b>no lo uses</b> y avisa a tu jefatura."},{"s":"quim_cc_solvente","t":"Pinturas, diluyentes y adhesivos de contacto","x":"Muchos liberan <b>vapores inflamables</b> que irritan, marean y viajan por el aire aunque no los veas.<ul><li>Envases siempre <b>tapados</b>: tápalos apenas termines.</li><li>Buena ventilación.</li><li><b>No fumes</b> ni hagas chispas cerca: un esmeril, una estufa o una llama pueden encender los vapores.</li><li>Guantes y lentes según la HDS; respirador solo si la HDS lo indica.</li></ul>","k":"Mantén los envases tapados y nada de fuego cerca."},{"s":"quim_cc_cemento","t":"Cemento: quema la piel","x":"El cemento es <b>alcalino</b>: húmedo, o mezclado con sudor, puede causar <b>quemaduras en la piel</b>, dermatitis y daño grave en los ojos.<ul><li><b>Guantes, lentes y manga larga</b>, sobre todo al recoger sacos rotos.</li><li>Si te cae en la piel, lava con abundante agua; no uses diluyente.</li><li>En los ojos: agua al menos 15 minutos, y avisa.</li><li>No dejes ropa empapada en cemento sobre la piel.</li></ul>"},{"s":"quim_cc_gas","t":"Cilindros de gas","x":"<ul><li>Siempre <b>de pie</b> y <b>encadenados</b> o sujetos, para que no caigan ni se dañe la válvula.</li><li>Lejos del calor, del sol directo y de chispas.</li><li>Con la válvula protegida; no se golpean, ruedan ni arrastran: se mueven en <b>carro</b>.</li><li>¿Olor a gas? <b>No enciendas ni apagues</b> luces ni equipos, ventila, aleja a las personas y avisa de inmediato.</li></ul>"},{"s":"quim_cc_alm","t":"Almacenamiento seguro (DS 43)","x":"El <b>DS 43</b> regula el almacenamiento de sustancias peligrosas. En tu sucursal:<ul><li>Inflamables en el lugar destinado, lejos de calor y chispas.</li><li>Envases <b>cerrados y etiquetados</b>.</li><li>Separados de productos incompatibles, según la HDS.</li><li>Nunca en pasillos ni salidas.</li><li>Líquidos y envases pesados, como galones, en <b>niveles bajos</b>.</li></ul>"},{"s":"quim_cc_derrame","t":"Derrame o envase roto","x":"<ul><li><b>Aleja a las personas</b>, también a los clientes.</li><li>Si es inflamable, nada de fuego ni chispas.</li><li>Ponte guantes y lentes.</li><li>Contén el derrame con material absorbente; si tu sucursal tiene kit antiderrame, úsalo.</li><li><b>Avisa</b> a tu jefatura.</li><li>El residuo no va al basurero común ni al desagüe: se elimina como indiquen la jefatura y la HDS.</li></ul>"},{"s":"quimicos_eyes","t":"Si hay contacto","x":"<ul><li><b>Ojos:</b> lava con abundante agua limpia <b>al menos 15 minutos</b>, con los párpados abiertos. No te frotes.</li><li><b>Piel:</b> retira la ropa contaminada y lava con agua y jabón.</li><li><b>Vapores:</b> sal al aire fresco.</li></ul>Avisa siempre a tu jefatura y acude a la <b>Mutual de Seguridad CChC</b> (fono 1407), llevando la <b>HDS o la etiqueta</b> del producto.","k":"Si te salpica en los ojos, lava 15 minutos con agua y avisa."}],"quiz":[{"s":"quimicos_hds","v":[{"q":"¿Dónde encuentras los peligros, el EPP y los primeros auxilios de un diluyente?","o":["En la Hoja de Datos de Seguridad (HDS)","En la boleta o factura de compra","En el catálogo de ventas","En el código de barras del envase"],"w":"La HDS (NCh 2245) es la fuente oficial de información del producto."},{"q":"Llegó un adhesivo nuevo que no conoces. ¿Qué haces antes de manipularlo?","o":["Reviso su HDS y su etiqueta","Lo huelo para saber si es fuerte","Le pregunto a un cliente que lo usa","Lo manipulo igual que el anterior"],"w":"La HDS y la etiqueta dicen sus peligros y el EPP. Nunca se huele un químico."},{"q":"La HDS indica qué EPP usar, los primeros auxilios y qué hacer ante un derrame.","vf":true,"w":"Verdadero. También indica peligros, cómo almacenarlo y qué hacer en un incendio."}]},{"s":"quimicos_bottles","v":[{"q":"Un compañero trasvasija diluyente a una botella de bebida para llevarlo al patio. ¿Qué le dices?","o":["Que no: va en su envase original o en uno rotulado","Que está bien si la cierra bien","Que está bien si la marca con plumón","Que está bien si es por poco rato"],"w":"En una botella de bebida, alguien puede tomarlo por error."},{"q":"¿En qué envase debe estar un químico?","o":["En su envase original o en uno rotulado","En una botella de bebida limpia","En un tarro sin etiqueta, bien tapado","En un balde abierto, para usarlo rápido"],"w":"El envase debe decir qué es y qué peligros tiene."},{"q":"Puedes guardar diluyente en una botella de bebida si la marcas con plumón.","vf":false,"w":"Falso. Nunca se usan envases de bebida o comida para químicos."}]},{"s":"quim_cc_gas","v":[{"q":"¿Cómo se almacena un cilindro de gas?","o":["De pie, encadenado o sujeto, y lejos del calor","Acostado, para que no se caiga","De pie, al sol, junto a la entrada","Acostado y amarrado, junto a los diluyentes"],"w":"De pie y sujeto no cae ni daña la válvula; el calor aumenta su presión."},{"q":"Debes mover un cilindro de gas de 45 kg. ¿Cómo lo haces?","o":["En carro, con la válvula protegida","Rodándolo acostado por el piso","Arrastrándolo inclinado","Tomándolo de la válvula"],"w":"Rodarlo, arrastrarlo o tomarlo de la válvula puede dañarla y provocar una fuga."},{"q":"¿Por qué el cilindro de gas se mantiene de pie y encadenado?","o":["Para que no caiga ni se dañe la válvula","Para que el gas salga más parejo","Para que ocupe menos espacio","Para que se vea su color"],"w":"Un cilindro que cae puede romper la válvula y liberar gas."}]},{"s":"quim_cc_cemento","v":[{"q":"El cemento solo es peligroso si se respira el polvo; en la piel no hace daño.","vf":false,"w":"Falso. Es alcalino: húmedo puede quemar la piel y dañar gravemente los ojos."},{"q":"Se rompió un saco de cemento y debes recogerlo. ¿Qué EPP usas?","o":["Guantes, lentes y manga larga","Solo guantes","Solo mascarilla","Ninguno, si lo haces rápido"],"w":"El cemento daña piel y ojos: protección para ambos."},{"q":"Te cayó cemento húmedo en el brazo. ¿Qué haces?","o":["Lavo con abundante agua y aviso","Lo dejo secar y lo sacudo","Lo limpio con diluyente","Lo limpio con un paño seco y sigo"],"w":"El agua lo retira; el diluyente daña más la piel y dejarlo secar prolonga la quemadura."}]},{"s":"quim_cc_derrame","v":[{"q":"Se cayó y se rompió un tarro de diluyente en el pasillo. ¿Qué haces primero?","o":["Alejo a las personas, evito fuego y chispas, y aviso","Lo limpio con un trapo, sin guantes","Lo tapo con cartones y sigo","Abro la llave y lo arrastro al desagüe"],"w":"Primero proteger a las personas y evitar que se encienda; luego contener con EPP."},{"q":"¿Qué haces con el residuo del derrame de diluyente ya absorbido?","o":["Lo elimino como indiquen la jefatura y la HDS","Lo boto en el basurero común","Lo tiro al desagüe con agua","Lo dejo en un rincón de la bodega"],"w":"Es un residuo peligroso: no va al basurero común ni al desagüe."},{"q":"Se rompió un galón de pintura en la sala con clientes cerca. ¿Cuál es el primer paso?","o":["Alejar a las personas del derrame","Ir a buscar el trapero","Avisar al proveedor","Taparlo con cartones y seguir"],"w":"Lo primero es que nadie pise el derrame ni se exponga a sus vapores."}]},{"s":"quimicos_pictos","v":[{"q":"El rombo con una llama en la etiqueta indica:","o":["Producto inflamable","Producto que se usa caliente","Producto corrosivo","Producto irritante"],"w":"La llama es el pictograma de inflamable (DS 57)."},{"q":"Un producto tiene el pictograma de corrosión. ¿Qué indica?","o":["Que daña la piel y los ojos","Que es inflamable","Que solo daña el medio ambiente","Que explota con golpes"],"w":"Corrosión: puede quemar piel y ojos. Guantes y lentes según la HDS."},{"q":"El rombo con una silueta humana y una estrella en el pecho indica:","o":["Daño grave a la salud","Irritación leve","Producto apto para uso humano","Producto certificado"],"w":"Indica daños graves, a veces a largo plazo. Revisa la HDS y usa el EPP indicado."}]},{"s":"quim_cc_solvente","v":[{"q":"Puedes fumar en la bodega de pinturas si los tarros están tapados.","vf":false,"w":"Falso. Puede haber vapores inflamables en el ambiente. Nada de fuego cerca."},{"q":"Terminaste de usar un tarro de diluyente. ¿Qué haces?","o":["Lo tapo de inmediato y lo guardo en su lugar","Lo dejo abierto para que ventile","Lo dejo destapado para la próxima vez","Lo tapo al final del turno"],"w":"Destapado libera vapores que irritan y pueden encenderse."},{"q":"¿Por qué el diluyente abierto es peligroso aunque nadie fume?","o":["Sus vapores pueden encenderse con una chispa y marean","Solo porque se seca y pierde calidad","Solo porque mancha el piso","Solo porque tiene mal olor"],"w":"Los vapores viajan: una chispa de esmeril o una estufa basta para encenderlos."}]},{"s":"quimicos_eyes","v":[{"q":"Te salpicó diluyente en los ojos. ¿Qué haces?","o":["Lavo con abundante agua al menos 15 minutos y aviso","Me froto los ojos con la manga","Me lavo un minuto y sigo","Espero a que se pase solo"],"w":"Agua abundante al menos 15 minutos, con los párpados abiertos, y avisar."},{"q":"¿Cuánto tiempo mínimo se lavan los ojos tras una salpicadura química?","o":["Al menos 15 minutos","Un minuto","Cinco minutos","Hasta que deje de arder"],"w":"Aunque deje de arder, el producto puede seguir dañando: 15 minutos como mínimo."},{"q":"Al ir a atenderte a la Mutual de Seguridad CChC por un contacto con un químico, conviene llevar la HDS o la etiqueta.","vf":true,"w":"Verdadero. Así el equipo de salud sabe qué producto fue y cómo tratarlo."}]},{"s":"quim_cc_alm","v":[{"q":"¿Dónde NO deben quedar los envases de pinturas y solventes?","o":["En pasillos, salidas o cerca del calor","En el lugar destinado, cerrados","En los niveles bajos del estante","Separados de los incompatibles"],"w":"Bloquean la evacuación y pueden encenderse. Van cerrados en su lugar (DS 43)."},{"q":"¿Dónde van los galones de pintura en el estante de bodega?","o":["En los niveles bajos, cerrados y etiquetados","En el nivel más alto","En el pasillo, para despachar rápido","Junto a la estufa, para que no se espesen"],"w":"Lo pesado y líquido abajo: si cae, cae de menos altura y se derrama menos."},{"q":"Los inflamables deben guardarse en el lugar destinado, lejos del calor y de las chispas.","vf":true,"w":"Verdadero. Cerrados, etiquetados y separados de los incompatibles."}]},{"s":"cc6_em_fuga","v":[{"q":"Sientes olor a gas cerca de los cilindros. ¿Qué haces?","o":["No enciendo nada, ventilo, alejo a las personas y aviso","Busco la fuga con un encendedor","Cierro puertas y ventanas para que no salga","Sigo trabajando si el olor es leve"],"w":"Una chispa o llama puede encender el gas. Se ventila y se avisa de inmediato."},{"q":"Hay olor a gas en la bodega. ¿Por qué no debes encender ni apagar la luz?","o":["Porque el interruptor puede hacer una chispa","Porque se puede cortar la luz","Porque el gas daña los equipos","Porque se gasta la ampolleta"],"w":"Al accionar un interruptor salta una pequeña chispa que puede encender el gas."},{"q":"Hay un fuerte olor a gas junto a los cilindros y hay clientes cerca. ¿Qué haces primero?","o":["Alejo a las personas sin accionar interruptores y aviso","Desenchufo los equipos cercanos","Enciendo el ventilador para sacar el gas","Busco de dónde sale antes de avisar"],"w":"Enchufes, interruptores y ventiladores hacen chispa. Primero las personas, luego avisar."}]}]},{"id":"sala_ventas","sec":"ventas","title":"Seguridad en la sala de ventas","thumb":"sv_intro","learn":[{"s":"sv_intro","t":"La sala también tiene peligros","x":"La sala de ventas parece tranquila, pero junta muchos peligros:<ul><li>Productos pesados en góndolas altas.</li><li>Sacos y cerámicas que se levantan a mano.</li><li>Derrames y pisos mojados por la lluvia.</li><li>Grúas o transpaletas reponiendo.</li><li>Cantos vivos de zinc, vidrio y flejes.</li><li>Clientes circulando, a veces con niños.</li></ul>Mira tu sala con ojos de prevención y avisa lo que esté mal."},{"s":"sv_gondolas","t":"Lo pesado, abajo","x":"<ul><li>Pon los productos <b>pesados en los niveles bajos</b>, como galones, sacos y cerámicas, y lo liviano arriba.</li><li>No dejes productos <b>sobresaliendo</b> del borde.</li><li>No sobrecargues las repisas.</li><li>Avisa si una repisa está doblada o mal encajada.</li></ul>¿Por qué? Si algo cae, cae de menos altura y no golpea a nadie en la cabeza. Un galón de 4 litros desde 2 metros puede lesionar gravemente a un cliente."},{"s":"sv_escalera_ok","t":"Reponer en altura: con escalera","x":"<ul><li><b>Nunca trepes</b> la góndola ni te subas a cajas, sillas o carros.</li><li>Usa una <b>escalera de tijera</b> revisada, totalmente abierta y trabada.</li><li>No te pares en el último peldaño ni en la tapa.</li><li>Sube y baja de frente, con tres puntos de apoyo.</li><li>Pide que un compañero te pase la carga; no la subas en brazos.</li><li>Delimita la zona si hay clientes.</li></ul>","k":"Para alcanzar arriba usa escalera, nunca trepes la góndola."},{"s":"sv_levantar","t":"Levantar sacos y cerámicas","x":"<ul><li>Acércate a la carga, pies separados.</li><li>Dobla las rodillas, <b>espalda recta</b>.</li><li>Carga <b>pegada al cuerpo</b>.</li><li>No gires el tronco: <b>gira con los pies</b>.</li></ul>Límites legales (Ley 20.949, Código del Trabajo): <b>25 kg</b> en hombres; <b>20 kg</b> en mujeres y menores de 18; las <b>embarazadas no pueden hacer carga manual</b>. Aunque estés bajo el límite, usa carro siempre que puedas."},{"s":"sv_ayuda","t":"Ayudar al cliente sin lesionarte","x":"Un cliente te pide llevar 10 cajas de cerámica o 6 sacos de cemento a su vehículo:<ul><li>Usa el <b>carro</b> o la plataforma.</li><li>Lo que pesa mucho o es largo, <b>entre dos</b>.</li><li>Si no hay carro, <b>un saco por vez</b>, aunque sean más viajes.</li><li>No lances sacos a la camioneta: acerca la carga y déjala.</li></ul>La buena atención no incluye lesionarte la espalda."},{"s":"sv_piso","t":"Pisos y pasillos","x":"<ul><li>Derrame de pintura o agua de lluvia en la entrada: <b>señalízalo</b> con letrero o cono y <b>límpialo</b>, o avisa de inmediato si no puedes.</li><li>Nada de cajas, pallets ni carros abandonados en los pasillos.</li><li>Extintores y salidas siempre despejados.</li></ul>Un piso resbaloso no se deja para después: el próximo que pase puede ser un cliente o un niño."},{"s":"sv_grua","t":"Grúa o transpaleta en la sala","x":"Al reponer con grúa horquilla o transpaleta:<ul><li>Solo opera quien está <b>capacitado y autorizado</b> por la empresa; una licencia de conducir no basta.</li><li><b>Aísla la zona</b> con conos y aleja a los clientes, aunque haya pocos.</li><li>Velocidad moderada, según las reglas internas.</li><li><b>Nadie bajo la carga levantada</b>: ni clientes ni compañeros.</li></ul>","k":"Nunca pases ni dejes pasar a nadie bajo la carga de la grúa."},{"s":"sv_cortes","t":"Cortes: zinc, vidrio y flejes","x":"<ul><li>Las planchas de zinc, vidrios y perfiles tienen <b>cantos vivos</b>: usa guantes, aunque las planchas sean nuevas.</li><li>Los <b>flejes</b> de pallets saltan al cortarlos: córtalos de lado, sujetando la punta, nunca de frente.</li><li>Con el cartonero, corta <b>hacia afuera del cuerpo</b> y ciérralo después de usarlo.</li><li>Recoge los flejes cortados: enredan y cortan.</li></ul>"},{"s":"sv_caja","t":"En la caja y el mesón","x":"<ul><li>Mantén el mesón ordenado: nada que pueda caer.</li><li>Cartonero y tijeras, cerrados y guardados.</li><li>Si pasas mucho rato de pie, <b>alterna la postura</b> y aprovecha las pausas.</li><li>No levantes productos pesados por sobre el mesón: que se lleven en carro.</li><li>Cables del computador y de la impresora ordenados, fuera del paso.</li></ul>"},{"s":"sv_auto","t":"Autocuidado: el apuro pesa","x":"La mayoría de los accidentes se relacionan con una acción insegura. En la sala, la típica es el <b>apuro</b>: llevar dos sacos de una vez porque hay fila, trepar la góndola por un segundo o dejar el derrame para después. La decisión segura: <b>un viaje más, carro o ayuda</b>. Y avisa las repisas dobladas y los pisos malos."}],"quiz":[{"s":"sv_gondolas","v":[{"q":"¿Dónde deben ir los productos más pesados en una góndola?","o":["En los niveles bajos","En el nivel más alto","En el nivel medio, a la vista","Donde haya espacio libre"],"w":"Lo pesado abajo: si cae, cae de menos altura y no golpea a nadie en la cabeza."},{"q":"Repones galones de pintura de 4 litros y cajas de lijas. ¿Cómo los ordenas?","o":["Galones abajo y lijas arriba","Galones arriba, porque se ven mejor","Mezclados, para que el cliente elija","Galones al borde de la repisa alta"],"w":"Pesado abajo, liviano arriba y nada sobresaliendo."},{"q":"¿Por qué los productos pesados van en los niveles bajos?","o":["Si caen, caen de menos altura y no golpean la cabeza","Porque así el cliente los ve mejor","Porque así la repisa alta luce ordenada","Porque abajo se venden más"],"w":"Un producto pesado que cae desde arriba puede lesionar gravemente a alguien."}]},{"s":"sv_escalera_mal","v":[{"q":"Un compañero repone trepando por las repisas de la góndola. ¿Qué corresponde?","o":["Que baje y use una escalera de tijera revisada","Que siga si se afirma bien","Que use una silla firme","Que se suba en una caja cerrada"],"w":"La góndola no es escalera: se puede volcar o él puede resbalar."},{"q":"Para reponer en el nivel alto de la góndola debes:","o":["Usar escalera de tijera abierta, sin pararte en el último peldaño","Trepar por las repisas, que son firmes","Usar una silla con respaldo","Pararte en el último peldaño para alcanzar más"],"w":"Escalera abierta y trabada, de frente y sin pisar el último peldaño ni la tapa."},{"q":"Trepar la góndola está permitido si es por pocos segundos.","vf":false,"w":"Falso. Nunca se trepa la góndola: se usa escalera."}]},{"s":"sv_levantar","v":[{"q":"El límite de carga manual para un hombre es:","o":["25 kg","50 kg","40 kg","30 kg"],"w":"Ley 20.949: 25 kg en hombres; 20 kg en mujeres y menores de 18; embarazadas no cargan."},{"q":"¿Cuál es el límite de carga manual para mujeres y menores de 18 años?","o":["20 kg","25 kg","15 kg","30 kg"],"w":"20 kg para mujeres y menores de 18. Aun así, conviene usar carro."},{"q":"Según la ley, una trabajadora embarazada:","o":["No puede realizar carga manual","Puede cargar hasta 20 kg","Puede cargar hasta 10 kg","Puede cargar si usa faja"],"w":"Las embarazadas no pueden hacer labores de carga y descarga manual."}]},{"s":"sv_levantar","v":[{"q":"Al levantar un saco de cemento, debes doblar la espalda y mantener las piernas rectas.","vf":false,"w":"Falso. Rodillas dobladas, espalda recta y carga pegada al cuerpo."},{"q":"¿Cómo levantas una caja de cerámica desde el piso?","o":["Rodillas dobladas, espalda recta y caja pegada","Piernas rectas y espalda doblada","Brazos estirados, caja lejos del cuerpo","Girando el tronco hacia el carro"],"w":"Así el esfuerzo lo hacen las piernas y no la espalda."},{"q":"Debes dejar un saco en el carro que está a tu lado. ¿Cómo giras?","o":["Muevo los pies, sin torcer el tronco","Giro la cintura con los pies fijos","Lo lanzo al carro","Giro rápido para no cansarme"],"w":"Torcer el tronco con carga daña la columna: se gira con los pies."}]},{"s":"sv_ayuda","v":[{"q":"Un cliente pide llevar 6 sacos de cemento a su camioneta. ¿Qué haces?","o":["Uso el carro o pido ayuda","Llevo dos sacos por vez para ir rápido","Los arrastro por el piso","Los lanzo a la camioneta desde atrás"],"w":"Carro, ayuda y un saco por vez: la atención no incluye lesionarte."},{"q":"Un cliente pide llevar 10 cajas de cerámica a su auto. ¿Qué haces?","o":["Uso el carro y pido ayuda si pesa mucho","Llevo tres cajas por vez para ir rápido","Llevo cinco y él lleva cinco a pulso","Las llevo apiladas hasta la cara"],"w":"Con carro se evitan sobreesfuerzos y caídas."},{"q":"Para llevar varios sacos al vehículo de un cliente, lo correcto es usar el carro o hacer viajes de un saco por vez.","vf":true,"w":"Verdadero. Más viajes, pero sin lesiones."}]},{"s":"sv_piso","v":[{"q":"Ves pintura derramada en un pasillo. ¿Qué haces?","o":["Lo señalizo y lo limpio, o aviso de inmediato","Lo dejo para el final del turno","Le pongo una caja encima","Sigo atendiendo y aviso cuando pueda"],"w":"Un piso resbaloso no espera: el próximo en pasar puede ser un cliente."},{"q":"Está lloviendo y la entrada de la sala está mojada. ¿Qué haces?","o":["Señalizo, seco o aviso de inmediato","Espero a que pare de llover","Pongo un cartón encima sin avisar","Aviso al final del turno"],"w":"Señalizar y secar evita resbalones de clientes y trabajadores."},{"q":"Si ves un derrame y no puedes limpiarlo de inmediato, debes señalizarlo y avisar.","vf":true,"w":"Verdadero. Nunca se deja un piso resbaloso sin señalizar."}]},{"s":"sv_grua","v":[{"q":"Cuando la grúa repone en la sala, ¿pueden pasar clientes bajo la carga?","o":["No, nadie pasa bajo la carga levantada","Sí, si van rápido","Sí, si un vendedor los guía","Sí, si la carga está bien amarrada"],"w":"Se aísla la zona y nadie pasa bajo la carga levantada."},{"q":"La grúa va a reponer en un pasillo de la sala. ¿Qué se hace?","o":["Aislar con conos y alejar a los clientes","Reponer sin aislar si hay pocos clientes","Pedir a los clientes que pasen con cuidado","Que un vendedor sostenga la carga"],"w":"Zona aislada y nadie bajo la carga, aunque haya pocos clientes."},{"q":"¿Quién puede quedar bajo una carga levantada por la grúa?","o":["Nadie, ni trabajador ni cliente","Solo el compañero que guía la maniobra","Solo quien ayuda a acomodar la carga","Un cliente, si va rápido"],"w":"Si la carga cae, quien esté debajo no tiene escapatoria."}]},{"s":"sv_grua","v":[{"q":"¿Quién puede operar la grúa horquilla en la sala?","o":["Solo quien está capacitado y autorizado por la empresa","Cualquier vendedor con experiencia","Quien tenga licencia de conducir","El jefe de turno, aunque no esté capacitado"],"w":"Solo opera quien está capacitado y autorizado por la empresa."},{"q":"El operador está en colación y un vendedor con licencia clase B quiere mover un pallet con la grúa. ¿Puede?","o":["No, solo opera quien está capacitado y autorizado","Sí, la licencia de conducir basta","Sí, si lo mueve despacio","Sí, si la jefatura no está"],"w":"Una licencia de conducir no autoriza a operar la grúa horquilla."},{"q":"Cualquier vendedor con experiencia puede operar la grúa en la sala si va despacio.","vf":false,"w":"Falso. Solo quien está capacitado y autorizado por la empresa."}]},{"s":"sv_cortes","v":[{"q":"Debes mover planchas de zinc nuevas. ¿Qué usas?","o":["Guantes, por los cantos vivos","Nada, si las tomas de los bordes","Solo lentes de seguridad","Guantes solo si están oxidadas"],"w":"Los cantos del zinc cortan aunque la plancha sea nueva."},{"q":"¿Cómo cortas el fleje de un pallet?","o":["De lado, sujetando la punta","De frente, para ver bien","Tirándolo con la mano hasta que salte","Con el cartonero, hacia el cuerpo"],"w":"El fleje salta al cortarlo: de lado y sujetando la punta."},{"q":"¿Cómo se usa el cartonero de forma segura?","o":["Cortando hacia afuera del cuerpo y cerrándolo después","Cortando hacia ti para tener más fuerza","Dejándolo abierto en el mesón para usarlo rápido","Con toda la hoja afuera para cortar más"],"w":"Corta hacia afuera y ciérralo: así evitas cortes propios y ajenos."}]},{"s":"sv_auto_mal","v":[{"q":"Tu compañero lleva dos sacos de cemento a la vez porque hay fila. ¿Qué le dices?","o":["Que use el carro o lleve uno por vez","Que está bien si dobla las rodillas","Que está bien si es un solo viaje","Que use faja y siga"],"w":"El apuro es la causa típica: un viaje más vale más que una lesión."},{"q":"Hay apuro en la sala. ¿Cuál es la decisión segura?","o":["Un viaje más, usar carro o pedir ayuda","Llevar dos sacos para ahorrar viajes","Trepar la góndola por un segundo","Dejar el derrame para después"],"w":"El apuro lleva a actos inseguros. Decide seguro aunque tome más tiempo."},{"q":"El apuro es una causa típica de actos inseguros en la sala, como cargar dos sacos a la vez.","vf":true,"w":"Verdadero. Un viaje más, carro o ayuda."}]}]},{"id":"atencion_publico","sec":"ventas","title":"Atención de público: clientes molestos y violencia de terceros","thumb":"ap_intro","learn":[{"s":"ap_intro","t":"Clientes molestos: pasa","x":"En {EMP} atendemos a mucha gente cada día. A veces un cliente llega molesto: un pedido que no llegó, una fila larga, un precio o un producto sin stock. Casi siempre se calma si lo atendemos bien. Pero un <b>insulto, una amenaza, una burla o un empujón</b> no son parte de la pega: son <b>violencia en el trabajo</b>, y se previenen, se registran y se denuncian."},{"s":"ap_escuchar","t":"Primero, escucha","x":"Tres pasos, en este orden:<ul><li><b>Escucha:</b> deja que cuente su problema sin interrumpir.</li><li><b>Repite</b> lo que entendiste: Entonces, su pedido no llegó.</li><li><b>Ofrece</b> algo concreto: Voy a revisar con bodega y le aviso en cinco minutos.</li></ul>No lo tomes como algo personal: está molesto con la situación, no contigo. Explicar que no es tu culpa suele enojar más."},{"s":"ap_tono","t":"Tono bajo: no discutas","x":"Si el cliente sube la voz, <b>tú bájala</b>. Habla lento y claro.<ul><li>No discutas quién tiene la razón.</li><li>No uses ironías ni gestos de burla.</li><li><b>No respondas el insulto</b>, ni con firmeza.</li><li>Trátalo de usted, con respeto.</li></ul>¿Por qué? La rabia se contagia: si discutes, el problema crece y el riesgo de agresión también."},{"s":"ap_distancia","t":"Distancia y salida libre","x":"<ul><li>Deja el <b>mesón entre tú y el cliente</b>.</li><li>Mantén <b>más de un brazo</b> de distancia.</li><li>No te dejes arrinconar: ten siempre una <b>salida libre</b> a tu alcance, no una pared a tu espalda.</li><li>No salgas del mesón a enfrentar a nadie.</li><li>No toques ni empujes al cliente, aunque sea para alejarlo.</li></ul>","k":"Mantén el mesón al medio, distancia y una salida libre."},{"s":"ap_retirate","t":"Cuándo retirarte","x":"Retírate y pide apoyo si el cliente:<ul><li>Insulta o amenaza.</li><li>Golpea el mesón o lanza cosas.</li><li>Se acerca de forma agresiva o intenta pasar al mesón.</li><li>Parece estar bajo efectos del alcohol o drogas.</li></ul>Di con calma: Voy a buscar a mi jefatura, y aléjate. Si alguien corre peligro, llama al <b>133 (Carabineros)</b>.","k":"Ante amenazas, retírate con calma y pide apoyo."},{"s":"ap_equipo","t":"Pide apoyo: no estás solo","x":"Un compañero o la jefatura pueden tomar el caso: a veces basta con que atienda otra persona. Si tu sucursal tiene una <b>palabra o señal para pedir ayuda</b>, apréndela: sirve para avisar sin alterar más al cliente. Si no la hay, pregunta a tu jefatura cómo avisar. Y si ves a un compañero en problemas, acércate a apoyarlo y avisa, <b>sin enfrentar al cliente</b>."},{"s":"ap_karin","t":"Ley Karin: violencia de terceros","x":"La <b>Ley 21.643 (Ley Karin)</b>, vigente desde el 1 de agosto de 2024, cubre el acoso laboral, el acoso sexual y la <b>violencia en el trabajo ejercida por terceros</b>: clientes, proveedores o usuarios. {EMP} debe tener un <b>protocolo de prevención</b>, y tú puedes <b>denunciar</b> ante la empresa o ante la Inspección del Trabajo, con reserva. Pregunta a tu jefatura dónde está el protocolo."},{"s":"ap_registra","t":"Registra y avisa","x":"Después de un incidente, aunque haya sido <b>solo verbal</b>, anota lo antes posible:<ul><li>Fecha y hora.</li><li>Qué dijo o hizo el cliente, con sus palabras.</li><li>Quiénes lo vieron.</li></ul>Avisa a tu jefatura <b>el mismo día</b>. Lo que no se registra no se puede prevenir: sirve para tomar medidas, como reforzar la atención en horas punta, y para respaldar una denuncia."},{"s":"ap_apoyo","t":"Si te afectó, pide apoyo","x":"Miedo, rabia o no poder dormir después de una agresión son reacciones normales. Habla con tu jefatura: puede derivarte a <b>atención psicológica en la Mutual de Seguridad CChC</b> (fono 1407). Si sufriste una <b>agresión física trabajando</b>, es un <b>accidente del trabajo</b> (Ley 16.744): avisa de inmediato para que se haga la denuncia y te atiendan sin costo."},{"s":"ap_auto","t":"Autocuidado: no te enganches","x":"La mayoría de los accidentes se relacionan con una acción insegura. Aquí, la típica es <b>engancharse</b>: responder el insulto, salir del mesón a poner en su lugar al cliente o seguirlo al estacionamiento. La decisión segura: <b>calma, distancia, retirarte y pedir apoyo</b>, y después registrar y avisar. También avisa las condiciones que generan roces, como filas largas sin atención."}],"quiz":[{"s":"ap_escuchar","v":[{"q":"Un cliente te grita porque su pedido no llegó. ¿Qué haces primero?","o":["Lo escucho sin interrumpir y repito lo que entendí","Le explico que no es mi culpa","Le pido que baje la voz o no lo atiendo","Lo derivo a otra caja sin decir nada"],"w":"Escuchar y repetir lo entendido calma. Justificarse o ignorarlo lo enciende."},{"q":"Un cliente reclama molesto por una fila larga. ¿Qué haces?","o":["Lo escucho, repito lo que entendí y le ofrezco algo concreto","Le explico que hay poco personal y que no es mi culpa","Le digo que espere sin responderle","Le digo que en otra ferretería es peor"],"w":"Escuchar, repetir y ofrecer algo concreto es lo que más calma."},{"q":"¿Cuál es el orden recomendado para atender a un cliente molesto?","o":["Escuchar, repetir lo entendido y ofrecer algo concreto","Explicar la política, ofrecer y despedir","Ofrecer algo de inmediato, sin escuchar","Interrumpir para aclarar el error"],"w":"Primero que se sienta escuchado; luego, una solución concreta."}]},{"s":"ap_tono","v":[{"q":"Si el cliente sube la voz, lo mejor es subirla también para que te respete.","vf":false,"w":"Falso. Si él sube la voz, tú la bajas: la rabia se contagia."},{"q":"El cliente te habla a gritos. ¿Cómo respondes?","o":["Bajo la voz y hablo lento y claro","Subo la voz para que me escuche","Le respondo con una broma para relajarlo","Le explico quién tiene la razón"],"w":"Un tono bajo baja la tensión. Bromas o discusiones la suben."},{"q":"¿Por qué no conviene discutir con un cliente alterado?","o":["La rabia se contagia y el riesgo de agresión crece","Porque el cliente siempre tiene la razón","Porque solo la jefatura puede discutir","Porque se pierde la venta"],"w":"Discutir hace crecer el conflicto y te expone a una agresión."}]},{"s":"ap_mal","v":[{"q":"El vendedor sale del mesón y le responde a gritos al cliente. ¿Qué debió hacer?","o":["Quedarse tras el mesón, bajar la voz y pedir apoyo","Responderle, pero sin garabatos","Salir del mesón para calmarlo de cerca","Tomarlo del brazo para alejarlo"],"w":"Salir del mesón y responder el insulto aumentan el riesgo de agresión."},{"q":"Un cliente te dice: ¡Usted no sabe nada! ¿Qué haces?","o":["No respondo el insulto, mantengo la calma y ofrezco revisar","Le respondo: ¡Y usted menos!","Le pido que se retire de la tienda","Le doy la espalda sin decir nada"],"w":"Responder o ignorar lo enciende más. Calma y una solución concreta."},{"q":"Responder el insulto con firmeza ayuda a que el cliente te respete.","vf":false,"w":"Falso. No se responde el insulto: se mantiene la calma y se pide apoyo si sigue."}]},{"s":"ap_distancia","v":[{"q":"¿Dónde conviene quedar al atender a un cliente alterado?","o":["Detrás del mesón, con distancia y una salida libre","Frente a frente, sin mesón, para dar confianza","Al fondo de la caja, contra la pared","A su lado, para mostrarle la pantalla"],"w":"El mesón y la distancia te protegen; la salida libre te permite retirarte."},{"q":"¿Qué distancia conviene mantener con un cliente alterado?","o":["Más de un brazo, con el mesón al medio","Medio brazo, para que te escuche bien","Pegado a él, para calmarlo","La que el cliente elija"],"w":"Con más de un brazo de distancia no te alcanza si intenta agredirte."},{"q":"Al atender a un cliente alterado, ¿qué debes tener siempre a tu alcance?","o":["Una salida libre para retirarte","Una pared a tu espalda","La caja cerrada a tu lado","Un rincón tranquilo"],"w":"Si te arrinconan, no puedes retirarte cuando la situación empeora."}]},{"s":"ap_retirate","v":[{"q":"El cliente golpea el mesón y te amenaza. ¿Qué haces?","o":["Me retiro con calma y pido apoyo a mi jefatura","Salgo del mesón a enfrentarlo","Le respondo en el mismo tono","Sigo atendiendo como si nada"],"w":"Ante amenazas: retirarse y pedir apoyo. Si alguien corre peligro, llama al 133."},{"q":"¿Cuál de estas señales indica que debes retirarte y pedir apoyo?","o":["El cliente amenaza o lanza cosas","El cliente reclama por un precio","El cliente pide hablar con la jefatura","El cliente se queja de la fila"],"w":"Las amenazas, golpes o lanzar objetos son señales de agresión."},{"q":"Un cliente amenaza con golpear a un compañero y no se calma. Si alguien corre peligro, ¿a qué número llamas?","o":["133","131","132","134"],"w":"133 es Carabineros. 131 es SAMU y 132 es Bomberos."}]},{"s":"ap_karin","v":[{"q":"La Ley Karin también cubre la violencia que ejercen clientes y proveedores contra los trabajadores.","vf":true,"w":"Verdadero. La violencia en el trabajo ejercida por terceros está incluida en la Ley 21.643."},{"q":"¿Ante quién puedes denunciar la violencia de un cliente según la Ley Karin?","o":["Ante la empresa o la Inspección del Trabajo","Solo ante Carabineros","Solo ante la Mutual","Solo ante el propio cliente"],"w":"La denuncia se hace ante la empresa o la Inspección del Trabajo."},{"q":"La Ley 21.643 (Ley Karin) cubre:","o":["Acoso laboral, acoso sexual y violencia de terceros","Solo el acoso de las jefaturas","Solo el acoso entre compañeros","Solo la violencia física con lesiones"],"w":"Incluye la violencia de clientes, proveedores y usuarios."}]},{"s":"ap_registra","v":[{"q":"¿Qué debes anotar después de un incidente con un cliente?","o":["Fecha y hora, qué pasó y quiénes lo vieron","Solo el monto de la compra","Solo el nombre del cliente","Solo si hubo golpes"],"w":"El registro permite tomar medidas y respalda una denuncia."},{"q":"¿Cuándo avisas a tu jefatura un incidente con un cliente?","o":["El mismo día","Solo si hubo golpes","Al final del mes, con los demás","Solo si el cliente vuelve"],"w":"Avisar el mismo día permite tomar medidas a tiempo."},{"q":"Si el incidente fue solo verbal, no vale la pena registrarlo.","vf":false,"w":"Falso. También se registra y se avisa: sirve para prevenir y para una denuncia."}]},{"s":"ap_apoyo","v":[{"q":"Un cliente te empujó mientras trabajabas. Eso es:","o":["Un accidente del trabajo que debes avisar","Un asunto personal entre tú y el cliente","Algo propio del rubro, sin cobertura","Solo un tema para Carabineros"],"w":"Una agresión física trabajando es accidente del trabajo (Ley 16.744). Avisa de inmediato."},{"q":"Después de una agresión no puedes dormir y sientes miedo. ¿Qué haces?","o":["Lo hablo con mi jefatura y pido apoyo psicológico en la Mutual","Lo guardo para mí, ya pasará","Pido cambio de turno sin contar el motivo","Tomo pastillas para dormir sin consultar"],"w":"Son reacciones normales. La Mutual de Seguridad CChC da apoyo psicológico."},{"q":"Una agresión física de un cliente mientras trabajas es accidente del trabajo y se debe avisar.","vf":true,"w":"Verdadero. Avisa a tu jefatura para la denuncia y la atención en la Mutual."}]},{"s":"ap_equipo","v":[{"q":"Ves que un cliente insulta a tu compañera en caja. ¿Qué haces?","o":["Me acerco a apoyarla y aviso a la jefatura, sin enfrentar al cliente","Sigo con lo mío, ella sabrá manejarlo","Le digo al cliente que se retire de inmediato","Defiendo a mi compañera respondiéndole"],"w":"Nadie está solo: apoyar a tiempo evita que escale, sin enfrentar al cliente."},{"q":"¿Para qué sirve una palabra o señal para pedir ayuda?","o":["Para avisar a compañeros sin alterar más al cliente","Para llamar directamente a Carabineros","Para cerrar la sucursal","Para que el cliente sepa que lo vigilan"],"w":"Permite pedir apoyo discretamente."},{"q":"Un cliente sigue alterado contigo pese a tus esfuerzos. ¿Qué haces?","o":["Pido que lo atienda un compañero o la jefatura","Sigo atendiendo hasta que se calme","Le digo que vuelva otro día","Le respondo con la misma firmeza"],"w":"A veces basta con que atienda otra persona."}]},{"s":"ap_auto","v":[{"q":"Un cliente te insulta y se va. ¿Qué haces?","o":["Registro lo ocurrido y aviso a mi jefatura","Lo sigo al estacionamiento para encararlo","Lo dejo pasar sin contarle a nadie","Lo comento en redes sociales"],"w":"Seguirlo es engancharse y te expone. Registrar y avisar permite prevenir."},{"q":"Frente a un cliente agresivo, la decisión segura es:","o":["Calma, distancia, retirarse y pedir apoyo","Responder en el mismo tono para poner límites","Salir del mesón para ponerle límites","Ignorarlo y seguir atendiendo a otros"],"w":"No engancharse protege tu integridad."},{"q":"Un compañero quiere salir a poner en su lugar a un cliente que lo insultó. ¿Qué le dices?","o":["Que no: se registra, se avisa y se pide apoyo","Que vaya, pero sin tocarlo","Que lo acompañas para que no vaya solo","Que espere a que el cliente salga del local"],"w":"Enfrentar al cliente es la acción insegura típica."}]}]},{"id":"asaltos","sec":"ventas","title":"Qué hacer ante un robo o asalto","thumb":"as_intro","learn":[{"s":"as_intro","t":"Tu vida vale más que la caja","x":"Un robo o asalto puede ocurrir en cualquier comercio, también en {EMP}. La regla de oro: <b>tu vida y la de los clientes valen más</b> que cualquier producto o dinero. Las cosas se reponen; una vida o una lesión grave, no. En esta charla verás qué hacer <b>antes</b> (manejo de caja), <b>durante</b> (no resistir, obedecer, observar) y <b>después</b> (avisar, no tocar nada y pedir apoyo)."},{"s":"as_noresistas","t":"Durante: no resistas","x":"<ul><li><b>No forcejees</b> ni intentes quitarle el arma o el dinero.</li><li>No grites ni hagas movimientos bruscos, como agacharte de golpe.</li><li>No te hagas el héroe ni mientas diciendo que no hay dinero.</li></ul>¿Por qué? El asaltante suele estar nervioso y apurado. Cualquier resistencia o sorpresa puede hacer que reaccione con violencia contra ti o contra un cliente.","k":"No resistas ni forcejees: tu vida vale más."},{"s":"as_obedece","t":"Obedece con calma","x":"<ul><li>Haz <b>solo lo que te pidan</b>, sin apuro.</li><li>Movimientos <b>lentos</b> y <b>manos a la vista</b>.</li><li><b>Avisa antes de moverte</b>: Voy a abrir la caja, o Voy a sacar las llaves del bolsillo.</li><li>No lo mires fijo ni lo desafíes.</li></ul>Mientras más corto y tranquilo sea el hecho, menos riesgo hay para todos."},{"s":"as_nopersigas","t":"No persigas","x":"Cuando el asaltante se va, <b>no lo sigas</b> ni salgas a la calle tras él, aunque vaya solo y no veas un arma: puede volver, puede tener cómplices afuera o puede herirte. Tampoco dejes que un compañero o un cliente lo persiga: pídeles con calma que no lo hagan. Lo robado no vale una lesión.","k":"Nunca persigas al asaltante."},{"s":"as_observa","t":"Observa para después","x":"Con disimulo, <b>sin mirarlo fijo</b>, trata de recordar:<ul><li>Estatura, contextura y ropa.</li><li>Rasgos, tatuajes, voz o forma de hablar.</li><li>Hacia dónde huyó.</li><li>Vehículo: tipo, color y patente, si lo hubo.</li></ul>No saques fotos ni lo sigas para verlo mejor. Estos datos ayudan a Carabineros."},{"s":"as_avisa133","t":"Cuando sea seguro: avisa","x":"Espera a que se hayan ido. Luego:<ul><li>Avisa a tu <b>jefatura</b>.</li><li>Llama al <b>133 (Carabineros)</b>.</li><li>Si hay lesionados, llama al <b>131 (SAMU)</b>.</li><li>Cierra el acceso si es posible, para que no vuelvan.</li></ul>Si tu sucursal tiene algún sistema de aviso, pregunta a tu jefatura cómo y cuándo usarlo sin exponerte."},{"s":"as_caja","t":"Antes: manejo de caja","x":"La prevención empieza antes:<ul><li><b>No exhibas ni cuentes dinero</b> a la vista de clientes.</li><li>Mantén la caja <b>cerrada</b> si te alejas, aunque sea un momento.</li><li>Haz los retiros de dinero según las reglas internas; no acumules.</li><li><b>No comentes montos</b> ni horarios de retiro o traslado de dinero, ni siquiera con clientes conocidos.</li></ul>"},{"s":"as_despues","t":"Después: no toques nada","x":"<ul><li>No toques ni ordenes el lugar donde estuvo el asaltante: mesón, caja, puerta u objetos que dejó.</li><li>Pide a los testigos que esperen, si pueden.</li><li>Anota lo que recuerdes, <b>cada uno por separado</b>, para que un relato no cambie al otro.</li><li>Sigue las instrucciones de Carabineros y de tu jefatura.</li></ul>Las huellas y los detalles se pierden fácil."},{"s":"as_accidente","t":"Es accidente del trabajo","x":"Un asalto sufrido trabajando es <b>accidente del trabajo</b> (Ley 16.744). Avisa a tu jefatura para que se haga la denuncia (DIAT) y acude a la <b>Mutual de Seguridad CChC</b> (fono 1407): atiende lesiones y entrega <b>apoyo psicológico</b>, aunque no tengas heridas. Miedo, angustia o insomnio después son reacciones normales: pide ayuda a tiempo."},{"s":"as_auto","t":"Autocuidado: decide antes","x":"La mayoría de los accidentes se relacionan con una acción insegura. En un asalto, las típicas son <b>forcejear, perseguir</b> o tener <b>dinero a la vista</b>. La decisión segura se toma <b>antes</b>, en calma, no en el momento: Si pasa, no resisto, observo y aviso al 133. Y avisa a tu jefatura las condiciones que te preocupan."}],"quiz":[{"s":"as_intro","v":[{"q":"Durante un asalto, ¿qué es lo más importante?","o":["Proteger tu vida y la de los clientes","Proteger el dinero de la caja","Proteger la mercadería de mayor valor","Retener al asaltante hasta que llegue Carabineros"],"w":"Las cosas se reponen; una vida o una lesión grave, no."},{"q":"Un asaltante exige el dinero de la caja. ¿Qué priorizas?","o":["Mi vida y la de los clientes: entrego sin resistir","El dinero, porque soy responsable de la caja","Esconder parte del dinero","Ganar tiempo discutiendo"],"w":"Ningún monto vale una lesión o una vida."},{"q":"Durante un asalto, lo correcto es proteger primero el dinero y la mercadería de la empresa.","vf":false,"w":"Falso. Primero tu vida y la de los clientes: las cosas se reponen."}]},{"s":"as_noresistas","v":[{"q":"Durante un asalto, lo correcto es no forcejear, no gritar y no hacer movimientos bruscos.","vf":true,"w":"Verdadero. Cualquier resistencia o sorpresa puede provocar una reacción violenta."},{"q":"¿Por qué no se debe resistir a un asaltante?","o":["Está nervioso y puede reaccionar con violencia","Porque el seguro lo cubre todo","Porque Carabineros llegará de inmediato","Porque le corresponde al guardia"],"w":"El nerviosismo del asaltante hace que cualquier resistencia sea peligrosa."},{"q":"Un asaltante grita: ¡La plata! ¿Cómo actúas?","o":["Sin forcejear, sin gritar y sin movimientos bruscos","Grito para alertar a los clientes","Me agacho rápido bajo el mesón","Le digo que no hay dinero"],"w":"Gritar, agacharse de golpe o mentir pueden provocar una reacción violenta."}]},{"s":"as_obedece","v":[{"q":"El asaltante te pide abrir la caja. ¿Cómo lo haces?","o":["Aviso que voy a abrir la caja y lo hago lento","Me muevo rápido para que se vaya luego","Le digo que no tengo la llave","La abro sin decir nada"],"w":"Avisar cada movimiento y hacerlo lento evita sobresaltos."},{"q":"Necesitas sacar las llaves de tu bolsillo para abrir. ¿Qué haces?","o":["Aviso que voy a sacar las llaves y lo hago lento","Las saco rápido sin decir nada","Le pido que las saque él","Le digo que no las tengo"],"w":"Un movimiento sin avisar puede parecerle que sacas un arma."},{"q":"Durante un asalto, ¿dónde mantienes las manos?","o":["A la vista, con movimientos lentos","En los bolsillos","Bajo el mesón","Detrás de la espalda"],"w":"Manos a la vista: el asaltante ve que no representas amenaza."}]},{"s":"as_nopersigas","v":[{"q":"El asaltante huye a la calle. ¿Qué haces?","o":["No lo persigo; espero y aviso","Lo sigo de lejos para ver hacia dónde va","Lo persigo con un compañero","Salgo a anotar la patente desde la vereda"],"w":"Puede volver, tener cómplices o herirte. Nunca se persigue."},{"q":"Un cliente quiere salir a perseguir al asaltante. ¿Qué haces?","o":["Le pido que no lo haga: puede volver o tener cómplices","Lo acompaño para que no vaya solo","Le paso algo para defenderse","Lo dejo, es decisión suya"],"w":"Tampoco se deja que clientes o compañeros persigan."},{"q":"Si el asaltante huye solo y sin arma visible, puedes seguirlo para ver hacia dónde va.","vf":false,"w":"Falso. Puede tener un arma oculta o cómplices. Nunca se persigue."}]},{"s":"as_avisa133","v":[{"q":"¿A qué número llamas para avisar del asalto a Carabineros?","o":["133","131","132","134"],"w":"133 es Carabineros; 131 es SAMU (lesionados); 132 es Bomberos."},{"q":"Tras el asalto hay un compañero herido. ¿A qué número llamas por atención de urgencia?","o":["131","133","132","134"],"w":"131 es SAMU, para lesionados. Carabineros es el 133."},{"q":"¿Cuándo llamas a Carabineros?","o":["Cuando el asaltante se haya ido y sea seguro","Durante el asalto, a escondidas","Antes de abrir la caja","Solo si hubo heridos"],"w":"Llamar durante el asalto te expone. Se avisa cuando sea seguro."}]},{"s":"as_caja_mal","v":[{"q":"Un cajero cuenta billetes sobre el mesón con clientes mirando. ¿Qué corresponde?","o":["Contar fuera de la vista y mantener la caja cerrada","Contarlo rápido para terminar luego","Contarlo en voz alta para no equivocarse","Pedir a los clientes que esperen de espaldas"],"w":"El dinero a la vista atrae robos."},{"q":"¿Cuál es una buena práctica de prevención en la caja?","o":["No comentar montos ni horarios de retiro de dinero","Acumular dinero para hacer un solo retiro","Dejar la caja abierta al ir a bodega un momento","Comentar los montos solo con clientes conocidos"],"w":"Montos y horarios son información para un asaltante."},{"q":"Mantener la caja cerrada cuando te alejas es una medida de prevención de asaltos.","vf":true,"w":"Verdadero. Junto con no exhibir dinero y retirar según las reglas internas."}]},{"s":"as_despues","v":[{"q":"Después del asalto, lo mejor es ordenar y limpiar el mesón de inmediato.","vf":false,"w":"Falso. No se toca nada: las huellas y los detalles sirven a Carabineros."},{"q":"Se fue el asaltante. ¿Qué haces con el lugar?","o":["No toco nada y espero a Carabineros","Ordeno para seguir atendiendo","Limpio el mesón donde se apoyó","Recojo lo que botó y lo guardo"],"w":"Las huellas y objetos son pruebas."},{"q":"¿Cómo anotan los testigos lo que vieron?","o":["Cada uno por separado","Todos juntos, para ponerse de acuerdo","Solo la jefatura anota","No anotan; esperan a Carabineros"],"w":"Por separado, para que un relato no influya en el otro."}]},{"s":"as_observa","v":[{"q":"¿Qué datos conviene recordar del asaltante?","o":["Estatura, ropa, rasgos y hacia dónde huyó","Solo lo que dijo","Solo el arma que usaba","Solo su edad aproximada"],"w":"Observa con disimulo, sin mirar fijo. Esos datos ayudan después."},{"q":"¿Cómo observas al asaltante?","o":["Con disimulo, sin mirarlo fijo","Mirándolo fijo a los ojos","Sacándole una foto con el celular","Siguiéndolo hasta la puerta"],"w":"Mirarlo fijo, fotografiarlo o seguirlo puede provocarlo."},{"q":"¿Qué datos del vehículo de huida sirven a Carabineros?","o":["Tipo, color y patente","Solo la marca","Solo si tenía vidrios polarizados","Ninguno; solo sirve la cara"],"w":"Tipo, color y patente ayudan a ubicarlo."}]},{"s":"as_accidente","v":[{"q":"Un asalto sufrido mientras trabajas es:","o":["Un accidente del trabajo (Ley 16.744)","Un problema solo de Carabineros","Un hecho sin cobertura si no hay heridas","Un accidente común, para tu previsión de salud"],"w":"Se denuncia y tienes atención en la Mutual, incluido apoyo psicológico."},{"q":"Tras un asalto no tuviste lesiones, pero no puedes dormir. ¿Qué haces?","o":["Aviso y pido apoyo psicológico en la Mutual","Nada, porque no hubo lesiones","Lo trato por mi cuenta en Fonasa o isapre","Espero unos meses a ver si se pasa"],"w":"La Mutual de Seguridad CChC entrega apoyo psicológico aunque no haya heridas."},{"q":"Después de un asalto en el trabajo, puedes recibir apoyo psicológico en la Mutual aunque no tengas heridas.","vf":true,"w":"Verdadero. Es accidente del trabajo y la atención incluye apoyo psicológico."}]},{"s":"as_auto","v":[{"q":"¿Cuándo conviene decidir cómo actuarás ante un asalto?","o":["Antes, en calma: no resistir, observar y avisar","En el momento, según cómo se vea el asaltante","Solo si la jefatura lo pide","Después del primer asalto"],"w":"En el momento, el miedo no deja pensar. La decisión se toma antes."},{"q":"Un compañero dice que si lo asaltan va a defender la caja. ¿Qué le dices?","o":["Que no: forcejear expone su vida y la de los clientes","Que está bien, si el asaltante no tiene arma","Que solo si hay otros compañeros","Que mejor esconda el dinero en el momento"],"w":"Forcejear es la acción insegura típica."},{"q":"¿Cuál combinación es la decisión segura ante un asalto?","o":["No resistir, observar y avisar al 133","No resistir y salir tras él a ver la patente","Obedecer, perseguir y anotar la patente","Esconder dinero, obedecer y avisar"],"w":"No resistir, observar con disimulo y avisar cuando sea seguro."}]}]},{"id":"pvd","sec":"admin","title":"Trabajo con computador: ergonomía y pausas","thumb":"pvd_intro","learn":[{"s":"pvd_intro","t":"Muchas horas frente a la pantalla","x":"Administrativos, cajeros, analistas y ejecutivos de venta de {EMP} pasan horas frente al computador. Una mala postura no duele el primer día, pero <b>sumada día a día</b> puede terminar en dolor de cuello, espalda, hombros y muñecas. Lo básico: pantalla a la altura de los ojos, codos en ángulo recto, pies apoyados y pausas. Ajustar tu puesto toma cinco minutos."},{"s":"pvd_pantalla","t":"La pantalla","x":"<ul><li>El <b>borde superior a la altura de los ojos</b> o un poco más abajo.</li><li>A unos <b>50 a 70 cm</b>: más o menos un brazo estirado.</li><li><b>De frente</b>, no girada a un lado: girar el cuello todo el día lo carga.</li></ul>Si la pantalla está baja, ponle una base o algo firme debajo. Si usas dos pantallas, la principal va al frente."},{"s":"pvd_silla","t":"Silla, espalda y pies","x":"<ul><li>Regula la altura: <b>codos en ángulo recto</b>, a la altura del escritorio.</li><li>Espalda <b>apoyada en el respaldo</b>, sobre todo la zona lumbar.</li><li><b>Pies planos</b> en el suelo o en un apoyapiés; no colgando ni cruzados todo el día.</li><li>Hombros relajados.</li></ul>Si tu silla no se regula o está dañada, <b>avisa a tu jefatura</b>.","k":"Ajusta tu silla: espalda apoyada, codos en ángulo recto y pies apoyados."},{"s":"pvd_teclado","t":"Teclado y mouse","x":"<ul><li>Teclado <b>cerca</b>, frente a ti, a la altura de los codos.</li><li><b>Muñecas rectas</b>: ni dobladas hacia arriba ni hacia los lados.</li><li>Mouse <b>al lado del teclado</b>, sin estirar el brazo.</li><li><b>Antebrazos apoyados</b> en el escritorio.</li></ul>Un brazo estirado hacia el mouse todo el día termina en dolor de hombro."},{"s":"pvd_vista","t":"Descansa la vista: 20-20-20","x":"Una <b>recomendación práctica</b>, no una norma legal: cada <b>20 minutos</b>, mira algo lejano, a unos <b>6 metros</b>, durante <b>20 segundos</b>. Parpadea a propósito: frente a la pantalla <b>parpadeamos menos</b> y los ojos se secan. Ojos cansados, ardor o visión borrosa son señales para descansar, no para acercarte a la pantalla."},{"s":"pvd_pausas","t":"Pausas activas","x":"Estar quieto también cansa, aunque no cargues peso. Cada cierto rato:<ul><li><b>Levántate</b> y camina un poco.</li><li>Estira cuello, hombros, espalda y muñecas, sin forzar.</li><li>Cambia de postura.</li></ul>Aprovecha tareas como ir a la impresora o a bodega para moverte, en vez de pedir que te las traigan."},{"s":"pvd_notebook","t":"Notebook y celular","x":"<ul><li>El notebook plano obliga a agachar la cabeza. Si lo usas muchas horas, ponlo sobre una <b>base</b> para subir la pantalla y usa <b>teclado y mouse aparte</b>.</li><li>El <b>celular</b>: súbelo a la altura de los ojos en vez de doblar el cuello.</li><li>Evita trabajar en la cama o el sillón, también en teletrabajo.</li></ul>"},{"s":"pvd_luz","t":"Luz y reflejos","x":"<ul><li>Pon la pantalla <b>al costado de la ventana</b>, no de frente ni de espaldas a ella.</li><li>Usa cortinas o persianas si el sol pega en la pantalla.</li><li>Ajusta el brillo a la luz del lugar.</li><li>Limpia la pantalla.</li></ul>Los reflejos y el encandilamiento te obligan a forzar la vista y a inclinarte, y así aparece el dolor de cuello."},{"s":"pvd_sintomas","t":"Señales de alerta","x":"Los <b>trastornos musculoesqueléticos de extremidades superiores (TMERT)</b> avisan antes:<ul><li>Dolor en cuello, hombros, codos o muñecas.</li><li><b>Hormigueo</b> o adormecimiento en manos y dedos, a veces de noche.</li><li>Pérdida de fuerza.</li></ul>Si se repiten, <b>avisa a tu jefatura</b> y consulta en la <b>Mutual de Seguridad CChC</b> (fono 1407). No te automediques.","k":"Si el hormigueo o el dolor se repiten, avisa y consulta."},{"s":"pvd_auto","t":"Autocuidado: \"termino y paro\"","x":"La mayoría de los accidentes y lesiones se relacionan con una acción insegura. Frente al computador, la típica es <b>termino esto y paro</b>: horas encorvado sin moverte, ignorando el dolor. La decisión segura: <b>ajusta tu puesto, haz la pausa ahora</b> y avisa si tu silla o tu pantalla no sirven."}],"quiz":[{"s":"pvd_pantalla","v":[{"q":"¿A qué altura debe estar el borde superior de la pantalla?","o":["A la altura de los ojos o un poco más abajo","Bien por encima de los ojos","A la altura del pecho","A la altura del teclado"],"w":"Así el cuello queda recto, sin mirar hacia arriba ni agacharse."},{"q":"¿A qué distancia de tus ojos va la pantalla?","o":["A unos 50 a 70 cm, como un brazo estirado","A unos 20 cm","A más de 1,2 m","Lo más cerca posible"],"w":"Muy cerca cansa la vista; muy lejos te inclina hacia adelante."},{"q":"La pantalla debe quedar de frente a ti, no girada hacia un lado.","vf":true,"w":"Verdadero. Girar el cuello todo el día lo carga y causa dolor."}]},{"s":"pvd_cel_mal","v":[{"q":"Revisas pedidos en el celular con el cuello doblado por largos ratos. ¿Qué cambias?","o":["Subo el celular a la altura de los ojos","Agacho más la cabeza para ver mejor","Lo uso recostado en el sillón","Aumento la letra y sigo igual"],"w":"Con el celular a la altura de los ojos, el cuello queda recto."},{"q":"¿Qué postura con el celular cuida tu cuello?","o":["Celular a la altura de los ojos y cuello recto","Celular en las rodillas y cuello doblado","Celular sobre el escritorio, inclinado sobre él","Celular entre la oreja y el hombro"],"w":"Doblar el cuello por horas sobrecarga cuello y hombros."},{"q":"¿Qué zona se sobrecarga al usar el celular con la cabeza agachada?","o":["Cuello y hombros","Rodillas","Tobillos","Caderas"],"w":"La cabeza inclinada pesa más para el cuello."}]},{"s":"pvd_teclado","v":[{"q":"Al escribir, las muñecas deben estar:","o":["Rectas, con el teclado cerca","Dobladas hacia arriba","Apoyadas en el borde del escritorio","Giradas hacia afuera"],"w":"Muñecas rectas y mouse junto al teclado, sin estirar el brazo."},{"q":"¿Dónde va el mouse?","o":["Al lado del teclado, sin estirar el brazo","En el otro extremo del escritorio","Sobre las piernas","Delante del teclado"],"w":"Estirar el brazo hacia el mouse todo el día termina en dolor de hombro."},{"q":"Al escribir, los antebrazos deben estar:","o":["Apoyados en el escritorio, con los codos en ángulo recto","En el aire, sin apoyo","Con los codos sobre la altura de los hombros","Apoyados solo en las muñecas"],"w":"Antebrazos apoyados descargan hombros y cuello."}]},{"s":"pvd_vista","v":[{"q":"La regla 20-20-20 es una norma legal obligatoria en Chile.","vf":false,"w":"Falso. Es una recomendación práctica para descansar la vista."},{"q":"¿Por qué se secan los ojos frente a la pantalla?","o":["Porque parpadeamos menos","Por el calor del computador","Por el polvo de la pantalla","Por la luz del teclado"],"w":"Frente a la pantalla parpadeamos menos: parpadea a propósito."},{"q":"Llevas una hora frente a la pantalla y te arden los ojos. ¿Qué haces?","o":["Miro algo lejano y parpadeo a propósito","Me acerco más a la pantalla","Subo el brillo al máximo","Sigo hasta terminar y después descanso"],"w":"El ardor es señal de descanso: mira lejos y parpadea."}]},{"s":"pvd_vista","v":[{"q":"Según la regla 20-20-20, cada 20 minutos debes:","o":["Mirar algo lejano durante 20 segundos","Cerrar los ojos durante 20 minutos","Levantarte y caminar 20 metros","Alejar la pantalla 20 cm"],"w":"Mira lejos unos 20 segundos y parpadea a propósito."},{"q":"En la regla 20-20-20, ¿a qué distancia aproximada miras?","o":["Unos 6 metros","Unos 50 centímetros","Unos 20 metros","Un metro"],"w":"Mirar a unos 6 metros relaja el enfoque de los ojos."},{"q":"La regla 20-20-20 significa:","o":["Cada 20 minutos, mirar a unos 6 m durante 20 segundos","Cada 20 segundos, mirar lejos 20 minutos","Una pausa de 20 minutos cada 20 horas","Mirar la pantalla a 20 cm"],"w":"Pausas cortas y frecuentes para la vista."}]},{"s":"pvd_silla","v":[{"q":"Los pies deben quedar:","o":["Planos en el suelo o en un apoyapiés","Colgando de la silla","Cruzados bajo la silla","Apoyados en las ruedas de la silla"],"w":"Pies apoyados, espalda en el respaldo y codos en ángulo recto."},{"q":"¿Cómo deben quedar los codos al escribir?","o":["En ángulo recto, a la altura del escritorio","Más abajo que el escritorio","Estirados hacia adelante","Sobre la altura de los hombros"],"w":"Se regula la altura de la silla hasta lograr codos en ángulo recto."},{"q":"Si tu silla no se puede regular o está dañada, debes avisar a tu jefatura.","vf":true,"w":"Verdadero. Una silla que no se ajusta impide una buena postura."}]},{"s":"pvd_luz","v":[{"q":"¿Dónde conviene poner la pantalla respecto de la ventana?","o":["Al costado de la ventana","De frente a la ventana","De espaldas a la ventana","Justo bajo la ventana"],"w":"Al costado se evitan reflejos y encandilamiento."},{"q":"El sol pega en tu pantalla y ves reflejos. ¿Qué haces?","o":["Cierro la cortina o dejo la pantalla al costado de la ventana","Subo el brillo y sigo","Me inclino para ver mejor","Pongo la pantalla de frente a la ventana"],"w":"Los reflejos obligan a forzar la vista y la postura."},{"q":"¿Por qué conviene evitar los reflejos en la pantalla?","o":["Te obligan a forzar la vista y la postura","Porque gastan la pantalla","Porque consumen más energía","Porque calientan el computador"],"w":"Forzar la vista lleva a inclinarse y a dolor de cuello."}]},{"s":"pvd_notebook","v":[{"q":"Si usas notebook muchas horas, lo recomendable es:","o":["Ponerlo en una base y usar teclado y mouse aparte","Usarlo en las piernas en el sillón","Bajar el brillo al mínimo","Inclinar la pantalla hacia atrás"],"w":"Así la pantalla sube a la altura de los ojos y las manos quedan bien."},{"q":"¿Qué logras al poner el notebook sobre una base?","o":["Subir la pantalla a la altura de los ojos","Que se enfríe solo","Escribir más rápido en su teclado","Ver mejor el teclado"],"w":"La base sube la pantalla; por eso se usa teclado y mouse aparte."},{"q":"Si usas notebook muchas horas, conviene ponerlo en una base y usar teclado y mouse aparte.","vf":true,"w":"Verdadero. El notebook plano obliga a agachar la cabeza."}]},{"s":"pvd_sintomas","v":[{"q":"Tienes hormigueo en las manos varias veces a la semana. ¿Qué haces?","o":["Aviso a mi jefatura y consulto en la Mutual","Espero a que se pase solo","Tomo un antiinflamatorio sin consultar","Uso una muñequera y no digo nada"],"w":"Es una señal de alerta de TMERT: se avisa y se consulta a tiempo."},{"q":"¿Cuál de estas es una señal de alerta de TMERT?","o":["Hormigueo o adormecimiento en manos y dedos","Ojos rojos al final del día","Dolor de cabeza por el ruido","Cansancio por dormir poco"],"w":"Dolor, hormigueo, adormecimiento y pérdida de fuerza en extremidades superiores."},{"q":"Te duele la muñeca cada tarde desde hace semanas. ¿Qué corresponde?","o":["Avisar a la jefatura y consultar en la Mutual de Seguridad CChC","Seguir igual: es normal en oficina","Esperar a que el dolor sea fuerte","Automedicarte y no avisar"],"w":"Consultar a tiempo evita que se vuelva una lesión crónica."}]},{"s":"pvd_pausas","v":[{"q":"Las pausas activas sirven solo para quienes cargan peso.","vf":false,"w":"Falso. Estar quieto también cansa: levántate, estira y camina."},{"q":"¿Qué es una pausa activa?","o":["Levantarse, estirar y caminar un poco","Revisar el celular sentado","Cambiar de programa en el computador","Tomar un café en el puesto"],"w":"Moverse y estirar descarga los músculos que trabajan quietos."},{"q":"¿Cómo aprovechas las tareas del día para moverte?","o":["Voy caminando a la impresora o a bodega","Pido que me traigan las impresiones","Uso el chat en vez de levantarme","Junto todo para levantarme una vez"],"w":"Cada tarea que te hace caminar es una pausa activa."}]}]},{"id":"oficina","sec":"admin","title":"Riesgos en la oficina","thumb":"of_intro","learn":[{"s":"of_intro","t":"La oficina también tiene riesgos","x":"En la oficina no hay grúas ni camiones, pero sí accidentes:<ul><li>Caídas por cables, cajones abiertos o pisos mojados.</li><li>Golpes por archivadores que se vuelcan.</li><li>Riesgo eléctrico por zapatillas sobrecargadas.</li><li>Caídas al subirse a una silla.</li><li>Emergencias como sismos e incendios.</li></ul>Y también el camino de ida y vuelta entre tu casa y {EMP}."},{"s":"of_caidas","t":"Caídas al mismo nivel","x":"<ul><li><b>Cables</b> por el piso: ordénalos por la orilla o con canaletas.</li><li><b>Cajones</b> abiertos, sobre todo los de abajo: ciérralos apenas los uses.</li><li>Alfombras levantadas, piso mojado o café derramado: <b>señaliza, limpia o avisa</b>.</li><li>No camines leyendo el celular.</li><li>Usa el pasamanos en las escaleras.</li></ul>"},{"s":"of_cajones","t":"Archivadores","x":"<ul><li>Abre <b>un cajón a la vez</b>: con dos abiertos arriba, el peso se va hacia adelante y el mueble se puede volcar sobre ti.</li><li>Pon lo <b>pesado en los cajones de abajo</b>.</li><li>Cierra cada cajón al terminar.</li><li>Si el mueble es alto, debe estar firme o anclado: si se mueve, avisa.</li></ul>"},{"s":"of_electrico","t":"Riesgo eléctrico","x":"<ul><li><b>No conectes una zapatilla a otra</b> (en cadena): se sobrecargan.</li><li>No sobrecargues enchufes con estufas, hervidores y equipos a la vez.</li><li>Desenchufa tomando el enchufe, no tirando del cable.</li><li>Cable pelado, enchufe caliente u olor a quemado: <b>no lo uses y avisa</b>.</li><li>Nunca eches agua sobre un equipo eléctrico.</li></ul>Si faltan enchufes, pide a tu jefatura que se instalen.","k":"Nunca conectes zapatillas en cadena; lo dañado se avisa."},{"s":"of_silla_mal","t":"La silla no es escalera","x":"Para alcanzar un archivo alto, <b>nunca te subas a una silla</b>, menos si tiene ruedas: se desliza o gira y caes de espaldas. Tampoco a cajas ni a un escritorio, aunque alguien sujete. Usa una <b>escalera o un piso de altura adecuado</b>, o pide ayuda. Y deja lo de uso frecuente a una altura cómoda, entre la cintura y los hombros.","k":"Nunca te subas a una silla, menos si tiene ruedas."},{"s":"of_orden","t":"Orden y aseo","x":"<ul><li>Nada de cajas ni archivos en el piso, en los pasillos ni frente a salidas.</li><li>Escritorio ordenado: menos cosas que caen.</li><li>Café o agua derramada: límpiala de inmediato.</li><li>Tijeras y cartoneros, cerrados y guardados.</li><li>Pedidos de resmas o insumos: al lugar que indique la jefatura, no al pasillo.</li></ul>El orden es la medida de prevención más barata que existe."},{"s":"of_evac","t":"Emergencias y evacuación","x":"<ul><li>Conoce las <b>vías de evacuación</b> y la <b>zona de seguridad</b>.</li><li>Puertas, pasillos y extintores, siempre <b>despejados</b>.</li><li>En un sismo: <b>agáchate, cúbrete y afírmate</b>, lejos de ventanas y muebles altos.</li><li>Evacúa caminando cuando se indique, sin correr y <b>sin volver por tus cosas</b>.</li><li>Sigue las instrucciones de los encargados de emergencia.</li></ul>"},{"s":"of_trayecto","t":"Accidente de trayecto","x":"Es el que ocurre en el <b>trayecto directo, de ida o regreso</b>, entre tu casa y el trabajo (Ley 16.744). Si te desvías por un motivo personal, como ir de compras, deja de ser trayecto directo. Si te pasa:<ul><li>Avisa a tu jefatura.</li><li>Acude a la <b>Mutual de Seguridad CChC</b> (fono 1407).</li><li>Guarda pruebas: parte o constancia de Carabineros, testigos u otros medios.</li></ul>"},{"s":"of_auto","t":"Autocuidado: \"es un segundo\"","x":"La mayoría de los accidentes se relacionan con una acción insegura. En la oficina, la típica es <b>es un segundo</b>: subirse a la silla, saltar el cable, dejar el cajón abierto. La decisión segura: <b>busca la escalera, ordena el cable, cierra el cajón</b>. Y avisa las condiciones inseguras que veas, aunque no sean de tu puesto: también es autocuidado."}],"quiz":[{"s":"of_silla_mal","v":[{"q":"Un compañero se sube a su silla con ruedas para alcanzar un archivo alto. ¿Qué corresponde?","o":["Que baje y use una escalera o piso adecuado","Que siga si alguien le sujeta la silla","Que trabe las ruedas y suba","Que se suba al escritorio, que es firme"],"w":"La silla se desliza o gira; el escritorio tampoco es escalera."},{"q":"¿Cuál es la forma correcta de alcanzar un archivo alto?","o":["Con una escalera o un piso de altura adecuado","Sobre una silla sin ruedas","Sobre una caja de archivos","Sobre el escritorio"],"w":"Se usa un equipo hecho para subir, o se pide ayuda."},{"q":"Subirse a una silla con ruedas está bien si es por un segundo y alguien la sujeta.","vf":false,"w":"Falso. Nunca se usa la silla como escalera."}]},{"s":"of_electrico","v":[{"q":"Se puede conectar una zapatilla eléctrica a otra si faltan enchufes.","vf":false,"w":"Falso. Las zapatillas en cadena se sobrecargan y pueden provocar un incendio."},{"q":"Te faltan enchufes en tu puesto. ¿Qué haces?","o":["Pido a mi jefatura que se instalen los necesarios","Conecto una zapatilla a otra","Uso un adaptador triple en la zapatilla","Conecto el hervidor y la estufa al mismo enchufe"],"w":"Sobrecargar enchufes calienta los cables y puede causar un incendio."},{"q":"¿Cómo se desenchufa un equipo?","o":["Tomando el enchufe, no tirando del cable","Tirando del cable cerca del enchufe","Tirando del cable con el equipo encendido","Moviendo el enchufe de lado a lado"],"w":"Tirar del cable lo daña y deja conexiones expuestas."}]},{"s":"of_cajones","v":[{"q":"¿Por qué conviene abrir un solo cajón del archivador a la vez?","o":["Porque con varios abiertos el mueble puede volcarse","Para que no se mezclen los papeles","Para que los rieles duren más","Para ahorrar espacio en el pasillo"],"w":"Con varios cajones abiertos arriba, el peso se va hacia adelante y el mueble se vuelca."},{"q":"¿Dónde guardas los archivos más pesados?","o":["En los cajones de abajo","En el cajón de arriba","Sobre el mueble","Repartidos en los cajones de arriba"],"w":"Lo pesado abajo da estabilidad al mueble."},{"q":"Abrir un cajón a la vez ayuda a evitar que el archivador se vuelque.","vf":true,"w":"Verdadero. Y lo pesado va en los cajones de abajo."}]},{"s":"of_caidas","v":[{"q":"Un cable cruza el pasillo de la oficina. ¿Qué haces?","o":["Lo ordeno por la orilla o aviso para canalizarlo","Lo salto cada vez","Le pongo una alfombra encima sin avisar","Lo dejo, ya todos lo conocen"],"w":"Los cables por el piso son una causa típica de caídas."},{"q":"Ves un cajón inferior abierto en el paso. ¿Qué haces?","o":["Lo cierro","Paso por el lado con cuidado","Aviso al final del día","Pongo una silla delante para que se vea"],"w":"Un cajón abierto abajo es una trampa para tropezar."},{"q":"Caminas por el pasillo leyendo el celular. ¿Qué riesgo aumentas?","o":["Tropezar con cables, cajones o piso mojado","Ninguno, si conoces la oficina","Solo el cansancio de la vista","Solo chocar con otra persona"],"w":"Sin mirar el piso no ves lo que te puede hacer caer."}]},{"s":"of_electrico","v":[{"q":"Notas olor a quemado en un enchufe. ¿Qué haces?","o":["Dejo de usarlo y aviso de inmediato","Sigo trabajando si funciona","Le echo agua para enfriarlo","Lo cambio de enchufe y no aviso"],"w":"No uses lo dañado y avisa. Nunca agua sobre equipos eléctricos."},{"q":"El hervidor tiene el cable pelado. ¿Qué haces?","o":["No lo uso y aviso","Lo uso con cuidado","Le pongo cinta y lo uso","Lo uso solo con las manos secas"],"w":"Un cable pelado puede dar una descarga o provocar un incendio."},{"q":"Un enchufe está caliente al tacto. ¿Qué haces?","o":["No lo uso y aviso a mi jefatura","Le echo agua para enfriarlo","Sigo usándolo si funciona","Conecto menos cosas y no aviso"],"w":"Un enchufe caliente indica sobrecarga o falla: se deja de usar y se avisa."}]},{"s":"of_evac","v":[{"q":"En un sismo, la conducta recomendada es:","o":["Agacharte, cubrirte y afirmarte","Correr por la escalera de inmediato","Pararte bajo el marco de la ventana","Salir corriendo al estacionamiento"],"w":"Es la recomendación de SENAPRED, lejos de ventanas y muebles altos."},{"q":"Durante el sismo, ¿de qué te alejas?","o":["De ventanas y muebles altos","Del escritorio","De tus compañeros","De la puerta de salida"],"w":"Los vidrios y muebles altos pueden caer sobre ti."},{"q":"Al evacuar, puedes volver por tus cosas si la salida está cerca.","vf":false,"w":"Falso. Se evacúa sin volver por nada."}]},{"s":"of_trayecto","v":[{"q":"Un accidente en el trayecto directo de tu casa al trabajo está cubierto por la Ley 16.744.","vf":true,"w":"Verdadero. El accidente de trayecto está definido en la Ley 16.744."},{"q":"¿Cuál de estos casos es accidente de trayecto?","o":["Caerte en la calle camino directo al trabajo","Caerte en el supermercado al desviarte a comprar","Accidentarte en un paseo el fin de semana","Lesionarte en el gimnasio antes del trabajo"],"w":"Solo el trayecto directo, de ida o regreso, entre la casa y el trabajo."},{"q":"Si tienes un accidente de trayecto, ¿qué haces?","o":["Aviso a mi jefatura y acudo a la Mutual de Seguridad CChC","Me atiendo en cualquier consultorio sin avisar","No hago nada si puedo caminar","Voy a la Inspección del Trabajo"],"w":"Avisar y atenderse en la Mutual permite que quede cubierto."}]},{"s":"accidente_pruebas","v":[{"q":"Si sufres un accidente de trayecto, ¿qué te sirve como prueba?","o":["Parte o constancia de Carabineros, testigos u otros medios","Nada, no se puede probar","Solo una publicación en redes sociales","Solo tu palabra, sin otros datos"],"w":"Avisa a tu jefatura, acude a la Mutual y guarda las pruebas."},{"q":"Te atropellaron camino al trabajo. ¿Qué conviene guardar?","o":["Parte de Carabineros y datos de testigos","Solo la boleta del pasaje","Nada, basta con contarlo","Solo una foto de la calle"],"w":"Estas pruebas acreditan que ocurrió en el trayecto directo."},{"q":"¿Para qué sirven el parte de Carabineros o los testigos en un accidente de trayecto?","o":["Para acreditar que ocurrió en el trayecto directo","Para cobrar una multa al otro conductor","Para pedir un día libre","No sirven si hay lesiones"],"w":"Con pruebas se acredita el accidente ante la Mutual."}]},{"s":"exitBlocked","v":[{"q":"Hay cajas apiladas frente a la puerta de salida. Eso es:","o":["Una condición insegura que debes despejar o avisar","Algo aceptable si es por poco rato","Un problema solo del personal de aseo","Un acto inseguro de quien pasa"],"w":"Las salidas siempre despejadas: en una emergencia no hay tiempo de moverlas."},{"q":"Llegó un pedido de resmas y no hay espacio. ¿Dónde NO pueden quedar?","o":["Frente a salidas, pasillos o extintores","En el lugar que indique la jefatura","En la bodega de insumos","En un estante bajo"],"w":"Salidas, pasillos y extintores deben quedar libres."},{"q":"Las salidas, los pasillos y los extintores deben estar siempre despejados.","vf":true,"w":"Verdadero. En una emergencia se necesitan libres de inmediato."}]},{"s":"of_auto","v":[{"q":"¿Cuál es la decisión segura frente al \"es un segundo\"?","o":["Buscar la escalera, ordenar el cable y cerrar el cajón","Hacerlo rápido para no perder tiempo","Hacerlo solo si nadie mira","Hacerlo con cuidado, sin cambiar nada"],"w":"Un segundo de apuro puede costar meses de recuperación."},{"q":"Ves un cable cruzando el pasillo que nadie ha reportado. ¿Qué haces?","o":["Lo ordeno por la orilla o aviso","Lo salto: no es mi puesto","Espero que alguien lo reporte","Le pongo un papel encima para que se vea"],"w":"Avisar condiciones inseguras también es autocuidado."},{"q":"¿Por qué el \"es un segundo\" es peligroso?","o":["Un segundo de apuro puede costar meses de lesión","Porque se pierde tiempo","Porque molesta a los compañeros","Porque solo lo prohíbe el reglamento"],"w":"La acción insegura típica en oficina nace del apuro."}]}]}]});
